INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('iulspop/production-app-template-postgres-supabase/documentation', 'documentation', 'iulspop', 'production-app-template-postgres-supabase', 'community', 'documentation iulspop production-app-template-postgres-supabase community The documentation skill helps developers create high-quality documentation with runnable examples, minimal and expanded concepts, and clear formatting. It benefits software engineers and technical writers. 使用AI Agent生成高质量的文档，包括代码示例和清晰的解释 AIエージェントを使用してドキュメントを生成し、コード例と明確な説明を含める AI 에이전트를 사용하여 문서를 생성하고, 코드 예제와 명확한 설명을 포함합니다 La documentación de software es fundamental para los desarrolladores. Aprende a crear documentación efectiva con ejemplos y diagramas claros La documentation est essentielle pour les développeurs. Découvrez comment créer des documentations efficaces avec des exemples minimalistes et des diagrammes clairs Die technische Dokumentation ist für Entwickler unerlässlich. Erfahren Sie, wie Sie effektive Dokumentationen mit runnable Beispielen und minimalen Beispielen erstellen können Crie documentação de software de alta qualidade com exemplos executáveis e conceitos claros, utilizando as melhores práticas de documentação Создавайте техническую документацию с помощью ИИ Агентов, используя примеры и концепции для повышения качества вашего ПО إنشاء وثائق برمجيات ممتازة باستخدام أمثلة قابلة للتشغيل وconcept واضحة مع أفضل الممارسات لأدوات الذكاء الاصطناعي how to write documentation documentation best practices documentation setup guide documentation for AI agents technical writing tips creating effective documentation documentation vs commenting code installing documentation tools documentation examples 文档生成 AI Agent 代码示例 清晰的解释 文档创建 高质量的文档 Runnable/copy-paste示例 H2/H3标题 小图表 避免术语 Generates documentation with runnable/copy-paste examples near the top of pages Pairs every concept with a minimal example and an expanded one Uses clear H2/H3 headings, short paragraphs, bullet lists, and callouts Adds small diagrams or screenshots where they clarify meaning Writes precise and concise language, avoiding jargon and idioms Documentation is a set of practices and guidelines for writing clear, concise, and precise technical documentation with examples, diagrams, and screenshots.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('muneebslog/Medsync/pest-testing', 'community', 'muneebslog', 'Medsync', 'muneebslog/Medsync', 'pest-testing', 0, 0, 23, '2026-03-07T01:49:01.731Z', '2026-03-07T02:50:19.103Z', '05bb6cfd7acdeeaa3c2b2317ed71bb6fe329eafd204a072cfced0157e6ebd473', '{"id":"muneebslog/Medsync/pest-testing","name":"pest-testing","description":{"en":"Pest-testing is a skill that enables developers to create and manage tests using Pest 3. It benefits developers working with PHP and Laravel frameworks.","zh":"Pest Testing 3 是一个 PHP 测试框架，用于创建和管理测试。它提供了便捷的测试创建和组织功能","ja":"Pest Testing 3 は、PHP テストフレームワークで、テストの作成と管理を行います。テストの作成と組織を簡単に行うことができます","ko":"Pest Testing 3은 PHP 테스트 프레임워크로 테스트를 생성하고 관리하는 데 사용됩니다. 테스트 생성과 조직을 쉽게 할 수 있습니다","es":"Pest es una herramienta de pruebas para PHP que permite crear tests unitarios y de características de manera eficiente","fr":"Pest est un outil de test pour PHP qui permet de créer des tests unitaires et de fonctionnalités de manière efficace","de":"Pest ist ein Testtool für PHP, mit dem Sie Einheitstests und Funktionalitätstests effizient erstellen können","pt":"O Pest-Testing é uma ferramenta para criar e gerenciar testes de unidade e recursos em projetos PHP, utilizando o framework Pest 3.","ru":"ИИ Агент Pest-Testing - это инструмент для создания и управления юнит-тестами и функциональными тестами в проектах PHP, использующий фреймворк Pest 3.","ar":"إيجنت اختبار الآفات هو أداة لإنشاء وتنظيم اختبارات الوحدة والميزات في مشاريع PHP، باستخدام إطار العمل Pest 3."},"seo":{"title":{"en":"Pest-Testing: Automated Test Setup Guide | AI Agent Skill","zh":"Pest Testing 3 入门指南：PHP 测试框架","ja":"Pest Testing 3 セットアップガイド：PHP テストフレームワーク","ko":"Pest Testing 3 시작하기: PHP 테스트 프레임워크","es":"Guía de configuración de pruebas de pest","fr":"Guide de mise en place des tests Pest","de":"Einrichtungsleitfaden für Pest-Tests","pt":"Guia de Configuração do Pest-Testing para Desenvolvedores","ru":"Настройка ИИ Агента Pest-Testing: Лучшие Практики","ar":"إعداد وتشغيل إيجنت اختبار الآفات للطورين"},"description":{"en":"Discover how to streamline your testing workflow with Pest 3 patterns and documentation. Learn how to create and organize tests with Pest and improve your de...","zh":"了解 Pest Testing 3 的基本用法和功能，包括创建测试、测试组织和调试","ja":"Pest Testing 3 の基本的な使用方法と機能について学びます。テストの作成、テストの組織、デバッグなど","ko":"Pest Testing 3의 기본 사용법과 기능을 알아보세요. 테스트 생성, 테스트 조직, 디버깅 등","es":"Aprende a configurar y utilizar Pest para pruebas unitarias y de características en PHP","fr":"Découvrez comment configurer et utiliser Pest pour les tests unitaires et de fonctionnalités en PHP","de":"Erfahren Sie, wie Sie Pest für Einheitstests und Funktionalitätstests in PHP einrichten und verwenden","pt":"Aprenda a configurar e usar o Pest-Testing para melhorar a eficiência dos testes de unidade e recursos em seu projeto","ru":"Узнайте, как настроить и использовать ИИ Агент Pest-Testing для повышения эффективности юнит-тестов и функциональных тестов","ar":"تعرف على كيفية إعداد وتشغيل إيجنت اختبار الآفات لتحسين كفاءة اختبارات الوحدة والميزات في مشروعك"},"definition":{"en":"Pest-testing is a software testing skill that utilizes Pest 3 patterns and documentation to create and organize unit and feature tests.","zh":"Pest Testing 3 是一个用于 PHP 应用的测试框架","ja":"Pest Testing 3 は、PHP アプリケーションのテストフレームワークです","ko":"Pest Testing 3은 PHP 애플리케이션을 위한 테스트 프레임워크입니다","es":"Pest es un framework de pruebas para PHP que utiliza la sintaxis de Pest 3","fr":"Pest est un framework de test pour PHP qui utilise la syntaxe de Pest 3","de":"Pest ist ein Testframework für PHP, das die Syntax von Pest 3 verwendet","pt":"Pest-Testing é uma técnica de teste que utiliza o framework Pest 3 para criar e gerenciar testes de unidade e recursos em projetos PHP.","ru":"ИИ Агент Pest-Testing - это техника тестирования, использующая фреймворк Pest 3 для создания и управления юнит-тестами и функциональными тестами в проектах PHP.","ar":"إيجنت اختبار الآفات هو تقنية اختبار تستخدم إطار العمل Pest 3 لإنشاء وتنظيم اختبارات الوحدة والميزات في مشاريع PHP."},"features":{"en":["Creates tests using `php artisan make:test --pest {name}` command","Organizes tests in the `tests/Feature` directory","Supports debugging test failures and working with datasets","Enables writing architecture tests using Pest 3","Utilizes `search-docs` for detailed Pest 3 patterns and documentation"],"zh":["使用 Pest 创建和管理测试","支持测试组织和调试","提供 `php artisan make:test --pest {name}` 命令","支持测试数据、模拟和测试组织","用于写入架构测试"],"ja":["Pest を使用してテストを作成して管理する","テストの組織とデバッグをサポート"," `php artisan make:test --pest {name}` コマンドを提供","テストデータ、モッキング、テストの組織をサポート","アーキテクチャテストの記述に使用"],"ko":["Pest를 사용하여 테스트를 생성하고 관리","테스트 조직 및 디버깅 지원"," `php artisan make:test --pest {name}` 명령 제공","테스트 데이터, 모의, 테스트 조직 지원","아키텍처 테스트 작성에 사용"],"es":["Creación de tests unitarios y de características con Pest 3","Organización de tests en el directorio tests/Feature","Uso de php artisan make:test para crear tests","Compatibilidad con datasets, mocking y organización de tests","Soporte para pruebas de arquitectura"],"fr":["Création de tests unitaires et de fonctionnalités avec Pest 3","Organisation des tests dans le répertoire tests/Feature","Utilisation de php artisan make:test pour créer des tests","Compatibilité avec les datasets, mocking et organisation des tests","Prise en charge des tests d''architecture"],"de":["Erstellung von Einheitstests und Funktionalitätstests mit Pest 3","Organisation von Tests im Verzeichnis tests/Feature","Verwendung von php artisan make:test zur Erstellung von Tests","Kompatibilität mit Daten, Mocking und Testorganisation","Unterstützung für Architekturtests"],"pt":["Criação de testes de unidade e recursos utilizando o comando `php artisan make:test --pest {name}`","Organização de testes em diretórios `tests/Feature`","Utilização do framework Pest 3 para gerenciar testes","Suporte à depuração de falhas de teste","Integração com datasets, mocking e organização de testes"],"ru":["Создание юнит-тестов и функциональных тестов с помощью команды `php artisan make:test --pest {name}`","Организация тестов в директориях `tests/Feature`","Использование фреймворка Pest 3 для управления тестами","Поддержка отладки неудач тестов","Интеграция с наборами данных, макетами и организацией тестов"],"ar":["إنشاء اختبارات الوحدة والميزات باستخدام الأمر `php artisan make:test --pest {name}`","تنظيم الاختبارات في الدلائل `tests/Feature`","استخدام إطار العمل Pest 3 لإدارة الاختبارات","دعم تصحيح أخطاء الاختبار","التكامل مع مجموعات البيانات والتعليمات والتنظيم الاختباري"]},"keywords":{"en":["how to use pest-testing","pest-testing setup guide","pest-testing vs phpunit","pest-testing install laravel","what is pest-testing","pest-testing alternative to jest"],"zh":["Pest Testing 3","PHP 测试框架","测试创建","测试组织","调试","PHP 艺术命令","测试数据","模拟","AIエージェント"],"ja":["Pest Testing 3","PHP テストフレームワーク","テスト作成","テスト組織","デバッグ","PHP アーティサンコマンド","テストデータ","モッキング","AIエージェント"],"ko":["Pest Testing 3","PHP 테스트 프레임워크","테스트 생성","테스트 조직","디버깅","PHP 아티즌 명령","테스트 데이터","모의","AI 에이전트"],"es":["pruebas de pest","pest 3","tests unitarios php","tests de características php","php artisan make:test","herramientas de pruebas php","framework de pruebas php","pest testing"],"fr":["tests pest","pest 3","tests unitaires php","tests de fonctionnalités php","php artisan make:test","outils de test php","framework de test php","pest testing"],"de":["pest-tests","pest 3","einheitstests php","funktionalitätstests php","php artisan make:test","testtools php","testframework php","pest testing"],"pt":["Pest-Testing","Testes de unidade","Testes de recursos","Pest 3","PHP","Desenvolvimento de software","Testes automatizados","Ferramentas de teste"],"ru":["ИИ Агент Pest-Testing","Юнит-тесты","Функциональные тесты","Pest 3","PHP","Разработка программного обеспечения","Автоматизированное тестирование","Инструменты тестирования"],"ar":["إيجنت اختبار الآفات","اختبارات الوحدة","اختبارات الميزات","Pest 3","PHP","تطوير البرمجيات","اختبارات آلية","أدوات الاختبار"]}},"owner":"muneebslog","repo":"Medsync","repoPath":"muneebslog/Medsync","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.731Z","topics":[],"category":"community","skillMd":{"name":"pest-testing","description":">-","bodyPreview":"# Pest Testing 3\n\n## When to Apply\n\nActivate this skill when:\n- Creating new tests (unit or feature)\n- Modifying existing tests\n- Debugging test failures\n- Working with datasets, mocking, or test organization\n- Writing architecture tests\n\n## Documentation\n\nUse `search-docs` for detailed Pest 3 patterns and documentation.\n\n## Basic Usage\n\n### Creating Tests\n\nAll tests must be written using Pest. Use `php artisan make:test --pest {name}`.\n\n### Test Organization\n\n- Tests live in the `tests/Feature`","body":"# Pest Testing 3\n\n## When to Apply\n\nActivate this skill when:\n- Creating new tests (unit or feature)\n- Modifying existing tests\n- Debugging test failures\n- Working with datasets, mocking, or test organization\n- Writing architecture tests\n\n## Documentation\n\nUse `search-docs` for detailed Pest 3 patterns and documentation.\n\n## Basic Usage\n\n### Creating Tests\n\nAll tests must be written using Pest. Use `php artisan make:test --pest {name}`.\n\n### Test Organization\n\n- Tests live in the `tests/Feature` and `tests/Unit` directories.\n- Do NOT remove tests without approval - these are core application code.\n- Test happy paths, failure paths, and edge cases.\n\n### Basic Test Structure\n\n<code-snippet name=\"Basic Pest Test Example\" lang=\"php\">\n\nit(''is true'', function () {\n    expect(true)->toBeTrue();\n});\n\n</code-snippet>\n\n### Running Tests\n\n- Run minimal tests with filter before finalizing: `php artisan test --compact --filter=testName`.\n- Run all tests: `php artisan test --compact`.\n- Run file: `php artisan test --compact tests/Feature/ExampleTest.php`.\n\n## Assertions\n\nUse specific assertions (`assertSuccessful()`, `assertNotFound()`) instead of `assertStatus()`:\n\n<code-snippet name=\"Pest Response Assertion\" lang=\"php\">\n\nit(''returns all'', function () {\n    $this->postJson(''/api/docs'', [])->assertSuccessful();\n});\n\n</code-snippet>\n\n| Use | Instead of |\n|-----|------------|\n| `assertSuccessful()` | `assertStatus(200)` |\n| `assertNotFound()` | `assertStatus(404)` |\n| `assertForbidden()` | `assertStatus(403)` |\n\n## Mocking\n\nImport mock function before use: `use function Pest\\Laravel\\mock;`\n\n## Datasets\n\nUse datasets for repetitive tests (validation rules, etc.):\n\n<code-snippet name=\"Pest Dataset Example\" lang=\"php\">\n\nit(''has emails'', function (string $email) {\n    expect($email)->not->toBeEmpty();\n})->with([\n    ''james'' => ''james@laravel.com'',\n    ''taylor'' => ''taylor@laravel.com'',\n]);\n\n</code-snippet>\n\n## Pest 3 Features\n\n### Architecture Testing\n\nPest 3 includes architecture testing to enforce code conventions:\n\n<code-snippet name=\"Architecture Test Example\" lang=\"php\">\n\narch(''controllers'')\n    ->expect(''App\\Http\\Controllers'')\n    ->toExtendNothing()\n    ->toHaveSuffix(''Controller'');\n\narch(''models'')\n    ->expect(''App\\Models'')\n    ->toExtend(''Illuminate\\Database\\Eloquent\\Model'');\n\narch(''no debugging'')\n    ->expect([''dd'', ''dump'', ''ray''])\n    ->not->toBeUsed();\n\n</code-snippet>\n\n### Type Coverage\n\nPest 3 provides improved type coverage analysis. Run with `--type-coverage` flag.\n\n## Common Pitfalls\n\n- Not importing `use function Pest\\Laravel\\mock;` before using mock\n- Using `assertStatus(200)` instead of `assertSuccessful()`\n- Forgetting datasets for repetitive validation tests\n- Deleting tests without approval"},"lastSynced":"2026-03-07T02:50:19.103Z","agentAnalysis":{"suitability":{"en":"Ideal for PHP and Laravel framework-focused agents seeking to streamline test creation and management with Pest 3.","zh":"适合使用 PHP 和 Laravel 框架的代理，旨在使用 Pest 3 简化测试创建和管理。","ja":"Pest 3 を使用してテストの作成と管理をストリームライン化しようとしている PHP と Laravel フレームワークに焦点を当てたエージェントに最適です。","ko":"Pest 3를 사용하여 테스트 생성 및 관리를 간소화하려는 PHP 및 Laravel 프레임워크에 중점을 둔 에이전트에게 적합합니다.","es":"Ideal para agentes enfocados en PHP y el framework Laravel que buscan simplificar la creación y gestión de pruebas con Pest 3.","fr":"Idéal pour les agents axés sur PHP et le framework Laravel qui cherchent à rationaliser la création et la gestion de tests avec Pest 3.","de":"Ideal für PHP- und Laravel-Framework-fokussierte Agenten, die die Erstellung und Verwaltung von Tests mit Pest 3 rationalisieren möchten.","pt":"Ideal para agentes focados no framework PHP e Laravel que buscam simplificar a criação e gestão de testes com Pest 3.","ru":"Идеально для агентов, ориентированных на фреймворк PHP и Laravel, стремящихся упростить создание и управление тестами с помощью Pest 3.","ar":"مثالي للوكلاء الذين يركزون على إطار العمل PHP وLaravel والذين يسعون إلى تسهيل إنشاء الاختبارات وإدارتها باستخدام Pest 3."},"recommendation":{"en":"Empowers agents to create and manage tests efficiently using Pest 3, facilitating unit and feature testing, debugging, and test organization with PHP and Laravel frameworks.","zh":"赋予代理使用 Pest 3 高效地创建和管理测试的能力，促进使用 PHP 和 Laravel 框架进行单元和功能测试、调试和测试组织。","ja":"Pest 3 を使用してテストを作成および管理するエージェントを強化し、PHP および Laravel フレームワークを使用した単体および機能テスト、デバッグ、およびテストの組織化を促進します。","ko":"Pest 3를 사용하여 테스트를 효율적으로 생성 및 관리할 수 있는 에이전트의 능력을 강화하여 PHP 및 Laravel 프레임워크를 사용한 단위 및 기능 테스트, 디버깅 및 테스트 조직을 촉진합니다.","es":"Habilita a los agentes a crear y gestionar pruebas de manera eficiente con Pest 3, facilitando las pruebas unitarias y de características, la depuración y la organización de pruebas con PHP y los frameworks de Laravel.","fr":"Permet aux agents de créer et de gérer des tests de manière efficace avec Pest 3, en facilitant les tests unitaires et de fonctionnalités, le débogage et l''organisation des tests avec PHP et les frameworks Laravel.","de":"Ermächtigt Agenten, Tests effizient mit Pest 3 zu erstellen und zu verwalten, wodurch die Erstellung von Unit- und Funktionalitätstests, Fehlersuche und Testorganisation mit PHP und Laravel-Frameworks erleichtert wird.","pt":"Habilita os agentes a criar e gerenciar testes de forma eficiente usando Pest 3, facilitando testes unitários e de recursos, depuração e organização de testes com os frameworks PHP e Laravel.","ru":"Наделяет агентов возможностью создавать и управлять тестами эффективно с помощью Pest 3, облегчая модульное и функциональное тестирование, отладку и организацию тестов с помощью фреймворков PHP и Laravel.","ar":"يمنح الوكلاء القدرة على إنشاء الاختبارات وإدارتها بفعالية باستخدام Pest 3، ويسهل الاختبارات الوحدوية واختبارات الميزات، وتصحيح الأخطاء، وتأطير الاختبارات باستخدام إطارات العمل PHP وLaravel."},"useCases":{"en":["Creating new unit and feature tests with Pest 3","Debugging test failures in Laravel applications","Organizing tests in the tests/Feature directory"],"zh":["使用 Pest 3 创建新的单元和功能测试","调试 Laravel 应用程序中的测试失败","在 tests/Feature 目录中组织测试"],"ja":["Pest 3 を使用して新しいユニットと機能テストを作成する","Laravel アプリケーションのテスト失敗をデバッグする","tests/Feature ディレクトリでテストを整理する"],"ko":["Pest 3를 사용하여 새로운 단위 및 기능 테스트를 생성하는 것","Laravel 애플리케이션의 테스트 실패를 디버깅하는 것","tests/Feature 디렉토리에서 테스트를 조직하는 것"],"es":["Crear nuevas pruebas unitarias y de características con Pest 3","Depurar errores de prueba en aplicaciones Laravel","Organizar pruebas en el directorio tests/Feature"],"fr":["Créer de nouvelles tests unitaires et de fonctionnalités avec Pest 3","Déboguer les échecs de test dans les applications Laravel","Organiser les tests dans le répertoire tests/Feature"],"de":["Erstellen neuer Unit- und Funktionalitätstests mit Pest 3","Fehlersuche bei Testfehlern in Laravel-Anwendungen","Organisieren von Tests im Verzeichnis tests/Feature"],"pt":["Criar novos testes unitários e de recursos com Pest 3","Depurar falhas de teste em aplicações Laravel","Organizar testes no diretório tests/Feature"],"ru":["Создание новых модульных и функциональных тестов с помощью Pest 3","Отладка неудач тестов в приложениях Laravel","Организация тестов в каталоге tests/Feature"],"ar":["إنشاء اختبارات وحدة وميزات جديدة مع Pest 3","تصحيح اخفاقات الاختبار في تطبيقات Laravel","تنظيم الاختبارات في الدليل tests/Feature"]},"limitations":{"en":["Requires PHP and Laravel framework setup","Specific to Pest 3 testing framework"],"zh":["需要 PHP 和 Laravel 框架设置","特定于 Pest 3 测试框架"],"ja":["PHP および Laravel フレームワークのセットアップが必要","Pest 3 テストフレームワークに特有"],"ko":["PHP 및 Laravel 프레임워크 설정이 필요","Pest 3 테스트 프레임워크에 특정"],"es":["Requiere configuración de PHP y framework de Laravel","Específico del framework de prueba Pest 3"],"fr":["Nécessite une configuration PHP et framework Laravel","Spécifique au framework de test Pest 3"],"de":["Benötigt PHP- und Laravel-Framework-Setup","Spezifisch für das Pest 3-Testframework"],"pt":["Exige configuração do framework PHP e Laravel","Específico para o framework de teste Pest 3"],"ru":["Требует настройки фреймворка PHP и Laravel","Специфичен для фреймворка тестирования Pest 3"],"ar":["يتطلب ضبط إطار العمل PHP وLaravel","محدد لإطار الاختبار Pest 3"]},"version":4},"contentHash":"05bb6cfd7acdeeaa3c2b2317ed71bb6fe329eafd204a072cfced0157e6ebd473","qualityScore":23}');
