INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('muneebslog/Medsync/pest-testing', 'pest-testing', 'muneebslog', 'Medsync', 'community', 'pest-testing muneebslog Medsync community Pest-testing is a skill that enables developers to create and manage tests using Pest 3. It benefits developers working with PHP and Laravel frameworks. Pest Testing 3 是一个 PHP 测试框架，用于创建和管理测试。它提供了便捷的测试创建和组织功能 Pest Testing 3 は、PHP テストフレームワークで、テストの作成と管理を行います。テストの作成と組織を簡単に行うことができます Pest Testing 3은 PHP 테스트 프레임워크로 테스트를 생성하고 관리하는 데 사용됩니다. 테스트 생성과 조직을 쉽게 할 수 있습니다 Pest es una herramienta de pruebas para PHP que permite crear tests unitarios y de características de manera eficiente Pest est un outil de test pour PHP qui permet de créer des tests unitaires et de fonctionnalités de manière efficace Pest ist ein Testtool für PHP, mit dem Sie Einheitstests und Funktionalitätstests effizient erstellen können O Pest-Testing é uma ferramenta para criar e gerenciar testes de unidade e recursos em projetos PHP, utilizando o framework Pest 3. ИИ Агент Pest-Testing - это инструмент для создания и управления юнит-тестами и функциональными тестами в проектах PHP, использующий фреймворк Pest 3. إيجنت اختبار الآفات هو أداة لإنشاء وتنظيم اختبارات الوحدة والميزات في مشاريع PHP، باستخدام إطار العمل Pest 3. how to use pest-testing pest-testing setup guide pest-testing vs phpunit pest-testing install laravel what is pest-testing pest-testing alternative to jest Pest Testing 3 PHP 测试框架 测试创建 测试组织 调试 PHP 艺术命令 测试数据 模拟 AIエージェント Creates tests using `php artisan make:test --pest {name}` command Organizes tests in the `tests/Feature` directory Supports debugging test failures and working with datasets Enables writing architecture tests using Pest 3 Utilizes `search-docs` for detailed Pest 3 patterns and documentation Pest-testing is a software testing skill that utilizes Pest 3 patterns and documentation to create and organize unit and feature tests.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Wolf-Tungsten/wolvrix/convert-develop', 'community', 'Wolf-Tungsten', 'wolvrix', 'Wolf-Tungsten/wolvrix', 'convert-develop', 8, 2, 21, '2026-02-25T13:11:33Z', '2026-02-26T08:35:47.952Z', '896d24566833e92a1725cfac47f2e1ce3f029ce723d5b7c92fe018e79160c110', '{"id":"Wolf-Tungsten/wolvrix/convert-develop","name":"convert-develop","description":{"zh":"convert-develop是一个用于优化开发过程的AI智能工具，通过GRH IR打造您的EDA工具链","ja":"convert-developは開発プロセスを最適化するためのAIエージェントです。GRH IRを使用してEDAツールチェーンを構築します","ko":"convert-develop는 개발 프로세스를 최적화하는 AI 에이전트입니다. GRH IR를 사용하여 EDA 툴체인을 구축합니다","es":"Crea tu cadena de herramientas EDA con GRH IR para mejorar tus proyectos de desarrollo","fr":"Créez votre chaîne d''outils EDA avec GRH IR pour améliorer vos projets de développement","de":"Erstellen Sie Ihre EDA-Toolchain mit GRH IR, um Ihre Entwicklungsprojekte zu verbessern","pt":"Desenvolva sua cadeia de ferramentas EDA com GRH IR e melhore sua produtividade","ru":"Создайте свою цепочку инструментов EDA с GRH IR и повысьте свою производительность","ar":"انشئ سلسلتك من أدوات EDA مع GRH IR و提高 إنتاجيتك","en":"Craft your EDA toolchain with GRH IR"},"seo":{"title":{"zh":"AI智能开发工具：convert-develop","ja":"AIエージェントを使用した開発効率化：convert-develop","ko":"AI 에이전트를 활용한 개발 최적화: convert-develop","es":"Herramientas de IA: Desarrolla con GRH IR","fr":"Outils d''IA: Créez votre chaîne d''outils EDA avec GRH IR","de":"KI-Tools: Entwickeln Sie mit GRH IR","pt":"Ferramentas de IA: Desenvolva com GRH IR","ru":"ИИ Агенты: Создавайте с GRH IR","ar":"أدوات الذكاء الاصطناعي: انشئ مع GRH IR","en":"convert-develop"},"description":{"zh":"convert-develop是一个用于优化开发过程的AI智能工具，通过GRH IR打造您的EDA工具链","ja":"convert-developは開発プロセスを最適化するためのAIエージェントです。GRH IRを使用してEDAツールチェーンを構築します","ko":"convert-develop는 개발 프로세스를 최적화하는 AI 에이전트입니다. GRH IR를 사용하여 EDA 툴체인을 구축합니다","es":"Crea tu cadena de herramientas EDA con GRH IR para mejorar tus proyectos de desarrollo","fr":"Créez votre chaîne d''outils EDA avec GRH IR pour améliorer vos projets de développement","de":"Erstellen Sie Ihre EDA-Toolchain mit GRH IR, um Ihre Entwicklungsprojekte zu verbessern","pt":"Desenvolva sua cadeia de ferramentas EDA com GRH IR e melhore sua produtividade","ru":"Создайте свою цепочку инструментов EDA с GRH IR и повысьте свою производительность","ar":"انشئ سلسلتك من أدوات EDA مع GRH IR و提高 إنتاجيتك","en":"Craft your EDA toolchain with GRH IR"},"definition":{"en":"Craft your EDA toolchain with GRH IR"},"features":{"zh":["使用GRH IR打造EDA工具链","优化开发过程和提高效率","支持多种开发语言和框架","提供实时代码分析和反馈","集成多种开发工具和服务"],"ja":["GRH IRを使用してEDAツールチェーンを構築","開発プロセスを最適化して効率を向上","複数の開発言語とフレームワークをサポート","リアルタイムコード分析とフィードバックを提供","複数の開発ツールとサービスを統合"],"ko":["GRH IR를 사용하여 EDA 툴체인을 구축","개발 프로세스를 최적화하고 효율성을 향상","여러 개발 언어와 프레임워크를 지원","실시간 코드 분석과 피드백을 제공","여러 개발 툴과 서비스를 통합"],"es":["Crea tu cadena de herramientas EDA personalizada","Mejora tus proyectos de desarrollo con GRH IR","Integra herramientas de IA en tu flujo de trabajo","Optimiza tus procesos de desarrollo con nuestra herramienta","Desarrolla aplicaciones más eficientes con convert-develop"],"fr":["Créez votre chaîne d''outils EDA sur mesure","Améliorez vos projets de développement avec GRH IR","Intégrez des outils d''IA dans votre flux de travail","Optimisez vos processus de développement avec notre outil","Développez des applications plus efficaces avec convert-develop"],"de":["Erstellen Sie Ihre individuelle EDA-Toolchain","Verbessern Sie Ihre Entwicklungsprojekte mit GRH IR","Integrieren Sie KI-Tools in Ihren Arbeitsablauf","Optimieren Sie Ihre Entwicklungsprozesse mit unserem Tool","Entwickeln Sie effizientere Anwendungen mit convert-develop"],"pt":["Crie sua cadeia de ferramentas EDA personalizada","Melhore sua produtividade com GRH IR","Desenvolva aplicativos com React e Node.js","Utilize a CLI para automação","Integre com outras ferramentas de desenvolvimento"],"ru":["Создайте свою цепочку инструментов EDA на заказ","Повысьте свою производительность с GRH IR","Разработайте приложения с React и Node.js","Используйте CLI для автоматизации","Интегрируйте с другими инструментами разработки"],"ar":["انشئ سلسلتك من أدوات EDA المخصصة","提高 إنتاجيتك مع GRH IR","طور تطبيقات مع React و Node.js","استخدم CLI للتحكم الآلي","دمج مع أدوات تطوير أخرى"]},"keywords":{"zh":["如何使用convert-develop","什么是GRH IR","convert-develop替代品","convert-develop vs 其他开发工具","convert-develop安装指南","convert-develop设置教程","AI智能开发工具","EDA工具链","开发过程优化"],"ja":["convert-developの使い方","GRH IRとは","convert-developの代替品","convert-develop vs その他の開発ツール","convert-developのインストールガイド","convert-developの設定方法","AIエージェント開発ツール","EDAツールチェーン","開発プロセスの最適化"],"ko":["convert-develop 사용법","GRH IR란","convert-develop 대안","convert-develop vs 다른 개발 도구","convert-develop 설치 가이드","convert-develop 설정 방법","AI 에이전트 개발 도구","EDA 툴체인","개발 프로세스 최적화"],"es":["herramientas de ia para desarrolladores","cómo usar GRH IR","alternativas a convert-develop","convert-develop vs otros herramientas de ia","instalación de convert-develop","guía de configuración de convert-develop","desarrollo de aplicaciones con ia","herramientas de desarrollo de software"],"fr":["outils d''ia pour développeurs","comment utiliser GRH IR","alternatives à convert-develop","convert-develop vs autres outils d''ia","installation de convert-develop","guide de configuration de convert-develop","développement d''applications avec ia","outils de développement de logiciels"],"de":["ki-tools für entwickler","wie man GRH IR verwendet","alternativen zu convert-develop","convert-develop vs andere ki-tools","installation von convert-develop","einrichtungsanleitung für convert-develop","entwicklung von anwendungen mit ki","entwicklungstools für software"],"pt":["ferramentas de ia","grh ir","desenvolvimento de aplicativos","react","node.js","cli","automacao","produtividade","desenvolvedores"],"ru":["ии агенты","grh ir","разработка приложений","react","node.js","cli","автоматизация","производительность","разработчики"],"ar":["أدوات الذكاء الاصطناعي","grh ir","تطوير التطبيقات","react","node.js","cli","التحكم الآلي","إنتاجية","مطورين"]}},"owner":"Wolf-Tungsten","repo":"wolvrix","repoPath":"Wolf-Tungsten/wolvrix","stars":8,"forks":2,"updatedAt":"2026-02-25T13:11:33Z","topics":[],"category":"community","skillMd":{"name":"convert-develop","description":"Standardize development for Convert steps in wolf-sv-parser. Use when asked to implement, continue, or review a Convert STEP XXXX task (e.g., convert step 17). Cover reading docs/convert/convert-progress.md, implementing code/tests, updating docs/convert/{convert-architecture,convert-workflow,convert-progress}, and asking for review.","bodyPreview":"# Convert Develop\n\n## Intake\n\n- Extract the step number from the request and normalize to 4 digits (e.g., 17 -> 0017).\n- Open `docs/convert/convert-progress.md` and locate the matching STEP section to capture target/plan/implementation.\n- Read `docs/convert/convert-architecture.md` and `docs/convert/convert-workflow.md` to align with the current design and flow.\n- Identify dependencies or prior steps that are being revised; plan to mark superseded content with strikethroughs.\n- Ask for clarifica","body":"# Convert Develop\n\n## Intake\n\n- Extract the step number from the request and normalize to 4 digits (e.g., 17 -> 0017).\n- Open `docs/convert/convert-progress.md` and locate the matching STEP section to capture target/plan/implementation.\n- Read `docs/convert/convert-architecture.md` and `docs/convert/convert-workflow.md` to align with the current design and flow.\n- Identify dependencies or prior steps that are being revised; plan to mark superseded content with strikethroughs.\n- Ask for clarification when the STEP definition is missing or ambiguous.\n\n## Implementation\n\n- Follow `AGENTS.md` and existing patterns in `include/convert.hpp`, `src/convert.cpp`, and related files.\n- Keep includes minimal; use C++20, 4-space indentation, and same-line braces.\n- Keep comments terse and avoid non-ASCII identifiers.\n\n## Tests\n\n- Add or extend tests under `tests/convert/` with fixtures in `tests/data/convert/`.\n- Register new test targets in `CMakeLists.txt` following the existing `convert-*` pattern and compile definitions.\n- Proactively run configure/build/tests: `cmake -S . -B build` (if needed), `cmake --build build -j$(nproc)`, then `ctest --test-dir build --output-on-failure` (or `ctest -R convert-...`).\n- If the user requests not to run tests or the environment blocks execution, explicitly state what was skipped and why.\n\n## Documentation Updates\n\n- Update `docs/convert/convert-architecture.md` as a static, top-down description of components and relationships.\n- Update `docs/convert/convert-workflow.md` as a runtime, front-to-back description of execution flow.\n- Keep documentation organized from general to specific; after stating principles, add a concrete example.\n- Append a new STEP section to `docs/convert/convert-progress.md` after the separator; preserve target/plan/implementation/finish status fields.\n\n## Review Handoff\n\n- Summarize code/test/doc changes and list tests executed.\n- Ask the user to review or confirm next actions.\n"},"lastSynced":"2026-02-26T08:35:47.952Z","agentAnalysis":{"suitability":{"en":"Perfect for Documentation Agents needing advanced content analysis and conversion capabilities with GRH IR and Markdown files.","zh":"非常适合需要高级内容分析和转换功能的文档代理，特别是与 GRH IR 和 Markdown 文件相关的功能。","ja":"ドキュメント エージェントが高度なコンテンツ分析および変換機能を必要とする場合に最適です。特に、GRH IR および Markdown ファイルに関連する機能です。","ko":"문서 에이전트가 고급 콘텐츠 분석 및 변환 기능을 필요로 하는 경우에 적합합니다. 특히 GRH IR 및 Markdown 파일과 관련된 기능입니다.","es":"Perfecto para Agentes de Documentación que necesitan capacidades avanzadas de análisis y conversión de contenido con GRH IR y archivos Markdown.","fr":"Parfait pour les Agents de Documentation ayant besoin de capacités avancées d''analyse et de conversion de contenu avec GRH IR et des fichiers Markdown.","de":"Perfekt für Dokumentationsagenten, die erweiterte Inhaltsanalyse- und Konvertierungsfunktionen mit GRH IR und Markdown-Dateien benötigen.","pt":"Perfeito para Agentes de Documentação que necessitam de capacidades avançadas de análise e conversão de conteúdo com GRH IR e arquivos Markdown.","ru":"Идеально подходит для агентов документации, которым необходимы расширенные возможности анализа и преобразования контента с GRH IR и файлами Markdown.","ar":"مثالي لعمليات الوكيل الوثائقية التي تحتاج إلى قدرات تحليل ومحوّل متقدمة مع GRH IR وملفات Markdown."},"recommendation":{"en":"Empowers agents to capture target plans and implementations from STEP sections in convert-progress.md, aligning with convert-architecture.md and convert-workflow.md designs, and manage dependencies with strikethroughs for superseded content using Markdown formatting.","zh":"赋予代理捕获来自 convert-progress.md 中的 STEP 部分的目标计划和实现细节，与 convert-architecture.md 和 convert-workflow.md 设计保持一致，并使用 Markdown 格式化来管理依赖关系，以删除线标记表示过时的内容。","ja":"エージェントが convert-progress.md の STEP セクションからターゲット プランと実装をキャプチャし、convert-architecture.md と convert-workflow.md の設計と一致させ、また Markdown フォーマットを使用して依存関係を管理し、取消線で過時になったコンテンツをマークすることを可能にします。","ko":"에이전트가 convert-progress.md의 STEP 섹션에서 목표 계획 및 구현을 캡처하여 convert-architecture.md 및 convert-workflow.md 디자인과 일치시키고 Markdown 형식을 사용하여 의존성을 관리하며 취소선으로 대체된 콘텐츠를 표시할 수 있도록 합니다.","es":"Habilita a los agentes a capturar planes y implementaciones objetivo desde secciones STEP en convert-progress.md, alineándose con los diseños de convert-architecture.md y convert-workflow.md, y gestionar dependencias con tachados para contenido obsoleto utilizando formato Markdown.","fr":"Permet aux agents de capturer des plans et des implementations cibles à partir de sections STEP dans convert-progress.md, en s''alignant sur les conceptions de convert-architecture.md et convert-workflow.md, et de gérer les dépendances avec des barrages pour le contenu obsolète en utilisant le formatage Markdown.","de":"Ermöglicht es Agenten, Zielpläne und -implementierungen aus STEP-Abschnitten in convert-progress.md zu erfassen, die mit den Entwürfen von convert-architecture.md und convert-workflow.md übereinstimmen, und Abhängigkeiten mit Durchstreichungen für veralteten Inhalt mithilfe von Markdown-Formatierung zu verwalten.","pt":"Habilita os agentes a capturar planos e implementações de destino a partir de seções STEP em convert-progress.md, alinhando com os designs convert-architecture.md e convert-workflow.md, e gerenciar dependências com strikethroughs para conteúdo ultrapassado usando formatação Markdown.","ru":"Предоставляет агентам возможность захватить целевые планы и реализации из разделов STEP в convert-progress.md, выравнивая их с дизайном convert-architecture.md и convert-workflow.md, и управлять зависимостями с помощью strikethroughs для устаревшего контента, используя форматирование Markdown.","ar":"يتمكّن الوكلاء من التقاط خطط وتنفيذ الهدف من أقسام STEP في convert-progress.md، وتصحيحه مع تصاميم convert-architecture.md و convert-workflow.md، وإدارة التبعيات باستخدام strikethroughs لمحتوى قديم باستخدام تنسيق Markdown."},"useCases":{"en":["Automating step extraction and normalization from requests","Generating conversion plans based on current architecture and workflow","Debugging dependencies and prior steps for revised content"],"zh":["自动化从请求中提取和归一化步骤","根据当前架构和工作流生成转换计划","调试依赖关系和以前的步骤以修订内容"],"ja":["リクエストからステップを抽出および正規化する自動化","現在のアーキテクチャとワークフローに基づいて変換プランを生成する","依存関係と以前のステップをデバッグしてコンテンツを修正する"],"ko":["요청에서 단계 추출 및 정규화를 자동화하는","현재 아키텍처 및 워크플로우를 기반으로 변환 계획을 생성하는","의존성 및 이전 단계를 디버깅하여 콘텐츠를 수정하는"],"es":["Automatización de la extracción y normalización de pasos desde solicitudes","Generación de planes de conversión en función de la arquitectura y el flujo de trabajo actuales","Depuración de dependencias y pasos anteriores para contenido revisado"],"fr":["Automatisation de l''extraction et de la normalisation des étapes à partir de demandes","Génération de plans de conversion en fonction de l''architecture et du flux de travail actuels","Débogage des dépendances et des étapes précédentes pour le contenu révisé"],"de":["Automatisierung der Extraktion und Normierung von Schritten aus Anfragen","Erstellung von Konvertierungsplänen basierend auf der aktuellen Architektur und dem Arbeitsablauf","Fehlerbehebung von Abhängigkeiten und vorherigen Schritten für überarbeiteten Inhalt"],"pt":["Automatizar a extração e normalização de etapas de solicitações","Gerar planos de conversão com base na arquitetura atual e no fluxo de trabalho","Depurar dependências e etapas anteriores para conteúdo revisado"],"ru":["Автоматизировать извлечение и нормализацию шагов из запросов","Генерировать планы преобразования на основе текущей архитектуры и рабочего процесса","Отладить зависимости и предыдущие шаги для пересмотренного контента"],"ar":["توفير自动ية استخراج وتنسيق خطوات الطلبات","إنشاء خطط التحويل بناءً على الهيكل الحالي وسير العمل","تصحيح الأخطاء في التبعيات والخطوات السابقة لمحتوى تمت مراجعته"]},"limitations":{"en":["Requires access to specific Markdown files (convert-progress.md, convert-architecture.md, convert-workflow.md)","Limited to handling STEP sections and Markdown formatting"],"zh":["需要访问特定的 Markdown 文件（convert-progress.md、convert-architecture.md、convert-workflow.md）","仅限处理 STEP 部分和 Markdown 格式"],"ja":["特定の Markdown ファイル（convert-progress.md、convert-architecture.md、convert-workflow.md）へのアクセスが必要","STEP セクションと Markdown フォーマットのみを処理できる"],"ko":["특정 Markdown 파일(convert-progress.md, convert-architecture.md, convert-workflow.md)에 액세스해야 함","STEP 섹션 및 Markdown 형식만 처리할 수 있음"],"es":["Requiere acceso a archivos Markdown específicos (convert-progress.md, convert-architecture.md, convert-workflow.md)","Limitado a la gestión de secciones STEP y formato Markdown"],"fr":["Nécessite un accès à des fichiers Markdown spécifiques (convert-progress.md, convert-architecture.md, convert-workflow.md)","Limité à la gestion de sections STEP et de formatage Markdown"],"de":["Erfordert Zugriff auf bestimmte Markdown-Dateien (convert-progress.md, convert-architecture.md, convert-workflow.md)","Begrenzt auf die Handhabung von STEP-Abschnitten und Markdown-Formatierung"],"pt":["Requer acesso a arquivos Markdown específicos (convert-progress.md, convert-architecture.md, convert-workflow.md)","Limitado ao tratamento de seções STEP e formatação Markdown"],"ru":["Требует доступа к определенным файлам Markdown (convert-progress.md, convert-architecture.md, convert-workflow.md)","Ограничен обработкой разделов STEP и форматированием Markdown"],"ar":["يتطلب الوصول إلى ملفات Markdown محددة (convert-progress.md، convert-architecture.md، convert-workflow.md)","محدود بمعالجة أقسام STEP وتنسيق Markdown"]},"version":3},"contentHash":"896d24566833e92a1725cfac47f2e1ce3f029ce723d5b7c92fe018e79160c110","qualityScore":21}');
