INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Wolf-Tungsten/wolvrix/convert-develop', 'convert-develop', 'Wolf-Tungsten', 'wolvrix', 'community', 'convert-develop Wolf-Tungsten wolvrix community convert-develop是一个用于优化开发过程的AI智能工具，通过GRH IR打造您的EDA工具链 convert-developは開発プロセスを最適化するためのAIエージェントです。GRH IRを使用してEDAツールチェーンを構築します convert-develop는 개발 프로세스를 최적화하는 AI 에이전트입니다. GRH IR를 사용하여 EDA 툴체인을 구축합니다 Crea tu cadena de herramientas EDA con GRH IR para mejorar tus proyectos de desarrollo Créez votre chaîne d''outils EDA avec GRH IR pour améliorer vos projets de développement Erstellen Sie Ihre EDA-Toolchain mit GRH IR, um Ihre Entwicklungsprojekte zu verbessern Desenvolva sua cadeia de ferramentas EDA com GRH IR e melhore sua produtividade Создайте свою цепочку инструментов EDA с GRH IR и повысьте свою производительность انشئ سلسلتك من أدوات EDA مع GRH IR و提高 إنتاجيتك Craft your EDA toolchain with GRH IR 如何使用convert-develop 什么是GRH IR convert-develop替代品 convert-develop vs 其他开发工具 convert-develop安装指南 convert-develop设置教程 AI智能开发工具 EDA工具链 开发过程优化 Craft your EDA toolchain with GRH IR');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('loopflowstudio/loopflow/direction-security', 'community', 'loopflowstudio', 'loopflow', 'loopflowstudio/loopflow', 'direction-security', 8, 0, 21, '2026-03-01T00:21:44Z', '2026-03-01T05:19:20.213Z', '9df735252f7d7db8a54be62ca02e8bb3bc6a380b019bfb2e2ee168a3102af782', '{"id":"loopflowstudio/loopflow/direction-security","name":"direction-security","description":{"zh":"方向安全是一种AI智能代理技能，用于协调LLMs进行编码，确保代码安全和高效","ja":"方向セキュリティは、AIエージェントのスキルで、LLMsを調和させてコードを書くためのものです","ko":"방향 보안은 LLMs를 조화롭게 코딩하여 보안과 효율성을 높이는 AI 에이전트 スキル입니다","es":"Organiza LLMs para codificar en armonía y mejora la seguridad de tu proyecto con nuestras herramientas de dirección","fr":"Organisez les LLMs pour coder en harmonie et améliorez la sécurité de votre projet avec nos outils de direction","de":"Organisieren Sie LLMs, um in Harmonie zu codieren und die Sicherheit Ihres Projekts mit unseren Richtungs-Tools zu verbessern","pt":"A habilidade de direção de segurança permite que os LLMs codifiquem em harmonia, melhorando a segurança e a eficiência do código","ru":"Навык направления безопасности позволяет ИИ кодировать в гармонии, улучшая безопасность и эффективность кода","ar":"تتيح مهارة أمن التوجيه للنماذج اللغوية الكبيرة كتابة الشفرات في وئام، مما يحسن من أمن الشفرة وفعاليته","en":"Arrange LLMs to code in harmony."},"seo":{"title":{"zh":"AI智能代理方向安全","ja":"AIエージェントの方向セキュリティ","ko":"AI 에이전트 방향 보안","es":"Herramientas de AI: Seguridad de Dirección para LLMs","fr":"Outils IA: Sécurité de Direction pour LLMs","de":"KI-Tools: Richtungs-Sicherheit für LLMs","pt":"Ferramentas de IA: Segurança de Direção","ru":"ИИ Агенты: Направление Безопасности","ar":"أدوات الذكاء الاصطناعي: أمن التوجيه","en":"direction-security"},"description":{"zh":"方向安全是一种AI智能代理技能，用于协调LLMs进行编码，确保代码安全和高效","ja":"方向セキュリティは、AIエージェントのスキルで、LLMsを調和させてコードを書くためのものです","ko":"방향 보안은 LLMs를 조화롭게 코딩하여 보안과 효율성을 높이는 AI 에이전트 スキル입니다","es":"Organiza LLMs para codificar en armonía y mejora la seguridad de tu proyecto con nuestras herramientas de dirección","fr":"Organisez les LLMs pour coder en harmonie et améliorez la sécurité de votre projet avec nos outils de direction","de":"Organisieren Sie LLMs, um in Harmonie zu codieren und die Sicherheit Ihres Projekts mit unseren Richtungs-Tools zu verbessern","pt":"A habilidade de direção de segurança permite que os LLMs codifiquem em harmonia, melhorando a segurança e a eficiência do código","ru":"Навык направления безопасности позволяет ИИ кодировать в гармонии, улучшая безопасность и эффективность кода","ar":"تتيح مهارة أمن التوجيه للنماذج اللغوية الكبيرة كتابة الشفرات في وئام، مما يحسن من أمن الشفرة وفعاليته","en":"Arrange LLMs to code in harmony."},"definition":{"en":"Arrange LLMs to code in harmony."},"features":{"zh":["协调LLMs进行编码","提升代码安全性","提高编码效率","支持多种编程语言","集成React、Python、Node.js等技术"],"ja":["LLMsを調和させてコードを書く","セキュリティを高める","効率を高める","多くのプログラミング言語をサポート","React、Python、Node.js等の技術を統合"],"ko":["LLMs를 조화롭게 코딩","보안을 높임","효율성을 높임","다수의 프로그래밍 언어 지원","React, Python, Node.js 등 기술 통합"],"es":["Mejora la seguridad de tu proyecto","Organiza LLMs para codificar en armonía","Integra con herramientas de desarrollo como React y Node.js","Permite la creación de códigos más seguros","Facilita la colaboración en equipo"],"fr":["Améliorez la sécurité de votre projet","Organisez les LLMs pour coder en harmonie","Intégrez avec des outils de développement comme React et Node.js","Permet la création de codes plus sécurisés","Facilite la collaboration d''équipe"],"de":["Verbessern Sie die Sicherheit Ihres Projekts","Organisieren Sie LLMs, um in Harmonie zu codieren","Integrieren Sie mit Entwicklungstools wie React und Node.js","Ermöglicht die Erstellung von sichereren Codes","Erleichtert die Teamzusammenarbeit"],"pt":["Codificação em harmonia","Melhoria da segurança do código","Aumento da eficiência do código","Integração com LLMs","Suporte a múltiplos frameworks"],"ru":["Кодирование в гармонии","Улучшение безопасности кода","Повышение эффективности кода","Интеграция с ИИ","Поддержка нескольких фреймворков"],"ar":["كتابة الشفرات في وئام","تحسين أمن الشفرة","زيادة فعالية الشفرة","التكامل مع النماذج اللغوية الكبيرة","دعم الإطارات المتعددة"]},"keywords":{"zh":["如何使用AI智能代理","什么是方向安全","AI智能代理替代品","LLMs编码教程","方向安全安装","AI智能代理设置指南"],"ja":["AIエージェントの使い方","方向セキュリティとは","AIエージェントの代替","LLMsのコード書き方","方向セキュリティのインストール","AIエージェントの設定ガイド"],"ko":["AI 에이전트 사용법","방향 보안이란","AI 에이전트 대체","LLMs 코딩 가이드","방향 보안 설치","AI 에이전트 설정 가이드"],"es":["herramientas de AI","seguridad de dirección","LLMs","codificar en armonía","mejorar la seguridad del proyecto","integrar con React","alternativas a LLMs","guía de instalación de LLMs","configuración de LLMs"],"fr":["outils IA","sécurité de direction","LLMs","coder en harmonie","améliorer la sécurité du projet","intégrer avec React","alternatives à LLMs","guide d''installation de LLMs","configuration de LLMs"],"de":["KI-Tools","Richtungs-Sicherheit","LLMs","in Harmonie codieren","Sicherheit des Projekts verbessern","integrieren mit React","Alternativen zu LLMs","Installationsanleitung für LLMs","Konfiguration von LLMs"],"pt":["como usar ferramentas de IA","o que é direção de segurança","ferramentas de IA para codificação","direção de segurança vs segurança do código","instalar ferramentas de IA","guia de configuração de ferramentas de IA"],"ru":["как использовать ИИ Агенты","что такое направление безопасности","ИИ Агенты для кодирования","направление безопасности vs безопасность кода","установить ИИ Агенты","руководство по настройке ИИ Агентов"],"ar":["كيفية استخدام أدوات الذكاء الاصطناعي","ما هي مهارة أمن التوجيه","أدوات الذكاء الاصطناعي للكتابة الشفرات","أمن التوجيه مقابل أمن الشفرة","تثبيت أدوات الذكاء الاصطناعي","دليل إعداد أدوات الذكاء الاصطناعي"]}},"owner":"loopflowstudio","repo":"loopflow","repoPath":"loopflowstudio/loopflow","stars":8,"forks":0,"updatedAt":"2026-03-01T00:21:44Z","topics":[],"category":"community","skillMd":{"name":"direction-security","description":"Defense in depth. Validate inputs, sanitize outputs, minimize attack surface.","bodyPreview":"Defense in depth. Validate inputs, sanitize outputs, minimize attack surface.\n\nAssume breach. Least privilege for every component. Audit sensitive operations.\n\n- Sanitize all external input before processing\n- Never log secrets or credentials\n- Prefer deny-by-default access patterns\n- Rotate secrets; don''t embed them in code\n- Treat security as a constraint, not a feature","body":"Defense in depth. Validate inputs, sanitize outputs, minimize attack surface.\n\nAssume breach. Least privilege for every component. Audit sensitive operations.\n\n- Sanitize all external input before processing\n- Never log secrets or credentials\n- Prefer deny-by-default access patterns\n- Rotate secrets; don''t embed them in code\n- Treat security as a constraint, not a feature\n"},"lastSynced":"2026-03-01T05:19:20.213Z","agentAnalysis":{"suitability":{"en":"Essential for Code-Generation Agents requiring hardened security practices and secure output.","zh":"对于需要强化安全实践和安全输出的代码生成智能体至关重要。","ja":"強固なセキュリティ慣行と安全な出力を必要とするコード生成エージェントに不可欠です。","ko":"강화된 보안 관행과 안전한 출력이 필요한 코드 생성 에이전트에게 필수적입니다.","es":"Esencial para los agentes de generación de código que requieren prácticas de seguridad reforzadas y salida segura.","fr":"Essentiel pour les agents de génération de code nécessitant des pratiques de sécurité renforcées et une sortie sécurisée.","de":"Wesentlich für Code-Generierungs-Agents, die gehärtete Sicherheitspraktiken und sichere Ausgabe erfordern.","pt":"Essencial para Agentes de Geração de Código que exigem práticas de segurança robustas e saída segura.","ru":"Необходим для Агентов Генерации Кода, требующих усиленных практик безопасности и безопасного вывода.","ar":"أساسي لوكلاء إنشاء التعليمات البرمجية التي تتطلب ممارسات أمان قوية ومخرجات آمنة."},"recommendation":{"en":"Implements a defense-in-depth security model by validating all external inputs and sanitizing outputs to minimize attack surface. Enforces least privilege access patterns and prevents credential logging, treating security as a core constraint rather than an afterthought.","zh":"通过验证所有外部输入并清理输出来最小化攻击面，从而实现纵深防御安全模型。强制执行最小权限访问模式并防止凭据记录，将安全视为核心约束而非事后补救措施。","ja":"すべての外部入力を検証し、出力をサニタイズして攻撃対象領域を最小化することにより、多層防御セキュリティモデルを実装します。最小権限のアクセスパターンを強制し、資格情報のログ記録を防止し、セキュリティを後付けではなく中核的な制約として扱います。","ko":"모든 외부 입력을 검증하고 출력을 무해화하여 공격 표면을 최소화함으로써 심층 방어 보안 모델을 구현합니다. 최소 권한 액세스 패턴을 시행하고 자격 증명 로깅을 방지하여 보안을 사후 고려가 아닌 핵심 제약 조건으로 취급합니다.","es":"Implementa un modelo de seguridad en profundidad validando todas las entradas externas y saneando las salidas para minimizar la superficie de ataque. Fuerza patrones de acceso con privilegios mínimos y evita la registración de credenciales, tratando la seguridad como una restricción principal en lugar de un pensamiento posterior.","fr":"Mettre en œuvre un modèle de sécurité en profondeur en validant toutes les entrées externes et en sanitisant les sorties pour minimiser la surface d''attaque. Fait respecter les modèles d''accès avec des privilèges minimum et empêche l''enregistrement des informations d''identification, traitant la sécurité comme une contrainte principale plutôt qu''une après-pensée.","de":"Implementiert ein Sicherheitsmodell in der Tiefe, indem alle externen Eingaben validiert und die Ausgaben gesäubert werden, um die Angriffsfläche zu minimieren. Erzwingt Muster des Mindestzugriffs und verhindert die Protokollierung von Anmeldeinformationen, wobei die Sicherheit als eine Kernbeschränkung und nicht als eine nachträgliche Überlegung behandelt wird.","pt":"Implementa um modelo de segurança em profundidade, validando todas as entradas externas e saneando as saídas para minimizar a superfície de ataque. Impõe padrões de acesso de privilégio mínimo e evita o registro de credenciais, tratando a segurança como uma restrição central e não como uma reflexão tardia.","ru":"Реализует модель безопасности в глубину путем проверки всех внешних входных данных и санирования выходных данных для минимизации поверхности атаки. Обеспечивает соблюдение шаблонов доступа с наименьшими привилегиями и предотвращает логирование учетных данных, рассматривая безопасность как основное ограничение, а не как второстепенную мысль.","ar":"يطبق نموذج أمان متعدد الطبقات من خلال التحقق من جميع المدخلات الخارجية وتنقية المخرجات لتقليل سطح الهجوم. يفرض أنماط وصول بأقل صلاحيات ويمنع تسجيل بيانات الاعتماد، ويعامل الأمان كقيد أساسي وليس كفكرة لاحقة."},"useCases":{"en":["Sanitizing external user input before code processing","Implementing deny-by-default access control patterns","Auditing and rotating embedded secrets in codebases","Preventing accidental credential exposure in log files"],"zh":["在代码处理前清理外部用户输入","实施默认拒绝访问控制模式","审计和轮换代码库中的嵌入式密钥","防止日志文件中的意外凭据暴露"],"ja":["コード処理前の外部ユーザー入力のサニタイズ","デフォルト拒否のアクセス制御パターンの実装","コードベース内の埋め込みシークレットの監査とローテーション","ログファイル内の偶発的な資格情報の露出防止"],"ko":["코드 처리 전 외부 사용자 입력 무해화","기본 거부 액세스 제어 패턴 구현","코드베이스에 내장된 비밀의 감사 및 순환","로그 파일에서의 실수로 인한 자격 증명 노출 방지"],"es":["Saneando la entrada de usuario externa antes del procesamiento de código","Implementando patrones de control de acceso por defecto","Auditoría y rotación de secretos incrustados en las bases de código","Prevención de la exposición accidental de credenciales en archivos de registro"],"fr":["Sanitiser les entrées utilisateur externes avant le traitement du code","Mettre en œuvre des modèles de contrôle d''accès par défaut","Auditer et faire pivoter les secrets intégrés dans les bases de code","Prévenir l''exposition accidentelle des informations d''identification dans les fichiers journaux"],"de":["Säubern der externen Benutzereingaben vor der Codeverarbeitung","Implementieren von Standardmuster für den Zugriffscontro","Auditorische Überprüfung und Rotation von in den Codebasen eingebetteten Geheimnissen","Verhinderung der unbeabsichtigten Offenlegung von Anmeldeinformationen in Log-Dateien"],"pt":["Sanitizando a entrada externa do usuário antes do processamento de código","Implementando padrões de controle de acesso de negação por padrão","Auditando e rotacionando segredos incorporados em bases de código","Prevenindo a exposição acidental de credenciais em arquivos de log"],"ru":["Санирование внешнего пользовательского ввода перед обработкой кода","Реализация шаблонов контроля доступа \"запрещено по умолчанию\"","Аудит и ротация встроенных секретов в кодовых базах","Предотвращение случайного раскрытия учетных данных в файлах журналов"],"ar":["تنقية مدخلات المستخدم الخارجية قبل معالجة التعليمات البرمجية","تنفيذ أنماط تحكم في الوصول بالرفض افتراضيًا","مراجعة وتدوير الأسرار المضمنة في قواعد التعليمات البرمجية","منع التعرض العرضي لبيانات الاعتماد في ملفات السجلات"]},"limitations":{"en":["Requires explicit input validation rules for each data type","Depends on environment for secret rotation mechanisms","Necessitates ongoing audit trail configuration for sensitive operations"],"zh":["需要为每种数据类型制定明确的输入验证规则","依赖于环境来实现密钥轮换机制","需要对敏感操作进行持续的审计跟踪配置"],"ja":["データタイプごとの明示的な入力検証ルールが必要","シークレットローテーション機構は環境に依存","機密操作には継続的な監査証跡の設定が必要"],"ko":["각 데이터 유형별 명시적 입력 검증 규칙 필요","비밀 순환 메커니즘은 환경에 의존","민감한 작업에 대한 지속적인 감사 추적 구성 필요"],"es":["Requiere reglas de validación de entrada explícitas para cada tipo de datos","Depende del entorno para los mecanismos de rotación de secretos","Requiere una configuración continua de auditoría para operaciones sensibles"],"fr":["Nécessite des règles de validation d''entrée explicites pour chaque type de données","Dépend de l''environnement pour les mécanismes de rotation de secrets","Nécessite une configuration d''audit continue pour les opérations sensibles"],"de":["Benötigt explizite Eingabevalidierungsregeln für jeden Datentyp","Hängt von der Umgebung für Geheimnisrotationsmechanismen ab","Erfordert eine kontinuierliche Audit-Konfiguration für sensible Operationen"],"pt":["Requer regras explícitas de validação de entrada para cada tipo de dado","Depende do ambiente para mecanismos de rotação de segredos","Necessita configuração contínua de trilha de auditoria para operações sensíveis"],"ru":["Требует явных правил проверки ввода для каждого типа данных","Зависит от среды для механизмов ротации секретов","Требует постоянной настройки журнала аудита для чувствительных операций"],"ar":["يتطلب قواعد تحقق صريحة من المدخلات لكل نوع بيانات","يعتمد على البيئة لآليات تدوير الأسرار","يتطلب تكوينًا مستمرًا لسجل التدقيق للعمليات الحساسة"]},"version":3},"contentHash":"9df735252f7d7db8a54be62ca02e8bb3bc6a380b019bfb2e2ee168a3102af782","qualityScore":21}');
