INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('loopflowstudio/loopflow/direction-security', 'direction-security', 'loopflowstudio', 'loopflow', 'community', 'direction-security loopflowstudio loopflow community 方向安全是一种AI智能代理技能，用于协调LLMs进行编码，确保代码安全和高效 方向セキュリティは、AIエージェントのスキルで、LLMsを調和させてコードを書くためのものです 방향 보안은 LLMs를 조화롭게 코딩하여 보안과 효율성을 높이는 AI 에이전트 スキル입니다 Organiza LLMs para codificar en armonía y mejora la seguridad de tu proyecto con nuestras herramientas de dirección Organisez les LLMs pour coder en harmonie et améliorez la sécurité de votre projet avec nos outils de direction Organisieren Sie LLMs, um in Harmonie zu codieren und die Sicherheit Ihres Projekts mit unseren Richtungs-Tools zu verbessern A habilidade de direção de segurança permite que os LLMs codifiquem em harmonia, melhorando a segurança e a eficiência do código Навык направления безопасности позволяет ИИ кодировать в гармонии, улучшая безопасность и эффективность кода تتيح مهارة أمن التوجيه للنماذج اللغوية الكبيرة كتابة الشفرات في وئام، مما يحسن من أمن الشفرة وفعاليته Arrange LLMs to code in harmony. 如何使用AI智能代理 什么是方向安全 AI智能代理替代品 LLMs编码教程 方向安全安装 AI智能代理设置指南 Arrange LLMs to code in harmony.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vnzzzz/slim/frontend-design', 'community', 'vnzzzz', 'slim', 'vnzzzz/slim', 'frontend-design', 0, 0, 21, '2026-03-05T06:20:06.307Z', '2026-03-05T08:45:59.701Z', '772a4afebd986c3350b4c9e816164cbf7445e84a899644e976cda0b8f1180454', '{"id":"vnzzzz/slim/frontend-design","name":"frontend-design","description":{"zh":"Server List Manager是AI智能代理前端设计的一部分，用于管理服务器列表","ja":"サーバーリストマネージャーはAIエージェントのフロントエンド設計の一部であり、サーバーリストを管理するために使用される","ko":"서버 목록 관리자는 AI 에이전트 프론트엔드 디자인의 일부로서 서버 목록을 관리하는 데 사용된다","es":"El Gestor de Lista de Servidores es una herramienta de diseño frontend que utiliza agentes de IA para automatizar tareas","fr":"Le Gestionnaire de Liste de Serveurs est un outil de conception frontend qui utilise des agents d''IA pour automatiser des tâches","de":"Der Server-Listen-Manager ist ein Frontend-Design-Tool, das IA-Tools verwendet, um Aufgaben zu automatisieren","pt":"O Gerenciador de Lista de Servidores é uma ferramenta de frontend que ajuda a gerenciar servidores com eficiência. Desenvolvida com React, Python e Node.js","ru":"Менеджер Списка Серверов - это инструмент frontend, который помогает эффективно управлять серверами. Разработан с использованием React, Python и Node.js","ar":"مدير قائمة الخوادم هو أداة ويب أمامي تساعد في إدارة الخوادم بفعالية. تم تطويره باستخدام React و Python و Node.js","en":"Server List Manager"},"seo":{"title":{"zh":"AI智能代理前端设计 - 服务器列表管理","ja":"AIエージェントのフロントエンド設計 - サーバーリストマネージャー","ko":"AI 에이전트 프론트엔드 디자인 - 서버 목록 관리자","es":"Herramientas de Diseño Frontend: Gestor de Lista de Servi...","fr":"Outils de Conception Frontend: Gestionnaire de Liste de S...","de":"Frontend-Design-Tools: Server-Listen-Manager","pt":"Ferramentas de Frontend: Gerenciador de Lista de Servidores","ru":"ИИ Агенты: Менеджер Списка Серверов для Frontend","ar":"أدوات الويب الأمامي: مدير قائمة الخوادم","en":"frontend-design"},"description":{"zh":"Server List Manager是AI智能代理前端设计的一部分，用于管理服务器列表","ja":"サーバーリストマネージャーはAIエージェントのフロントエンド設計の一部であり、サーバーリストを管理するために使用される","ko":"서버 목록 관리자는 AI 에이전트 프론트엔드 디자인의 일부로서 서버 목록을 관리하는 데 사용된다","es":"El Gestor de Lista de Servidores es una herramienta de diseño frontend que utiliza agentes de IA para automatizar tareas","fr":"Le Gestionnaire de Liste de Serveurs est un outil de conception frontend qui utilise des agents d''IA pour automatiser des tâches","de":"Der Server-Listen-Manager ist ein Frontend-Design-Tool, das IA-Tools verwendet, um Aufgaben zu automatisieren","pt":"O Gerenciador de Lista de Servidores é uma ferramenta de frontend que ajuda a gerenciar servidores com eficiência. Desenvolvida com React, Python e Node.js","ru":"Менеджер Списка Серверов - это инструмент frontend, который помогает эффективно управлять серверами. Разработан с использованием React, Python и Node.js","ar":"مدير قائمة الخوادم هو أداة ويب أمامي تساعد في إدارة الخوادم بفعالية. تم تطويره باستخدام React و Python و Node.js","en":"Server List Manager"},"definition":{"en":"Server List Manager"},"features":{"zh":["使用React设计用户界面","支持Node.js和CLI","提供服务器列表管理功能","实现AI智能代理集成","提高开发效率和生产力"],"ja":["Reactを使用してユーザーインターフェースを設計","Node.jsとCLIをサポート","サーバーリスト管理機能を提供","AIエージェントの統合を実現","開発効率と生産性を向上させる"],"ko":["React를 사용하여 사용자 인터페이스를 디자인","Node.js와 CLI를 지원","서버 목록 관리 기능을 제공","AI 에이전트의 통합을 구현","개발 효율성과 생산성을 향상시키다"],"es":["Diseño frontend automatizado","Gestión de servidores con agentes de IA","Integración con React y Node.js","Interfaz de línea de comandos (CLI) personalizable","Soporte para múltiples servidores","Seguridad y autenticación avanzadas"],"fr":["Conception frontend automatisée","Gestion de serveurs avec des agents d''IA","Intégration avec React et Node.js","Interface de ligne de commande (CLI) personnalisable","Prise en charge de plusieurs serveurs","Sécurité et authentification avancées"],"de":["Automatisiertes Frontend-Design","Server-Verwaltung mit IA-Tools","Integration mit React und Node.js","Anpassbare Kommandozeilen-Schnittstelle (CLI)","Unterstützung für mehrere Server","Erweiterte Sicherheit und Authentifizierung"],"pt":["Gerenciamento de servidores com React","Integração com Python e Node.js","Interface de usuário intuitiva","Gerenciamento de lista de servidores","Suporte a CLI"],"ru":["Управление серверами с помощью React","Интеграция с Python и Node.js","Интуитивно понятный интерфейс пользователя","Управление списком серверов","Поддержка CLI"],"ar":["إدارة الخوادم باستخدام React","التكامل مع Python و Node.js","واجهة مستخدم سهلة الاستخدام","إدارة قائمة الخوادم","دعم CLI"]},"keywords":{"zh":["如何使用AI智能代理","什么是前端设计","Server List Manager替代品","AI智能代理与其他工具的比较","如何安装Server List Manager","Server List Manager设置指南"],"ja":["AIエージェントの使用方法","フロントエンド設計とは","サーバーリストマネージャーの代替品","AIエージェントと他のツールの比較","サーバーリストマネージャーのインストール方法","サーバーリストマネージャーの設定ガイド"],"ko":["AI 에이전트를 사용하는 방법","프론트엔드 디자인 이란","서버 목록 관리자의 대체품","AI 에이전트와 다른 도구의 비교","서버 목록 관리자의 설치 방법","서버 목록 관리자의 설정 가이드"],"es":["cómo usar agentes de IA en frontend","herramientas de diseño frontend","Gestor de Lista de Servidores alternativa","Gestor de Lista de Servidores vs otros","instalación de Gestor de Lista de Servidores","guía de configuración de Gestor de Lista de Servidores","diseño frontend con React","diseño frontend con Node.js"],"fr":["comment utiliser des agents d''IA en frontend","outils de conception frontend","Gestionnaire de Liste de Serveurs alternative","Gestionnaire de Liste de Serveurs vs autres","installation de Gestionnaire de Liste de Serveurs","guide de configuration de Gestionnaire de Liste de Serveurs","conception frontend avec React","conception frontend avec Node.js"],"de":["wie man IA-Tools im Frontend verwendet","Frontend-Design-Tools","Server-Listen-Manager-Alternative","Server-Listen-Manager vs andere","Installation von Server-Listen-Manager","Konfigurationsanleitung für Server-Listen-Manager","Frontend-Design mit React","Frontend-Design mit Node.js"],"pt":["ferramentas de frontend","gerenciador de lista de servidores","react","python","node.js","cli","como usar gerenciador de lista de servidores","o que é gerenciador de lista de servidores","alternativas para gerenciador de lista de servidores"],"ru":["ИИ Агенты","инструменты frontend","менеджер списка серверов","react","python","node.js","cli","как использовать менеджер списка серверов","что такое менеджер списка серверов","альтернативы менеджеру списка серверов"],"ar":["أدوات الويب الأمامي","مدير قائمة الخوادم","react","python","node.js","cli","كيفية استخدام مدير قائمة الخوادم","ما هو مدير قائمة الخوادم","بديلات لمدير قائمة الخوادم"]}},"owner":"vnzzzz","repo":"slim","repoPath":"vnzzzz/slim","stars":0,"forks":0,"updatedAt":"2026-03-05T06:20:06.307Z","topics":[],"category":"community","skillMd":{"name":"frontend-design","description":"Create distinctive, production-grade frontend interfaces with high design quality. Use this skill for UI tasks that build web components, pages, or applications. Generates creative, polished code that avoids generic AI aesthetics.","bodyPreview":"Use this skill to design and implement bold, production-ready frontends when the request involves UI. Combine it with repository UI/UX requirements (`docs/ui/requirements.md`) and existing design systems.\n\n## Design Thinking\n\nBefore coding, lock in a clear, memorable direction:\n- **Purpose**: What problem does the interface solve? Who uses it?\n- **Tone**: Commit to a strong aesthetic (e.g., brutalist/raw, retro-futuristic, editorial/magazine, luxury/refined, playful/toy-like, industrial/utilitar","body":"Use this skill to design and implement bold, production-ready frontends when the request involves UI. Combine it with repository UI/UX requirements (`docs/ui/requirements.md`) and existing design systems.\n\n## Design Thinking\n\nBefore coding, lock in a clear, memorable direction:\n- **Purpose**: What problem does the interface solve? Who uses it?\n- **Tone**: Commit to a strong aesthetic (e.g., brutalist/raw, retro-futuristic, editorial/magazine, luxury/refined, playful/toy-like, industrial/utilitarian). Choose one and execute it precisely.\n- **Constraints**: Framework, performance, accessibility, build tooling.\n- **Differentiation**: What makes this unforgettable? Aim for a single standout idea.\n\nThen build working code (HTML/CSS/JS, React, templ, etc.) that is:\n- Production-grade and functional\n- Visually striking with a cohesive point of view\n- Meticulous in spacing, motion, and detail\n\n## Frontend Aesthetics Guidelines\n\n- **Typography**: Pick characterful, non-default fonts; pair a distinctive display font with a refined body font. Avoid Arial/Inter/Roboto/system defaults.\n- **Color & Theme**: Define a strong palette with CSS variables; prefer decisive dominance + accents over timid mixes.\n- **Motion**: Use meaningful animations (page load, staggered reveals, purposeful hover states). Prefer CSS; keep motion aligned to the chosen aesthetic.\n- **Spatial Composition**: Consider asymmetry, overlap, generous negative space or intentional density. Avoid cookie-cutter layouts.\n- **Background & Details**: Build atmosphere with gradients, meshes, textures, layered transparencies, dramatic shadows, decorative borders, custom cursors, or grain overlays—matching the aesthetic.\n\nAvoid generic AI-looking designs (purple-on-white defaults, predictable layouts, overused fonts, interchangeable components). Each UI should feel intentionally crafted for its context. Match implementation effort to the chosen style: maximalism demands rich effects; minimalism demands precise restraint.\n"},"lastSynced":"2026-03-05T08:45:59.701Z","agentAnalysis":{"suitability":{"en":"Perfect for UI-focused AI Agents needing production-ready frontend design capabilities with repository UI/UX requirements integration.","zh":"非常适合需要生产就绪的前端设计能力并将存储库 UI/UX 要求集成到 UI 集中的 AI 代理。","ja":"UI フォーカス型 AI エージェントに適しており、生産性の高いフロントエンド デザイン機能とリポジトリの UI/UX 要件の統合が可能です。","ko":"UI에 중점을 둔 AI 에이전트에 적합하며 생산 준비가 된 프런트엔드 디자인 기능과 리포지토리 UI/UX 요구 사항 통합을 제공합니다.","es":"Perfecto para agentes de inteligencia artificial centrados en la interfaz de usuario que necesitan capacidades de diseño de frontend listas para la producción con integración de requisitos de interfaz de usuario y experiencia del usuario del repositorio.","fr":"Parfait pour les agents d''intelligence artificielle axés sur l''interface utilisateur nécessitant des capacités de conception de frontend prêtes pour la production avec une intégration des exigences d''interface utilisateur et d''expérience utilisateur du référentiel.","de":"Perfekt für benutzeroberflächenorientierte KI-Agents, die produktionsreife Frontend-Designfunktionen mit Repository-Benutzeroberflächen/-Erfahrungsanforderungen-Integration benötigen.","pt":"Ideal para AI Agents focados em UI que necessitam de capacidades de frontend prontas para produção com integração de requisitos de UI/UX do repositório.","ru":"Идеально подходит для AI Agents, ориентированных на пользовательский интерфейс (UI), которым необходимы готовые к промышленному использованию возможности фронтенда с интеграцией требований к UI/UX из репозитория.","ar":"مثالي لوكلاء الذكاء الاصطناعي التي تركز على واجهة المستخدم (UI) وتحتاج إلى قدرات تصميم واجهة أمامية جاهزة للإنتاج مع دمج متطلبات واجهة المستخدم/تجربة المستخدم (UI/UX) للمستودع."},"recommendation":{"en":"Empowers agents to design bold, memorable interfaces using design thinking principles, combining repository UI/UX requirements with existing design systems, and implementing strong aesthetics like brutalist or luxury designs, all while leveraging protocols and file formats like .svg for seamless UI implementation.","zh":"赋予代理设计大胆、难忘的界面，使用设计思维原则，将存储库 UI/UX 要求与现有的设计系统相结合，并实现强烈的美学效果，如 brutalist 或 luxury 设计，同时利用协议和文件格式如 .svg 实现无缝的 UI 实现。","ja":"デザイン思考の原則に基づいて、リポジトリの UI/UX 要件と既存のデザイン システムを組み合わせ、ブラータリストやラグジュアリー デザインなどの強い美学を実現し、.svg などのプロトコルとファイル形式を利用してシームレスな UI 実装を可能にします。","ko":"대리人が 대담하고 기억에 남는 인터페이스를 설계할 수 있도록 해주는 동시에 디자인 사고 원칙을 사용하여 리포지토리 UI/UX 요구 사항과 기존 디자인 시스템을 결합하고 강한 미학을 구현하며 .svg와 같은 프로토콜 및 파일 형식을 사용하여无缝한 UI 구현을 제공합니다.","es":"Habilita a los agentes a diseñar interfaces memorables y atrevidas utilizando principios de diseño de pensamiento, combinando los requisitos de interfaz de usuario y experiencia del usuario del repositorio con los sistemas de diseño existentes e implementando una estética fuerte como diseños brutales o de lujo, todo mientras aprovecha protocolos y formatos de archivo como .svg para una implementación de interfaz de usuario sin problemas.","fr":"Permet aux agents de concevoir des interfaces audacieuses et mémorables en utilisant des principes de conception de pensée, en combinant les exigences d''interface utilisateur et d''expérience utilisateur du référentiel avec les systèmes de conception existants et en mettant en œuvre une esthétique forte comme des conceptions brutales ou de luxe, le tout en exploitant des protocoles et des formats de fichiers comme .svg pour une mise en œuvre d''interface utilisateur sans problème.","de":"Ermächtigt Agents, mutige, denkwürdige Schnittstellen zu entwerfen, indem sie Design-Denksprüche verwenden, die Repository-Benutzeroberflächen-/Erfahrungsanforderungen mit bestehenden Designsystemen kombinieren und eine starke Ästhetik wie Brutalist- oder Luxusdesigns implementieren, alles unter Ausnutzung von Protokollen und Dateiformaten wie .svg für eine nahtlose Benutzeroberflächenimplementierung.","pt":"Capacita os agentes a projetar interfaces ousadas e memoráveis usando princípios de design thinking, combinando requisitos de UI/UX do repositório com sistemas de design existentes e implementando estéticas fortes como designs brutalistas ou de luxo, tudo enquanto utiliza protocolos e formatos de arquivo como .svg para uma implementação de UI perfeita.","ru":"Позволяет агентам проектировать смелые, запоминающиеся интерфейсы, используя принципы дизайн-мышления, сочетая требования к UI/UX из репозитория с существующими дизайн-системами и реализуя выразительную эстетику, такую как бруталистский или роскошный дизайн, одновременно используя протоколы и форматы файлов, такие как .svg, для беспрепятственной реализации UI.","ar":"يمكن الوكلاء من تصميم واجهات جريئة لا تنسى باستخدام مبادئ التفكير التصميمي، والجمع بين متطلبات واجهة المستخدم/تجربة المستخدم (UI/UX) للمستودع وأنظمة التصميم الحالية، وتنفيذ جماليات قوية مثل التصاميم المتينة أو الفاخرة، كل ذلك مع الاستفادة من البروتوكولات وتنسيقات الملفات مثل .svg لتنفيذ سلس لواجهة المستخدم."},"useCases":{"en":["Designing production-ready frontends for server list managers","Implementing design systems with existing repository UI/UX requirements","Developing interfaces with strong aesthetics for various user personas"],"zh":["为服务器列表管理器设计生产就绪的前端","将设计系统与现有的存储库 UI/UX 要求集成","为各种用户角色开发具有强烈美学的界面"],"ja":["サーバー リスト マネージャー用の生産性の高いフロントエンドを設計する","既存のリポジトリ UI/UX 要件とデザイン システムを統合する","さまざまなユーザー役割用の強い美学を持つインターフェイスを開発する"],"ko":["서버 목록 관리자를 위한 생산 준비가 된 프런트엔드를 설계합니다.","기존의 리포지토리 UI/UX 요구 사항과 디자인 시스템을 통합합니다.","다양한 사용자 역할을 위한 강한 미학을 갖춘 인터페이스를 개발합니다."],"es":["Diseñar frontends listos para la producción para administradores de lista de servidores","Implementar sistemas de diseño con requisitos de interfaz de usuario y experiencia del usuario existentes del repositorio","Desarrollar interfaces con una estética fuerte para varios perfiles de usuario"],"fr":["Concevoir des frontends prêts pour la production pour les gestionnaires de liste de serveurs","Mettre en œuvre des systèmes de conception avec les exigences d''interface utilisateur et d''expérience utilisateur existantes du référentiel","Développer des interfaces avec une esthétique forte pour différents profils d''utilisateur"],"de":["Produktionsreife Frontends für Serverlisten-Manager entwerfen","Designsysteme mit bestehenden Repository-Benutzeroberflächen-/Erfahrungsanforderungen implementieren","Schnittstellen mit starker Ästhetik für verschiedene Benutzerprofile entwickeln"],"pt":["Projetar frontends prontos para produção para gerenciadores de lista de servidores","Implementar sistemas de design com requisitos de UI/UX existentes do repositório","Desenvolver interfaces com estéticas fortes para várias personas de usuário"],"ru":["Проектирование готовых к промышленному использованию фронтендов для менеджеров списков серверов","Внедрение дизайн-систем с существующими требованиями к UI/UX из репозитория","Разработка интерфейсов с выразительной эстетикой для различных пользовательских персон"],"ar":["تصميم واجهات أمامية جاهزة للإنتاج لمديري قوائم الخوادم","تنفيذ أنظمة تصميم مع متطلبات واجهة المستخدم/تجربة المستخدم (UI/UX) الحالية للمستودع","تطوير واجهات بجماليات قوية لشخصيات مستخدمين مختلفة"]},"limitations":{"en":["Requires existing repository UI/UX requirements documentation","Needs design system integration for consistency","Limited to frontend design, not backend development"],"zh":["需要现有的存储库 UI/UX 要求文档","需要设计系统集成以保证一致性","仅限于前端设计，不适用于后端开发"],"ja":["既存のリポジトリ UI/UX 要件のドキュメントが必要","一貫性を保つためにデザイン システムの統合が必要","フロントエンド デザインのみに限定され、バックエンド開発には不適"],"ko":["기존의 리포지토리 UI/UX 요구 사항 문서가 필요합니다.","일관성을 유지하기 위해 디자인 시스템 통합이 필요합니다.","프런트엔드 디자인만으로 제한되며, 백엔드 개발에는 적합하지 않습니다."],"es":["Requiere documentación existente de requisitos de interfaz de usuario y experiencia del usuario del repositorio","Necesita integración del sistema de diseño para la coherencia","Limitado al diseño de frontend, no al desarrollo de backend"],"fr":["Nécessite une documentation existante des exigences d''interface utilisateur et d''expérience utilisateur du référentiel","A besoin d''une intégration du système de conception pour la cohérence","Limité à la conception de frontend, pas au développement de backend"],"de":["Benötigt bestehende Dokumentation von Repository-Benutzeroberflächen-/Erfahrungsanforderungen","Benötigt Designsystem-Integration für Konsistenz","Begrenzt auf Frontend-Design, nicht auf Backend-Entwicklung"],"pt":["Requer documentação existente de requisitos de UI/UX do repositório","Necessita de integração com sistema de design para consistência","Limitado ao design de frontend, não ao desenvolvimento de backend"],"ru":["Требует наличия документации по требованиям к UI/UX из репозитория","Требует интеграции с дизайн-системой для обеспечения согласованности","Ограничено дизайном фронтенда, а не разработкой бэкенда"],"ar":["يتطلب وجود وثائق متطلبات واجهة المستخدم/تجربة المستخدم (UI/UX) الحالية للمستودع","يحتاج إلى دمج نظام التصميم لتحقيق الاتساق","يقتصر على تصميم الواجهة الأمامية، وليس تطوير الواجهة الخلفية"]},"version":3},"contentHash":"772a4afebd986c3350b4c9e816164cbf7445e84a899644e976cda0b8f1180454","qualityScore":21}');
