INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vnzzzz/slim/frontend-design', 'frontend-design', 'vnzzzz', 'slim', 'community', 'frontend-design vnzzzz slim community Server List Manager是AI智能代理前端设计的一部分，用于管理服务器列表 サーバーリストマネージャーはAIエージェントのフロントエンド設計の一部であり、サーバーリストを管理するために使用される 서버 목록 관리자는 AI 에이전트 프론트엔드 디자인의 일부로서 서버 목록을 관리하는 데 사용된다 El Gestor de Lista de Servidores es una herramienta de diseño frontend que utiliza agentes de IA para automatizar tareas Le Gestionnaire de Liste de Serveurs est un outil de conception frontend qui utilise des agents d''IA pour automatiser des tâches Der Server-Listen-Manager ist ein Frontend-Design-Tool, das IA-Tools verwendet, um Aufgaben zu automatisieren O Gerenciador de Lista de Servidores é uma ferramenta de frontend que ajuda a gerenciar servidores com eficiência. Desenvolvida com React, Python e Node.js Менеджер Списка Серверов - это инструмент frontend, который помогает эффективно управлять серверами. Разработан с использованием React, Python и Node.js مدير قائمة الخوادم هو أداة ويب أمامي تساعد في إدارة الخوادم بفعالية. تم تطويره باستخدام React و Python و Node.js Server List Manager 如何使用AI智能代理 什么是前端设计 Server List Manager替代品 AI智能代理与其他工具的比较 如何安装Server List Manager Server List Manager设置指南 Server List Manager');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('GGPrompts/htmlstyleguides/story', 'community', 'GGPrompts', 'htmlstyleguides', 'GGPrompts/htmlstyleguides', 'story', 9, 3, 20, '2026-03-07T00:13:05Z', '2026-03-07T01:51:21.833Z', '1b481c16c1333f754556325a2eacc35498af70318ff6c169c6c20b36dec6b13d', '{"id":"GGPrompts/htmlstyleguides/story","name":"story","description":{"en":"The Story skill generates interactive educational stories using $ARGUMENTS, with self-contained HTML, inline CSS/JS, and keyboard navigation. Benefiting developers and educators, it creates immersive experiences.","zh":"Story AI工具允许开发者创建交互式教育故事，使用自包含HTML、内联CSS/JS和键盘导航。通过解析参数和阅读样式指南目录，开发者可以创建具有分支点和多个结尾的自定义故事","ja":"AIエージェントStoryは、開発者が自包含HTML、インラインCSS/JS、キーボードナビゲーションを使用してインタラクティブな教育ストーリーを作成できるようにします。パラメータを解析し、スタイルガイドカタログを読むことで、開発者は分岐点や複数の終了点を持つカスタムストーリーを作成できます","ko":"Story AI 도구를 사용하면 개발자가 자체 포함 HTML, 인라인 CSS/JS 및 키보드 탐색을 사용하여 인터랙티브 교육 스토리를 생성할 수 있습니다. 매개 변수를 분석하고 스타일 가이드 카탈로그를 읽음으로써 개발자는 분기점 및 여러 종결점을 갖는 사용자 지정 스토리를 생성할 수 있습니다","es":"El skill de historia permite crear historias interactivas educativas con estilo personalizable y sin dependencias.","fr":"Le skill d''histoire permet de créer des histoires interactives éducatives avec style personnalisable et sans dépendances.","de":"Das Story-Skill ermöglicht die Erstellung interaktiver Bildungsgeschichten mit anpassbarem Stil und ohne Abhängigkeiten.","pt":"Crie histórias interativas com até 15 cenas, 5 pontos de ramificação e 3 finais, usando HTML autossuficiente com CSS/JS embutidos","ru":"Создайте интерактивные истории с 10-15 сценами, 3-5 точками ветвления и 2-3 концовками, используя самодостаточный HTML с inline CSS/JS","ar":"أنشئ قصصًا تفاعلية مع 10-15 مشهدًا و 3-5 نقطة فرع و 2-3 نهايات، باستخدام HTML مستقل مع CSS/JS مدمجة"},"seo":{"title":{"en":"Story: Interactive HTML Story Guide for AI Agents","zh":"AI工具Story设置指南：创建交互式教育故事","ja":"AIエージェントStoryのベストプラクティス：インタラクティブな教育ストーリーの構築","ko":"AI 도구 Story 설정 가이드: 인터랙티브 교육 스토리 만들기","es":"Guía de configuración de historias interactivas con estil...","fr":"Guide de mise en place d''histoires interactives avec styl...","de":"Einrichtungsleitfaden für interaktive Geschichten mit anp...","pt":"Guia de Configuração de Histórias Interativas com Ferrame...","ru":"Настройка Интерактивных Историй с ИИ Агентами","ar":"دليل إعداد القصص التفاعلية مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create self-contained HTML stories with inline CSS/JS and keyboard navigation. Get started with Story AI Agent Skill today!","zh":"使用Story AI工具创建交互式教育故事，了解自包含HTML、内联CSS/JS和键盘导航的技术细节","ja":"AIエージェントStoryを使用してインタラクティブな教育ストーリーを作成する方法、自包含HTML、インラインCSS/JS、キーボードナビゲーションについて学ぶ","ko":"Story AI 도구를 사용하여 인터랙티브 교육 스토리를 생성하고, 자체 포함 HTML, 인라인 CSS/JS 및 키보드 탐색에 대한 기술 세부 정보를 확인","es":"Crea historias educativas interactivas con estilo personalizable y sin dependencias. Copia y personaliza para crear experiencias únicas.","fr":"Créez des histoires éducatives interactives avec style personnalisable et sans dépendances. Copiez et personnalisez pour créer des expériences uniques.","de":"Erstellen Sie interaktive Bildungsgeschichten mit anpassbarem Stil und ohne Abhängigkeiten. Kopieren und anpassen, um einzigartige Erfahrungen zu schaffen.","pt":"Aprenda a criar histórias interativas autossuficientes em HTML com CSS/JS embutidos e navegação por teclado","ru":"Изучите создание интерактивных историй с inline CSS/JS и клавиатурной навигацией с помощью ИИ Агентов","ar":"تعلم كيفية إنشاء قصص تفاعلية自وCONTAINING HTML مع CSS/JS مدمجة وتجوال لوحة المفاتيح مع أدوات الذكاء الاصطناعي"},"definition":{"en":"Story is a self-contained HTML style guide for creating interactive educational stories with inline CSS/JS, keyboard navigation, and branching points.","zh":"Story AI工具是一种用于创建交互式教育故事的技术，使用自包含HTML、内联CSS/JS和键盘导航","ja":"AIエージェントStoryは、自包含HTML、インラインCSS/JS、キーボードナビゲーションを使用してインタラクティブな教育ストーリーを作成する技術です","ko":"Story AI 도구는 자체 포함 HTML, 인라인 CSS/JS 및 키보드 탐색을 사용하여 인터랙티브 교육 스토리를 생성하는 기술입니다","es":"Un skill de historia es una guía de estilo autocontenida en HTML para crear historias interactivas educativas.","fr":"Un skill d''histoire est une guide de style autocontenue en HTML pour créer des histoires interactives éducatives.","de":"Ein Story-Skill ist eine selbstenthaltene HTML-Stilguide für die Erstellung interaktiver Bildungsgeschichten.","pt":"Uma história interativa é um recurso de narrativa que permite ao usuário influenciar o curso da história","ru":"Интерактивная история - это функция повествования, позволяющая пользователю влиять на ход истории","ar":"القصة التفاعلية هي ميزة سرد تسمح للمستخدم بالتأثير على مسار القصة"},"features":{"en":["Generates interactive stories with 10-15 scenes and 3-5 branching points","Supports keyboard navigation using 1-9 keys","Creates self-contained HTML with inline CSS/JS","Follows conventions outlined in stories/CLAUDE.md","Parses arguments for style name and topic hints"],"zh":["自包含HTML","内联CSS/JS","键盘导航","分支点","多个结尾","参数解析"],"ja":["自包含HTML","インラインCSS/JS","キーボードナビゲーション","分岐点","複数の終了点","パラメータ解析"],"ko":["자체 포함 HTML","인라인 CSS/JS","키보드 탐색","분기점","여러 종결점","매개 변수 분석"],"es":["Estilo personalizable con CSS/JS integrados","Navegación por teclado con claves 1-9","Puntos de ramificación para historias interactivas","Sin dependencias para una implementación fácil","Compatibilidad con 10-15 escenas y 2-3 finales"],"fr":["Style personnalisable avec CSS/JS intégrés","Navigation au clavier avec les touches 1-9","Points de branchement pour des histoires interactives","Sans dépendances pour une mise en œuvre facile","Compatibilité avec 10-15 scènes et 2-3 fins"],"de":["Anpassbarer Stil mit integriertem CSS/JS","Tastaturnavigation mit den Tasten 1-9","Verzweigungspunkte für interaktive Geschichten","Ohne Abhängigkeiten für eine einfache Implementierung","Kompatibilität mit 10-15 Szenen und 2-3 Enden"],"pt":["HTML autossuficiente com CSS/JS embutidos","Navegação por teclado com 1-9 teclas","Até 15 cenas e 5 pontos de ramificação","3 finais personalizáveis","Suporte a estilos personalizados"],"ru":["Самодостаточный HTML с inline CSS/JS","Клавиатурная навигация с 1-9 клавишами","До 15 сцен и 5 точек ветвления","3 настраиваемых концовки","Поддержка пользовательских стилей"],"ar":["HTML مستقل مع CSS/JS مدمجة","تجوال لوحة المفاتيح مع 1-9 مفاتيح","حتى 15 مشهدًا و 5 نقاط فرع","3 نهايات قابلة للتعديل","دعم أسلوب مخصص"]},"keywords":{"en":["how to use story AI agent","what is story skill","story alternative to traditional learning","story vs interactive simulations","story install guide","story setup for AI agents","creating interactive stories with HTML","story skill for educational content"],"zh":["AI工具","交互式教育故事","自包含HTML","内联CSS/JS","键盘导航","分支点","多个结尾","参数解析","Story AI工具"],"ja":["AIエージェント","インタラクティブな教育ストーリー","自包含HTML","インラインCSS/JS","キーボードナビゲーション","分岐点","複数の終了点","パラメータ解析","AIエージェントStory"],"ko":["AI 도구","인터랙티브 교육 스토리","자체 포함 HTML","인라인 CSS/JS","키보드 탐색","분기점","여러 종결점","매개 변수 분석","AI 도구 Story"],"es":["historias interactivas","estilo personalizable","sin dependencias","navegación por teclado","puntos de ramificación","educación interactiva","Herramientas de IA para educación","Agentes de IA para aprendizaje"],"fr":["histoires interactives","style personnalisable","sans dépendances","navigation au clavier","points de branchement","éducation interactive","Outils d''IA pour l''éducation","Agents d''IA pour l''apprentissage"],"de":["interaktive Geschichten","anpassbarer Stil","ohne Abhängigkeiten","Tastaturnavigation","Verzweigungspunkte","interaktives Lernen","KI-Tools für Bildung","KI-Agenten für Lernen"],"pt":["histórias interativas","ferramentas de IA","HTML autossuficiente","CSS/JS embutidos","navegação por teclado","estilos personalizados","desenvolvimento web interativo"],"ru":["интерактивные истории","ИИ Агенты","самодостаточный HTML","inline CSS/JS","клавиатурная навигация","пользовательские стили","интерактивное веб-разработка"],"ar":["قصص تفاعلية","أدوات الذكاء الاصطناعي","HTML مستقل","CSS/JS مدمجة","تجوال لوحة المفاتيح","أسلوب مخصص","تطوير ويب تفاعلي"]}},"owner":"GGPrompts","repo":"htmlstyleguides","repoPath":"GGPrompts/htmlstyleguides","stars":9,"forks":3,"updatedAt":"2026-03-07T00:13:05Z","topics":[],"category":"community","skillMd":{"name":"story","description":"Build an interactive educational story with a style guide aesthetic","bodyPreview":"# Build an Interactive Story\n\nCreate an interactive educational story using **$ARGUMENTS**.\n\nFollow the full conventions in `stories/CLAUDE.md`. The story must be self-contained HTML with inline CSS/JS, 10-15 scenes, 3-5 branching points, 2-3 endings, and keyboard navigation (1-9 keys).\n\n## Phase 0 — Plan (interactive)\n\n1. Parse the argument: first word is the style name, optional remaining words hint at the topic.\n2. Read the **Style Guide Catalog** table in `README.md` to confirm the style is","body":"# Build an Interactive Story\n\nCreate an interactive educational story using **$ARGUMENTS**.\n\nFollow the full conventions in `stories/CLAUDE.md`. The story must be self-contained HTML with inline CSS/JS, 10-15 scenes, 3-5 branching points, 2-3 endings, and keyboard navigation (1-9 keys).\n\n## Phase 0 — Plan (interactive)\n\n1. Parse the argument: first word is the style name, optional remaining words hint at the topic.\n2. Read the **Style Guide Catalog** table in `README.md` to confirm the style is available (empty Story column) and see what''s already taken.\n3. Read the chosen style''s HTML file from `styles/{name}.html` to extract the design system.\n4. Read `stories/CLAUDE.md` for the template and conventions.\n4. Read 1 existing story to match structure — skim for the STORY data format, engine pattern, and component mapping.\n5. If no topic was given:\n   - Research the style''s cultural/historical period\n   - Propose 2-3 story concepts that thematically match the aesthetic\n   - Ask the user to pick one\n6. Propose the story arc: title, setting, 10-15 scene outline with branching diagram, key historical facts, and how style components map to narrative functions (e.g., \"cards = case files\", \"alerts = discoveries\").\n7. Discuss with the user before proceeding.\n\n## Phase 1 — Research (parallel Sonnet subagents)\n\nLaunch 2-3 **sonnet** subagents in parallel to research:\n- **Historical facts**: Real names, dates, numbers, events for the chosen topic. Need 8-12 concrete facts.\n- **Cultural context**: Period details, atmosphere, vocabulary appropriate to the era.\n- **Style component mapping**: How to repurpose the style guide''s CSS classes for narrative elements.\n\nEach subagent returns structured research notes.\n\n## Phase 2 — Build (sequential Opus subagents)\n\nUse 3-4 sequential **opus** subagents:\n\n1. **First agent**: Create the full HTML file with adapted CSS, title screen with back-to-stories link, scene wrapper structure, and the story engine JavaScript. Write the first 5 scenes of the STORY object. Include CSS for scene types (narration, investigation, confrontation, ending).\n2. **Second agent**: Read the file, add scenes 6-10 (or remaining scenes). Ensure branching points connect correctly.\n3. **Third agent**: Read the file, add remaining scenes and endings. Verify all `next` values point to defined scenes. Ensure every scene has a `fact` property. Test that no orphan scenes exist.\n4. **Fourth agent (polish)**: Read complete file. Verify scene graph integrity (no dead ends, no orphans), keyboard navigation works, clue tracker collects facts, all historical content is accurate.\n\n**Critical rules for build agents:**\n- Each agent MUST read the current file before writing\n- All `next` values in choices must reference existing scene IDs in the STORY object\n- Every scene needs: `year`, `era`, `content`, `fact`, `choices`\n- Endings should offer \"Play Again\" (next: ''intro'') and \"Back to Stories\" (next: ''_exit'')\n- Back-to-stories link on title screen: `<a href=\"index.html\">`\n\n## Phase 3 — Brief & Index\n\n1. Write a research brief to `stories/briefs/{style-name}-brief.md` documenting the historical facts, story arc, and component mapping.\n2. Read `stories/index.html` to understand the card format.\n3. Add a card for the new story with: scene count, ending count, style name, title, description.\n4. Update the **Style Guide Catalog** table in `README.md` — add the story title in the Story column for the chosen style.\n5. Commit with message: `Add {title} interactive story ({style-name} style)`\n6. Push using: `git config --global credential.helper store && echo \"https://GGPrompts:$(gh auth token --user GGPrompts)@github.com\" > ~/.git-credentials && git push origin main`\n"},"lastSynced":"2026-03-07T01:51:21.833Z","agentAnalysis":{"suitability":{"en":"Perfect for Educational Agents needing interactive HTML content generation with inline CSS/JS and keyboard navigation.","zh":"非常适合需要交互式HTML内容生成、内联CSS/JS和键盘导航的教育代理。","ja":"教育エージェントがインタラクティブなHTMLコンテンツを生成し、インラインCSS/JSとキーボードナビゲーションを使用する必要がある場合に最適です。","ko":"교育 에이전트가 대화형 HTML 콘텐츠 생성, 인라인 CSS/JS 및 키보드 탐색이 필요한 경우에 적합합니다.","es":"Perfecto para Agentes Educativos que necesitan generar contenido HTML interactivo con CSS/JS en línea y navegación por teclado.","fr":"Parfait pour les Agents Éducatifs ayant besoin de générer du contenu HTML interactif avec du CSS/JS en ligne et une navigation au clavier.","de":"Perfekt für Bildungsagenten, die interaktiven HTML-Inhalt mit inline-CSS/JS und Tastaturnavigation benötigen.","pt":"Perfeito para Agentes Educacionais que necessitam de geração de conteúdo HTML interativo com CSS/JS em linha e navegação por teclado.","ru":"Идеально подходит для образовательных агентов, которым требуется генерация интерактивного контента HTML с встроенным CSS/JS и навигацией с помощью клавиатуры.","ar":"مثالي للوكلاء التعليميين الذين يحتاجون إلى توليد محتوى HTML تفاعلي مع CSS/JS داخل النص وتنقل لوحة المفاتيح."},"recommendation":{"en":"Empowers agents to create immersive educational experiences with self-contained HTML, utilizing inline CSS/JS for styling and interactivity, and enabling keyboard navigation for seamless user interaction.","zh":"赋予代理创建沉浸式教育体验的能力，使用自包含的HTML，内联CSS/JS进行样式和交互，并启用键盘导航以实现无缝的用户交互。","ja":"エージェントが自己包含されたHTMLを使用して、インラインCSS/JSによるスタイリングとインタラクティブ性、およびシームレスなユーザーインタラクションを可能にするキーボードナビゲーションで、没入感のある教育体験を作成する能力を提供します。","ko":"에이전트가 자체 포함 HTML을 사용하여 인라인 CSS/JS를 통한 스타일링 및 상호 작용과無斷な 사용자 상호 작용을 가능하게 하는 키보드 탐색으로沒入感 있는 교육 경험을 만들 수 있는 능력을 부여합니다.","es":"Permite a los agentes crear experiencias educativas inmersivas con HTML autocontenido, utilizando CSS/JS en línea para el estilo y la interactividad, y habilitando la navegación por teclado para una interacción del usuario sin problemas.","fr":"Permet aux agents de créer des expériences éducatives immersives avec un HTML auto-contenu, en utilisant du CSS/JS en ligne pour le style et l''interactivité, et en activant la navigation au clavier pour une interaction utilisateur fluide.","de":"Ermöglicht es Agenten, immersive Bildungserlebnisse mit selbstenthaltenem HTML zu erstellen, indem sie inline-CSS/JS für Stil und Interaktivität nutzen und die Tastaturnavigation für eine nahtlose Benutzerinteraktion aktivieren.","pt":"Habilita os agentes a criar experiências educacionais imersivas com HTML autocontido, utilizando CSS/JS em linha para estilização e interatividade, e permitindo a navegação por teclado para interação do usuário sem interrupção.","ru":"Позволяет агентам создавать погружающие образовательные trải nghiệm с自одостаточным HTML, используя встроенный CSS/JS для стилизации и интерактивности, и обеспечивающий навигацию с помощью клавиатуры для беспрепятственной взаимодействия пользователя.","ar":"يمنح الوكلاء khảية إنشاء تجارب تعليمية غامرة مع HTML مستقل، مستخدمين CSS/JS داخل النص لتحسين المظهر والتفاعل، وتمكين التنقل بلوحة المفاتيح لتفاعل المستخدم دون انقطاع."},"useCases":{"en":["Generating interactive educational stories with branching points and multiple endings","Creating immersive experiences with inline CSS/JS and keyboard navigation","Developing interactive content for educational platforms with self-contained HTML"],"zh":["生成具有分支点和多个结尾的交互式教育故事","使用内联CSS/JS和键盘导航创建沉浸式体验","为教育平台开发自包含HTML的交互式内容"],"ja":["分岐ポイントと複数のエンディングを備えたインタラクティブな教育ストーリーを生成する","インラインCSS/JSとキーボードナビゲーションを使用して没入感のある体験を作成する","教育プラットフォーム用の自己包含されたHTMLのインタラクティブなコンテンツを開発する"],"ko":["분기점과 여러개의 결말을 가진 대화형 교육 이야기를 생성","인라인 CSS/JS 및 키보드 탐색을 사용하여沒入感 있는 경험을 만들기","교육 플랫폼을 위한 자체 포함 HTML의 대화형 콘텐츠를 개발"],"es":["Generar historias educativas interactivas con puntos de ramificación y múltiples finales","Crear experiencias inmersivas con CSS/JS en línea y navegación por teclado","Desarrollar contenido interactivo para plataformas educativas con HTML autocontenido"],"fr":["Générer des histoires éducatives interactives avec des points de branchement et plusieurs fins","Créer des expériences immersives avec du CSS/JS en ligne et une navigation au clavier","Développer du contenu interactif pour les plateformes éducatives avec un HTML auto-contenu"],"de":["Interaktive Bildungsgeschichten mit Verzweigungspunkten und mehreren Enden generieren","Immersive Erfahrungen mit inline-CSS/JS und Tastaturnavigation erstellen","Interaktiven Inhalt für Bildungsplattformen mit selbstenthaltenem HTML entwickeln"],"pt":["Geração de histórias educacionais interativas com pontos de ramificação e múltiplos finais","Criação de experiências imersivas com CSS/JS em linha e navegação por teclado","Desenvolvimento de conteúdo interativo para plataformas educacionais com HTML autocontido"],"ru":["Генерация интерактивных образовательных историй с точками ветвления и несколькими концовками","Создание погружающих trải nghiệm с встроенным CSS/JS и навигацией с помощью клавиатуры","Разработка интерактивного контента для образовательных платформ с自одостаточным HTML"],"ar":["توليد قصص تعليمية تفاعلية مع نقاط انعطاف ونهايات متعددة","إنشاء تجارب غامرة مع CSS/JS داخل النص وتنقل لوحة المفاتيح","تطوير محتوى تفاعلي من أجل منصات تعليمية مع HTML مستقل"]},"limitations":{"en":["Requires adherence to specific story conventions outlined in stories/CLAUDE.md","Limited to 10-15 scenes, 3-5 branching points, and 2-3 endings per story","Keyboard navigation limited to 1-9 keys"],"zh":["需要遵守stories/CLAUDE.md中概述的特定故事约定","每个故事最多限制为10-15个场景，3-5个分支点和2-3个结尾","键盘导航仅限于1-9键"],"ja":["stories/CLAUDE.mdに概説されている特定のストーリー規約に従う必要がある","各ストーリーは10〜15のシーン、3〜5の分岐ポイント、2〜3のエンディングに制限される","キーボードナビゲーションは1〜9キーのみに制限される"],"ko":["stories/CLAUDE.md에概説되어 있는 특정한 스토리 규약을 따르는 것이 필요","각각의 스토리는 10〜15개의 씬, 3〜5개의 분기점, 2〜3개의 결말로 제한된다","키보드 탐색은 1〜9키로만 제한된다"],"es":["Requiere adherirse a convenciones de historia específicas descritas en stories/CLAUDE.md","Limitado a 10-15 escenas, 3-5 puntos de ramificación y 2-3 finales por historia","La navegación por teclado está limitada a las teclas 1-9"],"fr":["Nécessite de se conformer à des conventions d''histoire spécifiques décrites dans stories/CLAUDE.md","Limité à 10-15 scènes, 3-5 points de branchement et 2-3 fins par histoire","La navigation au clavier est limitée aux touches 1-9"],"de":["Erfordert die Einhaltung spezifischer in stories/CLAUDE.md beschriebener Geschichtenskonventionen","Begrenzt auf 10-15 Szenen, 3-5 Verzweigungspunkte und 2-3 Enden pro Geschichte","Die Tastaturnavigation ist auf die Tasten 1-9 beschränkt"],"pt":["Exige adesão a convenções de história específicas delineadas em stories/CLAUDE.md","Limitado a 10-15 cenas, 3-5 pontos de ramificação e 2-3 finais por história","Navegação por teclado limitada às teclas 1-9"],"ru":["Требует соблюдения определенных условий истории, изложенных в stories/CLAUDE.md","Ограничен 10-15 сценами, 3-5 точками ветвления и 2-3 концовками на историю","Навигация с помощью клавиатуры ограничена клавишами 1-9"],"ar":["يتطلب اتباع اتفاقيات قصة محددة مخططة في stories/CLAUDE.md","محدود بـ 10-15 مشهد، 3-5 نقاط انعطاف و 2-3 نهاية لكل قصة","تنقل لوحة المفاتيح مقيد بأزرار 1-9"]},"version":4},"contentHash":"1b481c16c1333f754556325a2eacc35498af70318ff6c169c6c20b36dec6b13d","qualityScore":20}');
