INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('GGPrompts/htmlstyleguides/story', 'story', 'GGPrompts', 'htmlstyleguides', 'community', 'story GGPrompts htmlstyleguides community The Story skill generates interactive educational stories using $ARGUMENTS, with self-contained HTML, inline CSS/JS, and keyboard navigation. Benefiting developers and educators, it creates immersive experiences. Story AI工具允许开发者创建交互式教育故事，使用自包含HTML、内联CSS/JS和键盘导航。通过解析参数和阅读样式指南目录，开发者可以创建具有分支点和多个结尾的自定义故事 AIエージェントStoryは、開発者が自包含HTML、インラインCSS/JS、キーボードナビゲーションを使用してインタラクティブな教育ストーリーを作成できるようにします。パラメータを解析し、スタイルガイドカタログを読むことで、開発者は分岐点や複数の終了点を持つカスタムストーリーを作成できます Story AI 도구를 사용하면 개발자가 자체 포함 HTML, 인라인 CSS/JS 및 키보드 탐색을 사용하여 인터랙티브 교육 스토리를 생성할 수 있습니다. 매개 변수를 분석하고 스타일 가이드 카탈로그를 읽음으로써 개발자는 분기점 및 여러 종결점을 갖는 사용자 지정 스토리를 생성할 수 있습니다 El skill de historia permite crear historias interactivas educativas con estilo personalizable y sin dependencias. Le skill d''histoire permet de créer des histoires interactives éducatives avec style personnalisable et sans dépendances. Das Story-Skill ermöglicht die Erstellung interaktiver Bildungsgeschichten mit anpassbarem Stil und ohne Abhängigkeiten. Crie histórias interativas com até 15 cenas, 5 pontos de ramificação e 3 finais, usando HTML autossuficiente com CSS/JS embutidos Создайте интерактивные истории с 10-15 сценами, 3-5 точками ветвления и 2-3 концовками, используя самодостаточный HTML с inline CSS/JS أنشئ قصصًا تفاعلية مع 10-15 مشهدًا و 3-5 نقطة فرع و 2-3 نهايات، باستخدام HTML مستقل مع CSS/JS مدمجة how to use story AI agent what is story skill story alternative to traditional learning story vs interactive simulations story install guide story setup for AI agents creating interactive stories with HTML story skill for educational content AI工具 交互式教育故事 自包含HTML 内联CSS/JS 键盘导航 分支点 多个结尾 参数解析 Story AI工具 Generates interactive stories with 10-15 scenes and 3-5 branching points Supports keyboard navigation using 1-9 keys Creates self-contained HTML with inline CSS/JS Follows conventions outlined in stories/CLAUDE.md Parses arguments for style name and topic hints Story is a self-contained HTML style guide for creating interactive educational stories with inline CSS/JS, keyboard navigation, and branching points.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('janekbaraniewski/openusage/review-design', 'community', 'janekbaraniewski', 'openusage', 'janekbaraniewski/openusage', 'review-design', 8, 0, 20, '2026-02-28T00:55:36Z', '2026-03-06T06:49:20.589Z', '21ad03e1cd4456763ff5de1ab8c5d9b72f0226f290e81d050c4aebb34c6ef438', '{"id":"janekbaraniewski/openusage/review-design","name":"review-design","description":{"en":"The review-design skill enables developers to track spend and usage across various AI tools, including Claude, Cursor, and Codex. It helps developers monitor their AI usage and optimize their workflow.","zh":"Review Design 是一种技术，用于跟踪和管理 AI 工具的使用情况，包括 Claude、Cursor 和 Copilot","ja":"Review Design は、AIエージェントの使用状況を追跡し、コストを最適化するための技術です","ko":"Review Design은 Claude, Cursor, Copilot의 사용량을 모니터링하고 최적화하는 기술입니다","es":"Review Design es una habilidad que permite a los desarrolladores revisar documentos de diseño contra la base de código","fr":"Review Design est une compétence qui permet aux développeurs de réviser les documents de conception contre la base de code","de":"Review Design ist eine Fähigkeit, die es Entwicklern ermöglicht, Design-Dokumente gegen die Codebasis zu überprüfen","pt":"O Review Design é uma ferramenta que ajuda a otimizar o código, permitindo que os desenvolvedores revisem e aprimorem suas soluções com agentes de IA como Claude e Codex.","ru":"Review Design - это инструмент, который помогает оптимизировать код, позволяя разработчикам просматривать и совершенствовать свои решения с помощью ИИ Агентов, таких как Claude и Codex.","ar":"مراجعة التصميم هي أداة تساعد في تحسين الكود، مما يسمح للمطورين بمراجعة وتحسين حلولهم مع وكلاء الذكاء الاصطناعي مثل Claude و Codex."},"seo":{"title":{"en":"Review Design: AI-Powered Code Review Setup Guide | AI Ag...","zh":"Review Design 设置指南 - 跟踪 Claude、Cursor 和 Copilot 的使用情况","ja":"Review Design のベストプラクティス - AIエージェントの使用状況を追跡","ko":"Review Design 설정 가이드 - Claude, Cursor, Copilot 사용량 모니터링","es":"Guía de Configuración de Review Design para Agentes de IA","fr":"Guide de Mise en Place de Review Design pour les Agents IA","de":"Einrichtungsleitfaden für Review Design für KI-Agenten","pt":"Guia de Configuração do Review Design: Otimizando o Códig...","ru":"Настройка Инструментов ИИ: Review Design для Оптимизации ...","ar":"دليل إعداد مراجعة التصميم: تحسين الكود باستخدام Claude و ..."},"description":{"en":"Unlock efficient code review with review-design. Discover how to track spend and usage across AI tools like Claude, Copilot, and Codex. Get started now!","zh":"了解 Review Design 技术，跟踪和管理 AI 工具的使用情况，包括 Claude、Cursor 和 Copilot","ja":"Review Design を使用して AIエージェントの使用状況を追跡し、コストを最適化する方法を学ぶ","ko":"Review Design을 사용하여 Claude, Cursor, Copilot의 사용량을 모니터링하고 최적화하는 방법","es":"Aprende a configurar Review Design para rastrear el uso y gastos de Claude, Cursor, OpenRouter y más","fr":"Découvrez comment configurer Review Design pour suivre l''utilisation et les dépenses de Claude, Cursor, OpenRouter et plus","de":"Erfahren Sie, wie Sie Review Design konfigurieren, um die Nutzung und Ausgaben von Claude, Cursor, OpenRouter und mehr zu verfolgen","pt":"Aprenda a configurar o Review Design para otimizar seu código com Claude, Codex e outros agentes de IA. Melhore a eficiência do seu desenvolvimento com nossa...","ru":"Узнайте, как настроить Review Design для оптимизации вашего кода с помощью ИИ Агентов, таких как Claude, Codex и другие. Улучшите эффективность вашего развит...","ar":"تعرف على كيفية إعداد مراجعة التصميم لتحسين كودك باستخدام وكلاء الذكاء الاصطناعي مثل Claude و Codex وغيرهم. تحسين كفاءة تطويرك مع دليلنا العملي."},"definition":{"en":"review-design is a skill that allows developers to review design documents against their codebase, supporting tools like Claude, Copilot, and Gemini.","zh":"Review Design 是一种技术，用于跟踪和管理 AI 工具的使用情况","ja":"Review Design は、AIエージェントの使用状況を追跡するための技術です","ko":"Review Design은 AI 도구의 사용량을 모니터링하는 기술입니다","es":"Review Design es una habilidad de agente de IA que verifica la coherencia entre el diseño y la implementación","fr":"Review Design est une compétence d''agent IA qui vérifie la cohérence entre la conception et la mise en œuvre","de":"Review Design ist eine Fähigkeit von KI-Agenten, die die Konsistenz zwischen Design und Implementierung überprüft","pt":"O que é Review Design? É uma ferramenta de revisão de código que ajuda a otimizar soluções de desenvolvimento com agentes de IA.","ru":"Что такое Review Design? Это инструмент ревью кода, который помогает оптимизировать решения разработки с помощью ИИ Агентов.","ar":"ما هي مراجعة التصميم؟ هي أداة مراجعة الكود التي تساعد في تحسين حلول التطوير مع وكلاء الذكاء الاصطناعي."},"features":{"en":["Tracks spend and usage across Claude, Cursor, OpenRouter, Copilot, Gemini, Codex, and more","Supports invocation to review design documents against the codebase","Reads and follows the full skill specification in docs/skills/review-design/SKILL.md","Monitors AI usage with tools like Claude-usage-monitor and OpenRouter-usage","Integrates with coding agents like Copilot and Codex","Provides a unified dashboard for AI cost tracking and AI usage monitoring"],"zh":["跟踪 Claude、Cursor 和 Copilot 的使用情况","支持多个 AI 工具的使用情况跟踪","提供详细的使用情况报告","支持 CLI 和 API 接口","集成 Codex 和 Gemini 的使用情况跟踪","支持 OpenRouter 的使用情况跟踪"],"ja":["AIエージェントの使用状況を追跡","複数の AI ツールの使用状況を追跡","詳細な使用状況レポートを提供","CLI と API インターフェースをサポート","Codex と Gemini の使用状況を追跡","OpenRouter の使用状況を追跡"],"ko":["Claude, Cursor, Copilot의 사용량을 모니터링","다중 AI 도구의 사용량을 모니터링","상세한 사용량 보고서를 제공","CLI와 API 인터페이스를 지원","Codex와 Gemini의 사용량을 모니터링","OpenRouter의 사용량을 모니터링"],"es":["Invocación de revisión de diseño contra la base de código","Compatibilidad con Claude, Cursor, OpenRouter y más","Seguimiento de uso y gastos de agentes de IA","Integración con herramientas de desarrollo como Codex y Copilot","Soporte para múltiples tecnologías de desarrollo"],"fr":["Invocation de révision de conception contre la base de code","Compatibilité avec Claude, Cursor, OpenRouter et plus","Suivi de l''utilisation et des dépenses des agents IA","Intégration avec des outils de développement tels que Codex et Copilot","Prise en charge de plusieurs technologies de développement"],"de":["Aufruf der Designüberprüfung gegen die Codebasis","Kompatibilität mit Claude, Cursor, OpenRouter und mehr","Verfolgung der Nutzung und Ausgaben von KI-Agenten","Integration mit Entwicklungstools wie Codex und Copilot","Unterstützung für mehrere Entwicklungstechnologien"],"pt":["Revisão de código com Claude e Codex","Otimização de soluções de desenvolvimento","Integração com agentes de IA como Cursor e Copilot","Análise de uso e gastos de recursos de IA","Suporte a múltiplos agentes de IA, incluindo Gemini e OpenRouter"],"ru":["Просмотр кода с помощью ИИ Агентов, таких как Claude и Codex","Оптимизация решений разработки","Интеграция с ИИ Агентами, такими как Cursor и Copilot","Анализ использования и расхода ресурсов ИИ","Поддержка нескольких ИИ Агентов, включая Gemini и OpenRouter"],"ar":["مراجعة الكود باستخدام وكلاء الذكاء الاصطناعي مثل Claude و Codex","تحسين حلول التطوير","التكامل مع وكلاء الذكاء الاصطناعي مثل Cursor و Copilot","تحليل استخدام واستهلاك موارد الذكاء الاصطناعي","دعم وكلاء الذكاء الاصطناعي المتعددين، بما في ذلك Gemini و OpenRouter"]},"keywords":{"en":["how to use review-design","review-design alternative","review-design setup guide","what is review-design","review-design vs Copilot","review-design install","AI cost tracking with review-design","Claude usage monitoring with review-design","Codex integration with review-design"],"zh":["Review Design","AI 工具使用情况跟踪","Claude 使用情况","Cursor 使用情况","Copilot 使用情况","AI 成本优化","AI 使用情况报告"],"ja":["Review Design","AIエージェント使用状況追跡","AIツール使用状況追跡","Claude使用状況","Cursor使用状況","Copilot使用状況","AIコスト最適化","AI使用状況レポート"],"ko":["Review Design","AI 도구 사용량 모니터링","Claude 사용량","Cursor 사용량","Copilot 사용량","AI 비용 최적화","AI 사용량 보고서"],"es":["Review Design","agentes de IA","diseño de software","desarrollo de software","Claude","Cursor","OpenRouter","Codex","Copilot"],"fr":["Review Design","agents IA","conception de logiciels","développement de logiciels","Claude","Cursor","OpenRouter","Codex","Copilot"],"de":["Review Design","KI-Agenten","Software-Design","Software-Entwicklung","Claude","Cursor","OpenRouter","Codex","Copilot"],"pt":["review design","otimização de código","agentes de ia","claude","codex","cursor","copilot","gemini","openrouter","desenvolvimento de software"],"ru":["review design","оптимизация кода","ии агенты","claude","codex","cursor","copilot","gemini","openrouter","разработка программного обеспечения"],"ar":["مراجعة التصميم","تحسين الكود","وكلاء الذكاء الاصطناعي","claude","codex","cursor","copilot","gemini","openrouter","تطوير البرمجيات"]}},"owner":"janekbaraniewski","repo":"openusage","repoPath":"janekbaraniewski/openusage","stars":8,"forks":0,"updatedAt":"2026-02-28T00:55:36Z","topics":["ai-cost","ai-cost-tracking","ai-spending","ai-usage","claude","claude-code","claude-code-usage","claude-usage-monitor","codex","coding-agents","copilot","copilot-usage","cursor","gemini-cli","llm-usage","openrouter","openrouter-usage"],"category":"community","skillMd":{"name":"review-design","description":"Review a design doc against the codebase","bodyPreview":"# Skill: Review Design\n\n> **Invocation**: Review a design doc against the codebase\n\nRead and follow the full skill specification in `docs/skills/review-design/SKILL.md`.","body":"# Skill: Review Design\n\n> **Invocation**: Review a design doc against the codebase\n\nRead and follow the full skill specification in `docs/skills/review-design/SKILL.md`.\n"},"lastSynced":"2026-03-06T06:49:20.589Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing comprehensive codebase analysis and design doc review capabilities.","zh":"非常适合需要对代码库进行全面分析和设计文档审查的开发代理。","ja":"開発エージェントが包括的なコードベース分析およびデザインドキュメントのレビュー機能を必要とする場合に最適です。","ko":"개발 에이전트가 종합적인 코드베이스 분석 및 설계 문서 검토 기능을 필요로 하는 경우에 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan un análisis de codebase y capacidades de revisión de documentos de diseño integrales.","fr":"Parfait pour les agents de développement nécessitant une analyse complète de codebase et des capacités de révision de documents de conception.","de":"Perfekt für Entwicklungssagenten, die eine umfassende Codebase-Analyse und Design-Dokumenten-Überprüfungsfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de análise abrangente de código e revisão de documentos de design.","ru":"Идеально для агентов разработки, которым необходима комплексная анализ кодовой базы и обзор документации по проектированию.","ar":"مثالي لعمليات تطوير الوكلاء الذين يحتاجون إلى تحليل شاملة لقاعدة الشفرة ومراجعة وثائق التصميم."},"recommendation":{"en":"Empowers agents to track spend and usage across various AI tools, including Claude, Cursor, and Codex, providing optimized workflow monitoring and AI usage insights through design doc analysis against codebases.","zh":"赋予代理跟踪各种AI工具（包括Claude、Cursor和Codex）上的支出和使用情况的能力，通过设计文档分析提供优化的工作流监控和AI使用洞察。","ja":"Claude、Cursor、Codexを含む様々なAIツールでの支出と使用状況をエージェントが追跡できるようにし、コードベースに対するデザインドキュメントの分析を通じて最適化されたワークフローの監視とAIの使用状況に関する洞察を提供します。","ko":"에이전트가 Claude, Cursor, Codex를 포함한 다양한 AI 도구의 비용과 사용량을 추적할 수 있도록 하며, 설계 문서 분석을 통해 최적화된 워크플로우 모니터링 및 AI 사용량에 대한 통찰력을 제공합니다.","es":"Habilita a los agentes a realizar un seguimiento del gasto y uso en varias herramientas de inteligencia artificial, incluidas Claude, Cursor y Codex, y proporciona una monitorización de flujo de trabajo optimizada y conocimientos sobre el uso de la inteligencia artificial a través del análisis de documentos de diseño frente a codebases.","fr":"Permet aux agents de suivre les dépenses et l''utilisation de divers outils d''intelligence artificielle, notamment Claude, Cursor et Codex, et fournit une surveillance du flux de travail optimisée et des connaissances sur l''utilisation de l''intelligence artificielle grâce à l''analyse de documents de conception par rapport aux codebases.","de":"Ermächtigt Agenten, den Aufwand und die Nutzung verschiedener KI-Tools wie Claude, Cursor und Codex zu verfolgen und bietet eine optimierte Überwachung der Arbeitsabläufe und Erkenntnisse über den KI-Einsatz durch die Analyse von Design-Dokumenten gegen Codebases.","pt":"Habilita os agentes a rastrear gastos e utilização em várias ferramentas de IA, incluindo Claude, Cursor e Codex, fornecendo monitoramento de fluxo de trabalho otimizado e insights de utilização de IA por meio da análise de documentos de design contra código.","ru":"Наделяет агентов возможностью отслеживать расходы и использование различных инструментов ИИ, включая Claude, Cursor и Codex, обеспечивая оптимизированный мониторинг рабочего процесса и анализ использования ИИ посредством анализа документации по проектированию против кодовой базы.","ar":"تمكّن الوكلاء من تتبع الإنفاق والاستخدام عبر أدوات الذكاء الاصطناعي المختلفة، بما في ذلك Claude و Cursor و Codex، وتوفير مراقبة تدفق العمل المتكامل والرؤى حول استخدام الذكاء الاصطناعي من خلال تحليل وثائق التصميم مقابل قاعدة الشفرة."},"useCases":{"en":["Automating design doc reviews against codebases","Monitoring AI tool usage and spend","Optimizing workflow through comprehensive content analysis"],"zh":["自动化代码库对设计文档的审查","监控AI工具的使用情况和支出","通过全面内容分析优化工作流"],"ja":["コードベースに対するデザインドキュメントのレビューの自動化","AIツールの使用状況と支出の監視","包括的なコンテンツ分析を通じてワークフローの最適化"],"ko":["설계 문서에 대한 코드베이스의 검토 자동화","AI 도구의 사용량 및 비용 모니터링","종합적인 콘텐츠 분석을 통해 워크플로우 최적화"],"es":["Automatización de revisiones de documentos de diseño frente a codebases","Monitoreo del uso y gasto de herramientas de inteligencia artificial","Optimización del flujo de trabajo a través de un análisis integral de contenido"],"fr":["Automatisation des révisions de documents de conception par rapport aux codebases","Surveillance de l''utilisation et des dépenses des outils d''intelligence artificielle","Optimisation du flux de travail grâce à une analyse complète de contenu"],"de":["Automatisierung von Design-Dokumenten-Überprüfungen gegen Codebases","Überwachung der Nutzung und des Aufwands von KI-Tools","Optimierung der Arbeitsabläufe durch umfassende Inhaltsanalyse"],"pt":["Automatizar revisões de documentos de design contra código","Monitorar utilização e gastos de ferramentas de IA","Otimizar fluxo de trabalho por meio da análise abrangente de conteúdo"],"ru":["Автоматизировать обзор документации по проектированию против кодовой базы","Отслеживать использование и расходы инструментов ИИ","Оптимизировать рабочий процесс посредством комплексного анализа контента"],"ar":["أتمتة مراجعة وثائق التصميم مقابل قاعدة الشفرة","مراقبة استخدام ومصاريف أدوات الذكاء الاصطناعي","تحسين تدفق العمل من خلال تحليل متكامل للمحتوى"]},"limitations":{"en":["Requires access to design documents and codebase","Compatibility with specific AI tools like Claude, Cursor, and Codex"],"zh":["需要访问设计文档和代码库","与特定的AI工具（如Claude、Cursor和Codex）兼容"],"ja":["デザインドキュメントとコードベースへのアクセスが必要","Claude、Cursor、Codexなどの特定のAIツールとの互換性"],"ko":["설계 문서 및 코드베이스에 대한 접근이 필요","Claude, Cursor, Codexなどの 특정 AI 도구와의 호환성"],"es":["Requiere acceso a documentos de diseño y codebase","Compatibilidad con herramientas de inteligencia artificial específicas como Claude, Cursor y Codex"],"fr":["Nécessite l''accès aux documents de conception et aux codebases","Compatibilité avec des outils d''intelligence artificielle spécifiques comme Claude, Cursor et Codex"],"de":["Erfordert den Zugriff auf Design-Dokumente und Codebases","Kompatibilität mit bestimmten KI-Tools wie Claude, Cursor und Codex"],"pt":["Requer acesso a documentos de design e código","Compatibilidade com ferramentas de IA específicas como Claude, Cursor e Codex"],"ru":["Требует доступа к документации по проектированию и кодовой базе","Совместимость с определенными инструментами ИИ, такими как Claude, Cursor и Codex"],"ar":["يتطلب الوصول إلى وثائق التصميم وقاعدة الشفرة","التوافق مع أدوات الذ