INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('janekbaraniewski/openusage/review-design', 'review-design', 'janekbaraniewski', 'openusage', 'community', 'review-design janekbaraniewski openusage community ai-cost ai-cost-tracking ai-spending ai-usage claude claude-code claude-code-usage claude-usage-monitor codex coding-agents copilot copilot-usage cursor gemini-cli llm-usage openrouter openrouter-usage The review-design skill enables developers to track spend and usage across various AI tools, including Claude, Cursor, and Codex. It helps developers monitor their AI usage and optimize their workflow. Review Design 是一种技术，用于跟踪和管理 AI 工具的使用情况，包括 Claude、Cursor 和 Copilot Review Design は、AIエージェントの使用状況を追跡し、コストを最適化するための技術です Review Design은 Claude, Cursor, Copilot의 사용량을 모니터링하고 최적화하는 기술입니다 Review Design es una habilidad que permite a los desarrolladores revisar documentos de diseño contra la base de código Review Design est une compétence qui permet aux développeurs de réviser les documents de conception contre la base de code Review Design ist eine Fähigkeit, die es Entwicklern ermöglicht, Design-Dokumente gegen die Codebasis zu überprüfen O Review Design é uma ferramenta que ajuda a otimizar o código, permitindo que os desenvolvedores revisem e aprimorem suas soluções com agentes de IA como Claude e Codex. Review Design - это инструмент, который помогает оптимизировать код, позволяя разработчикам просматривать и совершенствовать свои решения с помощью ИИ Агентов, таких как Claude и Codex. مراجعة التصميم هي أداة تساعد في تحسين الكود، مما يسمح للمطورين بمراجعة وتحسين حلولهم مع وكلاء الذكاء الاصطناعي مثل Claude و Codex. how to use review-design review-design alternative review-design setup guide what is review-design review-design vs Copilot review-design install AI cost tracking with review-design Claude usage monitoring with review-design Codex integration with review-design Review Design AI 工具使用情况跟踪 Claude 使用情况 Cursor 使用情况 Copilot 使用情况 AI 成本优化 AI 使用情况报告 Tracks spend and usage across Claude, Cursor, OpenRouter, Copilot, Gemini, Codex, and more Supports invocation to review design documents against the codebase Reads and follows the full skill specification in docs/skills/review-design/SKILL.md Monitors AI usage with tools like Claude-usage-monitor and OpenRouter-usage Integrates with coding agents like Copilot and Codex Provides a unified dashboard for AI cost tracking and AI usage monitoring review-design is a skill that allows developers to review design documents against their codebase, supporting tools like Claude, Copilot, and Gemini.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Crainax/War3Lib/zinc-dual-index-pattern', 'community', 'Crainax', 'War3Lib', 'Crainax/War3Lib', 'zinc-dual-index-pattern', 8, 3, 20, '2026-02-21T00:58:02Z', '2026-03-06T06:50:08.148Z', '900674325adc27809bc34d31d2713b91324824e7c39be89d9f0346f56e749b2e', '{"id":"Crainax/War3Lib/zinc-dual-index-pattern","name":"zinc-dual-index-pattern","description":{"en":"The zinc-dual-index-pattern skill enables developers to efficiently implement War3Lib features, including compact traversal, O(1) deletion, and dual-view indexing. This skill benefits developers working with War3Lib.","zh":"Zinc双重索引模式是一种War3Lib紧凑数组实现，支持O(1)删除和双视图索引","ja":"Zincデュアルインデックスパターンは、War3Libコンパクト配列を実現するための方法で、O(1)削除とデュアルビューインデックスをサポート","ko":"Zinc 듀얼 인덱스 패턴은 War3Lib 컴팩트 배열을 구현하는 방법으로, O(1) 삭제 및 듀얼 뷰 인덱스를 지원","es":"El patrón de indexación doble zinc es una técnica para implementar iteraciones eficientes y eliminación O(1) de elementos en War3Lib","fr":"Le modèle d''indexation double zinc est une technique pour mettre en œuvre des itérations efficaces et une suppression O(1) d''éléments dans War3Lib","de":"Das zinc-Dual-Index-Muster ist eine Technik zur Implementierung effizienter Iterationen und O(1)-Löschung von Elementen in War3Lib","pt":"O zinc-dual-index-pattern é uma técnica de otimização para algoritmos de busca e ordenação em War3Lib, permitindo uma iteração compacta e remoção eficiente de elementos.","ru":"Шаблон zinc-dual-index-pattern - это метод оптимизации алгоритмов поиска и сортировки в War3Lib, обеспечивающий компактную итерацию и эффективное удаление элементов для ИИ Агентов","ar":"نمط zinc-dual-index-pattern هو تقنية لتحسين خوارزميات البحث والترتيب في War3Lib، مما يسمح بالتكرار المدمج وإزالة الكفاءة للأدوات الذكية"},"seo":{"title":{"en":"zinc-dual-index-pattern: Optimized War3Lib Setup Guide | ...","zh":"Zinc 双重索引模式Setup Guide - War3Lib紧凑数组","ja":"Zincデュアルインデックスパターン設定ガイド - War3Libコンパクト配列","ko":"Zinc 듀얼 인덱스 패턴 설정 가이드 - War3Lib компакт массив","es":"Guía de configuración de zinc-dual-index-pattern para des...","fr":"Configurer le modèle d''indexation double zinc pour les dé...","de":"Einrichtungsleitfaden für Entwickler: zinc-dual-index-pat...","pt":"Guia de Configuração do zinc-dual-index-pattern para Dese...","ru":"Настройка шаблона zinc-dual-index-pattern: Лучшие Практик...","ar":"دليل إعداد zinc-dual-index-pattern لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient War3Lib development with zinc-dual-index-pattern. Discover how to implement O(1) deletion, compact arrays, and dual-view indexing. Get start...","zh":"使用Zinc双重索引模式实现War3Lib紧凑数组，支持O(1)删除和双视图索引","ja":"Zincデュアルインデックスパターンを使用してWar3Libコンパクト配列を実現します。O(1)削除とデュアルビューインデックスをサポート","ko":"Zinc 듀얼 인덱스 패턴을 사용하여 War3Lib 컴팩트 배열을 구현합니다. O(1) 삭제 및 듀얼 뷰 인덱스를 지원","es":"Aprenda a implementar el patrón de indexación doble zinc en War3Lib para una iteración eficiente y eliminación O(1) de elementos","fr":"Découvrez comment mettre en œuvre le modèle d''indexation double zinc dans War3Lib pour une itération efficace et une suppression O(1) d''éléments","de":"Erfahren Sie, wie Sie das zinc-Dual-Index-Muster in War3Lib implementieren, um eine effiziente Iteration und O(1)-Löschung von Elementen zu ermöglichen","pt":"Aprenda a implementar o zinc-dual-index-pattern para melhorar a eficiência de seus algoritmos de busca e ordenação em War3Lib","ru":"Узнайте, как использовать шаблон zinc-dual-index-pattern для оптимизации поиска и сортировки в War3Lib для ИИ Агентов","ar":"تعرف على كيفية تطبيق نمط zinc-dual-index-pattern لتحسين كفاءة خوارزميات البحث والترتيب في War3Lib لأدوات الذكاء الاصطناعي"},"definition":{"en":"zinc-dual-index-pattern is a technique for optimizing War3Lib development with compact arrays, O(1) deletion, and dual-view indexing, enabling efficient data management and querying.","zh":"Zinc双重索引模式是一种数据结构，实现War3Lib紧凑数组，支持高效删除和查询","ja":"Zincデュアルインデックスパターンは、War3Libコンパクト配列を実現するためのデータ構造で、高效な削除と検索をサポート","ko":"Zinc 듀얼 인덱스 패턴은 War3Lib 컴팩트 배열을 구현하는 데이터 구조로, 효율적인 삭제 및 검색을 지원","es":"El patrón de indexación doble zinc es una técnica de programación que permite una iteración eficiente y eliminación O(1) de elementos","fr":"Le modèle d''indexation double zinc est une technique de programmation qui permet une itération efficace et une suppression O(1) d''éléments","de":"Das zinc-Dual-Index-Muster ist eine ProgrammierTechnik, die eine effiziente Iteration und O(1)-Löschung von Elementen ermöglicht","pt":"O zinc-dual-index-pattern é uma técnica de programação que permite a iteração compacta e remoção eficiente de elementos em arrays","ru":"Шаблон zinc-dual-index-pattern - это техника программирования, обеспечивающая компактную итерацию и эффективное удаление элементов в массивах для ИИ Агентов","ar":"نمط zinc-dual-index-pattern هو تقنية برمجية تتيح التكرار المدمج وإزالة الكفاءة للعناصر في المصفوفات"},"features":{"en":["Enables compact traversal of arrays without empty slots","Supports O(1) deletion using swap-remove technique","Provides dual-view indexing for simultaneous global and grouped listing","Allows for efficient querying and traversal of data","Includes reference documentation for implementation guidance","Supports War3Lib examples and checklist for development"],"zh":["紧凑遍历：数组无空洞，for遍历不需要跳过空位","O(1)删除：用尾部交换（swap-remove）移除元素","双视图索引：同一实例同时存在于全局列表和分组列表","支持按需加载参考文档","实现War3Lib紧凑数组","高效删除和查询"],"ja":["コンパクトな遍历：配列に空洞がないため、forループで空のスロットをスキップする必要がない","O(1)削除：末尾の交換（swap-remove）を使用して要素を削除","デュアルビューインデックス：同じインスタンスがグローバルリストとグループリストの両方に存在","必要な参考文書をロードする機能","War3Libコンパクト配列の実現","効率的な削除と検索"],"ko":["컴팩트한遍历：배열에 빈 공간이 없으므로 for 루프에서 빈 슬롯을 건너뛰지 않아도 됨","O(1) 삭제：末尾의 교환（swap-remove）을 사용하여 요소를 삭제","듀얼 뷰 인덱스：같은 인스턴스가 글로벌 리스트와 그룹 리스트 양쪽에 존재","필요한 参考文書를 로드하는 기능","War3Lib 컴팩트 배열의 구현","효율적인 삭제 및 검색"],"es":["Iteración compacta sin saltos","Eliminación O(1) de elementos mediante intercambio","Indexación doble para listas globales y de g