INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Crainax/War3Lib/zinc-dual-index-pattern', 'zinc-dual-index-pattern', 'Crainax', 'War3Lib', 'community', 'zinc-dual-index-pattern Crainax War3Lib community The zinc-dual-index-pattern skill enables developers to efficiently implement War3Lib features, including compact traversal, O(1) deletion, and dual-view indexing. This skill benefits developers working with War3Lib. Zinc双重索引模式是一种War3Lib紧凑数组实现，支持O(1)删除和双视图索引 Zincデュアルインデックスパターンは、War3Libコンパクト配列を実現するための方法で、O(1)削除とデュアルビューインデックスをサポート Zinc 듀얼 인덱스 패턴은 War3Lib 컴팩트 배열을 구현하는 방법으로, O(1) 삭제 및 듀얼 뷰 인덱스를 지원 El patrón de indexación doble zinc es una técnica para implementar iteraciones eficientes y eliminación O(1) de elementos en War3Lib Le modèle d''indexation double zinc est une technique pour mettre en œuvre des itérations efficaces et une suppression O(1) d''éléments dans War3Lib Das zinc-Dual-Index-Muster ist eine Technik zur Implementierung effizienter Iterationen und O(1)-Löschung von Elementen in War3Lib O zinc-dual-index-pattern é uma técnica de otimização para algoritmos de busca e ordenação em War3Lib, permitindo uma iteração compacta e remoção eficiente de elementos. Шаблон zinc-dual-index-pattern - это метод оптимизации алгоритмов поиска и сортировки в War3Lib, обеспечивающий компактную итерацию и эффективное удаление элементов для ИИ Агентов نمط zinc-dual-index-pattern هو تقنية لتحسين خوارزميات البحث والترتيب في War3Lib، مما يسمح بالتكرار المدمج وإزالة الكفاءة للأدوات الذكية how to use zinc-dual-index-pattern zinc-dual-index-pattern War3Lib optimization zinc-dual-index-pattern vs traditional indexing zinc-dual-index-pattern setup guide zinc-dual-index-pattern install what is zinc-dual-index-pattern zinc-dual-index-pattern alternative zinc-dual-index-pattern documentation War3Lib development with zinc-dual-index-pattern Zinc双重索引模式 War3Lib紧凑数组 O(1)删除 双视图索引 紧凑遍历 AIエージェント War3Lib 数据结构 高效删除 高效查询 Enables compact traversal of arrays without empty slots Supports O(1) deletion using swap-remove technique Provides dual-view indexing for simultaneous global and grouped listing Allows for efficient querying and traversal of data Includes reference documentation for implementation guidance Supports War3Lib examples and checklist for development zinc-dual-index-pattern is a technique for optimizing War3Lib development with compact arrays, O(1) deletion, and dual-view indexing, enabling efficient data management and querying.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DataCovey/nornweave/commit', 'community', 'DataCovey', 'nornweave', 'DataCovey/nornweave', 'commit', 6, 0, 20, '2026-02-23T05:15:44Z', '2026-03-07T01:52:18.133Z', 'fe658e086519acca671d0a4a65c2643003bfe440338fe58802f4badd28ec94ff', '{"id":"DataCovey/nornweave/commit","name":"commit","description":{"en":"Commit is an open-source, self-hosted API that enables AI Agents to utilize standard email providers. It supports Mailgun, SES, and SendGrid, turning them into Inbox-as-a-Service.","zh":"Commit是一个开源、自托管的API，能够将标准邮件提供商转换为Inbox-as-a-Service，支持Mailgun、SES、SendGrid等","ja":"CommitはオープンソースのセルフホストAPIで、標準メールプロバイダーをInbox-as-a-Serviceに変換することができます","ko":"Commit는 오픈소스 自托管 API로 표준 이메일 제공자를 Inbox-as-a-Service로 전환할 수 있습니다","es":"Commit es una API de código abierto que convierte proveedores de correo electrónico en ''Inbox-as-a-Service'' para agentes de AI. Utiliza Mailgun, SES y SendGrid.","fr":"Commit est une API open source qui transforme les fournisseurs de messagerie en ''Inbox-as-a-Service'' pour les outils d''IA. Elle utilise Mailgun, SES et SendGrid.","de":"Commit ist eine Open-Source-API, die E-Mail-Anbieter in ''Inbox-as-a-Service'' für KI-Agents umwandelt. Sie verwendet Mailgun, SES und SendGrid.","pt":"O Commit é uma API de código aberto que transforma provedores de email em ''Inbox-as-a-Service'' para AI Agents, utilizando Mailgun, SES e SendGrid.","ru":"Commit - это открытая API, которая превращает провайдеров электронной почты в ''Inbox-as-a-Service'' для ИИ Агентов, используя Mailgun, SES и SendGrid.","ar":"Commit هو واجهة برمجة تطبيقات مفتوحة المصدر تحول مزودي البريد الإلكتروني إلى ''Inbox-as-a-Service'' للعوامل الذكية، باستخدام Mailgun و SES و SendGrid."},"seo":{"title":{"en":"Commit: Self-Hosted API Setup Guide for AI Agents","zh":"Commit_SETUP GUIDE: 将标准邮件提供商转换为Inbox-as-a-Service","ja":"Commitベストプラクティス: メールプロバイダーをInbox-as-a-Serviceに","ko":"Commit 설정 가이드: 표준 이메일 제공자를 Inbox-as-a-Service로","es":"Guía de configuración de Commit para agentes de AI","fr":"Guide de mise en place de Commit pour les outils d''IA","de":"Einrichtungsanleitung für Commit für KI-Agents","pt":"Commit: Guia de Configuração para AI Agents com Email","ru":"Commit: Настройка ИИ Агентов с Email-провайдерами","ar":"Commit: دليل إعداد العوامل الذكية مع البريد الإلكتروني"},"description":{"en":"Unlock the power of Inbox-as-a-Service with Commit, an open-source API for AI Agents. Learn how to integrate with Mailgun, SES, and SendGrid today!","zh":"使用Commit将Mailgun、SES、SendGrid等标准邮件提供商转换为Inbox-as-a-Service，实现AI代理的高效邮件管理","ja":"Commitを使用して、メールプロバイダーをInbox-as-a-Serviceに変換し、AIエージェントのメール管理を効率化する","ko":"Commit를 사용하여 표준 이메일 제공자를 Inbox-as-a-Service로 전환하여 AI 에이전트의 이메일 관리를 효율화","es":"Aprende a utilizar Commit para convertir proveedores de correo electrónico estándar en ''Inbox-as-a-Service'' para agentes de AI","fr":"Découvrez comment utiliser Commit pour transformer les fournisseurs de messagerie standard en ''Inbox-as-a-Service'' pour les outils d''IA","de":"Erfahren Sie, wie Sie Commit verwenden können, um Standard-E-Mail-Anbieter in ''Inbox-as-a-Service'' für KI-Agents umzuwandeln","pt":"Aprenda a configurar o Commit para transformar provedores de email em ''Inbox-as-a-Service'' para AI Agents","ru":"Узнайте, как настроить Commit для преобразования провайдеров электронной почты в ''Inbox-as-a-Service'' для ИИ Агентов","ar":"تعرف على كيفية إعداد Commit لتحويل مزودي البريد الإلكتروني إلى ''Inbox-as-a-Service'' للعوامل الذكية"},"definition":{"en":"Commit is an open-source API that transforms email providers into Inbox-as-a-Service for AI Agents, utilizing protocols like Mailgun, SES, and SendGrid.","zh":"Commit是一种开源的自托管API，用于将标准邮件提供商转换为Inbox-as-a-Service","ja":"Commitは、標準メールプロバイダーをInbox-as-a-Serviceに変換するオープンソースのセルフホストAPIです","ko":"Commit는 표준 이메일 제공자를 Inbox-as-a-Service로 전환하는 오픈소스 自托管 API입니다","es":"Commit es una API autohospedada que convierte proveedores de correo electrónico estándar en ''Inbox-as-a-Service'' para agentes de AI","fr":"Commit est une API autohébergée qui transforme les fournisseurs de messagerie standard en ''Inbox-as-a-Service'' pour les outils d''IA","de":"Commit ist eine selbstgehostete API, die Standard-E-Mail-Anbieter in ''Inbox-as-a-Service'' für KI-Agents umwandelt","pt":"O Commit é uma API que permite transformar provedores de email em ''Inbox-as-a-Service'' para AI Agents.","ru":"Commit - это API, которая позволяет преобразовать провайдеров электронной почты в ''Inbox-as-a-Service'' для ИИ Агентов.","ar":"Commit هو واجهة برمجة تطبيقات تمكن من تحويل مزودي البريد الإلكتروني إلى ''Inbox-as-a-Service'' للعوامل الذكية."},"features":{"en":["Utilizes standard email providers like Mailgun, SES, and SendGrid","Supports Conventional Commits for best practices","Enables self-hosted Inbox-as-a-Service for AI Agents","Compatible with Python for seamless integration","Allows committing changes to the current branch using specific commands"],"zh":["支持Mailgun、SES、SendGrid等标准邮件提供商","将标准邮件提供商转换为Inbox-as-a-Service","使用Conventional Commits的最佳实践","支持自托管部署","使用Python开发"],"ja":["Mailgun、SES、SendGridなどの標準メールプロバイダーをサポート","標準メールプロバイダーをInbox-as-a-Serviceに変換","Conventional Commitsのベストプラクティスを使用","セルフホストデプロイをサポート","Pythonで開発"],"ko":["Mailgun, SES, SendGrid 등 표준 이메일 제공자를 지원","표준 이메일 제공자를 Inbox-as-a-Service로 전환","Conventional Commits의 베스트 프랙티스를 사용","셀프 호스팅 배포를 지원","Python으로 개발"],"es":["Soporte para Mailgun, SES y SendGrid","API autohospedada para agentes de AI","Compatibilidad con Conventional Commits","Capacidad de commit de cambios en la rama actual","Uso de mejores prácticas para commits"],"fr":["Prise en charge de Mailgun, SES et SendGrid","API autohébergée pour les outils d''IA","Compatibilité avec Conventional Commits","Capacité de commit des modifications dans la branche actuelle","Utilisation des meilleures pratiques pour les commits"],"de":["Unterstützung für Mailgun, SES und SendGrid","Selbstgehostete API für KI-Agents","Kompatibilität mit Conventional Commits","Fähigkeit, Änderungen im aktuellen Branch zu committen","Verwendung von Best Practices für Commits"],"pt":["Integração com Mailgun, SES e SendGrid","Suporte a AI Agents e LLM","Código aberto e auto-hospedado","Utiliza Conventional Commits para commit de alterações","Desenvolvido em Python"],"ru":["Интеграция с Mailgun, SES и SendGrid","Поддержка ИИ Агентов и LLM","Открытый код и самохостинг","Использует Conventional Commits для фиксации изменений","Разработан на Python"],"ar":["التكامل مع Mailgun و SES و SendGrid","دعم العوامل الذكية و LLM","كود مفتوح و ذاتي الاستضافة","استخدام Conventional Commits لالتزام التغييرات","مطور باستخدام Python"]},"keywords":{"en":["how to use commit","commit setup guide","commit alternative to Mailgun","commit vs SendGrid","what is commit","commit install for AI Agents","commit self-hosted API","commit and Conventional Commits","commit for llm-agents","commit with python"],"zh":["Commit","Inbox-as-a-Service","AI代理","邮件管理","Mailgun","SES","SendGrid","Python","自托管"],"ja":["Commit","Inbox-as-a-Service","AIエージェント","メール管理","Mailgun","SES","SendGrid","Python","セルフホスト"],"ko":["Commit","Inbox-as-a-Service","AI 에이전트","이메일 관리","Mailgun","SES","SendGrid","Python","셀프 호스팅"],"es":["agentes de AI","herramientas de AI","Commit","Mailgun","SES","SendGrid","API autohospedada","Conventional Commits","mejores prácticas para commits"],"fr":["outils d''IA","agents d''IA","Commit","Mailgun","SES","SendGrid","API autohébergée","Conventional Commits","meilleures pratiques pour les commits"],"de":["KI-Agents","KI-Tools","Commit","Mailgun","SES","SendGrid","selbstgehostete API","Conventional Commits","Best Practices für Commits"],"pt":["commit ai agents","inbox as a service","email providers","mailgun","ses","sendgrid","ai tools","llm agents","python"],"ru":["commit ИИ Агенты","inbox as a service","провайдеры электронной почты","mailgun","ses","sendgrid","ИИ инструменты","llm агенты","python"],"ar":["commit العوامل الذكية","inbox as a service","مزودو البريد الإلكتروني","mailgun","ses","sendgrid","أدوات ذكية","llm عوامل","python"]}},"owner":"DataCovey","repo":"nornweave","repoPath":"DataCovey/nornweave","stars":6,"forks":0,"updatedAt":"2026-02-23T05:15:44Z","topics":["agent","ai-tools","email","llm","llm-agents","mcp-server","python","self-hosted"],"category":"community","skillMd":{"name":"commit","description":"Commit the changes made on this chat session to the current branch. Use best practices from Conventional Commits.","bodyPreview":"Commit the changes made on this chat session to the current branch. Use best practices from Conventional Commits.","body":"Commit the changes made on this chat session to the current branch. Use best practices from Conventional Commits.\n"},"lastSynced":"2026-03-07T01:52:18.133Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing standardized version control and email integration capabilities.","zh":"适用于需要标准化版本控制和电子邮件集成功能的DevOps代理。","ja":"DevOpsエージェントが標準化されたバージョン管理と電子メール統合機能を必要とする場合に適しています。","ko":"표준화된 버전 관리 및 이메일 통합 기능이 필요한 DevOps 에이전트에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan un control de versiones estandarizado y capacidades de integración de correo electrónico.","fr":"Parfait pour les agents DevOps ayant besoin d''un contrôle de version standardisé et de capacités d''intégration de messagerie électronique.","de":"Perfekt für DevOps-Agents, die ein standardisiertes Versionskontrollsystem und E-Mail-Integration benötigen.","pt":"Perfeito para Agents DevOps que necessitam de controle de versão padronizado e capacidades de integração de e-mail.","ru":"Идеально для агентов DevOps, которым необходимы стандартизированный контроль версий и возможности интеграции электронной почты.","ar":"مثالي للوكلاء DevOps الذين يحتاجون إلى التحكم الإصدار المعمول به والقدرات التكامل البريد الإلكتروني."},"recommendation":{"en":"Empowers agents to manage Inbox-as-a-Service using Mailgun, SES, and SendGrid, while adhering to Conventional Commits best practices for transparent and organized change tracking through protocols like SMTP and APIs.","zh":"赋予代理管理Inbox-as-a-Service的能力，使用Mailgun、SES和SendGrid，同时遵循Conventional Commits最佳实践，通过SMTP和API等协议实现透明和组织化的变更跟踪。","ja":"エージェントがInbox-as-a-Serviceを管理できるようにし、Mailgun、SES、SendGridを使用しながら、SMTPやAPIなどのプロトコルを介して透明で組織化された変更追跡を可能にするConventional Commitsのベストプラクティスに従う。","ko":"에이전트가 Inbox-as-a-Service를 관리할 수 있도록 하며, Mailgun, SES, SendGrid를 사용하면서 SMTP 및 API와 같은 프로토콜을 통해 투명하고 조직화된 변경 추적을 가능하게 하는 Conventional Commits의 모범 사례를 따릅니다.","es":"Habilita a los agentes a administrar Inbox-as-a-Service utilizando Mailgun, SES y SendGrid, mientras sigue las mejores prácticas de Conventional Commits para un seguimiento de cambios transparente y organizado a través de protocolos como SMTP y API.","fr":"Permet aux agents de gérer Inbox-as-a-Service en utilisant Mailgun, SES et SendGrid, tout en suivant les meilleures pratiques de Conventional Commits pour un suivi des modifications transparent et organisé via des protocoles tels que SMTP et API.","de":"Ermöglicht es Agenten, Inbox-as-a-Service mithilfe von Mailgun, SES und SendGrid zu verwalten, während sie den Conventional Commits-Best-Practices für transparente und organisierte Änderungsnachverfolgung durch Protokolle wie SMTP und API folgen.","pt":"Habilita os agentes a gerenciar Inbox-as-a-Service usando Mailgun, SES e SendGrid, enquanto adere às melhores práticas de Conventional Commits para rastreamento de alterações transparente e organizada por meio de protocolos como SMTP e APIs.","ru":"Позволяет агентам управлять Inbox-as-a-Service с помощью Mailgun, SES и SendGrid, при этом соблюдая лучшие практики Conventional Commits для прозрачной и организованной отслеживания изменений через протоколы, такие как SMTP и API.","ar":"تمكّن الوكلاء من إدارة Inbox-as-a-Service باستخدام Mailgun و SES و SendGrid، مع الالتزام بممارسات Conventional Commits الأفضل لتعقب التغييرات الشفافة والمُنظمة عبر بروتوكولات مثل SMTP و APIs."},"useCases":{"en":["Automating commit messages with semantic versioning","Integrating email services for notification and alert systems","Standardizing branch management with Conventional Commits"],"zh":["使用语义版本控制自动化提交消息","将电子邮件服务集成到通知和警报系统中","使用Conventional Commits标准化分支管理"],"ja":["セマンティックバージョニングを使用してコミットメッセージを自動化する","電子メールサービスを通知と警報システムに統合する","Conventional Commitsを使用してブランチ管理を標準化する"],"ko":["의미 버전 관리를 사용하여 커밋 메시지를 자동화하는 것","이메일 서비스를 알림 및 경고 시스템에 통합하는 것","Conventional Commits를 사용하여 분기 관리를 표준화하는 것"],"es":["Automatizar mensajes de confirmación con versión semántica","Integrar servicios de correo electrónico para sistemas de notificación y alerta","Establecer un estándar para la gestión de ramas con Conventional Commits"],"fr":["Automatiser les messages de validation avec une version sémantique","Intégrer les services de messagerie électronique pour les systèmes de notification et d''alerte","Normaliser la gestion des branches avec Conventional Commits"],"de":["Automatisieren von Commit-Nachrichten mit semantischer Versionierung","Integration von E-Mail-Diensten für Benachrichtigungs- und Warnsysteme","Standardisierung der Verwaltung von Branches mit Conventional Commits"],"pt":["Automatizar mensagens de compromisso com versionamento semântico","Integrar serviços de e-mail para sistemas de notificação e alerta","Padronizar gerenciamento de branch com Conventional Commits"],"ru":["Автоматизировать сообщения о фиксации с семантическим версионированием","Интегрировать сервисы электронной почты для систем оповещения и уведомления","Стандартизировать управление ветками с помощью Conventional Commits"],"ar":["تأتمت رسائل الالتزام بإصدار معنوي","تكامل خدمات البريد الإلكتروني لأنظمة الإشعار والتنبيه","تقييس إدارة الفروع مع Conventional Commits"]},"limitations":{"en":["Requires self-hosted API setup","Supports Mailgun, SES, and SendGrid only"],"zh":["需要自托管API设置","仅支持Mailgun、SES和SendGrid"],"ja":["セルフホストAPI設定が必要","Mailgun、SES、SendGridのみをサポート"],"ko":["자체 호스팅 API 설정이 필요","Mailgun, SES, SendGrid만 지원"],"es":["Requiere una configuración de API autohospedada","Solo admite Mailgun, SES y SendGrid"],"fr":["Nécessite une configuration d''API auto-hébergée","Ne prend en charge que Mailgun, SES et SendGrid"],"de":["Erfordert eine selbstgehostete API-Konfiguration","Unterstützt nur Mailgun, SES und SendGrid"],"pt":["Requer configuração de API auto-hospedada","Suporta apenas Mailgun, SES e SendGrid"],"ru":["Требует настройки самохостингового API","Поддерживает только Mailgun, SES и SendGrid"],"ar":["يتطلب إعداد API مُضيف ذاتي","يدعم Mailgun و SES و SendGrid فقط"]},"version":4},"contentHash":"fe658e086519acca671d0a4a65c2643003bfe440338fe58802f4badd28ec94ff","qualityScore":20}');
