INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DataCovey/nornweave/commit', 'commit', 'DataCovey', 'nornweave', 'community', 'commit DataCovey nornweave community agent ai-tools email llm llm-agents mcp-server python self-hosted Commit is an open-source, self-hosted API that enables AI Agents to utilize standard email providers. It supports Mailgun, SES, and SendGrid, turning them into Inbox-as-a-Service. Commit是一个开源、自托管的API，能够将标准邮件提供商转换为Inbox-as-a-Service，支持Mailgun、SES、SendGrid等 CommitはオープンソースのセルフホストAPIで、標準メールプロバイダーをInbox-as-a-Serviceに変換することができます Commit는 오픈소스 自托管 API로 표준 이메일 제공자를 Inbox-as-a-Service로 전환할 수 있습니다 Commit es una API de código abierto que convierte proveedores de correo electrónico en ''Inbox-as-a-Service'' para agentes de AI. Utiliza Mailgun, SES y SendGrid. Commit est une API open source qui transforme les fournisseurs de messagerie en ''Inbox-as-a-Service'' pour les outils d''IA. Elle utilise Mailgun, SES et SendGrid. Commit ist eine Open-Source-API, die E-Mail-Anbieter in ''Inbox-as-a-Service'' für KI-Agents umwandelt. Sie verwendet Mailgun, SES und SendGrid. O Commit é uma API de código aberto que transforma provedores de email em ''Inbox-as-a-Service'' para AI Agents, utilizando Mailgun, SES e SendGrid. Commit - это открытая API, которая превращает провайдеров электронной почты в ''Inbox-as-a-Service'' для ИИ Агентов, используя Mailgun, SES и SendGrid. Commit هو واجهة برمجة تطبيقات مفتوحة المصدر تحول مزودي البريد الإلكتروني إلى ''Inbox-as-a-Service'' للعوامل الذكية، باستخدام Mailgun و SES و SendGrid. how to use commit commit setup guide commit alternative to Mailgun commit vs SendGrid what is commit commit install for AI Agents commit self-hosted API commit and Conventional Commits commit for llm-agents commit with python Commit Inbox-as-a-Service AI代理 邮件管理 Mailgun SES SendGrid Python 自托管 Utilizes standard email providers like Mailgun, SES, and SendGrid Supports Conventional Commits for best practices Enables self-hosted Inbox-as-a-Service for AI Agents Compatible with Python for seamless integration Allows committing changes to the current branch using specific commands Commit is an open-source API that transforms email providers into Inbox-as-a-Service for AI Agents, utilizing protocols like Mailgun, SES, and SendGrid.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zlliang/zlliang/reviewing', 'community', 'zlliang', 'zlliang', 'zlliang/zlliang', 'reviewing', 4, 0, 20, '2026-02-27T06:20:14Z', '2026-03-06T06:58:10.735Z', 'f8ac3a65bd59ff27ea435c18bca09684d631cd5bfa55dc35e7b2b2d5f62c3b31', '{"id":"zlliang/zlliang/reviewing","name":"reviewing","description":{"en":"The reviewing skill helps developers refine their content by checking for grammar, writing style, and topic clarity issues, benefiting programmers and writers alike.","zh":"AI工具审查功能可以帮助开发者优化编程和写作中的语法、写作风格和内容结构问题","ja":"AIエージェントのレビュー機能は、開発者がプログラミングと文章作成における文法、文章スタイル、コンテンツ構造の問題を最適化するのに役立ちます","ko":"AI 에이전트의 리뷰 기능은 개발자가 프로그래밍 및 작성을 개선하고, 문법, 작성 스타일 및 콘텐츠 구조의 문제를 최적화하는 데 도움을 줍니다","es":"Revisar contenido implica verificar la gramática, el estilo de escritura y la estructura de temas para asegurar la claridad","fr":"La révision de contenu implique la vérification de la grammaire, du style d''écriture et de la structure des sujets pour assurer la clarté","de":"Die Überprüfung von Inhalten beinhaltet die Prüfung von Grammatik, Schreibstil und Themenstruktur, um Klarheit zu gewährleisten","pt":"A revisão de conteúdo é uma habilidade que ajuda a melhorar a qualidade do texto e do código, verificando erros de gramática e estilo.","ru":"Проверка контента - это навык, который помогает улучшить качество текста и кода, проверяя ошибки грамматики и стиля.","ar":"أداة الاستعراض هي ميزة تساعد على تحسين جودة النص والكود، من خلال التحقق من الأخطاء النحوية والأسلوبية."},"seo":{"title":{"en":"Reviewing: Content Optimization Guide for AI Agents","zh":"AI工具审查指南：语法、写作风格和内容结构优化","ja":"AIエージェントのレビュー設定ガイド：文法、文章スタイル、コンテンツ構造の最適化","ko":"AI 에이전트 리뷰 설정 가이드: 문법, 작성 스타일 및 콘텐츠 구조 최적화","es":"Guía de configuración de revisión de contenido","fr":"Configurer l''agent de révision de contenu","de":"Einrichten des Inhalts-Review-Tools","pt":"Guia de Configuração de Revisão de Conteúdo para Desenvol...","ru":"ИИ Агенты: Руководство по Настройке Проверки Контента","ar":"دليل إعداد أداة الاستعراض لْمطورين"},"description":{"en":"Discover how reviewing enhances content quality, learn to load content-authoring and english-writing skills, and get expert tips on grammar and clarity","zh":"提高您的编程和写作技能，通过AI工具审查实现语法、写作风格和内容结构的优化","ja":"AIエージェントのレビュー機能を使用して、プログラミングと文章作成のスキルを向上させ、文法、文章スタイル、コンテンツ構造を最適化する","ko":"AI 에이전트의 리뷰 기능을 사용하여 프로그래밍 및 작성을 개선하고, 문법, 작성 스타일 및 콘텐츠 구조를 최적화합니다","es":"Aprende a revisar contenido con precisión, incluyendo gramática, estilo de escritura y estructura de temas","fr":"Découvrez comment réviser du contenu avec précision, y compris la grammaire, le style d''écriture et la structure des sujets","de":"Erfahren Sie, wie Sie Inhalte präzise überprüfen, einschließlich Grammatik, Schreibstil und Themenstruktur","pt":"Aprenda a configurar a revisão de conteúdo para melhorar a qualidade do seu código e texto, com dicas e práticas recomendadas.","ru":"Узнайте, как настроить проверку контента, чтобы улучшить качество вашего кода и текста, с советами и рекомендациями.","ar":"تعلم كيفية إعداد أداة الاستعراض لتحسين جودة كودك ونصك، مع نصائح وأفضل الممارسات."},"definition":{"en":"Reviewing is the process of examining content for grammar and writing style issues, awkward phrasing, and topic clarity, to improve overall content structure.","zh":"AI工具审查是指使用AI技术对编程和写作内容进行语法、写作风格和内容结构的检查和优化","ja":"AIエージェントのレビューとは、AI技術を使用してプログラミングと文章作成のコンテンツを文法、文章スタイル、コンテンツ構造面で検証および最適化すること","ko":"AI 에이전트의 리뷰란 AI 기술을 사용하여 프로그래밍 및 작성된 콘텐츠의 문법, 작성 스타일 및 콘텐츠 구조를 검증 및 최적화하는 것을 말합니다","es":"La revisión es el proceso de examinar y corregir el contenido para asegurar la precisión y la claridad","fr":"La révision est le processus d''examen et de correction du contenu pour assurer la précision et la clarté","de":"Die Überprüfung ist der Prozess der Prüfung und Korrektur von Inhalten, um Genauigkeit und Klarheit zu gewährleisten","pt":"Revisão de conteúdo é o processo de verificar e melhorar a qualidade do texto e do código.","ru":"Проверка контента - это процесс проверки и улучшения качества текста и кода.","ar":"أداة الاستعراض هي عملية التحقق وتحسين جودة النص والكود."},"features":{"en":["Checks for grammar and writing style issues in content","Examines content for awkward or unnatural phrasing","Evaluates topic clarity and overall content structure","Loads content-authoring skill for comprehensive review","Utilizes english-writing skill for English language drafts","Responds in the draft''s language for seamless integration"],"zh":["语法检查","写作风格优化","内容结构分析","支持content-authoring技能","支持english-writing技能"],"ja":["文法チェック","文章スタイルの最適化","コンテンツ構造の分析","content-authoringスキルのサポート","english-writingスキルのサポート"],"ko":["문법 검사","작성 스타일 최적화","콘텐츠 구조 분석","content-authoring 기능 지원","english-writing 기능 지원"],"es":["Verificación de gramática y estilo de escritura","Análisis de estructura de temas y claridad","Compatibilidad con el skill de autoría de contenido","Soporte para inglés y otros idiomas","Revisión de frases incómodas o poco naturales","Carga de habilidades de escritura en inglés"],"fr":["Vérification de la grammaire et du style d''écriture","Analyse de la structure des sujets et de la clarté","Compatibilité avec la compétence d''authoring de contenu","Prise en charge de l''anglais et d''autres langues","Révision de phrases maladroites ou peu naturelles","Chargement des compétences d''écriture en anglais"],"de":["Prüfung von Grammatik und Schreibstil","Analyse von Themenstruktur und Klarheit","Kompatibilität mit der Content-Authoring-Fähigkeit","Unterstützung für Englisch und andere Sprachen","Überprüfung von unangenehmen oder unnatürlichen Phrasen","Laden von Englisch-Schreibfähigkeiten"],"pt":["Verificação de erros de gramática e estilo","Análise de clareza de tópicos e estrutura de conteúdo","Suporte à carga do skill de autorização de conteúdo","Integração com o skill de escrita em inglês"],"ru":["Проверка ошибок грамматики и стиля","Анализ ясности тем и структуры контента","Поддержка загрузки навыка авторизации контента","Интеграция с навыком написания на английском языке"],"ar":["التحقق من الأخطاء النحوية والأسلوبية","تحليل وضوح المواضيع وهيكل المحتوى","دعم تحميل ميزة تصريح المحتوى","التكامل مع ميزة الكتابة باللغة الإنجليزية"]},"keywords":{"en":["how to use reviewing","what is reviewing","reviewing alternative","reviewing vs proofreading","reviewing install guide","reviewing setup for AI agents","content optimization techniques","english writing skills for developers","grammar and clarity checking tools"],"zh":["AI工具审查","编程优化","写作优化","语法检查","内容结构分析","content-authoring","english-writing","AI审查工具","代码审查"],"ja":["AIエージェントのレビュー","プログラミングの最適化","文章作成の最適化","文法チェック","コンテンツ構造の分析","content-authoring","english-writing","AIレビューツール","コードレビュー"],"ko":["AI 에이전트의 리뷰","프로그래밍 최적화","작성 최적화","문법 검사","콘텐츠 구조 분석","content-authoring","english-writing","AI 리뷰 도구","코드 리뷰"],"es":["herramientas de revisión de contenido","agentes de IA para revisión","revisión de gramática y estilo","estructura de temas y claridad","cómo revisar contenido","mejores prácticas de revisión","revisión de contenido en inglés","revisión de contenido con AI","herramientas de autoría de contenido"],"fr":["outils de révision de contenu","agents IA pour la révision","révision de grammaire et de style","structure des sujets et clarté","comment réviser du contenu","meilleures pratiques de révision","révision de contenu en anglais","révision de contenu avec IA","outils d''authoring de contenu"],"de":["Inhalts-Review-Tools","KI-Agents für die Überprüfung","Überprüfung von Grammatik und Stil","Themenstruktur und Klarheit","wie man Inhalte überprüft","beste Praktiken für die Überprüfung","Inhalts-Review auf Englisch","Inhalts-Review mit KI","Content-Authoring-Tools"],"pt":["revisão de conteúdo","desenvolvimento de software","qualidade de código","gramática e estilo","autorização de conteúdo","escrita em inglês","ferramentas de desenvolvimento"],"ru":["проверка контента","разработка программного обеспечения","качество кода","грамматика и стиль","авторизация контента","написание на английском языке","инструменты разработки"],"ar":["أداة الاستعراض","تطوير البرمجيات","جودة الكود","النحو والأسلوب","تصريح المحتوى","الكتابة باللغة الإنجليزية","أدوات التطوير"]}},"owner":"zlliang","repo":"zlliang","repoPath":"zlliang/zlliang","stars":4,"forks":0,"updatedAt":"2026-02-27T06:20:14Z","topics":[],"category":"community","skillMd":{"name":"reviewing","description":"Reviews drafts for grammar, style, phrasing, clarity, and structure. Use when asked to review a draft or article.","bodyPreview":"# Reviewing\n\nReview the draft for:\n\n1. Grammar and writing style issues\n2. Awkward or unnatural phrasing\n3. Topic clarity and overall content structure\n\nLoad the `content-authoring` skill. Also load `english-writing` if the draft is in English. Respond in the draft''s language.","body":"# Reviewing\n\nReview the draft for:\n\n1. Grammar and writing style issues\n2. Awkward or unnatural phrasing\n3. Topic clarity and overall content structure\n\nLoad the `content-authoring` skill. Also load `english-writing` if the draft is in English. Respond in the draft''s language.\n"},"lastSynced":"2026-03-06T06:58:10.735Z","agentAnalysis":{"suitability":{"en":"Ideal for Language Agents requiring precise content refinement through grammar and writing style analysis.","zh":"适合需要通过语法和写作风格分析来精确改进内容的语言代理。","ja":"言語エージェントが文法や文章スタイルの分析を通じてコンテンツを精密に改良する必要がある場合に適しています。","ko":"언어 에이전트가 문법 및 글쓰기 스타일 분석을 통해 콘텐츠를 정밀하게 개선해야 하는 경우에 적합합니다.","es":"Ideal para Agentes de Lenguaje que requieren un refinamiento preciso de contenido a través del análisis de gramática y estilo de escritura.","fr":"Idéal pour les Agents de Langage nécessitant un affinement précis du contenu grâce à l''analyse de la grammaire et du style d''écriture.","de":"Ideal für Sprachagenten, die eine präzise Inhaltsverfeinerung durch Grammatik- und Schreibstilanalyse erfordern.","pt":"Ideal para Agentes de Linguagem que requerem refino preciso de conteúdo por meio de análise de gramática e estilo de escrita.","ru":"Идеально для языковых агентов, требующих точного уточнения контента посредством анализа грамматики и стиля письма.","ar":"مثالي للوكلاء اللغويين الذين يتطلبون تعديل دقيق للمحتوى من خلال تحليل القواعد والنص"},"recommendation":{"en":"Empowers agents to refine content by checking for grammar, writing style, and topic clarity issues, utilizing natural language processing to enhance readability and coherence, and supporting multiple languages through conditional loading of language-specific skills like english-writing.","zh":"赋予代理能力，通过检查语法、写作风格和主题清晰度问题，利用自然语言处理来增强可读性和连贯性，并支持多语言，通过条件加载语言特定的技能，如 english-writing。","ja":"エージェントが文法、文章スタイル、トピックの明確性の問題をチェックすることでコンテンツを改良できるようにし、自然言語処理を利用して可読性と連貫性を高め、条件付きでロードされる言語特有のスキル seperti english-writing を通じて複数の言語をサポートします。","ko":"에이전트가 문법, 글쓰기 스타일, 주제 명확성 문제를 확인하여 콘텐츠를 개선할 수 있도록 하며, 자연어 처리를 활용하여 가독성과 일관성을 향상시키고, english-writing과 같은 언어별 특정 스킬을 조건부 로딩하여 다중 언어를 지원합니다.","es":"Habilita a los agentes a refinar el contenido mediante la comprobación de errores de gramática, estilo de escritura y claridad de tema, utilizando el procesamiento de lenguaje natural para mejorar la legibilidad y coherencia, y admitiendo varios idiomas a través de la carga condicional de habilidades específicas de lenguaje como english-writing.","fr":"Permet aux agents d''affiner le contenu en vérifiant les problèmes de grammaire, de style d''écriture et de clarté de sujet, en utilisant le traitement automatique des langues pour améliorer la lisibilité et la cohérence, et en prenant en charge plusieurs langues via le chargement conditionnel de compétences spécifiques à la langue comme english-writing.","de":"Ermächtigt die Agenten, den Inhalt durch Überprüfung von Grammatik-, Schreibstil- und Themenklarheitsproblemen zu verfeinern, indem sie die natürliche Sprachverarbeitung nutzen, um Lesbarkeit und Kohärenz zu verbessern, und mehrere Sprachen durch bedingte Ladung von sprachspezifischen Fähigkeiten wie english-writing zu unterstützen.","pt":"Habilita os agentes a refinar o conteúdo, verificando problemas de gramática, estilo de escrita e clareza de tópico, utilizando processamento de linguagem natural para melhorar a legibilidade e a coerência, e suportando vários idiomas por meio do carregamento condicional de habilidades específicas de idioma, como inglês-escrita.","ru":"Наделяет агентов возможностью уточнять контент, проверяя на наличие проблем с грамматикой, стилем письма и ясностью темы, используя обработку естественного языка для улучшения читаемости и связности, и поддерживая несколько языков за счет условной загрузки языково-специфических навыков, таких как английское письмо.","ar":"تمكّن الوكلاء من تعديل المحتوى عن طريق التحقق من مشاكل القواعد وأسلوب الكتابة ووضوح الموضوع، واستخدام معالجة اللغة الطبيعية لتحسين القراءة والترابط، ودعم اللغات المتعددة من خلال تحميل مهارات محددة للغة بشكل مشروط، مثل الكتابة باللغة الإنجليزية."},"useCases":{"en":["Refining technical documentation for clarity","Debugging grammar issues in auto-generated content","Enhancing topic structure in articles and blog posts"],"zh":["改进技术文档的清晰度","调试自动生成内容中的语法问题","增强文章和博客帖子的主题结构"],"ja":["技術文書の明確性を高める","自動生成コンテンツの文法の問題をデバッグする","記事やブログ投稿のトピック構造を強化する"],"ko":["기술 문서의 명확성을 높이는こと","자동 생성 콘텐츠의 문법 문제를 디버깅하는 것","기사 및 블로그 게시물의 주제 구조를 강화하는 것"],"es":["Refinamiento de documentación técnica para mayor claridad","Depuración de errores de gramática en contenido generado automáticamente","Mejora de la estructura de temas en artículos y publicaciones de blogs"],"fr":["Affinement de la documentation technique pour plus de clarté","Débogage des problèmes de grammaire dans le contenu généré automatiquement","Amélioration de la structure de sujet dans les articles et les billets de blog"],"de":["Verfeinerung von technischer Dokumentation für bessere Klarheit","Fehlerbehebung bei Grammatikfehlern in automatisch generiertem Inhalt","Verbesserung der Themenstruktur in Artikeln und Blog-Beiträgen"],"pt":["Refinamento de documentação técnica para clareza","Depuração de problemas de gramática em conteúdo gerado automaticamente","Melhoria da estrutura de tópicos em artigos e posts de blog"],"ru":["Уточнение технической документации для ясности","Отладка проблем с грамматикой в автоматически сгенерированном контенте","Улучшение структуры тем в статьях и блогах"],"ar":["تعديل الوثائق الفنية لزيادة الوضوح","تصحيح مشاكل القواعد في المحتوى المولّد آليًا","تحسين هيكل المواضيع في المقالات ومنشورات المدونة"]},"limitations":{"en":["Requires loading of content-authoring skill","Language-specific skills like english-writing may be necessary for non-English content"],"zh":["需要加载内容创作技能","可能需要加载语言特定的技能，如 english-writing，以支持非英语内容"],"ja":["コンテンツ作成スキルをロードする必要がある","英語以外のコンテンツをサポートするために、english-writing などの言語特有のスキルをロードする必要があるかもしれない"],"ko":["콘텐츠 작성 스킬을 로딩해야 함","영어 이외의 콘텐츠를 지원하기 위해 english-writing과 같은 언어별 특정 스킬을 로딩해야 할 수 있음"],"es":["Requiere la carga de la habilidad de creación de contenido","Las habilidades específicas de lenguaje como english-writing pueden ser necesarias para contenido no en inglés"],"fr":["Nécessite le chargement de la compétence de création de contenu","Les compétences spécifiques à la langue comme english-writing peuvent être nécessaires pour le contenu non anglais"],"de":["Erfordert das Laden der Inhalts-Erstellungsfähigkeit","Sprachspezifische Fähigkeiten wie english-writing können für nicht-englischen Inhalt erforderlich sein"],"pt":["Requer carregamento de habilidade de autorização de conteúdo","Habilidades específicas de idioma, como inglês-escrita, podem ser necessárias para conteúdo não em inglês"],"ru":["Требует загрузки навыка создания контента","Языково-специфические навыки, такие как английское письмо, могут быть необходимы для неанглийского контента"],"ar":["يتطلب تحميل مهارة صياغة المحتوى","مهارات محددة للغة، مثل الكتابة باللغة الإنجليزية، قد تكون ضرورية للمحتوى غير الإنجليزي"]},"version":4},"contentHash":"f8ac3a65bd59ff27ea435c18bca09684d631cd5bfa55dc35e7b2b2d5f62c3b31","qualityScore":20}');
