INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zlliang/zlliang/reviewing', 'reviewing', 'zlliang', 'zlliang', 'community', 'reviewing zlliang zlliang community The reviewing skill helps developers refine their content by checking for grammar, writing style, and topic clarity issues, benefiting programmers and writers alike. AI工具审查功能可以帮助开发者优化编程和写作中的语法、写作风格和内容结构问题 AIエージェントのレビュー機能は、開発者がプログラミングと文章作成における文法、文章スタイル、コンテンツ構造の問題を最適化するのに役立ちます AI 에이전트의 리뷰 기능은 개발자가 프로그래밍 및 작성을 개선하고, 문법, 작성 스타일 및 콘텐츠 구조의 문제를 최적화하는 데 도움을 줍니다 Revisar contenido implica verificar la gramática, el estilo de escritura y la estructura de temas para asegurar la claridad La révision de contenu implique la vérification de la grammaire, du style d''écriture et de la structure des sujets pour assurer la clarté Die Überprüfung von Inhalten beinhaltet die Prüfung von Grammatik, Schreibstil und Themenstruktur, um Klarheit zu gewährleisten A revisão de conteúdo é uma habilidade que ajuda a melhorar a qualidade do texto e do código, verificando erros de gramática e estilo. Проверка контента - это навык, который помогает улучшить качество текста и кода, проверяя ошибки грамматики и стиля. أداة الاستعراض هي ميزة تساعد على تحسين جودة النص والكود، من خلال التحقق من الأخطاء النحوية والأسلوبية. how to use reviewing what is reviewing reviewing alternative reviewing vs proofreading reviewing install guide reviewing setup for AI agents content optimization techniques english writing skills for developers grammar and clarity checking tools AI工具审查 编程优化 写作优化 语法检查 内容结构分析 content-authoring english-writing AI审查工具 代码审查 Checks for grammar and writing style issues in content Examines content for awkward or unnatural phrasing Evaluates topic clarity and overall content structure Loads content-authoring skill for comprehensive review Utilizes english-writing skill for English language drafts Responds in the draft''s language for seamless integration Reviewing is the process of examining content for grammar and writing style issues, awkward phrasing, and topic clarity, to improve overall content structure.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('connerohnesorge/spectr/spectr-apply', 'community', 'connerohnesorge', 'spectr', 'connerohnesorge/spectr', 'spectr-apply', 3, 2, 20, '2026-02-04T14:23:44Z', '2026-03-06T07:01:18.627Z', '1c0c89270b43b9a17f4ad673bc3363e4777830ea6f4ae32fc567a690a28c25d5', '{"id":"connerohnesorge/spectr/spectr-apply","name":"spectr-apply","description":{"en":"spectr-apply enables developers to implement validatable spec driven development, inspired by openspec and kiro, for efficient and straightforward project management. It benefits developers working with Golang, CLI, and TUI.","zh":"spectr-apply是一种有效的Spec驱动开发工具，使用开源规范和Kiro进行开发","ja":"spectr-applyは、オープンソースの規格とKiroを使用したSpec駆動開発ツールです","ko":"spectr-apply는 오픈 소스 규격과 Kiro를 사용한 Spec 주도 개발 도구입니다","es":"spectr-apply es una herramienta de desarrollo dirigido por especificaciones que utiliza validación de especificaciones y CLI de Golang para agilizar el proceso de desarrollo","fr":"spectr-apply est un outil de développement dirigé par spécifications qui utilise la validation de spécifications et la CLI Golang pour accélérer le processus de développement","de":"spectr-apply ist ein Tool für spezifikationsgesteuerte Entwicklung, das die Validierung von Spezifikationen und die Golang-CLI verwendet, um den Entwicklungsprozess zu beschleunigen","pt":"O spectr-apply é uma ferramenta para desenvolvimento dirigido por especificações inspirada em openspec e kiro","ru":"spectr-apply - это инструмент для спецификации-ориентированного разработки, вдохновленный openspec и kiro для ИИ Агентов","ar":"spectr-apply هو أداة لتطوير الإرشادات الموثوقة بالاعتماد على مواصفات مستوحاة من openspec و kiro"},"seo":{"title":{"en":"spectr-apply: Validatable Spec Driven Development Setup G...","zh":"spectr-apply Setup Guide: AIエージェント开发最佳实践","ja":"spectr-apply セットアップガイド: AIエージェント開発のベストプラクティス","ko":"spectr-apply 설정 가이드: AI 에이전트 개발 모범 사례","es":"Guía de configuración de spectr-apply para desarrollo dir...","fr":"Guide de configuration de spectr-apply pour le développem...","de":"Konfigurationsleitfaden für spectr-apply zur spezifikatio...","pt":"Guia de Configuração do spectr-apply para Desenvolvimento...","ru":"Настройка spectr-apply для Спецификации-ориентированного ...","ar":"دليل إعداد spectr-apply لتطوير الإرشادات الموثوقة بالاعتم..."},"description":{"en":"Unlock efficient development with spectr-apply. Learn how to apply validatable spec driven development principles with our expert guide and streamline your w...","zh":"了解spectr-apply的有效开发实践，使用开源规范和Kiro进行Spec驱动开发","ja":"spectr-applyの有効な開発実践について学び、オープンソースの規格とKiroを使用したSpec駆動開発を実現する","ko":"spectr-apply의有效한 개발 실무를 배우고, 오픈 소스 규격과 Kiro를 사용한 Spec 주도 개발을 구현하세요","es":"Aprende a utilizar spectr-apply para agilizar tu desarrollo con validación de especificaciones y CLI de Golang","fr":"Découvrez comment utiliser spectr-apply pour accélérer votre développement avec validation de spécifications et CLI Golang","de":"Erfahren Sie, wie Sie spectr-apply verwenden, um Ihre Entwicklung mit Spezifikationsvalidierung und Golang-CLI zu beschleunigen","pt":"Aprenda a configurar o spectr-apply para desenvolvimento dirigido por especificações com bubbletea, cli e golang","ru":"Узнайте, как настроить spectr-apply для спецификации-ориентированного разработки с bubbletea, cli и golang для ИИ Агентов","ar":"تعرف على كيفية إعداد spectr-apply لتطوير الإرشادات الموثوقة بالاعتماد على مواصفات باستخدام bubbletea و cli و golang"},"definition":{"en":"spectr-apply is a validatable spec driven development tool inspired by openspec and kiro, designed to simplify development processes with minimal implementations and tightly scoped changes.","zh":"spectr-apply是一种AI工具，用于Spec驱动开发和有效开发实践","ja":"spectr-applyは、Spec駆動開発と有効な開発実践を実現するAIエージェントです","ko":"spectr-apply는 Spec 주도 개발과 효과적인 개발 실무를 위한 AI 에이전트입니다","es":"spectr-apply es una herramienta de desarrollo que aplica principios de validación de especificaciones para agilizar el proceso de desarrollo","fr":"spectr-apply est un outil de développement qui applique les principes de validation de spécifications pour accélérer le processus de développement","de":"spectr-apply ist ein Entwicklungstool, das die Prinzipien der Spezifikationsvalidierung anwendet, um den Entwicklungsprozess zu beschleunigen","pt":"O que é spectr-apply? Uma ferramenta para desenvolvimento dirigido por especificações","ru":"Что такое spectr-apply? Инструмент для спецификации-ориентированного разработки ИИ Агентов","ar":"ما هو spectr-apply? أداة لتطوير الإرشادات الموثوقة بالاعتماد على مواصفات"},"features":{"en":["Runs `spectr acc` command for change proposal application and acceptance","Follows Guardrails principles for straightforward and minimal implementations","Supports spec-driven-development (SDD) with openspec and kiro inspirations","Utilizes CLI and TUI for efficient project management","References `spectr/AGENTS.md` and `spectr/project.md` for project conventions","Tracks TODOs with step-by-step completion for streamlined development"],"zh":["使用开源规范进行Spec驱动开发","支持Kiro和Bubbletea","提供命令行接口（CLI）","实现有效的开发实践和守护","支持TUI和Kong-CLI"],"ja":["オープンソースの規格を使用したSpec駆動開発","KiroとBubbleteaのサポート","コマンドラインインターフェース（CLI）を提供","有効な開発実践とガードレールの実現","TUIとKong-CLIのサポート"],"ko":["오픈 소스 규격을 사용한 Spec 주도 개발","Kiro와 Bubbletea의 지원","명령 줄 인터페이스（CLI）제공","유효한 개발 실무와 가드레일의 구현","TUI와 Kong-CLI의 지원"],"es":["Validación de especificaciones inspirada en openspec y kiro","Desarrollo dirigido por especificaciones con CLI de Golang","Implementaciones minimalistas y enfocadas en el resultado","Integración con bubbletea y kong-cli","Proceso de cambio con guardrails para evitar la complejidad"],"fr":["Validation de spécifications inspirée par openspec et kiro","Développement dirigé par spécifications avec CLI Golang","Implémentations minimalistes et axées sur le résultat","Intégration avec bubbletea et kong-cli","Processus de changement avec des guardrails pour éviter la complexité"],"de":["Validierung von Spezifikationen inspiriert von openspec und kiro","Spezifikationsgesteuerte Entwicklung mit Golang-CLI","Minimalistische und ergebnisorientierte Implementierungen","Integration mit bubbletea und kong-cli","Änderungsprozess mit Schutzmechanismen zur Vermeidung von Komplexität"],"pt":["Desenvolvimento dirigido por especificações com inspiração em openspec e kiro","Integração com bubbletea para interfaces de usuário","Suporte a cli para operações de linha de comando","Implementação em golang para desempenho e escalabilidade","Processo de aplicação de propostas de alteração com guardrails","Suporte a tui para interfaces de usuário de texto"],"ru":["Спецификация-ориентированное разработка с вдохновением от openspec и kiro для ИИ Агентов","Интеграция с bubbletea для интерфейсов пользователя","Поддержка cli для операций командной строки","Реализация на golang для производительности и масштабируемости","Процесс применения предложений изменений с guardrails","Поддержка tui для интерфейсов пользователя текста"],"ar":["تطوير الإرشادات الموثوقة بالاعتماد على مواصفات مستوحاة من openspec و kiro","التكامل مع bubbletea ل_interfaces المستخدم","دعم cli لعمليات سطر الأوامر","تنفيذ في golang لأداء وقابلية للتوسع","عملية تطبيق مقترحات التغيير مع guardrails","دعم tui ل_interfaces المستخدم النصية"]},"keywords":{"en":["how to use spectr-apply","spectr-apply setup guide","spectr-apply vs openspec","what is spectr-apply","spectr-apply install","spectr-apply alternative","spectr-apply and kiro","spectr-apply for Golang developers","spectr-apply CLI commands","spectr-apply TUI integration"],"zh":["spectr-apply","Spec驱动开发","AI工具","开源规范","Kiro","Bubbletea","CLI","TUI","Kong-CLI"],"ja":["spectr-apply","Spec駆動開発","AIエージェント","オープンソースの規格","Kiro","Bubbletea","CLI","TUI","Kong-CLI"],"ko":["spectr-apply","Spec 주도 개발","AI 에이전트","오픈 소스 규격","Kiro","Bubbletea","CLI","TUI","Kong-CLI"],"es":["desarrollo dirigido por especificaciones","validación de especificaciones","CLI de Golang","openspec","kiro","bubbletea","kong-cli","especificaciones de software","desarrollo de software ágil"],"fr":["développement dirigé par spécifications","validation de spécifications","CLI Golang","openspec","kiro","bubbletea","kong-cli","spécifications de logiciel","développement de logiciel agile"],"de":["spezifikationsgesteuerte Entwicklung","Validierung von Spezifikationen","Golang-CLI","openspec","kiro","bubbletea","kong-cli","Software-Spezifikationen","agile Software-Entwicklung"],"pt":["desenvolvimento dirigido por especificações","spectr-apply","openspec","kiro","bubbletea","cli","golang","tui","validatable spec driven development"],"ru":["спецификация-ориентированное разработка","spectr-apply","openspec","kiro","bubbletea","cli","golang","tui","ИИ Агенты","validatable spec driven development"],"ar":["تطوير الإرشادات الموثوقة بالاعتماد على مواصفات","spectr-apply","openspec","kiro","bubbletea","cli","golang","tui","أدوات الذكاء الاصطناعي","validatable spec driven development"]}},"owner":"connerohnesorge","repo":"spectr","repoPath":"connerohnesorge/spectr","stars":3,"forks":2,"updatedAt":"2026-02-04T14:23:44Z","topics":["bubbletea","cli","golang","kiro","kong-cli","openspec","sdd","spec-driven-development","tui"],"category":"community","skillMd":{"name":"spectr-apply","description":"Apply or accept a change proposal and implement its tasks","bodyPreview":"# Change Proposal Application/Acceptance Process\n\n## Guardrails\n\n- Favor straightforward, minimal implementations first and add complexity only\n  when it is requested or clearly required.\n- Keep changes tightly scoped to the requested outcome.\n- Refer to `spectr/AGENTS.md` and `spectr/project.md` (located inside\n  the `spectr/` directory—run `ls spectr`) for project and\n  Spectr conventions or clarifications.\n\n## Steps\n\nTrack these steps as TODOs and complete them one by one.\n\n1. Run `spectr acc","body":"# Change Proposal Application/Acceptance Process\n\n## Guardrails\n\n- Favor straightforward, minimal implementations first and add complexity only\n  when it is requested or clearly required.\n- Keep changes tightly scoped to the requested outcome.\n- Refer to `spectr/AGENTS.md` and `spectr/project.md` (located inside\n  the `spectr/` directory—run `ls spectr`) for project and\n  Spectr conventions or clarifications.\n\n## Steps\n\nTrack these steps as TODOs and complete them one by one.\n\n1. Run `spectr accept <id>` to convert `tasks.md` to `tasks.jsonc` format for\n   stable task tracking. Note: Both `tasks.md` (human-readable source) and\n   `tasks.jsonc` (runtime source of truth) coexist after accept—update task\n   statuses in `tasks.jsonc`.\n2. Read `spectr/changes/<id>/proposal.md`, `design.md` (if present), and\n   `tasks.jsonc` to confirm scope and acceptance criteria.\n3. Work through tasks sequentially, keeping edits minimal and focused on the\n   requested change. Update the task status in `tasks.jsonc` after verifying\n   the work.\n4. Confirm completion before updating statuses—make sure every item in\n   `tasks.jsonc` is finished.\n5. Verify/Update all task status in `tasks.jsonc` after all work is done. Tasks\n   have status values: `pending`, `in_progress`, `completed`.\n6. Read `spectr/changes/` and `spectr/specs/` directories when additional\n   context is required.\n\n## Reference\n\n- Read `spectr/changes/<id>/proposal.md` for proposal details.\n- Read `spectr/changes/<id>/specs/<capability>/spec.md` for delta specs.\n"},"lastSynced":"2026-03-06T07:01:18.627Z","agentAnalysis":{"suitability":{"en":"Perfect for Golang and CLI-focused Agents needing efficient project management through spec-driven development.","zh":"非常适合需要通过规范驱动开发实现高效项目管理的Golang和CLI专注的Agent。","ja":"GolangとCLIに焦点を当てたエージェントが、仕様駆動開発を通じてプロジェクト管理を効率的に行う必要がある場合に最適です。","ko":"Golang과 CLI에 중점을 둔 에이전트가 규격 구동 개발을 통해 프로젝트 관리를 효율적으로 수행해야 하는 경우에 적합합니다.","es":"Perfecto para agentes de Golang y CLI que necesitan una gestión de proyectos eficiente a través del desarrollo dirigido por especificaciones.","fr":"Parfait pour les agents Golang et CLI qui nécessitent une gestion de projet efficace via le développement dirigé par spécifications.","de":"Perfekt für Golang- und CLI-Agents, die eine effiziente Projektverwaltung durch spezifikationsgetriebene Entwicklung benötigen.","pt":"Perfeito para Agentes Golang e CLI que necessitam de gerenciamento de projetos eficiente por meio do desenvolvimento orientado por especificações.","ru":"Идеально подходит для агентов Golang и CLI, которым необходим эффективный менеджмент проектов через разработку, управляемую спецификациями.","ar":"مثالي لعميل Golang و CLI الذي يحتاج إلى إدارة مشاريع فعالة من خلال التطوير القائم على المواصفات."},"recommendation":{"en":"Empowers agents to implement validatable spec-driven development using openspec and kiro inspirations, streamlining project management with straightforward and minimal implementations, while supporting Golang, CLI, and TUI environments through spectr-apply.","zh":"赋予代理实现使用openspec和kiro灵感的有效的规范驱动开发，通过简洁和最小化的实现来简化项目管理，同时支持Golang、CLI和TUI环境通过spectr-apply。","ja":"エージェントに、openspecとkiroのインスピレーションを使用した有効な仕様駆動開発を実装する力を与え、プロジェクト管理を簡素化し、最小限の実装でGolang、CLI、TUI環境をspectr-applyを通じてサポートします。","ko":"에이전트가 openspec과 kiro의 영감을 사용하여 유효한 규격 구동 개발을 구현할 수 있도록 하며, 프로젝트 관리를 간소화하고, 최소한의 구현으로 Golang, CLI, TUI 환경을 spectr-apply를 통해 지원합니다.","es":"Habilita a los agentes a implementar un desarrollo dirigido por especificaciones validables utilizando inspiraciones de openspec y kiro, simplificando la gestión de proyectos con implementaciones directas y mínimas, y apoyando entornos de Golang, CLI y TUI a través de spectr-apply.","fr":"Permet aux agents de mettre en œuvre un développement dirigé par spécifications validables en utilisant des inspirations openspec et kiro, en rationalisant la gestion de projet avec des implementations directes et minimales, et en prenant en charge les environnements Golang, CLI et TUI via spectr-apply.","de":"Ermächtigt Agenten, ein spezifikationsgetriebenes Entwicklung mit validierbaren Spezifikationen mithilfe von openspec- und kiro-Inspirationen umzusetzen, wodurch die Projektverwaltung durch direkte und minimale Implementierungen rationalisiert wird und Golang-, CLI- und TUI-Umgebungen über spectr-apply unterstützt werden.","pt":"Habilita os agentes a implementar desenvolvimento orientado por especificações validáveis usando inspirações openspec e kiro, simplificando o gerenciamento de projetos com implementações diretas e mínimas, mantendo suporte a ambientes Golang, CLI e TUI por meio do spectr-apply.","ru":"Позволяет агентам реализовывать валидируемое разработку, управляемую спецификациями, используя идеи openspec и kiro, оптимизируя менеджмент проектов посредством прямых и минимальных реализаций, поддерживая среды Golang, CLI и TUI через spectr-apply.","ar":"تمكّن العميل من تنفيذ تطوير قائم على المواصفات صالحة للتحقق باستخدام إلهامات openspec و kiro، وبذلك يُبسّط إدارة المشاريع من خلال التطبيقات المباشرة والحد الأدنى، مع دعم بيئات Golang و CLI و TUI من خلال spectr-apply."},"useCases":{"en":["Automating project management workflows","Generating validatable specifications for Golang projects","Implementing efficient CLI and TUI interfaces for spec-driven development"],"zh":["自动化项目管理工作流程","为Golang项目生成有效的规范","为规格驱动开发实现高效的CLI和TUI接口"],"ja":["プロジェクト管理ワークフローの自動化","Golangプロジェクトのための有効な仕様の生成","仕様駆動開発のための効率的なCLIとTUIインターフェイスの実装"],"ko":["프로젝트 관리 워크플로 자동화","Golang 프로젝트를 위한 유효한 규격 생성","규격 구동 개발을 위한 효율적인 CLI와 TUI 인터페이스 구현"],"es":["Automatizar flujos de trabajo de gestión de proyectos","Generar especificaciones validables para proyectos de Golang","Implementar interfaces eficientes de CLI y TUI para el desarrollo dirigido por especificaciones"],"fr":["Automatiser les flux de travail de gestion de projet","Générer des spécifications validables pour les projets Golang","Mettre en œuvre des interfaces CLI et TUI efficaces pour le développement dirigé par spécifications"],"de":["Automatisierung von Projektmanagement-Workflows","Erzeugen von validierbaren Spezifikationen für Golang-Projekte","Implementierung effizienter CLI- und TUI-Schnittstellen für die spezifikationsgetriebene Entwicklung"],"pt":["Automatizar fluxos de trabalho de gerenciamento de projetos","Gerar especificações válidas para projetos Golang","Implementar interfaces CLI e TUI eficientes para desenvolvimento orientado por especificações"],"ru":["Автоматизировать рабочие процессы менеджмента проектов","Генерировать валидные спецификации для проектов Golang","Реализовывать эффективные интерфейсы CLI и TUI для разработки, управляемой спецификациями"],"ar":["آلية워크 اتوماتيكية لإدارة المشاريع","توليد مواصفات صالحة للمشاريع Golang","تنفيذ واجهات CLI و TUI فعالة لتطوير قائم على المواصفات"]},"limitations":{"en":["Requires Golang environment","Favors minimal implementations with potential added complexity","Scoped to spectr and openspec conventions"],"zh":["需要Golang环境","偏爱最小化实现，可能增加复杂性","仅限于spectr和openspec约定"],"ja":["Golang環境が必要","最小限の実装を偏愛し、複雑性が増加する可能性がある","spectrとopenspecの規約のみに限定"],"ko":["Golang 환경이 필요","최소한의 구현을 선호하며, 복잡성이 증가할 수 있음","spectr와 openspec 규약에만 한정"],"es":["Requiere un entorno de Golang","Favorece implementaciones mínimas con complejidad potencialmente agregada","Limitado a las convenciones de spectr y openspec"],"fr":["Nécessite un environnement Golang","Privilégie les implementations minimales avec une complexité potentiellement ajoutée","Limité aux conventions de spectr et openspec"],"de":["Erfordert eine Golang-Umgebung","Bevorzugt minimale Implementierungen mit potenziell hinzugefügter Komplexität","Eingeschränkt auf die Konventionen von spectr und openspec"],"pt":["Requer ambiente Golang","Favor implementações mínimas com complexidade potencialmente adicionada","Limitado às convenções spectr e openspec"],"ru":["Требуется среда Golang","Отдаёт предпочтение минимальным реализациям с потенциально добавленной сложностью","Ограничен конвенциями spectr и openspec"],"ar":["يتطلب بيئة Golang","يفضل التطبيقات المحدودة مع إمكانية إضافة تعقيدات","محدود بالاتفاقيات spectr و openspec"]},"version":4},"contentHash":"1c0c89270b43b9a17f4ad673bc3363e4777830ea6f4ae32fc567a690a28c25d5","qualityScore":20}');
