INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('connerohnesorge/spectr/spectr-apply', 'spectr-apply', 'connerohnesorge', 'spectr', 'community', 'spectr-apply connerohnesorge spectr community bubbletea cli golang kiro kong-cli openspec sdd spec-driven-development tui spectr-apply enables developers to implement validatable spec driven development, inspired by openspec and kiro, for efficient and straightforward project management. It benefits developers working with Golang, CLI, and TUI. spectr-apply是一种有效的Spec驱动开发工具，使用开源规范和Kiro进行开发 spectr-applyは、オープンソースの規格とKiroを使用したSpec駆動開発ツールです spectr-apply는 오픈 소스 규격과 Kiro를 사용한 Spec 주도 개발 도구입니다 spectr-apply es una herramienta de desarrollo dirigido por especificaciones que utiliza validación de especificaciones y CLI de Golang para agilizar el proceso de desarrollo spectr-apply est un outil de développement dirigé par spécifications qui utilise la validation de spécifications et la CLI Golang pour accélérer le processus de développement spectr-apply ist ein Tool für spezifikationsgesteuerte Entwicklung, das die Validierung von Spezifikationen und die Golang-CLI verwendet, um den Entwicklungsprozess zu beschleunigen O spectr-apply é uma ferramenta para desenvolvimento dirigido por especificações inspirada em openspec e kiro spectr-apply - это инструмент для спецификации-ориентированного разработки, вдохновленный openspec и kiro для ИИ Агентов spectr-apply هو أداة لتطوير الإرشادات الموثوقة بالاعتماد على مواصفات مستوحاة من openspec و kiro how to use spectr-apply spectr-apply setup guide spectr-apply vs openspec what is spectr-apply spectr-apply install spectr-apply alternative spectr-apply and kiro spectr-apply for Golang developers spectr-apply CLI commands spectr-apply TUI integration spectr-apply Spec驱动开发 AI工具 开源规范 Kiro Bubbletea CLI TUI Kong-CLI Runs `spectr acc` command for change proposal application and acceptance Follows Guardrails principles for straightforward and minimal implementations Supports spec-driven-development (SDD) with openspec and kiro inspirations Utilizes CLI and TUI for efficient project management References `spectr/AGENTS.md` and `spectr/project.md` for project conventions Tracks TODOs with step-by-step completion for streamlined development spectr-apply is a validatable spec driven development tool inspired by openspec and kiro, designed to simplify development processes with minimal implementations and tightly scoped changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('detorresramos/CaramelDB/catching-up', 'community', 'detorresramos', 'CaramelDB', 'detorresramos/CaramelDB', 'catching-up', 3, 0, 20, '2026-03-04T05:00:34Z', '2026-03-06T07:03:16.049Z', '6494ee99dc75d5f671924d207fc31fd9026e85c7b6af2b63208a9dd2c1c033eb', '{"id":"detorresramos/CaramelDB/catching-up","name":"catching-up","description":{"en":"The catching-up skill analyzes the current state of a git branch, focusing on actual code changes. It benefits developers by summarizing additions, removals, and modifications made to the codebase.","zh":"catching-up工具用于获取当前分支的状态，包括代码变更和提交历史","ja":"catching-up AIエージェントは、現在のブランチの状態を把握するためのツールです","ko":"catching-up 도구는 현재 브랜치의 상태를 파악하고 코드 변경 사항을 확인합니다","es":"El skill ''catching-up'' te permite entender los cambios de código en una rama mediante la ejecución de comandos git","fr":"Le skill ''catching-up'' vous permet de comprendre les modifications de code dans une branche en exécutant des commandes git","de":"Der Skill ''catching-up'' ermöglicht es Ihnen, Code-Änderungen in einem Branch durch Ausführen von Git-Befehlen zu verstehen","pt":"O Catching-up ajuda desenvolvedores a entender as alterações de código em um branch. Veja como usar git diff para resumir as mudanças.","ru":"Catching-up помогает разработчикам понять изменения кода в ветке. Узнайте, как использовать git diff для сводки изменений с ИИ Агентами","ar":"يُساعد Catching-up المطورين على فهم التغييرات في الكود في فرع. تعلم كيفية استخدام git diff لملخص للتغييرات مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"catching-up: Git Branch Analysis for AI Agents | AI Agent...","zh":"catching-up 工具快速入门","ja":"catching-up AIエージェントの設定方法","ko":"catching-up 도구 사용법 및 가이드","es":"Guía de configuración de ''catching-up'' para desarrolladores","fr":"Mise en route de ''catching-up'' pour les développeurs","de":"Einrichtungsleitfaden für ''catching-up'' für Entwickler","pt":"Guia de Configuração do Catching-up para Desenvolvedores","ru":"Настройка Catching-up: Руководство для Разработчиков с ИИ...","ar":"دليل إعداد Catching-up للبرمجة مع أدوات الذكاء الاصطناعي"},"description":{"en":"Get up to speed with catching-up, the AI agent skill that analyzes git branches. Learn how to understand code changes with git diff and improve your developm...","zh":"了解catching-up工具的功能和技术细节，快速上手","ja":"catching-up AIエージェントの使い方と特徴を紹介","ko":"catching-up 도구의 기능과 사용 방법을 알아보세요","es":"Aprende a utilizar ''catching-up'' para entender los cambios de código en una rama","fr":"Découvrez comment utiliser ''catching-up'' pour comprendre les modifications de code dans une branche","de":"Erfahren Sie, wie Sie ''catching-up'' verwenden, um Code-Änderungen in einem Branch zu verstehen","pt":"Aprenda a usar o Catching-up para entender as alterações de código em um branch com git diff e resumo das mudanças","ru":"Узнайте, как использовать Catching-up для понимания изменений кода в ветке с помощью git diff и сводки изменений с ИИ Агентами","ar":"تعلم كيفية استخدام Catching-up لفهم التغييرات في الكود في فرع مع git diff وملخص للتغييرات مع أدوات الذكاء الاصطناعي"},"definition":{"en":"catching-up is a git branch analysis skill that uses git diff to understand code changes and provide a summary of what was added, removed, or modified","zh":"catching-up工具是一种用于获取当前分支状态的技术工具","ja":"catching-up AIエージェントは、現在のブランチの状態を把握するための技術ツールです","ko":"catching-up 도구는 현재 브랜치의 상태를 파악하는 기술 도구입니다","es":"¿Qué es ''catching-up''? Un skill de AI que resume los cambios de código en una rama","fr":"Qu''est-ce que ''catching-up''? Un skill d''IA qui résume les modifications de code dans une branche","de":"Was ist ''catching-up''? Ein AI-Skill, der Code-Änderungen in einem Branch zusammenfasst","pt":"O Catching-up é uma ferramenta que resume as alterações de código em um branch","ru":"Catching-up - это инструмент, который сводит изменения кода в ветке с ИИ Агентами","ar":"Catching-up هو أداة تُقدم ملخصًا للتغييرات في الكود في فرع مع أدوات الذكاء الاصطناعي"},"features":{"en":["Runs git diff to identify changed files","Analyzes git diff output to understand code changes","Provides a summary of additions, removals, and modifications","Groups related changes together thematically","Displays branch context, including current branch name and base branch"],"zh":["支持git diff命令","显示代码变更和提交历史","自动总结代码变更","支持多种编程语言","集成了git bookkeeping功能"],"ja":["git diffコマンドをサポート","コードの変更とコミット履歴を表示","コードの変更を自動でまとめる","多くのプログラミング言語をサポート","git bookkeeping機能を統合"],"ko":["git diff 명령어 지원","코드 변경 사항과 커밋 기록 표시","코드 변경 사항 자동 요약","다양한 프로그래밍 언어 지원","git bookkeeping 기능 통합"],"es":["Ejecuta ''git diff'' para ver los cambios de código","Resume los cambios de código en una rama","Entiende el contexto de la rama actual y la rama base","Identifica los archivos modificados y los cambios realizados","Proporciona una visión general de los cambios de código","Utiliza comandos git para analizar los cambios de código"],"fr":["Exécute ''git diff'' pour voir les modifications de code","Résume les modifications de code dans une branche","Comprend le contexte de la branche actuelle et de la branche de base","Identifie les fichiers modifiés et les modifications apportées","Fournit une vue d''ensemble des modifications de code","Utilise des commandes git pour analyser les modifications de code"],"de":["Führt ''git diff'' aus, um Code-Änderungen anzuzeigen","Zusammenfassung der Code-Änderungen in einem Branch","Versteht den Kontext des aktuellen und des Basis-Banches","Identifiziert geänderte Dateien und Änderungen","Bietet eine Übersicht über die Code-Änderungen","Verwendet Git-Befehle, um Code-Änderungen zu analysieren"],"pt":["Resumo das alterações de código com git diff","Análise das mudanças em arquivos-chave","Entendimento do que foi adicionado, removido ou modificado","Agrupamento de mudanças relacionadas","Contexto da branch atual e da branch base","Integração com o Git para entender as alterações"],"ru":["Сводка изменений кода с помощью git diff","Анализ изменений в ключевых файлах","Понимание того, что было добавлено, удалено или изменено","Группировка связанных изменений","Контекст текущей ветки и базовой ветки","Интеграция с Git для понимания изменений с ИИ Агентами"],"ar":["ملخص للتغييرات في الكود مع git diff","تحليل التغييرات في الملفات الرئيسية","فهم ما تم إضافته أو إزالته أو تعديله","تجميع التغييرات المتعلقة","سياق الفرع الحالي والفرع الأساسي","التكامل مع Git لفهم التغييرات مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use catching-up","git branch analysis","catching-up alternative","catching-up vs git status","catching-up install","catching-up setup guide","what is catching-up","git diff tutorial","catching-up for developers"],"zh":["catching-up工具","git diff命令","代码变更","提交历史","AI工具","技术开发","编程语言","git bookkeeping"],"ja":["catching-up AIエージェント","git diffコマンド","コードの変更","コミット履歴","AIエージェント","技術開発","プログラミング言語","git bookkeeping"],"ko":["catching-up 도구","git diff 명령어","코드 변경 사항","커밋 기록","AI 도구","기술 개발","프로그래밍 언어","git bookkeeping"],"es":["herramientas de desarrollo","ai para desarrolladores","git diff","rama de código","cambios de código","resumen de cambios","contexto de rama","análisis de código"],"fr":["outils de développement","ia pour développeurs","git diff","branche de code","modifications de code","résumé des modifications","contexte de branche","analyse de code"],"de":["entwicklertools","künstliche intelligenz für entwickler","git diff","code-branch","code-änderungen","zusammenfassung der änderungen","branch-kontext","code-analyse"],"pt":["catching-up","git diff","alterações de código","resumo de mudanças","desenvolvimento de software","ferramentas de desenvolvimento","git","programação","desenvolvedores"],"ru":["catching-up","git diff","изменения кода","сводка изменений","разработка программного обеспечения","инструменты разработки","git","программирование","разработчики","ИИ Агенты"],"ar":["catching-up","git diff","تغيرات الكود","ملخص للتغييرات","تطوير البرمجيات","أدوات التطوير","git","برمجة","مطورون","أدوات الذكاء الاصطناعي"]}},"owner":"detorresramos","repo":"CaramelDB","repoPath":"detorresramos/CaramelDB","stars":3,"forks":0,"updatedAt":"2026-03-04T05:00:34Z","topics":[],"category":"community","skillMd":{"name":"catching-up","description":"Catch up on the current branch — understand whats changed relative to the base branch. Use when starting a session or switching context.","bodyPreview":"Get me up to speed on the current state of this branch. Focus on understanding the *actual code changes*, not git bookkeeping.\n\n1. **Branch context**: Current branch name and base branch. One line.\n2. **What changed**: Run `git diff <base>...HEAD --stat` to see which files changed, then read the key changed files and the diff (`git diff <base>...HEAD`) to understand the substance of the changes. Summarize *what* was added, removed, or modified and *why* — group related changes together thematica","body":"Get me up to speed on the current state of this branch. Focus on understanding the *actual code changes*, not git bookkeeping.\n\n1. **Branch context**: Current branch name and base branch. One line.\n2. **What changed**: Run `git diff <base>...HEAD --stat` to see which files changed, then read the key changed files and the diff (`git diff <base>...HEAD`) to understand the substance of the changes. Summarize *what* was added, removed, or modified and *why* — group related changes together thematically rather than file-by-file.\n3. **Working tree**: Briefly note any staged changes, unstaged changes, or untracked files. Skip sections that are empty.\n\nPrioritize reading and understanding the actual code over listing commits. The goal is for the reader to walk away understanding the design decisions and current state of work on this branch.\n\n$ARGUMENTS\n"},"lastSynced":"2026-03-06T07:03:16.049Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing git branch summarization and code change understanding.","zh":"适合需要 git 分支摘要和代码更改理解的代码分析代理。","ja":"コード分析エージェントが git ブランチの概要とコードの変更を理解する必要がある場合に適しています。","ko":"git 브랜치 요약 및 코드 변경 이해가 필요한 코드 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Código que necesitan resumir ramas de git y comprender los cambios de código.","fr":"Parfait pour les agents d''analyse de code nécessitant une synthèse des branches Git et une compréhension des modifications de code.","de":"Perfekt für Code-Analyse-Agents, die eine Zusammenfassung von Git-Branches und ein Verständnis von Code-Änderungen benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de resumo de branch do git e compreensão de alterações de código.","ru":"Идеально подходит для Агентов Анализа Кодов, требующих сводки ветвей git и понимания изменений кода.","ar":"مثالي لعمليات تحليل الشفرة التي تحتاج إلى تلخيص فرع جيت و فهم التغييرات في الشفرة."},"recommendation":{"en":"Empowers agents to summarize git diff outputs, providing insights into actual code changes, including additions, removals, and modifications, using git commands like `git diff --stat` and `git diff`.","zh":"赋予代理人总结 git diff 输出的能力，提供对实际代码更改的见解，包括添加、删除和修改，使用诸如 `git diff --stat` 和 `git diff` 的 git 命令。","ja":"エージェントが `git diff --stat` や `git diff` などの git コマンドを使用して、git diff 出力を要約し、実際のコード変更に関する洞察を提供することを可能にします。これには、追加、削除、変更などが含まれます。","ko":"에이전트가 `git diff --stat` 및 `git diff`와 같은 git 명령을 사용하여 git diff 출력을 요약하고 실제 코드 변경에 대한 통찰력을 제공할 수 있도록 합니다. 추가, 제거, 수정 등이 포함됩니다.","es":"Habilita a los agentes a resumir las salidas de git diff, proporcionando información sobre los cambios de código reales, incluyendo adiciones, eliminaciones y modificaciones, utilizando comandos de git como `git diff --stat` y `git diff`.","fr":"Permet aux agents de résumer les sorties de git diff, fournissant des informations sur les modifications de code réelles, y compris les ajouts, les suppressions et les modifications, en utilisant des commandes Git comme `git diff --stat` et `git diff`.","de":"Ermächtigt die Agents, die Ausgaben von git diff zusammenzufassen und so Einblicke in die tatsächlichen Code-Änderungen zu gewähren, einschließlich Hinzufügungen, Entfernungen und Modifikationen, unter Verwendung von Git-Befehlen wie `git diff --stat` und `git diff`.","pt":"Habilita os agentes a resumir as saídas do git diff, fornecendo informações sobre as alterações de código reais, incluindo adições, remoções e modificações, usando comandos git como `git diff --stat` e `git diff`.","ru":"Наделяет агентов возможностью суммировать выводы git diff, предоставляя информацию о фактических изменениях кода, включая добавления, удаления и модификации, используя команды git, такие как `git diff --stat` и `git diff`.","ar":"تمكّن الوكلاء من تلخيص مخرجات git diff، وتقديم رؤى حول التغييرات الفعلية في الشفرة، بما في ذلك الإضافات والتحويلات والتعديلات، باستخدام أوامر جيت مثل `git diff --stat` و `git diff`."},"useCases":{"en":["Summarizing code changes between git branches","Automating code review processes by highlighting key changes","Debugging issues by understanding the substance of recent code modifications"],"zh":["总结 git 分支之间的代码更改","通过突出显示关键更改来自动化代码审查过程","通过了解最近的代码修改的实质来调试问题"],"ja":["git ブランチ間のコード変更を要約する","重要な変更を強調してコードレビューの自動化","最近のコード変更の内容を理解して問題をデバッグする"],"ko":["git 브랜치 간의 코드 변경을 요약하는 것","중요한 변경 사항을 강조하여 코드 리뷰 프로세스를 자동화하는 것","최근의 코드 변경 사항의 본질을 이해하여 문제를 디버깅하는 것"],"es":["Resumir los cambios de código entre ramas de git","Automatizar los procesos de revisión de código resaltando los cambios clave","Depurar problemas al comprender la sustancia de las modificaciones de código recientes"],"fr":["Résumer les modifications de code entre les branches Git","Automatiser les processus d''examen de code en mettant en évidence les modifications clés","Déboguer les problèmes en comprenant la substance des modifications de code récentes"],"de":["Zusammenfassung der Code-Änderungen zwischen Git-Branches","Automatisierung der Code-Überprüfungsprozesse durch Hervorhebung der wichtigsten Änderungen","Fehlerbehebung durch das Verständnis der Substanz der kürzlichen Code-Modifikationen"],"pt":["Resumir alterações de código entre branches do git","Automatizar processos de revisão de código destacando alterações-chave","Depurar problemas entendendo a essência das modificações recentes de código"],"ru":["Сводка изменений кода между ветвями git","Автоматизация процессов проверки кода, подчеркивая ключевые изменения","Отладка проблем, понимая суть недавних изменений кода"],"ar":["تلخيص التغييرات في الشفرة بين فروع جيت","تأتميم عمليات مراجعة الشفرة من خلال تسليط الضوء على التغييرات الرئيسية","تصحيح الأخطاء من خلال فهم جوهر التعديلات الأخيرة على الشفرة"]},"limitations":{"en":["Requires git repository access","Limited to analyzing code changes, not git bookkeeping"],"zh":["需要 git 仓库访问","仅限于分析代码更改，而不是 git 书籍保管"],"ja":["git リポジトリへのアクセスが必要","コードの変更を分析することのみに限られ、git の書籍保管には対応していない"],"ko":["git 저장소 액세스가 필요함","코드 변경 사항만 분석할 수 있으며 git 도서관 보관에는 제한됨"],"es":["Requiere acceso al repositorio de git","Limitado al análisis de cambios de código, no a la contabilidad de git"],"fr":["Nécessite un accès au référentiel Git","Limité à l''analyse des modifications de code, et non à la comptabilité Git"],"de":["Benötigt Zugriff auf das Git-Repository","Begrenzt auf die Analyse von Code-Änderungen, nicht auf die Git-Buchhaltung"],"pt":["Requer acesso ao repositório git","Limitado à análise de alterações de código, não ao bookkeeping do git"],"ru":["Требуется доступ к репозиторию git","Ограничен анализом изменений кода, а не учетом git"],"ar":["يتطلب الوصول إلى مستودع جيت","محدود بتحليل التغييرات في الشفرة، وليس دفتر جيت"]},"version":4},"contentHash":"6494ee99dc75d5f671924d207fc31fd9026e85c7b6af2b63208a9dd2c1c033eb","qualityScore":20}');
