INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('detorresramos/CaramelDB/catching-up', 'catching-up', 'detorresramos', 'CaramelDB', 'community', 'catching-up detorresramos CaramelDB community The catching-up skill analyzes the current state of a git branch, focusing on actual code changes. It benefits developers by summarizing additions, removals, and modifications made to the codebase. catching-up工具用于获取当前分支的状态，包括代码变更和提交历史 catching-up AIエージェントは、現在のブランチの状態を把握するためのツールです catching-up 도구는 현재 브랜치의 상태를 파악하고 코드 변경 사항을 확인합니다 El skill ''catching-up'' te permite entender los cambios de código en una rama mediante la ejecución de comandos git Le skill ''catching-up'' vous permet de comprendre les modifications de code dans une branche en exécutant des commandes git Der Skill ''catching-up'' ermöglicht es Ihnen, Code-Änderungen in einem Branch durch Ausführen von Git-Befehlen zu verstehen O Catching-up ajuda desenvolvedores a entender as alterações de código em um branch. Veja como usar git diff para resumir as mudanças. Catching-up помогает разработчикам понять изменения кода в ветке. Узнайте, как использовать git diff для сводки изменений с ИИ Агентами يُساعد Catching-up المطورين على فهم التغييرات في الكود في فرع. تعلم كيفية استخدام git diff لملخص للتغييرات مع أدوات الذكاء الاصطناعي how to use catching-up git branch analysis catching-up alternative catching-up vs git status catching-up install catching-up setup guide what is catching-up git diff tutorial catching-up for developers catching-up工具 git diff命令 代码变更 提交历史 AI工具 技术开发 编程语言 git bookkeeping Runs git diff to identify changed files Analyzes git diff output to understand code changes Provides a summary of additions, removals, and modifications Groups related changes together thematically Displays branch context, including current branch name and base branch catching-up is a git branch analysis skill that uses git diff to understand code changes and provide a summary of what was added, removed, or modified');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('arcasilesgroup/ai-engineering/release', 'community', 'arcasilesgroup', 'ai-engineering', 'arcasilesgroup/ai-engineering', 'release', 3, 0, 20, '2026-03-05T15:06:25Z', '2026-03-07T01:53:22.631Z', 'c2641bebfc440c980d1fd9fbf22a923698a7a84c59f63fcba1964cf82997d4a4', '{"id":"arcasilesgroup/ai-engineering/release","name":"release","description":{"en":"The Release skill turns any repo into a governed AI workspace, benefiting developers who use Claude Code, GitHub Copilot, Cursor, Gemini, and Codex. It enforces quality gates, security scanning, and risk management locally via git hooks.","zh":"Release AI 工作空间通过 git hooks 实现质量控制、安全扫描和风险管理，支持多种 AI 工具","ja":"Release AI エージェントは、git hooks を使用してコードの品質を保証し、セキュリティスキャンとリスク管理を実現","ko":"Release AI 워크스페이스는 git hooks를 통해 코드 품질 관리, 보안 스캔, 리스크 관리를 제공합니다","es":"Release es una herramienta que convierte cualquier repositorio en un espacio de trabajo de IA gobernado, con calidad, escaneo de seguridad y gestión de riesgos","fr":"Release est un outil qui transforme n''importe quel référentiel en un espace de travail d''IA géré, avec qualité, analyse de sécurité et gestion des risques","de":"Release ist ein Tool, das jedes Repository in einen reglementierten AI-Arbeitsbereich umwandelt, mit Qualität, Sicherheitsscanning und Risikomanagement","pt":"O Release é uma ferramenta que permite transformar qualquer repositório em um espaço de trabalho de IA governado, com recursos como portas de qualidade, varredura de segurança e gerenciamento de riscos","ru":"Release — это инструмент, который позволяет превратить любой репозиторий в регулируемое рабочее пространство ИИ, с функциями контроля качества, сканирования безопасности и управления рисками","ar":"Release هو أداة تمكن من تحويل أي مستودع إلى مساحة عمل إدارة ذكاء اصطناعي مع ميزات مثل بوابات الجودة وفحص الأمان وإدارة المخاطر"},"seo":{"title":{"en":"Release: Setup Guide for AI Agents | AI Agent Skill","zh":"Release AI 工作空间设置指南","ja":"Release AI エージェントのベストプラクティス","ko":"Release AI 워크스페이스 구축 가이드","es":"Guía de configuración de Release: Implementación de espac...","fr":"Guide de configuration de Release : Mise en place d''espac...","de":"Release-Setup-Leitfaden: Einrichtung von reglementierten ...","pt":"Guia de Configuração do Release: Integração com Ferrament...","ru":"Настройка Release: Интеграция с ИИ Агентами и GitHub Copilot","ar":"دليل إعداد Release: دمج مع أدوات التطوير والموارد البشرية"},"description":{"en":"Unlock governed AI workspaces with Release. Discover how to enforce quality gates, security scanning, and risk management via git hooks. Get started now!","zh":"通过 Release AI 工作空间实现质量控制、安全扫描和风险管理，支持 Claude Code、GitHub Copilot 等","ja":"Release AI エージェントで質の高いコードを保証し、セキュリティスキャンとリスク管理を実現","ko":"Release AI 워크스페이스에서 코드 품질 관리, 보안 스캔, 리스크 관리를 구현하세요","es":"Aprende a convertir cualquier repositorio en un espacio de trabajo de IA gobernado con Release, que ofrece calidad, escaneo de seguridad y gestión de riesgos","fr":"Découvrez comment transformer n''importe quel référentiel en un espace de travail d''IA géré avec Release, qui propose qualité, analyse de sécurité et gestion ...","de":"Erfahren Sie, wie Sie jedes Repository in einen reglementierten AI-Arbeitsbereich mit Release umwandeln, der Qualität, Sicherheitsscanning und Risikomanageme...","pt":"Aprenda a configurar o Release para tornar qualquer repositório em um espaço de trabalho de IA governado com qualidade, segurança e gerenciamento de riscos","ru":"Узнайте, как настроить Release для превращения любого репозитория в регулируемое рабочее пространство ИИ с контролем качества, безопасностью и управлением ри...","ar":"تعرف على كيفية إعداد Release لتحويل أي مستودع إلى مساحة عمل إدارة ذكاء اصطناعي مع تطبيق مراقبة الجودة وأمان الفحص وإدارة المخاطر"},"definition":{"en":"Release is a skill that enables governed AI workspaces by enforcing quality gates, security scanning, and risk management via git hooks, compatible with AI agents like Claude Code and GitHub Copilot.","zh":"Release AI 工作空间是一种通过 git hooks 实现的代码管理和安全扫描工具","ja":"Release AI エージェントは、AI エージェントの一種で、コードの品質を保証し、セキュリティスキャンとリスク管理を実現","ko":"Release AI 워크스페이스는 코드 관리와 보안 스캔을 위한 AI 도구입니다","es":"Release es un agente de IA que permite implementar espacios de trabajo de IA gobernados","fr":"Release est un agent d''IA qui permet de mettre en place des espaces de travail d''IA gérés","de":"Release ist ein AI-Agent, der die Implementierung von reglementierten AI-Arbeitsbereichen ermöglicht","pt":"O Release é uma ferramenta de desenvolvimento que integra recursos de qualidade, segurança e gerenciamento de riscos em repositórios de código","ru":"Release — это инструмент разработки, который интегрирует функции контроля качества, безопасности и управления рисками в репозитории кода","ar":"Release هو أداة تطوير تدمج ميزات مراقبة الجودة وأمان الفحص وإدارة المخاطر في مستودعات الشفرة"},"features":{"en":["Enforces quality gates via git hooks","Performs security scanning for risk management","Works with Claude Code, GitHub Copilot, Cursor, Gemini, and Codex","Activates agent persona defined in .ai-engineering/agents/release.md","Reads the agent file completely for adoption of identity, capabilities, and behavior"],"zh":["支持 Claude Code、GitHub Copilot、Cursor、Gemini 和 Codex","通过 git hooks 实现质量控制和安全扫描","提供风险管理和代码审查功能","支持多种编程语言和开发环境","提高代码质量和安全性","简化代码审查和测试流程"],"ja":["Claude Code、GitHub Copilot、Cursor、Gemini、Codex をサポート","git hooks を使用してコードの品質を保証","セキュリティスキャンとリスク管理を実現","多くのプログラミング言語と開発環境をサポート","コードの品質とセキュリティを向上","コードレビューとテストのプロセスを簡素化"],"ko":["Claude Code, GitHub Copilot, Cursor, Gemini, Codex 지원","git hooks를 통해 코드 품질 관리와 보안 스캔","리스크 관리와 코드 리뷰 기능 제공","다양한 프로그래밍 언어와 개발 환경 지원","코드 품질과 보안性 향상","코드 리뷰와 테스트 프로세스 간소화"],"es":["Integración con Claude Code, GitHub Copilot, Cursor, Gemini y Codex","Calidad de código asegurada mediante quality gates","Escaneo de seguridad y gestión de riesgos","Funciona con git hooks para una implementación local","Soporte para la adopción de la identidad y el comportamiento del agente"],"fr":["Intégration avec Claude Code, GitHub Copilot, Cursor, Gemini et Codex","Qualité de code assurée grâce aux quality gates","Analyse de sécurité et gestion des risques","Fonctionne avec les git hooks pour une mise en œuvre locale","Prise en charge de l''adoption de l''identité et du comportement de l''agent"],"de":["Integration mit Claude Code, GitHub Copilot, Cursor, Gemini und Codex","Code-Qualität durch Quality Gates sichergestellt","Sicherheitsscanning und Risikomanagement","Funktioniert mit git hooks für eine lokale Implementierung","Unterstützung für die Übernahme der Identität und des Verhaltens des Agents"],"pt":["Integração com Claude Code, GitHub Copilot, Cursor, Gemini e Codex","Portas de qualidade para garantir a consistência do código","Varredura de segurança para detectar vulnerabilidades","Gerenciamento de riscos para minimizar problemas","Funciona com git hooks para garantir a conformidade"],"ru":["Интеграция с Claude Code, GitHub Copilot, Cursor, Gemini и Codex","Контроль качества для обеспечения согласованности кода","Сканирование безопасности для обнаружения уязвимостей","Управление рисками для минимизации проблем","Работает с git hooks для обеспечения соответствия"],"ar":["التكامل مع Claude Code و GitHub Copilot و Cursor و Gemini و Codex","بوابات الجودة لضمان توافق الشفرة","فحص الأمان لاكتشاف الثغرات","إدارة المخاطر لتقليل المشاكل","يعمل مع git hooks لضمان الامتثال"]},"keywords":{"en":["how to use release","release setup guide","release alternative to git hooks","release vs GitHub Copilot","what is release skill","release install for AI agents","release and Claude Code integration","git hooks for security scanning","governed AI workspaces with release"],"zh":["AI 工作空间","Release AI","代码管理","安全扫描","风险管理","git hooks","Claude Code","GitHub Copilot","AI 工具","代码审查"],"ja":["AI エージェント","Release AI","コード管理","セキュリティスキャン","リスク管理","git hooks","Claude Code","GitHub Copilot","AI ツール","コードレビュー"],"ko":["AI 워크스페이스","Release AI","코드 관리","보안 스캔","리스크 관리","git hooks","Claude Code","GitHub Copilot","AI 도구","코드 리뷰"],"es":["agente de IA","herramientas de desarrollo de IA","DevSecOps","git hooks","calidad de código","seguridad de código","gestión de riesgos","Claude Code","GitHub Copilot"],"fr":["agent d''IA","outils de développement d''IA","DevSecOps","git hooks","qualité de code","sécurité de code","gestion des risques","Claude Code","GitHub Copilot"],"de":["AI-Agent","AI-Entwicklungstools","DevSecOps","git hooks","Code-Qualität","Code-Sicherheit","Risikomanagement","Claude Code","GitHub Copilot"],"pt":["Release","IA","desenvolvimento de software","ferramentas de desenvolvimento","qualidade de código","segurança de código","gerenciamento de riscos","git hooks","Claude Code","GitHub Copilot"],"ru":["Release","ИИ","разработка программного обеспечения","инструменты разработки","контроль качества кода","безопасность кода","управление рисками","git hooks","Claude Code","GitHub Copilot"],"ar":["Release","الذكاء الاصطناعي","تطوير البرمجيات","أدوات التطوير","جودة الشفرة","أمان الشفرة","إدارة المخاطر","git hooks","Claude Code","GitHub Copilot"]}},"owner":"arcasilesgroup","repo":"ai-engineering","repoPath":"arcasilesgroup/ai-engineering","stars":3,"forks":0,"updatedAt":"2026-03-05T15:06:25Z","topics":["ai-agents","claude-code","developer-tools","devsecops","github-copilot"],"category":"community","skillMd":{"name":"release","description":"ALM + GitOps: commit, PR, deploy, triage, changelog","bodyPreview":"Activate the agent persona defined in `.ai-engineering/agents/release.md`.\n\nRead the agent file completely. Adopt the identity, capabilities, and behavior.","body":"Activate the agent persona defined in `.ai-engineering/agents/release.md`.\n\nRead the agent file completely. Adopt the identity, capabilities, and behavior.\n"},"lastSynced":"2026-03-07T01:53:22.631Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code, GitHub Copilot, and Cursor needing a governed workspace with enforced quality gates and security scanning via git hooks.","zh":"适合像 Claude Code、GitHub Copilot 和 Cursor 这样的 AI Agents，它们需要一个有强制质量门和通过 git hooks 进行安全扫描的受管工作空间。","ja":"Claude Code、GitHub Copilot、Cursor などの AI エージェントに適しています。これらは、git hooks を介したセキュリティ スキャンと強制された品質ゲートを備えた管理されたワークスペースを必要とします。","ko":"Claude Code, GitHub Copilot, Cursor와 같은 AI 에이전트에게 적합합니다. 이러한 에이전트는 관리되는 작업 공간과 git hooks를 통한 보안 스캔 및 강제된 품질 게이트가 필요합니다.","es":"Ideal para agentes de IA como Claude Code, GitHub Copilot y Cursor que necesitan un espacio de trabajo gobernado con puertas de calidad obligatorias y análisis de seguridad a través de ganchos de git.","fr":"Idéal pour les agents IA comme Claude Code, GitHub Copilot et Cursor nécessitant un espace de travail réglementé avec des portes de qualité obligatoires et un balayage de sécurité via des crochets de git.","de":"Ideal für KI-Agenten wie Claude Code, GitHub Copilot und Cursor, die einen regulierten Arbeitsbereich mit vorgeschriebenen Qualitätsprüfungen und Sicherheitsprüfungen über Git-Hooks benötigen.","pt":"Ideal para agentes de IA como Claude Code, GitHub Copilot e Cursor que necessitam de um espaço de trabalho governado com portais de qualidade impostos e varredura de segurança via git hooks.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code, GitHub Copilot и Cursor, которым требуется регулируемое рабочее пространство с обязательными воротами качества и сканированием безопасности через git hooks.","ar":"مثالي للأعضاء الاصطناعيين مثل Claude Code و GitHub Copilot و Cursor الذين يحتاجون إلى مساحة عمل محكمة مع بوابات جودة مفروضة وفحص أمان عبر git hooks."},"recommendation":{"en":"Empowers agents to enforce quality gates, perform security scanning, and manage risk locally through git hooks, ensuring a secure and reliable AI development environment with protocols like GitHub and languages supported by Claude Code and Codex.","zh":"赋予代理执行强制质量门、进行安全扫描和通过 git hooks 在本地管理风险，确保一个安全可靠的 AI 开发环境，支持 GitHub 和 Claude Code 以及 Codex 支持的语言。","ja":"エージェントに、強制された品質ゲートの実施、セキュリティ スキャンの実行、および git hooks を介したローカルリスク管理を可能にし、GitHub や Claude Code および Codex でサポートされている言語をサポートする、セキュアで信頼性の高い AI 開発環境を提供します。","ko":"에이전트가 강제된 품질 게이트를 적용하고, 보안 스캔을 수행하며, git hooks를 통해 로컬에서 위험을 관리할 수 있도록 해줌으로써, GitHub와 Claude Code 및 Codex에서 지원하는 언어를 지원하는 보안하고 신뢰할 수 있는 AI 개발 환경을 제공합니다.","es":"Habilita a los agentes a aplicar puertas de calidad, realizar análisis de seguridad y gestionar riesgos de forma local a través de ganchos de git, asegurando un entorno de desarrollo de IA seguro y fiable con protocolos como GitHub y lenguajes compatibles con Claude Code y Codex.","fr":"Permet aux agents d''appliquer des portes de qualité, d''effectuer des analyses de sécurité et de gérer les risques localement via des crochets de git, garantissant ainsi un environnement de développement d''IA sécurisé et fiable avec des protocoles comme GitHub et des langages pris en charge par Claude Code et Codex.","de":"Ermächtigt die Agenten, Qualitätsprüfungen durchzusetzen, Sicherheitsprüfungen durchzuführen und Risiken lokal über Git-Hooks zu verwalten, wodurch ein sicheres und zuverlässiges KI-Entwicklungsumfeld mit Protokollen wie GitHub und Sprachen, die von Claude Code und Codex unterstützt werden, gewährleistet wird.","pt":"Habilita os agentes a impor portais de qualidade, realizar varreduras de segurança e gerenciar riscos localmente por meio de git hooks, garantindo um ambiente de desenvolvimento de IA seguro e confiável com protocolos como o GitHub e linguagens suportadas pelo Claude Code e Codex.","ru":"Предоставляет агентам возможность обеспечивать воротами качества, выполнять сканирование безопасности и управлять рисками локально через git hooks, гарантируя безопасную и надежную среду разработки ИИ с протоколами, такими как GitHub, и языками, поддерживаемыми Claude Code и Codex.","ar":"تمكن الوكلاء من فرض بوابات جودة وأداء فحص أمان وادارة المخاطر محليا من خلال git hooks، مما يضمن بيئة تطوير آمنة وموثوقة للاعضاء الاصطناعيين مع بروتوكولات مثل جيت هب ولغات مدعومة من كلود كود وكودكس."},"useCases":{"en":["Enforcing quality gates for AI code","Performing security scans on GitHub repositories","Managing risk through local git hooks"],"zh":["执行 AI 代码的质量门","在 GitHub 存储库上执行安全扫描","通过本地 git hooks 管理风险"],"ja":["AI コードの品質ゲートの適用","GitHub リポジトリのセキュリティ スキャン","ローカル git hooks によるリスク管理"],"ko":["AI 코드의 품질 게이트 적용","GitHub 저장소의 보안 스캔","로컬 git hooks를 통한 위험 관리"],"es":["Aplicar puertas de calidad para el código de IA","Realizar análisis de seguridad en los repositorios de GitHub","Gestionar riesgos a través de ganchos de git locales"],"fr":["Appliquer des portes de qualité pour le code IA","Effectuer des analyses de sécurité sur les référentiels GitHub","Gérer les risques via des crochets de git locaux"],"de":["Qualitätsprüfungen für KI-Code durchsetzen","Sicherheitsprüfungen in GitHub-Repositorys durchführen","Risiken über lokale Git-Hooks verwalten"],"pt":["Impor portais de qualidade para código de IA","Realizar varreduras de segurança em repositórios do GitHub","Gerenciar riscos por meio de git hooks locais"],"ru":["Обеспечение воротами качества для кода ИИ","Выполнение сканирования безопасности в репозиториях GitHub","Управление рисками через локальные git hooks"],"ar":["فرض بوابات جودة للكود الاصطناعي","أداء فحص أمان على مستودعات جيت هب","ادارة المخاطر من خلال git hooks محلي"]},"limitations":{"en":["Requires git hooks setup","Limited to local development environments"],"zh":["需要设置 git hooks","仅限本地开发环境"],"ja":["git hooks の設定が必要","ローカル開発環境に限定される"],"ko":["git hooks 설정이 필요","로컬 개발 환경에만 제한"],"es":["Requiere configuración de ganchos de git","Limitado a entornos de desarrollo locales"],"fr":["Nécessite la configuration de crochets de git","Limité aux environnements de développement locaux"],"de":["Benötigt die Einrichtung von Git-Hooks","Begrenzt auf lokale Entwicklungsumgebungen"],"pt":["Requer configuração de git hooks","Limitado a ambientes de desenvolvimento locais"],"ru":["Требуется настройка git hooks","Ограничен локальными средами разработки"],"ar":["يتطلب إعداد git hooks","محدود بالبيئات التطويرية المحلية"]},"version":4},"contentHash":"c2641bebfc440c980d1fd9fbf22a923698a7a84c59f63fcba1964cf82997d4a4","qualityScore":20}');
