INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('arcasilesgroup/ai-engineering/release', 'release', 'arcasilesgroup', 'ai-engineering', 'community', 'release arcasilesgroup ai-engineering community ai-agents claude-code developer-tools devsecops github-copilot The Release skill turns any repo into a governed AI workspace, benefiting developers who use Claude Code, GitHub Copilot, Cursor, Gemini, and Codex. It enforces quality gates, security scanning, and risk management locally via git hooks. Release AI 工作空间通过 git hooks 实现质量控制、安全扫描和风险管理，支持多种 AI 工具 Release AI エージェントは、git hooks を使用してコードの品質を保証し、セキュリティスキャンとリスク管理を実現 Release AI 워크스페이스는 git hooks를 통해 코드 품질 관리, 보안 스캔, 리스크 관리를 제공합니다 Release es una herramienta que convierte cualquier repositorio en un espacio de trabajo de IA gobernado, con calidad, escaneo de seguridad y gestión de riesgos Release est un outil qui transforme n''importe quel référentiel en un espace de travail d''IA géré, avec qualité, analyse de sécurité et gestion des risques Release ist ein Tool, das jedes Repository in einen reglementierten AI-Arbeitsbereich umwandelt, mit Qualität, Sicherheitsscanning und Risikomanagement O Release é uma ferramenta que permite transformar qualquer repositório em um espaço de trabalho de IA governado, com recursos como portas de qualidade, varredura de segurança e gerenciamento de riscos Release — это инструмент, который позволяет превратить любой репозиторий в регулируемое рабочее пространство ИИ, с функциями контроля качества, сканирования безопасности и управления рисками Release هو أداة تمكن من تحويل أي مستودع إلى مساحة عمل إدارة ذكاء اصطناعي مع ميزات مثل بوابات الجودة وفحص الأمان وإدارة المخاطر how to use release release setup guide release alternative to git hooks release vs GitHub Copilot what is release skill release install for AI agents release and Claude Code integration git hooks for security scanning governed AI workspaces with release AI 工作空间 Release AI 代码管理 安全扫描 风险管理 git hooks Claude Code GitHub Copilot AI 工具 代码审查 Enforces quality gates via git hooks Performs security scanning for risk management Works with Claude Code, GitHub Copilot, Cursor, Gemini, and Codex Activates agent persona defined in .ai-engineering/agents/release.md Reads the agent file completely for adoption of identity, capabilities, and behavior Release is a skill that enables governed AI workspaces by enforcing quality gates, security scanning, and risk management via git hooks, compatible with AI agents like Claude Code and GitHub Copilot.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bierecode/bierecode/build-check', 'community', 'bierecode', 'bierecode', 'bierecode/bierecode', 'build-check', 2, 0, 20, '2026-03-06T18:46:43Z', '2026-03-07T01:53:35.949Z', '3013ff40731d332fd63621687b66ee27a70fee172c32ed368b303e612dacf5bc', '{"id":"bierecode/bierecode/build-check","name":"build-check","description":{"en":"The build-check skill automates build analysis by running `npm run build` and suggesting fixes for errors. It benefits developers by streamlining the build process.","zh":"build-check是一种运行npm构建和分析错误的技能，帮助开发者快速识别和修复问题","ja":"build-checkはnpmビルドを実行しエラーを分析するスキルで、開発者が問題を迅速に特定し修復するのに役立ちます","ko":"build-check는 npm 빌드를 실행하고 오류를 분석하는 스킬로 개발자가 문제를 신속하게 식별하고 수정하는 데 도움이 됩니다","es":"build-check es una herramienta que ejecuta npm run build y analiza errores. Ayuda a los desarrolladores a identificar y solucionar problemas en su código","fr":"build-check est un outil qui exécute npm run build et analyse les erreurs. Il aide les développeurs à identifier et à résoudre les problèmes dans leur code","de":"build-check ist ein Tool, das npm run build ausführt und Fehler analysiert. Es hilft Entwicklern, Probleme in ihrem Code zu identifizieren und zu beheben","pt":"O build-check é uma ferramenta que executa o comando npm run build e analisa erros. Ele ajuda a identificar problemas no código e sugere soluções.","ru":"ИИ Агент build-check запускает команду npm run build и анализирует ошибки. Он помогает выявить проблемы в коде и предложить решения.","ar":"build-check هو أداة تنفذ الأمر npm run build وتحليل الأخطاء. يساعد في تحديد المشاكل في الكود واقتراح حلول."},"seo":{"title":{"en":"build-check: Automated Build Analysis for AI Agents | AI ...","zh":"build-check.setup指南：运行npm构建和错误分析","ja":"build-checkセットアップガイド：npmビルドとエラーアナリシス","ko":"build-check 설정 가이드: npm 빌드 및 오류 분석","es":"Guía de configuración para build-check: Análisis de error...","fr":"Guide de mise en place pour build-check : Analyse des err...","de":"Einrichtungsleitfaden für build-check: Fehleranalyse und ...","pt":"Guia de Configuração do build-check: Análise de Erros e S...","ru":"Настройка ИИ Агента build-check: Руководство по Анализу О...","ar":"دليل إعداد build-check: تحليل الأخطاء وإصلاحها"},"description":{"en":"Discover how build-check simplifies build process analysis. Run automated checks and fix errors with ease. Learn more and get started today!","zh":"使用build-check运行npm构建，分析错误，建议修复，并报告成功或问题","ja":"build-checkを使用してnpmビルドを実行し、エラーを分析し、修復を提案し、成功または問題を報告します","ko":"build-check를 사용하여 npm 빌드를 실행하고 오류를 분석하고 수정을 제안하고 성공 또는 문제를 보고합니다","es":"Aprende a utilizar build-check para analizar errores y sugerir soluciones. Mejora tus habilidades de desarrollo con esta herramienta AI","fr":"Découvrez comment utiliser build-check pour analyser les erreurs et suggérer des corrections. Améliorez vos compétences de développement avec cet outil IA","de":"Erfahren Sie, wie Sie build-check verwenden, um Fehler zu analysieren und Lösungen vorzuschlagen. Verbessern Sie Ihre Entwicklerfähigkeiten mit diesem AI-Tool","pt":"Aprenda a configurar o build-check e a analisar erros no processo de build com npm. Descubra como identificar e solucionar problemas comuns.","ru":"Узнайте, как настроить ИИ Агент build-check и проанализировать ошибки в процессе сборки с помощью npm. Ознакомьтесь с распространенными проблемами и их решен...","ar":"تعرف على كيفية إعداد build-check وتحليل الأخطاء في عملية البناء باستخدام npm. اكتشف كيفية تحديد ومعالجة المشاكل الشائعة."},"definition":{"en":"build-check is a skill that automates the build process analysis by running a series of commands, including `cd bierecode && npm run build`, to identify and suggest fixes for errors.","zh":"build-check是一种AI工具，运行npm run build命令并分析错误","ja":"build-checkはAIエージェントで、npm run buildコマンドを実行しエラーを分析します","ko":"build-check는 AI 도구로 npm run build 명령을 실행하고 오류를 분석합니다","es":"build-check es una herramienta de análisis de errores que utiliza npm para identificar problemas en el código","fr":"build-check est un outil d''analyse d''erreurs qui utilise npm pour identifier les problèmes dans le code","de":"build-check ist ein Tool zur Fehleranalyse, das npm verwendet, um Probleme im Code zu identifizieren","pt":"O build-check é uma ferramenta de análise de erros que ajuda a identificar problemas no processo de build.","ru":"ИИ Агент build-check - это инструмент анализа ошибок, помогающий выявить проблемы в процессе сборки.","ar":"build-check هو أداة تحليل الأخطاء التي تساعد في تحديد المشاكل في عملية البناء."},"features":{"en":["Runs `cd bierecode && npm run build` to analyze build errors","Analyzes referenced files to suggest fixes for build failures","Reports success or lists issues for further review","Utilizes npm for build process management","Executes commands in a specific directory (bierecode) for targeted analysis"],"zh":["运行npm run build命令","分析构建错误","建议修复","报告成功或问题","支持CLI命令","集成npm构建过程"],"ja":["npm run buildコマンドを実行","ビルドエラーを分析","修復を提案","成功または問題を報告","CLIコマンドをサポート","npmビルドプロセスに統合"],"ko":["npm run build 명령을 실행","빌드 오류를 분석","수정을 제안","성공 또는 문제를 보고","CLI 명령을 지원","npm 빌드 프로세스에 통합"],"es":["Ejecuta npm run build para compilar el código","Analiza errores y sugiere soluciones","Identifica problemas en el código utilizando npm","Proporciona informes de éxito o lista de problemas","Utiliza CLI para ejecutar comandos","Integra con herramientas de desarrollo como React y Node.js"],"fr":["Exécute npm run build pour compiler le code","Analyse les erreurs et suggère des corrections","Identifie les problèmes dans le code en utilisant npm","Fournit des rapports de succès ou une liste de problèmes","Utilise la CLI pour exécuter des commandes","Intègre avec des outils de développement tels que React et Node.js"],"de":["Führt npm run build aus, um den Code zu kompilieren","Analysiert Fehler und schlägt Lösungen vor","Identifiziert Probleme im Code mithilfe von npm","Stellt Erfolgsberichte oder eine Liste von Problemen bereit","Verwendet die CLI, um Befehle auszuführen","Integriert mit Entwicklungstools wie React und Node.js"],"pt":["Executa o comando npm run build","Analisa erros no processo de build","Sugere soluções para problemas comuns","Ajuda a identificar problemas no código","Integração com npm"],"ru":["Запускает команду npm run build","Анализирует ошибки в процессе сборки","Предлагает решения для распространенных проблем","Помогает выявить проблемы в коде","Интеграция с npm"],"ar":["تنفذ الأمر npm run build","تحليل الأخطاء في عملية البناء","يقترح حلولاً للمشاكل الشائعة","يساعد في تحديد المشاكل في الكود","التكامل مع npm"]},"keywords":{"en":["how to use build-check","build-check setup guide","what is build-check","build-check alternative","build-check vs manual build analysis","automated build process analysis","npm build error fixing","build-check install"],"zh":["build-check","npm构建","错误分析","AI工具","CLI命令","npm run build","构建错误","修复建议","成功报告","问题报告"],"ja":["build-check","npmビルド","エラーアナリシス","AIエージェント","CLIコマンド","npm run build","ビルドエラー","修復提案","成功報告","問題報告"],"ko":["build-check","npm 빌드","오류 분석","AI 도구","CLI 명령","npm run build","빌드 오류","수정 제안","성공 보고","문제 보고"],"es":["build-check","análisis de errores","npm","desarrollo de software","herramientas de desarrollo","CLI","React","Node.js","codificación","depuración"],"fr":["build-check","analyse d''erreurs","npm","développement de logiciels","outils de développement","CLI","React","Node.js","codage","débogage"],"de":["build-check","Fehleranalyse","npm","Softwareentwicklung","Entwicklungstools","CLI","React","Node.js","Codierung","Fehlersuche"],"pt":["build-check","análise de erros","npm","processo de build","soluções de problemas","desenvolvimento de software","ferramentas de desenvolvimento","otimização de código","depuração de código"],"ru":["build-check","ИИ Агенты","анализ ошибок","npm","процесс сборки","решения проблем","разработка программного обеспечения","инструменты разработки","оптимизация кода","отладка кода"],"ar":["build-check","أدوات الذكاء الاصطناعي","تحليل الأخطاء","npm","عملية البناء","حلول المشاكل","تطوير البرمجيات","أدوات التطوير","تحسين الكود","تصحيح الكود"]}},"owner":"bierecode","repo":"bierecode","repoPath":"bierecode/bierecode","stars":2,"forks":0,"updatedAt":"2026-03-06T18:46:43Z","topics":[],"category":"community","skillMd":{"name":"build-check","description":"Build the Astro site and report any errors. Use after making changes.","bodyPreview":"Run `cd bierecode && npm run build` and analyze any errors. If build fails, read the referenced files and suggest fixes. Report success or list issues.","body":"Run `cd bierecode && npm run build` and analyze any errors. If build fails, read the referenced files and suggest fixes. Report success or list issues.\n"},"lastSynced":"2026-03-07T01:53:35.949Z","agentAnalysis":{"suitability":{"en":"Ideal for JavaScript Agents requiring automated build analysis and error resolution using npm","zh":"适用于需要使用npm进行自动化构建分析和错误解决的JavaScript Agents","ja":"npmを使用した自動化されたビルド分析およびエラーリソリューションを必要とするJavaScriptエージェントに適しています","ko":"npm을 사용하여 자동화된 빌드 분석 및 오류 해결을 필요한 JavaScript 에이전트에 적합합니다","es":"Ideal para agentes de JavaScript que requieren análisis de compilación automatizado y resolución de errores utilizando npm","fr":"Idéal pour les agents JavaScript nécessitant une analyse de construction automatisée et une résolution d''erreurs utilisant npm","de":"Ideal für JavaScript-Agents, die eine automatisierte Build-Analyse und Fehlerbehebung unter Verwendung von npm erfordern","pt":"Ideal para Agentes JavaScript que requerem análise de compilação automatizada e resolução de erros usando npm","ru":"Идеально для агентов JavaScript, требующих автоматического анализа сборки и решения ошибок с помощью npm","ar":"مثالي لعميل JavaScript الذين يحتاجون إلى تحليل بناء آلي وتصحيح أخطاء باستخدام npm"},"recommendation":{"en":"Empowers agents to streamline the build process by running `npm run build` and suggesting fixes for errors, leveraging npm''s package management capabilities and analyzing referenced files for issue resolution, all while utilizing JavaScript and Node.js ecosystems","zh":"赋予代理人通过运行`npm run build`简化构建过程并利用npm的包管理功能和分析引用的文件来解决问题的能力，同时利用JavaScript和Node.js生态系统","ja":"`npm run build`を実行してビルドプロセスを簡素化し、npmのパッケージ管理機能と参照ファイルの分析を利用してエラーを修正することを代理人に可能にし、JavaScriptおよびNode.jsエコシステムを活用する","ko":"`npm run build`를 실행하여 빌드 프로세스를 간소화하고 npm의 패키지 관리 기능과 참조 파일을 분석하여 오류를 수정할 수 있는 기능을 에이전트에게 부여하며 JavaScript 및 Node.js 생태계를 활용합니다","es":"Habilita a los agentes a simplificar el proceso de compilación ejecutando `npm run build` y sugiriendo soluciones para errores, aprovechando las capacidades de gestión de paquetes de npm y analizando los archivos de referencia para la resolución de problemas, todo mientras se utiliza JavaScript y los ecosistemas de Node.js","fr":"Permet aux agents de rationaliser le processus de construction en exécutant `npm run build` et en suggérant des correctifs pour les erreurs, en exploitant les capacités de gestion de packages de npm et en analysant les fichiers référencés pour la résolution des problèmes, le tout en utilisant JavaScript et les écosystèmes Node.js","de":"Ermächtigt Agenten, den Build-Prozess zu rationalisieren, indem sie `npm run build` ausführen und Fehlerbehebungen vorschlagen, indem sie die Paketverwaltungsfunktionen von npm nutzen und referenzierte Dateien zur Fehlerbehebung analysieren, und zwar unter Verwendung von JavaScript und Node.js-Ökosystemen","pt":"Habilita os agentes a simplificar o processo de compilação executando `npm run build` e sugerindo correções para erros, aproveitando as capacidades de gerenciamento de pacotes do npm e analisando arquivos referenciados para resolução de problemas, tudo isso utilizando os ecossistemas JavaScript e Node.js","ru":"Позволяет агентам оптимизировать процесс сборки, запуская `npm run build` и предлагая исправления ошибок, используя возможности управления пакетами npm и анализируя ссылочные файлы для решения проблем, все это при использовании экосистем JavaScript и Node.js","ar":"يمنح العميل القدرة على تبسيط عملية البناء من خلال تشغيل `npm run build` واقتراح تصحيحات للأخطاء، مستفيداً من قدرات إدارة الحزم من npm وتحليل الملفات المرتبطة لحل المشكلات، كل ذلك مع استخدام بيئات JavaScript وNode.js"},"useCases":{"en":["Automating build analysis for JavaScript projects","Debugging npm build errors","Suggesting fixes for build failures in Node.js applications"],"zh":["为JavaScript项目自动化构建分析","调试npm构建错误","为Node.js应用程序的构建故障建议修复"],"ja":["JavaScriptプロジェクトの自動化されたビルド分析","npmビルドエラーのデバッグ","Node.jsアプリケーションのビルド障害の修正を提案"],"ko":["JavaScript 프로젝트를 위한 자동화된 빌드 분석","npm 빌드 오류 디버깅","Node.js 애플리케이션의 빌드 실패에 대한 수정 제안"],"es":["Automatización del análisis de compilación para proyectos de JavaScript","Depuración de errores de compilación de npm","Sugerencia de soluciones para errores de compilación en aplicaciones de Node.js"],"fr":["Automatisation de l''analyse de construction pour les projets JavaScript","Débogage des erreurs de construction npm","Suggestion de correctifs pour les erreurs de construction dans les applications Node.js"],"de":["Automatisierung der Build-Analyse für JavaScript-Projekte","Fehlerbehebung bei npm-Build-Fehlern","Vorschlag zur Behebung von Build-Fehlern in Node.js-Anwendungen"],"pt":["Automatizar a análise de compilação para projetos JavaScript","Depurar erros de compilação do npm","Sugerir correções para falhas de compilação em aplicações Node.js"],"ru":["Автоматизация анализа сборки для проектов JavaScript","Отладка ошибок сборки npm","Предложение исправлений для сбоев сборки в приложениях Node.js"],"ar":["تأتمتة تحليل البناء لمشاريع JavaScript","تصحيح أخطاء بناء npm","اقتراح تصحيحات لفشل البناء في تطبيقات Node.js"]},"limitations":{"en":["Requires npm installation","JavaScript and Node.js ecosystem only","Needs filesystem access to run `npm run build`"],"zh":["需要npm安装","仅适用于JavaScript和Node.js生态系统","需要文件系统访问来运行`npm run build`"],"ja":["npmのインストールが必要","JavaScriptおよびNode.jsエコシステムのみ","`npm run build`を実行するためにファイルシステムへのアクセスが必要"],"ko":["npm 설치가 필요합니다","JavaScript 및 Node.js 생태계만 해당","`npm run build`를 실행하기 위해 파일 시스템 접근이 필요합니다"],"es":["Requiere instalación de npm","Solo ecosistema de JavaScript y Node.js","Necesita acceso al sistema de archivos para ejecutar `npm run build`"],"fr":["Nécessite l''installation de npm","Uniquement l''écosystème JavaScript et Node.js","Nécessite un accès au système de fichiers pour exécuter `npm run build`"],"de":["Benötigt npm-Installation","Nur JavaScript- und Node.js-Ökosystem","Benötigt Dateisystemzugriff, um `npm run build` auszuführen"],"pt":["Requer instalação do npm","Apenas ecossistemas JavaScript e Node.js","Necessita acesso ao sistema de arquivos para executar `npm run build`"],"ru":["Требуется установка npm","Только экосистемы JavaScript и Node.js","Требуется доступ к файловой системе для запуска `npm run build`"],"ar":["يتطلب تثبيت npm","نظام بيئي JavaScript وNode.js فقط","يتطلب وصولاً إلى نظام الملفات لتشغيل `npm run build`"]},"version":4},"contentHash":"3013ff40731d332fd63621687b66ee27a70fee172c32ed368b303e612dacf5bc","qualityScore":20}');
