INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bierecode/bierecode/build-check', 'build-check', 'bierecode', 'bierecode', 'community', 'build-check bierecode bierecode community The build-check skill automates build analysis by running `npm run build` and suggesting fixes for errors. It benefits developers by streamlining the build process. build-check是一种运行npm构建和分析错误的技能，帮助开发者快速识别和修复问题 build-checkはnpmビルドを実行しエラーを分析するスキルで、開発者が問題を迅速に特定し修復するのに役立ちます build-check는 npm 빌드를 실행하고 오류를 분석하는 스킬로 개발자가 문제를 신속하게 식별하고 수정하는 데 도움이 됩니다 build-check es una herramienta que ejecuta npm run build y analiza errores. Ayuda a los desarrolladores a identificar y solucionar problemas en su código build-check est un outil qui exécute npm run build et analyse les erreurs. Il aide les développeurs à identifier et à résoudre les problèmes dans leur code build-check ist ein Tool, das npm run build ausführt und Fehler analysiert. Es hilft Entwicklern, Probleme in ihrem Code zu identifizieren und zu beheben O build-check é uma ferramenta que executa o comando npm run build e analisa erros. Ele ajuda a identificar problemas no código e sugere soluções. ИИ Агент build-check запускает команду npm run build и анализирует ошибки. Он помогает выявить проблемы в коде и предложить решения. build-check هو أداة تنفذ الأمر npm run build وتحليل الأخطاء. يساعد في تحديد المشاكل في الكود واقتراح حلول. how to use build-check build-check setup guide what is build-check build-check alternative build-check vs manual build analysis automated build process analysis npm build error fixing build-check install build-check npm构建 错误分析 AI工具 CLI命令 npm run build 构建错误 修复建议 成功报告 问题报告 Runs `cd bierecode && npm run build` to analyze build errors Analyzes referenced files to suggest fixes for build failures Reports success or lists issues for further review Utilizes npm for build process management Executes commands in a specific directory (bierecode) for targeted analysis build-check is a skill that automates the build process analysis by running a series of commands, including `cd bierecode && npm run build`, to identify and suggest fixes for errors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tfunk1030/bnredo/check', 'community', 'tfunk1030', 'bnredo', 'tfunk1030/bnredo', 'check', 1, 1, 20, '2026-02-21T23:04:54Z', '2026-03-06T07:10:39.635Z', 'c3cc39ccc38e8c78068de51e43f2c30cda3aa2d6d323f2cb0b031cef23fcee21', '{"id":"tfunk1030/bnredo/check","name":"check","description":{"en":"The check skill runs both type checks and linting in parallel, reporting errors and confirming all clear. It benefits developers by ensuring code quality and integrity.","zh":"代码检查功能使用npx tsc和expo lint进行类型检查和代码风格检查","ja":"AIエージェントのコードチェック機能は、npx tscとexpo lintを使用してコードのタイプチェックとスタイルチェックを行います","ko":"코드 검사 기능은 npx tsc와 expo lint를 사용하여 코드의 타입 체크와 스타일 체크를 수행합니다","es":"El check de calidad es una habilidad que ejecuta comandos de verificación en paralelo con tsc y eslint para asegurar la calidad del código","fr":"Le check de qualité est une fonctionnalité qui exécute des commandes de vérification en paralelo avec tsc et eslint pour garantir la qualité du code","de":"Der Qualitätsscheck ist eine Fähigkeit, die Überprüfungsbefehle parallel mit tsc und eslint ausführt, um die Codequalität sicherzustellen","pt":"O Check é uma ferramenta para verificar a qualidade do código, executando npx tsc e npx expo lint em paralelo.","ru":"Check - это инструмент для проверки качества кода, запускающий npx tsc и npx expo lint параллельно.","ar":"أداة الفحص هي أداة لتحسين جودة الكود من خلال تشغيل npx tsc و npx expo lint بشكل متوازي"},"seo":{"title":{"en":"check: Quality Assurance Setup Guide | AI Agent Skill","zh":"代码检查设置指南 - 使用npx tsc和expo lint","ja":"AIエージェントのコードチェックベストプラクティス - npx tscとexpo lint","ko":"코드 검사 설정 가이드 - npx tsc와 expo lint 사용","es":"Guía de configuración de verificación de calidad con tsc ...","fr":"Configurer le check de qualité avec tsc et eslint - Meill...","de":"Einrichten des Qualitätsschecks mit tsc und eslint - Tech...","pt":"Guia de Configuração do Check: Verificação de Código","ru":"ИИ Агенты: Настройка проверки кода с помощью Check","ar":"دليل إعداد أداة الفحص: فحص الكود باستخدام Check"},"description":{"en":"Run type checks and linting in parallel with check. Get instant results and ensure code quality. Learn how to integrate check into your workflow today!","zh":"了解如何使用npx tsc和expo lint进行代码检查，确保您的代码质量和一致性","ja":"AIエージェントのコードチェック機能を使用して、コードの品質と一致性を確保する方法を学びます","ko":"코드 검사 기능을 사용하여 코드 품질과 일관성을 보장하는 방법을 알아보세요","es":"Aprende a ejecutar comandos de verificación de calidad en paralelo con tsc y eslint para asegurar la integridad de tu código","fr":"Découvrez comment exécuter des commandes de vérification de qualité en paralelo avec tsc et eslint pour garantir l''intégrité de votre code","de":"Erfahren Sie, wie Sie Qualitätsscheck-Befehle mit tsc und eslint parallel ausführen, um die Integrität Ihres Codes sicherzustellen","pt":"Aprenda a configurar o Check para verificar seu código com npx tsc e npx expo lint. Melhore a qualidade do seu código.","ru":"Настройте проверку кода с помощью ИИ Агентов и Check. Запускайте npx tsc и npx expo lint параллельно.","ar":"تعلم كيفية إعداد أداة الفحص لتحسين جودة الكود الخاص بك باستخدام npx tsc و npx expo lint"},"definition":{"en":"check is a quality assurance tool that runs type checks via npx tsc and linting via npx expo lint, reporting results and errors.","zh":"代码检查是使用npx tsc和expo lint等工具进行代码质量和一致性检查的过程","ja":"コードチェックは、npx tscやexpo lintなどのツールを使用してコードの品質と一致性を確認するプロセスです","ko":"코드 검사는 npx tsc와 expo lint 등의 도구를 사용하여 코드 품질과 일관성을 확인하는 과정입니다","es":"Un check de calidad es una verificación automatizada que utiliza tsc y eslint para detectar errores en el código","fr":"Un check de qualité est une vérification automatisée qui utilise tsc et eslint pour détecter les erreurs dans le code","de":"Ein Qualitätsscheck ist eine automatisierte Überprüfung, die tsc und eslint verwendet, um Fehler im Code zu erkennen","pt":"O que é Check? É uma ferramenta de verificação de código que executa typecheck e lint em paralelo.","ru":"Что такое Check? Это инструмент для проверки кода, запускающий typecheck и lint параллельно.","ar":"ما هي أداة الفحص؟ هي أداة للفحص الكود التي تعمل على تشغيل الفحص النوعي و lint بشكل متوازي"},"features":{"en":["Runs npx tsc --noEmit for type checking","Executes npx expo lint for ESLint validation","Reports errors from both type checks and linting","Confirms all clear when no errors are found","Runs type checks and linting in parallel for efficiency","Supports Expo and TypeScript projects"],"zh":["使用npx tsc进行类型检查","使用expo lint进行代码风格检查","并行运行检查以提高效率","报告代码错误和警告","确认代码清晰和一致性"],"ja":["npx tscを使用したタイプチェック","expo lintを使用したコードスタイルチェック","チェックの並行実行による効率化","コードエラーと警告の報告","コードのクリア性と一致性の確認"],"ko":["npx tsc를 사용한 타입 체크","expo lint를 사용한 코드 스타일 체크","체크의 병렬 실행으로 효율성 향상","코드 에러와 경고의 보고","코드의 클리어성과 일관성의 확인"],"es":["Ejecución paralela de comandos de verificación con tsc y eslint","Detección de errores con tsc y eslint","Informe de resultados de verificación","Compatibilidad con comandos de línea de comandos (CLI)","Integración con herramientas de desarrollo como Expo"],"fr":["Exécution parallèle de commandes de vérification avec tsc et eslint","Détection d''erreurs avec tsc et eslint","Rapport de résultats de vérification","Compatibilité avec les commandes de ligne de commande (CLI)","Intégration avec des outils de développement comme Expo"],"de":["Parallele Ausführung von Überprüfungsbefehlen mit tsc und eslint","Fehlererkennung mit tsc und eslint","Bericht über die Überprüfungsergebnisse","Kompatibilität mit Befehlszeilenbefehlen (CLI)","Integration mit Entwicklungstools wie Expo"],"pt":["Execução paralela de npx tsc e npx expo lint","Verificação de tipo com npx tsc","Verificação de lint com npx expo lint","Relatórios de erros detalhados","Confirmação de código limpo"],"ru":["Параллельный запуск npx tsc и npx expo lint","Проверка типа с помощью npx tsc","Проверка lint с помощью npx expo lint","Детальные отчеты об ошибках","Подтверждение чистого кода"],"ar":["تشغيل متوازي ل npx tsc و npx expo lint","فحص النوع باستخدام npx tsc","فحص lint باستخدام npx expo lint","تقارير مفصلة بالأخطاء","إتمام الكود النظيف"]},"keywords":{"en":["how to use check","what is check","check alternative","check vs eslint","check install","check setup guide","npx tsc --noEmit","npx expo lint","TypeScript quality assurance"],"zh":["代码检查","npx tsc","expo lint","代码质量","代码一致性","AI工具","代码开发"],"ja":["コードチェック","npx tsc","expo lint","コード品質","コード一致性","AIエージェント","コード開発"],"ko":["코드 검사","npx tsc","expo lint","코드 품질","코드 일관성","AI도구","코드 개발"],"es":["check de calidad","tsc","eslint","verificación de código","desarrollo de software","herramientas de desarrollo","Expo","CLI","automatización de pruebas"],"fr":["check de qualité","tsc","eslint","vérification de code","développement de logiciels","outils de développement","Expo","CLI","automatisation de tests"],"de":["Qualitätsscheck","tsc","eslint","Code-Überprüfung","Software-Entwicklung","Entwicklungstools","Expo","CLI","Automatisierung von Tests"],"pt":["Check","verificação de código","npx tsc","npx expo lint","typecheck","lint","qualidade de código","desenvolvimento de software"],"ru":["Check","ИИ Агенты","проверка кода","npx tsc","npx expo lint","typecheck","lint","качество кода","разработка программного обеспечения"],"ar":["أداة الفحص","فحص الكود","npx tsc","npx expo lint","فحص النوع","فحص lint","جودة الكود","تطوير البرمجيات"]}},"owner":"tfunk1030","repo":"bnredo","repoPath":"tfunk1030/bnredo","stars":1,"forks":1,"updatedAt":"2026-02-21T23:04:54Z","topics":[],"category":"community","skillMd":{"name":"check","description":"Run typecheck and lint in parallel","bodyPreview":"# Quality Check\n\nRun both checks and report results:\n\n1. `npx tsc --noEmit` (typecheck)\n2. `npx expo lint` (eslint)\n\nRun both in parallel. Report errors from both. If clean, confirm all clear.","body":"# Quality Check\n\nRun both checks and report results:\n\n1. `npx tsc --noEmit` (typecheck)\n2. `npx expo lint` (eslint)\n\nRun both in parallel. Report errors from both. If clean, confirm all clear.\n"},"lastSynced":"2026-03-06T07:10:39.635Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents needing parallel type checking and linting capabilities with npx tsc and expo lint","zh":"适用于需要并行类型检查和linting功能的代码审查代理，支持使用npx tsc和expo lint","ja":"並列型チェックとlinting機能を必要とするコードレビュー代理に適しています。npx tscとexpo lintを使用します","ko":"병렬 형식 확인 및 linting 기능이 필요한 코드 검토 에이전트에 적합합니다. npx tsc와 expo lint를 사용합니다","es":"Ideal para Agentes de Revisión de Código que necesitan capacidades de comprobación de tipos y linting paralelas con npx tsc y expo lint","fr":"Idéal pour les Agents de Révision de Code ayant besoin de capacités de vérification de types et de linting parallèles avec npx tsc et expo lint","de":"Ideal für Code-Review-Agents, die parallele Typprüf- und Linting-Funktionen mit npx tsc und expo lint benötigen","pt":"Ideal para Agentes de Revisão de Código que necessitam de verificação de tipo paralela e capacidades de linting com npx tsc e expo lint","ru":"Идеально для агентов код-ревью, которым требуются параллельные проверки типов и возможности linting с помощью npx tsc и expo lint","ar":"مثالي لوكلاء مراجعة الشفرة الذين يحتاجون إلى التحقق المتوازي للنوع وسمات linting مع npx tsc و expo lint"},"recommendation":{"en":"Empowers agents to run `npx tsc --noEmit` and `npx expo lint` in parallel, ensuring code quality and integrity through comprehensive type checks and eslint validation, reporting errors and confirming all clear","zh":"赋予代理运行`npx tsc --noEmit`和`npx expo lint`的能力，通过全面类型检查和eslint验证，确保代码质量和完整性，报告错误并确认所有清除","ja":"代理が`npx tsc --noEmit`と`npx expo lint`を並列して実行できるようにし、包括的な型チェックとeslint検証によってコードの品質と完全性を確保し、エラーを報告し、すべてクリアを確認します","ko":"에이전트가 `npx tsc --noEmit`와 `npx expo lint`를 병렬로 실행할 수 있도록 하여, 포괄적인 유형 확인 및 eslint 검증을 통해 코드 품질 및 무결성을 보장하고, 오류를 보고하고 모든 클리어를 확인합니다","es":"Permite a los agentes ejecutar `npx tsc --noEmit` y `npx expo lint` en paralelo, garantizando la calidad y la integridad del código a través de comprobaciones de tipos y validaciones de eslint, informando de errores y confirmando que todo está correcto","fr":"Permet aux agents d''exécuter `npx tsc --noEmit` et `npx expo lint` en parallèle, garantissant la qualité et l''intégrité du code grâce à des vérifications de types et des validations eslint, signalant les erreurs et confirmant que tout est correct","de":"Ermöglicht es den Agenten, `npx tsc --noEmit` und `npx expo lint` parallel auszuführen, wodurch die Codequalität und -integrität durch umfassende Typprüfungen und eslint-Validierungen sichergestellt werden, Fehler gemeldet werden und bestätigt wird, dass alles in Ordnung ist","pt":"Habilita os agentes a executar `npx tsc --noEmit` e `npx expo lint` em paralelo, garantindo a qualidade e integridade do código por meio de verificações de tipo abrangentes e validação do eslint, relatando erros e confirmando tudo limpo","ru":"Позволяет агентам запускать `npx tsc --noEmit` и `npx expo lint` параллельно, гарантируя качество и целостность кода за счет всесторонних проверок типов и валидации eslint, сообщая об ошибках и подтверждая все чистое","ar":"تمكن الوكلاء من تشغيل `npx tsc --noEmit` و `npx expo lint` بالتوازي ، مما يضمن جودة الشفرة وسلامتها من خلال عمليات التحقق الشاملة للنوع وعمليات التحقق من eslint ، وتقديم تقارير عن الأخطاء وتأكيد كل شيء نظيف"},"useCases":{"en":["Validating code syntax with eslint","Detecting type errors using tsc","Automating code review processes for JavaScript projects"],"zh":["使用eslint验证代码语法","使用tsc检测类型错误","自动化JavaScript项目的代码审查流程"],"ja":["eslintを使用してコードの構文を検証する","tscを使用して型エラーを検出する","JavaScriptプロジェクトのコードレビュー処理を自動化する"],"ko":["eslint를 사용하여 코드 구문을 확인한다","tsc를 사용하여 유형 오류를 감지한다","JavaScript 프로젝트의 코드 검토 프로세스를 자동화한다"],"es":["Validar la sintaxis del código con eslint","Detectar errores de tipo con tsc","Automatizar procesos de revisión de código para proyectos JavaScript"],"fr":["Valider la syntaxe du code avec eslint","Détecter les erreurs de type avec tsc","Automatiser les processus de révision de code pour les projets JavaScript"],"de":["Validieren der Codesyntax mit eslint","Fehler von Typen mit tsc erkennen","Automatisieren von Code-Review-Prozessen für JavaScript-Projekte"],"pt":["Validar sintaxe de código com eslint","Detectar erros de tipo usando tsc","Automatizar processos de revisão de código para projetos JavaScript"],"ru":["Проверка синтаксиса кода с помощью eslint","Обнаружение ошибок типов с помощью tsc","Автоматизация процессов код-ревью для проектов JavaScript"],"ar":["التحقق من بنية الشفرة باستخدام eslint","الكشف عن أخطاء النوع باستخدام tsc","تأتمة عمليات مراجعة الشفرة لمشاريع JavaScript"]},"limitations":{"en":["Requires Node.js environment","Limited to JavaScript projects with tsc and expo lint support"],"zh":["需要Node.js环境","仅限于支持tsc和expo lint的JavaScript项目"],"ja":["Node.js環境が必要","tscとexpo lintをサポートするJavaScriptプロジェクトのみ"],"ko":["Node.js 환경이 필요합니다","tsc와 expo lint를 지원하는 JavaScript 프로젝트에만 적용됩니다"],"es":["Requiere un entorno Node.js","Limitado a proyectos JavaScript con soporte para tsc y expo lint"],"fr":["Nécessite un environnement Node.js","Limité aux projets JavaScript avec prise en charge de tsc et expo lint"],"de":["Benötigt eine Node.js-Umgebung","Begrenzt auf JavaScript-Projekte mit Unterstützung für tsc und expo lint"],"pt":["Requer ambiente Node.js","Limitado a projetos JavaScript com suporte a tsc e expo lint"],"ru":["Требуется среда Node.js","Ограничен для проектов JavaScript с поддержкой tsc и expo lint"],"ar":["يتطلب بيئة Node.js","محدود لمشاريع JavaScript مع دعم tsc و expo lint"]},"version":4},"contentHash":"c3cc39ccc38e8c78068de51e43f2c30cda3aa2d6d323f2cb0b031cef23fcee21","qualityScore":20}');
