INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tfunk1030/bnredo/check', 'check', 'tfunk1030', 'bnredo', 'community', 'check tfunk1030 bnredo community The check skill runs both type checks and linting in parallel, reporting errors and confirming all clear. It benefits developers by ensuring code quality and integrity. 代码检查功能使用npx tsc和expo lint进行类型检查和代码风格检查 AIエージェントのコードチェック機能は、npx tscとexpo lintを使用してコードのタイプチェックとスタイルチェックを行います 코드 검사 기능은 npx tsc와 expo lint를 사용하여 코드의 타입 체크와 스타일 체크를 수행합니다 El check de calidad es una habilidad que ejecuta comandos de verificación en paralelo con tsc y eslint para asegurar la calidad del código Le check de qualité est une fonctionnalité qui exécute des commandes de vérification en paralelo avec tsc et eslint pour garantir la qualité du code Der Qualitätsscheck ist eine Fähigkeit, die Überprüfungsbefehle parallel mit tsc und eslint ausführt, um die Codequalität sicherzustellen O Check é uma ferramenta para verificar a qualidade do código, executando npx tsc e npx expo lint em paralelo. Check - это инструмент для проверки качества кода, запускающий npx tsc и npx expo lint параллельно. أداة الفحص هي أداة لتحسين جودة الكود من خلال تشغيل npx tsc و npx expo lint بشكل متوازي how to use check what is check check alternative check vs eslint check install check setup guide npx tsc --noEmit npx expo lint TypeScript quality assurance 代码检查 npx tsc expo lint 代码质量 代码一致性 AI工具 代码开发 Runs npx tsc --noEmit for type checking Executes npx expo lint for ESLint validation Reports errors from both type checks and linting Confirms all clear when no errors are found Runs type checks and linting in parallel for efficiency Supports Expo and TypeScript projects check is a quality assurance tool that runs type checks via npx tsc and linting via npx expo lint, reporting results and errors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LoopedLMs/ouro_rl/read-arxiv-paper', 'community', 'LoopedLMs', 'ouro_rl', 'LoopedLMs/ouro_rl', 'read-arxiv-paper', 1, 0, 20, '2026-02-25T16:31:04Z', '2026-03-06T07:12:00.626Z', '9814499fd74be37bfb23b7f81d2a30f1d9e65e9819c85cfeb6cea4a85ba9e7ad', '{"id":"LoopedLMs/ouro_rl/read-arxiv-paper","name":"read-arxiv-paper","description":{"en":"The read-arxiv-paper skill fetches TeX sources from arXiv papers, benefiting AI agents and developers. It normalizes URLs and downloads paper sources.","zh":"read-arxiv-paper技能可以自动化下载arxiv论文的TeX源码，支持开发者快速获取所需资源","ja":"read-arxiv-paperスキルはarxiv論文のTeXソースを自動的にダウンロードし、開発者が必要なリソースを迅速に取得できるようにします","ko":"read-arxiv-paper 스킬은 arxiv 논문의 TeX 소스를 자동으로 다운로드하여 개발자가 필요한 리소스를 빠르게 가져올 수 있도록 합니다","es":"El agente de lectura de artículos de arXiv permite descargar fuentes de TeX de documentos de investigación de arXiv","fr":"L''agent de lecture de documents arXiv permet de télécharger les sources TeX des articles de recherche arXiv","de":"Der arXiv-Paper-Lese-Agent ermöglicht das Herunterladen von TeX-Quellen von arXiv-Forschungsdokumenten","pt":"O read-arxiv-paper é uma ferramenta que permite fetch de fontes TeX de artigos do arXiv. Aprenda a configurá-la.","ru":"read-arxiv-paper - это инструмент, который позволяет скачивать исходники TeX из arXiv. Узнайте, как его настроить.","ar":"read-arxiv-paper هو أداة تمكنك من تنزيل مصادر TeX من موقع arXiv. تعرف على كيفية إعدادها."},"seo":{"title":{"en":"read-arxiv-paper: TeX Source Fetching Setup Guide | AI Ag...","zh":"read-arxiv-paper Setup Guide: 利用TeX源码","ja":"read-arxiv-paper セットアップガイド: TeXソースの取得","ko":"read-arxiv-paper 설정 가이드: TeX 소스 다운로드","es":"Guía de configuración del agente de lectura de artículos ...","fr":"Guide d''installation de l''agent de lecture de documents a...","de":"Einrichtungsanleitung für den arXiv-Paper-Lese-Agenten","pt":"Guia de Configuração do read-arxiv-paper para Desenvolved...","ru":"Настройка read-arxiv-paper: ИИ Агенты для Разработчиков","ar":"دليل إعداد read-arxiv-paper لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to fetch TeX sources from arXiv papers with read-arxiv-paper. Learn to normalize URLs and download paper sources with this AI agent skill.","zh":"了解read-arxiv-paper技能，实现自动化下载arxiv论文的TeX源码，提高开发效率","ja":"read-arxiv-paperスキルを使用してarxiv論文のTeXソースを自動的にダウンロードし、開発効率を向上させる","ko":"read-arxiv-paper 스킬을 사용하여 arxiv 논문의 TeX 소스를 자동으로 다운로드하고 개발 효율을 높입니다","es":"Aprende a configurar el agente de lectura de artículos de arXiv para descargar fuentes de TeX de documentos de investigación","fr":"Découvrez comment installer l''agent de lecture de documents arXiv pour télécharger les sources TeX des articles de recherche","de":"Erfahren Sie, wie Sie den arXiv-Paper-Lese-Agenten einrichten, um TeX-Quellen von Forschungsdokumenten herunterzuladen","pt":"Aprenda a configurar o read-arxiv-paper para fetch de fontes TeX de artigos do arXiv","ru":"Узнайте, как настроить read-arxiv-paper для скачивания исходников TeX из arXiv с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد read-arxiv-paper لتنزيل مصادر TeX من موقع arXiv باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"read-arxiv-paper is a skill that fetches TeX sources from arXiv papers by normalizing URLs and downloading paper sources.","zh":"read-arxiv-paper是一种AI工具，用于下载arxiv论文的TeX源码","ja":"read-arxiv-paperはAIエージェントで、arxiv論文のTeXソースをダウンロードするために使用されます","ko":"read-arxiv-paper는 arxiv 논문의 TeX 소스를 다운로드하기 위한 AI 도구입니다","es":"Un agente de lectura de artículos de arXiv es una herramienta que permite descargar fuentes de TeX de documentos de investigación","fr":"Un agent de lecture de documents arXiv est un outil qui permet de télécharger les sources TeX des articles de recherche","de":"Ein arXiv-Paper-Lese-Agent ist ein Tool, das das Herunterladen von TeX-Quellen von Forschungsdokumenten ermöglicht","pt":"O que é read-arxiv-paper? É uma ferramenta que normaliza URLs e fetch de fontes TeX de artigos do arXiv.","ru":"Что такое read-arxiv-paper? Это инструмент, который нормализует URL и скачивает исходники TeX из arXiv.","ar":"ما هو read-arxiv-paper؟ هو أداة تقوم بتحويل عناوين URL وتحميل مصادر TeX من موقع arXiv."},"features":{"en":["Normalizes arXiv paper URLs to fetch TeX sources","Downloads paper sources from normalized URLs","Supports fetching from https://www.arxiv.org/src/ URLs","Relies on relative file paths to the project root directory","Utilizes the .claude/ folder for project root identification"],"zh":["支持自动化下载arxiv论文的TeX源码","实现URL规范化，确保下载正确的TeX源码","支持开发者快速获取所需资源"],"ja":["arxiv論文のTeXソースを自動的にダウンロードする","URLを正規化して、正しいTeXソースをダウンロードする","開発者が必要なリソースを迅速に取得できるようにする"],"ko":["arxiv 논문의 TeX 소스를 자동으로 다운로드","URL을 정규화하여 올바른 TeX 소스를 다운로드","개발자가 필요한 리소스를 빠르게 가져올 수 있도록 함"],"es":["Normalización de URLs de artículos de arXiv","Descarga de fuentes de TeX de documentos de investigación","Compatibilidad con la estructura de directorios de arXiv","Uso de URLs de fuente de TeX para la descarga","Integración con la herramienta de línea de comandos CLI"],"fr":["Normalisation des URLs des documents arXiv","Téléchargement des sources TeX des articles de recherche","Compatibilité avec la structure de répertoires arXiv","Utilisation des URLs de source TeX pour le téléchargement","Intégration avec l''outil de ligne de commande CLI"],"de":["Normalisierung von arXiv-Artikel-URLs","Herunterladen von TeX-Quellen von Forschungsdokumenten","Kompatibilität mit der arXiv-Verzeichnisstruktur","Verwendung von TeX-Quell-URLs für das Herunterladen","Integration mit der CLI-Kommandozeilenwerkzeug"],"pt":["Normalização de URLs do arXiv","Fetch de fontes TeX de artigos","Suporte a URLs no formato https://www.arxiv.org/src/","Capacidade de lidar com diferentes formatos de URLs","Integração com ferramentas de desenvolvimento"],"ru":["Нормализация URL из arXiv","Скачивание исходников TeX из статей","Поддержка URL в формате https://www.arxiv.org/src/","Возможность работать с разными форматами URL","Интеграция с инструментами разработки"],"ar":["تحويل عناوين URL من موقع arXiv","تحميل مصادر TeX من المقالات","دعم عناوين URL بالصيغة https://www.arxiv.org/src/","القدرة على التعامل مع صيغ مختلفة من عناوين URL","التكامل مع أدوات التطوير"]},"keywords":{"en":["how to use read-arxiv-paper","read-arxiv-paper alternative","read-arxiv-paper setup guide","what is read-arxiv-paper","read-arxiv-paper vs other AI skills","install read-arxiv-paper","read-arxiv-paper for AI agents","TeX source fetching with read-arxiv-paper","arXiv paper URL normalization"],"zh":["read-arxiv-paper","arxiv论文下载","TeX源码","AI工具","自动化下载","开发效率"],"ja":["read-arxiv-paper","arxiv論文ダウンロード","TeXソース","AIエージェント","自動ダウンロード","開発効率"],"ko":["read-arxiv-paper","arxiv 논문 다운로드","TeX 소스","AI 도구","자동 다운로드","개발 효율"],"es":["agente de lectura de artículos de arXiv","descarga de fuentes de TeX","arXiv paper","herramienta de lectura de artículos de investigación","tecnologías de inteligencia artificial","agentes de lectura de documentos","normalización de URLs","descarga de documentos de investigación"],"fr":["agent de lecture de documents arXiv","téléchargement de sources TeX","document arXiv","outil de lecture d''articles de recherche","technologies d''intelligence artificielle","agents de lecture de documents","normalisation des URLs","téléchargement de documents de recherche"],"de":["arXiv-Paper-Lese-Agent","Herunterladen von TeX-Quellen","arXiv-Dokument","Werkzeug für das Lesen von Forschungsdokumenten","Technologien der künstlichen Intelligenz","Lese-Agenten für Dokumente","Normalisierung von URLs","Herunterladen von Forschungsdokumenten"],"pt":["read-arxiv-paper","arXiv","TeX","fetch de fontes","normalização de URLs","desenvolvimento de software","ferramentas de desenvolvimento","configuração do read-arxiv-paper"],"ru":["read-arxiv-paper","arXiv","TeX","скачивание исходников","нормализация URL","разработка программного обеспечения","инструменты разработки","настройка read-arxiv-paper","ИИ Агенты"],"ar":["read-arxiv-paper","arXiv","TeX","تحميل مصادر","تحويل عناوين URL","تطوير البرمجيات","أدوات التطوير","إعداد read-arxiv-paper","أدوات الذكاء الاصطناعي"]}},"owner":"LoopedLMs","repo":"ouro_rl","repoPath":"LoopedLMs/ouro_rl","stars":1,"forks":0,"updatedAt":"2026-02-25T16:31:04Z","topics":[],"category":"community","skillMd":{"name":"read-arxiv-paper","description":"Use this skill when when asked to read an arxiv paper given an arxiv URL","bodyPreview":"All file paths below are relative to the **project root** (the directory containing the `.claude/` folder, not the skill directory itself).\n\nYou will be given a URL of an arxiv paper, for example:\n\nhttps://www.arxiv.org/abs/2601.07372\n\n### Part 1: Normalize the URL\n\nThe goal is to fetch the TeX Source of the paper (not the PDF!), the URL always looks like this:\n\nhttps://www.arxiv.org/src/2601.07372\n\nNotice the /src/ in the url. Once you have the URL:\n\n### Part 2: Download the paper source\n\nFetch","body":"All file paths below are relative to the **project root** (the directory containing the `.claude/` folder, not the skill directory itself).\n\nYou will be given a URL of an arxiv paper, for example:\n\nhttps://www.arxiv.org/abs/2601.07372\n\n### Part 1: Normalize the URL\n\nThe goal is to fetch the TeX Source of the paper (not the PDF!), the URL always looks like this:\n\nhttps://www.arxiv.org/src/2601.07372\n\nNotice the /src/ in the url. Once you have the URL:\n\n### Part 2: Download the paper source\n\nFetch the url to a local .tar.gz file.\n\n### Part 3: Unpack the file in that folder\n\nUnpack the contents into `./knowledge/{arxiv_id}` directory and delete the .tar.gz.\n\n### Part 4: Locate the entrypoint\n\nEvery latex source usually has an entrypoint, such as `main.tex` or something like that.\n\n### Part 5: Read the paper\n\nOnce you''ve found the entrypoint, Read the contents and then recurse through all other relevant source files to read the paper.\n\n#### Part 6: Report\n\nOnce you''ve read the paper, produce a summary of the paper into a markdown file at `./knowledge/summary_{tag}.md`. Notice that 1) use the local knowledge directory here (it''s easier for me to open and reference here), and 2) generate some reasonable `tag` like e.g. `conditional_memory` or whatever seems appropriate given the paper. Probably make sure that the tag doesn''t exist yet so you''re not overwriting files.\n\nAs for the summary itself, remember that you''re processing this paper within the context of the ouro_rl repository, which explores the Ouro pretrained language model. Focus on how the paper''s ideas might apply to loading, fine-tuning, or doing RL with the Ouro model.\n"},"lastSynced":"2026-03-06T07:12:00.626Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Agents needing to fetch and analyze TeX sources from arXiv papers.","zh":"非常适合需要获取和分析arXiv论文中的TeX源的研究代理。","ja":"arXiv論文からのTeXソースを取得して分析する必要があるリサーチエージェントに最適です。","ko":"arXiv 논문에서 TeX 소스를 가져와 분석해야 하는 연구 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Investigación que necesitan recuperar y analizar fuentes TeX de artículos de arXiv.","fr":"Parfait pour les Agents de Recherche ayant besoin de récupérer et d''analyser les sources TeX des articles arXiv.","de":"Perfekt für Forschungsagenten, die Quellen im TeX-Format aus arXiv-Artikeln abrufen und analysieren müssen.","pt":"Perfeito para Agentes de Pesquisa que precisam buscar e analisar fontes TeX de artigos do arXiv.","ru":"Идеально подходит для агентов-исследователей, которым необходимо извлекать и анализировать источники TeX из статей arXiv.","ar":"مثالي لعميل البحث الذي يحتاج إلى استخراج و تحليل مصادر TeX من الأوراق البحثية في arXiv."},"recommendation":{"en":"Empowers agents to normalize arXiv URLs and download paper sources using the /src/ protocol, facilitating advanced data analysis and machine learning model training on scientific publications in TeX format.","zh":"赋予代理人标准化arXiv URL和使用/src/协议下载论文源的能力，从而实现对科学出版物的TeX格式进行高级数据分析和机器学习模型训练。","ja":"エージェントにarXiv URLを標準化し、/src/プロトコルを使用して論文ソースをダウンロードする機能を与え、TeX形式の科学出版物に対して高度なデータ分析と機械学習モデルトレーニングを可能にします。","ko":"에이전트에게 arXiv URL을 표준화하고 /src/ 프로토콜을 사용하여 논문 소스를 다운로드하는 기능을 부여하여 TeX 형식의 과학 출판물에 대한 고급 데이터 분석 및 기계 학습 모델 훈련을 가능하게 합니다.","es":"Permite a los agentes normalizar URLs de arXiv y descargar fuentes de artículos utilizando el protocolo /src/, facilitando un análisis de datos avanzado y un entrenamiento de modelos de aprendizaje automático sobre publicaciones científicas en formato TeX.","fr":"Permet aux agents de normaliser les URLs arXiv et de télécharger les sources des articles en utilisant le protocole /src/, facilitant ainsi une analyse de données avancée et un entraînement de modèles d''apprentissage automatique sur des publications scientifiques au format TeX.","de":"Ermöglicht es Agenten, arXiv-URLs zu normalisieren und Quellen von Artikeln unter Verwendung des /src/-Protokolls herunterzuladen, wodurch eine erweiterte Datenanalyse und ein Training von Machine-Learning-Modellen auf wissenschaftlichen Veröffentlichungen im TeX-Format erleichtert wird.","pt":"Permite que os agentes normalizem URLs do arXiv e façam download de fontes de artigos usando o protocolo /src/, facilitando a análise de dados avançada e o treinamento de modelos de aprendizado de máquina em publicações científicas no formato TeX.","ru":"Предоставляет агентам возможность нормализовать URL-адреса arXiv и загружать источники статей с помощью протокола /src/, облегчая проведение расширенного анализа данных и обучение моделей машинного обучения на научных публикациях в формате TeX.","ar":"يتمكن العملاء من تنسيق عناوين URL من arXiv وتنزيل مصادر الأوراق البحثية باستخدام بروتوكول /src/، مما يسهل تحليل البيانات المتقدم وتدريب نماذج التعلم الالي على المنشورات العلمية بالتنسيق TeX."},"useCases":{"en":["Normalizing arXiv URLs for consistent data ingestion","Downloading TeX sources for paper analysis and information extraction","Fetching paper metadata for research cataloging and indexing"],"zh":["标准化arXiv URL以实现一致的数据摄取","下载TeX源以进行论文分析和信息提取","获取论文元数据以进行研究编目和索引"],"ja":["一貫したデータインジェストのためにarXiv URLを標準化する","論文分析と情報抽出のためにTeXソースをダウンロードする","研究カタログとインデックスのために論文メタデータを取得する"],"ko":["일관된 데이터摄取을 위한 arXiv URL 표준화","논문 분석 및 정보 추출을 위한 TeX 소스 다운로드","연구 카탈로그 및 색인을 위한 논문 메타데이터 가져오기"],"es":["Normalizar URLs de arXiv para una ingesta de datos coherente","Descargar fuentes TeX para el análisis de artículos y la extracción de información","Recuperar metadatos de artículos para el catálogo y el índice de investigaciones"],"fr":["Normaliser les URLs arXiv pour une ingestion de données cohérente","Télécharger les sources TeX pour l''analyse d''articles et l''extraction d''informations","Récupérer les métadonnées d''articles pour le catalogage et l''indexation de la recherche"],"de":["arXiv-URLs normalisieren, um eine konsistente Datenübernahme zu ermöglichen","TeX-Quellen herunterladen, um Artikel zu analysieren und Informationen zu extrahieren","ArtikelmMetadaten abrufen, um Forschungskataloge und -indizes zu erstellen"],"pt":["Normalizar URLs do arXiv para ingestão de dados consistente","Baixar fontes TeX para análise de artigos e extração de informações","Buscar metadados de artigos para catalogação e indexação de pesquisas"],"ru":["Нормализовать URL-адреса arXiv для последовательного потребления данных","Загрузить источники TeX для анализа статей и извлечения информации","Получить метаданные статей для каталогизации и индексации исследований"],"ar":["تنسيق عناوين URL من arXiv لاستيعاب البيانات المتسق","تنزيل مصادر TeX لتحليل الأوراق البحثية واستخراج المعلومات","استرجاع بيانات وصف الأوراق البحثية لتسجيل البحوث وفهارسها"]},"limitations":{"en":["Requires internet access for arXiv URL normalization and paper source download","Limited to arXiv papers with available TeX sources"],"zh":["需要互联网访问以标准化arXiv URL和下载论文源","仅限于具有可用TeX源的arXiv论文"],"ja":["arXiv URLを標準化し、論文ソースをダウンロードするためにインターネットアクセスが必要","TeXソースが利用可能なarXiv論文のみに限定される"],"ko":["arXiv URL을 표준화하고 논문 소스를 다운로드하기 위해 인터넷 액세스가 필요함","TeX 소스가 사용 가능한 arXiv 논문만에 국한됨"],"es":["Requiere acceso a Internet para la normalización de URLs de arXiv y la descarga de fuentes de artículos","Limitado a artículos de arXiv con fuentes TeX disponibles"],"fr":["Nécessite un accès à Internet pour la normalisation des URLs arXiv et le téléchargement des sources d''articles","Limité aux articles arXiv avec des sources TeX disponibles"],"de":["Benötigt Internetzugang für die Normalisierung von arXiv-URLs und den Download von Artikelquellen","Begrenzt auf arXiv-Artikel mit verfügbaren TeX-Quellen"],"pt":["Requer acesso à internet para normalização de URLs do arXiv e download de fontes de artigos","Limitado a artigos do arXiv com fontes TeX disponíveis"],"ru":["Требуется доступ к интернету для нормализации URL-адресов arXiv и загрузки источников статей","Ограничен статьями arXiv с доступными источниками TeX"],"ar":["يتطلب الوصول إلى الإنترنت لتنسيق عناوين URL من arXiv وتنزيل مصادر الأوراق البحثية","محدود بالأوراق البحثية من arXiv التي تحتوي على مصادر TeX المتاحة"]},"version":4},"contentHash":"9814499fd74be37bfb23b7f81d2a30f1d9e65e9819c85cfeb6cea4a85ba9e7ad","qualityScore":20}');
