INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LoopedLMs/ouro_rl/read-arxiv-paper', 'read-arxiv-paper', 'LoopedLMs', 'ouro_rl', 'community', 'read-arxiv-paper LoopedLMs ouro_rl community The read-arxiv-paper skill fetches TeX sources from arXiv papers, benefiting AI agents and developers. It normalizes URLs and downloads paper sources. read-arxiv-paper技能可以自动化下载arxiv论文的TeX源码，支持开发者快速获取所需资源 read-arxiv-paperスキルはarxiv論文のTeXソースを自動的にダウンロードし、開発者が必要なリソースを迅速に取得できるようにします read-arxiv-paper 스킬은 arxiv 논문의 TeX 소스를 자동으로 다운로드하여 개발자가 필요한 리소스를 빠르게 가져올 수 있도록 합니다 El agente de lectura de artículos de arXiv permite descargar fuentes de TeX de documentos de investigación de arXiv L''agent de lecture de documents arXiv permet de télécharger les sources TeX des articles de recherche arXiv Der arXiv-Paper-Lese-Agent ermöglicht das Herunterladen von TeX-Quellen von arXiv-Forschungsdokumenten O read-arxiv-paper é uma ferramenta que permite fetch de fontes TeX de artigos do arXiv. Aprenda a configurá-la. read-arxiv-paper - это инструмент, который позволяет скачивать исходники TeX из arXiv. Узнайте, как его настроить. read-arxiv-paper هو أداة تمكنك من تنزيل مصادر TeX من موقع arXiv. تعرف على كيفية إعدادها. how to use read-arxiv-paper read-arxiv-paper alternative read-arxiv-paper setup guide what is read-arxiv-paper read-arxiv-paper vs other AI skills install read-arxiv-paper read-arxiv-paper for AI agents TeX source fetching with read-arxiv-paper arXiv paper URL normalization read-arxiv-paper arxiv论文下载 TeX源码 AI工具 自动化下载 开发效率 Normalizes arXiv paper URLs to fetch TeX sources Downloads paper sources from normalized URLs Supports fetching from https://www.arxiv.org/src/ URLs Relies on relative file paths to the project root directory Utilizes the .claude/ folder for project root identification read-arxiv-paper is a skill that fetches TeX sources from arXiv papers by normalizing URLs and downloading paper sources.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('joshband/LocusQ/skill_design', 'community', 'joshband', 'LocusQ', 'joshband/LocusQ', 'skill_design', 1, 0, 20, '2026-02-27T04:26:57Z', '2026-03-06T07:14:01.285Z', 'a52d8160061d35f9470ce0578a513ae6564ae34c0706bde305fb152cebadeb7c', '{"id":"joshband/LocusQ/skill_design","name":"skill_design","description":{"en":"The skill_design skill enables AI agents to utilize LocusQ, a Quadraphonic 3D Spatial Audio Tool, benefiting developers working with JUCE 8 VST3/AU plugins. It streamlines audio workflow integration.","zh":"LocusQ 是一个 Quadraphonic 3D Spatial Audio Tool，使用 JUCE 8 VST3/AU 插件技术","ja":"LocusQ はクアドラフォニック 3D Spatial Audio Tool であり、JUCE 8 VST3/AU プラグイン技術を使用","ko":"LocusQ는 쿼드라포닉 3D Spatial Audio Tool로서 JUCE 8 VST3/AU 플러그인 기술을 사용","es":"LocusQ es una herramienta de audio 3D espacial quadrafónica que utiliza JUCE 8 VST3/AU Plugin para ofrecer experiencias de audio inmersivas","fr":"LocusQ est un outil audio 3D spatial quadraphonique qui utilise JUCE 8 VST3/AU Plugin pour offrir des expériences audio immersives","de":"LocusQ ist ein 3D-Spatial-Audio-Tool mit Quadraphonie, das JUCE 8 VST3/AU Plugin verwendet, um immersive Audio-Erfahrungen zu bieten","pt":"O LocusQ é uma ferramenta de áudio 3D espacial quadrafônica que utiliza a tecnologia JUCE 8 VST3/AU Plugin para processar áudio","ru":"LocusQ - это инструмент Quadraphonic 3D Spatial Audio, который использует технологию JUCE 8 VST3/AU Plugin для обработки аудио ИИ Агенты","ar":"LocusQ هو أداة الصوت ثلاثي الأبعاد المكانية Quadraphonic التي تستخدم تقنية JUCE 8 VST3/AU Plugin لمعالجة الصوت"},"seo":{"title":{"en":"skill_design: Quadraphonic 3D Spatial Audio Setup Guide |...","zh":"LocusQ Quadraphonic 3D Spatial Audio Tool 设计指南","ja":"LocusQ クアドラフォニック 3D Spatial Audio Tool 設計ガイド","ko":"LocusQ 쿼드라포닉 3D Spatial Audio Tool 설계 가이드","es":"Guía de configuración de LocusQ para diseño de audio 3D","fr":"Guide de mise en route de LocusQ pour la conception audio 3D","de":"Einrichtungsleitfaden für LocusQ 3D-Audio-Design","pt":"Guia de Configuração do LocusQ - Ferramenta de Áudio 3D","ru":"Настройка LocusQ - Инструмент Quadraphonic 3D Spatial Aud...","ar":"دليل إعداد LocusQ - أداة الصوت ثلاثي الأبعاد المكانية"},"description":{"en":"Discover how to leverage LocusQ for immersive audio experiences. Learn to integrate the JUCE 8 VST3/AU plugin with your AI agent workflow today!","zh":"了解 LocusQ Quadraphonic 3D Spatial Audio Tool 的设计和开发，包括 JUCE 8 VST3/AU 插件","ja":"LocusQ クアドラフォニック 3D Spatial Audio Tool の設計と開発について学ぶ、JUCE 8 VST3/AU プラグインを含む","ko":"LocusQ 쿼드라포닉 3D Spatial Audio Tool의 설계와 개발에 대해 알아보세요, JUCE 8 VST3/AU 플러그인을 포함","es":"Aprende a utilizar LocusQ para crear experiencias de audio 3D inmersivas con nuestra guía de configuración y mejores prácticas","fr":"Découvrez comment utiliser LocusQ pour créer des expériences audio 3D immersives avec notre guide de configuration et de meilleures pratiques","de":"Erfahren Sie, wie Sie LocusQ verwenden, um immersive 3D-Audio-Erfahrungen mit unserer Einrichtungsanleitung und Best Practices zu erstellen","pt":"Aprenda a configurar o LocusQ, uma ferramenta de áudio 3D espacial quadrafônica, e explore suas capacidades de processamento de áudio","ru":"Узнайте, как настроить LocusQ, инструмент Quadraphonic 3D Spatial Audio, и изучите его возможности обработки аудио ИИ Агенты","ar":"تعرف على كيفية إعداد LocusQ، أداة الصوت ثلاثي الأبعاد المكانية Quadraphonic، واكتشف إمكانيات معالجة الصوت"},"definition":{"en":"skill_design is a technical skill that allows AI agents to interact with LocusQ, a 3D spatial audio tool, for enhanced audio processing capabilities.","zh":"LocusQ 是一个用于创建 3D 空间音频的工具","ja":"LocusQ は 3D 空間オーディオを作成するためのツール","ko":"LocusQ는 3D 공간 오디오를 생성하기 위한 도구","es":"LocusQ es una herramienta de diseño de audio 3D que utiliza tecnologías de audio espacial para crear experiencias inmersivas","fr":"LocusQ est un outil de conception audio 3D qui utilise des technologies audio spatiales pour créer des expériences immersives","de":"LocusQ ist ein Tool für das 3D-Audio-Design, das Audio-Raumtechnologien verwendet, um immersive Erfahrungen zu erstellen","pt":"O que é LocusQ? É uma ferramenta de áudio 3D espacial quadrafônica que processa áudio utilizando JUCE 8 VST3/AU Plugin","ru":"Что такое LocusQ? Это инструмент Quadraphonic 3D Spatial Audio, который обрабатывает аудио с помощью JUCE 8 VST3/AU Plugin ИИ Агенты","ar":"ما هو LocusQ؟ هو أداة الصوت ثلاثي الأبعاد المكانية Quadraphonic التي تعالج الصوت باستخدام JUCE 8 VST3/AU Plugin"},"features":{"en":["Executes the design skill with provided arguments","Follows the APC required load sequence","Reads `.codex/rules/agent.md` for configuration","Supports JUCE 8 VST3/AU plugin integration","Utilizes the LocusQ Quadraphonic 3D Spatial Audio Tool","Processes audio workflows based on `.codex/workflows/design.md`"],"zh":["支持 JUCE 8 VST3/AU 插件","Quadraphonic 3D Spatial Audio","设计和开发指南","APC Codex 规则支持","SKILL.md 文档支持"],"ja":["JUCE 8 VST3/AU プラグインをサポート","クアドラフォニック 3D Spatial Audio","設計と開発ガイド","APC Codex ルールをサポート","SKILL.md ドキュメントをサポート"],"ko":["JUCE 8 VST3/AU 플러그인을 지원","쿼드라포닉 3D Spatial Audio","설계와 개발 가이드","APC Codex 규칙을 지원","SKILL.md 문서를 지원"],"es":["Compatibilidad con JUCE 8 VST3/AU Plugin","Diseño de audio 3D espacial quadrafónico","Seguimiento de la secuencia de carga de APC","Ejecución de la habilidad de diseño con argumentos personalizados"],"fr":["Compatibilité avec JUCE 8 VST3/AU Plugin","Conception audio 3D spatial quadraphonique","Suivi de la séquence de chargement APC","Exécution de la compétence de conception avec des arguments personnalisés"],"de":["Kompatibilität mit JUCE 8 VST3/AU Plugin","3D-Spatial-Audio-Design mit Quadraphonie","Verfolgung der APC-Ladesequenz","Ausführung der Designfähigkeit mit benutzerdefinierten Argumenten"],"pt":["Utiliza a tecnologia JUCE 8 VST3/AU Plugin","Processamento de áudio 3D espacial quadr