INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('joshband/LocusQ/skill_design', 'skill_design', 'joshband', 'LocusQ', 'community', 'skill_design joshband LocusQ community The skill_design skill enables AI agents to utilize LocusQ, a Quadraphonic 3D Spatial Audio Tool, benefiting developers working with JUCE 8 VST3/AU plugins. It streamlines audio workflow integration. LocusQ 是一个 Quadraphonic 3D Spatial Audio Tool，使用 JUCE 8 VST3/AU 插件技术 LocusQ はクアドラフォニック 3D Spatial Audio Tool であり、JUCE 8 VST3/AU プラグイン技術を使用 LocusQ는 쿼드라포닉 3D Spatial Audio Tool로서 JUCE 8 VST3/AU 플러그인 기술을 사용 LocusQ es una herramienta de audio 3D espacial quadrafónica que utiliza JUCE 8 VST3/AU Plugin para ofrecer experiencias de audio inmersivas LocusQ est un outil audio 3D spatial quadraphonique qui utilise JUCE 8 VST3/AU Plugin pour offrir des expériences audio immersives LocusQ ist ein 3D-Spatial-Audio-Tool mit Quadraphonie, das JUCE 8 VST3/AU Plugin verwendet, um immersive Audio-Erfahrungen zu bieten O LocusQ é uma ferramenta de áudio 3D espacial quadrafônica que utiliza a tecnologia JUCE 8 VST3/AU Plugin para processar áudio LocusQ - это инструмент Quadraphonic 3D Spatial Audio, который использует технологию JUCE 8 VST3/AU Plugin для обработки аудио ИИ Агенты LocusQ هو أداة الصوت ثلاثي الأبعاد المكانية Quadraphonic التي تستخدم تقنية JUCE 8 VST3/AU Plugin لمعالجة الصوت how to use skill_design skill_design setup guide LocusQ plugin integration JUCE 8 VST3/AU plugin tutorial skill_design vs audio workflow tools what is skill_design skill_design install for AI agents 3D spatial audio tool alternatives Quadraphonic audio plugin setup LocusQ Quadraphonic 3D Spatial Audio JUCE 8 VST3/AU AIエージェント 音频工具 设计指南 开发工具 Executes the design skill with provided arguments Follows the APC required load sequence Reads `.codex/rules/agent.md` for configuration Supports JUCE 8 VST3/AU plugin integration Utilizes the LocusQ Quadraphonic 3D Spatial Audio Tool Processes audio workflows based on `.codex/workflows/design.md` skill_design is a technical skill that allows AI agents to interact with LocusQ, a 3D spatial audio tool, for enhanced audio processing capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shiromac/wpfAutoTester/wpf-ui', 'community', 'shiromac', 'wpfAutoTester', 'shiromac/wpfAutoTester', 'wpf-ui', 1, 0, 20, '2026-03-06T07:48:00Z', '2026-03-06T13:11:33.674Z', 'ec2b74f6999c9154ad47d98579fb9dde7a5775890a4d618e7e39d174bfccf8e4', '{"id":"shiromac/wpfAutoTester/wpf-ui","name":"wpf-ui","description":{"en":"The wpf-ui skill integrates Claude Code with WPF applications for automated UI testing. It uses screenshot analysis and control tree inspection (`list_controls`, `list_windows`) to autonomously test and fix UI issues, benefiting developers building .NET desktop applications.","zh":"WPF UI自动化测试AI驱动的UI测试，支持inspect、click和type模式","ja":"WPF UI自動化エージェントは、inspect、click、typeモードをサポートするAI駆動のUIテスト","ko":"WPF UI 자동화 테스트 에이전트는 inspect, click, type 모드를 지원하는 AI 기반의 UI 테스트","es":"WPF UI es un agente de pruebas automatizadas que utiliza la inteligencia artificial para explorar y probar aplicaciones, y corregir errores encontrados","fr":"WPF UI est un agent de tests automatisés qui utilise l''intelligence artificielle pour explorer et tester des applications, et corriger les erreurs trouvées","de":"WPF UI ist ein Agent für automatisierte Tests, der künstliche Intelligenz nutzt, um Anwendungen zu erkunden und zu testen, und Fehler zu beheben","pt":"O agente WPF-UI é uma ferramenta de teste de interface impulsionada por IA que automatiza a exploração e teste de aplicações WPF","ru":"ИИ Агент WPF-UI - это инструмент для тестирования интерфейса, работающий на основе ИИ, который автоматизирует исследование и тестирование приложений WPF","ar":"وحدة تحكم واجهة المستخدم WPF-UI هي أداة اختبار واجهة مدعومة بالذكاء الاصطناعي التي تلقم التحقق التلقائي والتجريب لبرامج WPF"},"seo":{"title":{"en":"wpf-ui: AI-Powered WPF UI Testing Agent | Setup Guide","zh":"WPF UI自动化测试指南 - AI驱动的UI测试","ja":"WPF UI自動化エージェントの設定方法 - AIエージェント","ko":"WPF UI 자동화 테스트 가이드 - AI 에이전트","es":"Guía de configuración de WPF UI para pruebas automatizada...","fr":"Guide de configuration de WPF UI pour les tests automatis...","de":"Konfigurationsleitfaden für WPF UI-Tests mit KI-Agents","pt":"Guia de Configuração do Agente WPF-UI para Testes de Inte...","ru":"Настройка ИИ Агента WPF-UI для тестирования интерфейса","ar":"دليل إعداد وحدات تحكم واجهة المستخدم WPF-UI من أجل الاختب..."},"description":{"en":"Automate WPF UI testing with Claude AI. This agent analyzes screenshots, autonomously explores controls via `list_controls`, and performs clicks or text inpu...","zh":"使用WPF UI自动化测试AI驱动的UI测试，提高测试效率和准确性","ja":"WPF UI自動化エージェントを使ってUIの自動テストを実行し、テストの効率と精度を向上させる","ko":"WPF UI 자동화 테스트 에이전트를 사용하여 UI 자동 테스트를 수행하고 테스트 효율과 정확도를 향상시키다","es":"Aprende a configurar WPF UI para pruebas automatizadas con Agentes de Inteligencia Artificial y mejora la eficiencia de tus pruebas","fr":"Découvrez comment configurer WPF UI pour les tests automatisés avec des Agents d''Intelligence Artificielle et améliorez l''efficacité de vos tests","de":"Erfahren Sie, wie Sie WPF UI für automatisierte Tests mit KI-Agents konfigurieren und die Effizienz Ihrer Tests verbessern","pt":"Aprenda a configurar o agente WPF-UI para automação de testes de interface com Claude Code e melhore a eficiência do seu desenvolvimento","ru":"Узнайте, как настроить ИИ Агент WPF-UI для автоматизации тестирования интерфейса с Claude Code и повысьте эффективность разработки","ar":"تعرف على كيفية إعداد وحدة تحكم واجهة المستخدم WPF-UI للتحقق التلقائي مع Claude Code وتحسين كفاءة التطوير"},"definition":{"en":"wpf-ui is an AI agent skill that automates testing for Windows Presentation Foundation (WPF) applications. It uses Claude to read screenshots, understand UI state via the `list_controls` command, and autonomously perform actions like clicking elements or typing text based on mode detection.","zh":"WPF UI自动化测试是指使用AI驱动的UI测试工具自动化WPF应用程序的UI测试","ja":"WPF UI自動化エージェントとは、AI駆動のUIテストツールを使ってWPFアプリケーションのUIテストを自動化すること","ko":"WPF UI 자동화 테스트란 AI 기반의 UI 테스트 도구를 사용하여 WPF 애플리케이션의 UI 테스트를 자동화하는 것","es":"Un agente de inteligencia artificial para pruebas automatizadas de interfaz de usuario de WPF","fr":"Un agent d''intelligence artificielle pour les tests automatisés d''interface utilisateur WPF","de":"Ein KI-Agent für automatisierte Tests von WPF-Benutzeroberflächen","pt":"O que é um agente WPF-UI? É uma ferramenta de teste de interface que usa IA para automatizar testes em aplicações WPF","ru":"Что такое ИИ Агент WPF-UI? Это инструмент для тестирования интерфейса, который использует ИИ для автоматизации тестирования приложений WPF","ar":"ما هي وحدة تحكم واجهة المستخدم WPF-UI? هي أداة اختبار واجهة تستخدم الذكاء الاصطناعي للتحقق التلقائي من برامج WPF"},"features":{"en":["Automated mode detection for ''inspect'', ''click'', or ''type'' operations based on $ARGUMENTS","Retrieves window list and control tree hierarchy using `list_windows` and `list_controls` commands","Captures application state through integrated `screenshot` functionality for AI analysis","Resolves target UI elements for interaction via the `resolve_target` tool","Brings target windows to the foreground using the `focus_window` command"],"zh":["支持inspect、click和type模式","自动获取当前窗口列表","自动获取目标窗口的target_id","自动获取控件树","自动截取屏幕截图"],"ja":["inspect、click、typeモードをサポート","現在のウィンドウ一覧を自動で取得","対象ウィンドウのtarget_idを自動で取得","コントロールツリーを自動で取得","スクリーンショットを自動で撮影"],"ko":["inspect, click, type 모드를 지원","현재 창 목록을 자동으로 가져옴","대상 창의 target_id를 자동으로 가져옴","컨트롤 트리를 자동으로 가져옴","스크린샷을 자동으로 촬영"],"es":["Exploración automática de la interfaz de usuario","Pruebas de clic y entrada de texto","Captura de pantalla y análisis de la interfaz de usuario","Corrección automática de errores encontrados","Integración con Claude Code para análisis de código","Soporte para varios modos de prueba, incluyendo inspect, click y type"],"fr":["Exploration automatique de l''interface utilisateur","Tests de clic et de saisie de texte","Capture d''écran et analyse de l''interface utilisateur","Correction automatique des erreurs trouvées","Intégration avec Claude Code pour l''analyse de code","Prise en charge de plusieurs modes de test, notamment inspect, click et type"],"de":["Automatisierte Erkundung der Benutzeroberfläche","Klick- und Texteingabetests","Bildschirmaufnahme und Analyse der Benutzeroberfläche","Automatische Korrektur von Fehlern","Integration mit Claude Code für Code-Analyse","Unterstützung für verschiedene Testmodi, einschließlich inspect, click und type"],"pt":["Automação de testes de interface com Claude Code","Suporte a vários modos de teste, incluindo inspecção, clique e digitação","Uso de ferramentas como list_windows, resolve_target e focus_window","Captura de tela e análise de estado de UI","Integração com tecnologias de desenvolvimento de software"],"ru":["Автоматизация тестирования интерфейса с помощью Claude Code","Поддержка нескольких режимов тестирования, включая инспекцию, клик и ввод текста","Использование инструментов, таких как list_windows, resolve_target и focus_window","Сделать скриншот и анализ состояния интерфейса","Интеграция с технологиями разработки программного обеспечения"],"ar":["التحقق التلقائي لواجهة المستخدم مع Claude Code","دعم أوضاع اختبار متعددة، بما في ذلك الفحص والضغط والكتابة","استخدام أدوات مثل list_windows و resolve_target و focus_window","التقاط الشاشة وتحليل حالة واجهة المستخدم","التكامل مع تقنيات تطوير البرمجيات"]},"keywords":{"en":["wpf-ui AI agent setup","how to use wpf-ui with Claude","wpf-ui vs traditional UI testing","automate WPF application testing","wpf-ui install guide","Claude Code WPF integration","wpf-ui inspect mode tutorial","list_controls command wpf"],"zh":["WPF UI自动化测试","AI驱动的UI测试","自动化测试工具","WPF应用程序测试","UI测试框架","AI测试工具","自动化测试解决方案"],"ja":["WPF UI自動化エージェント","AI駆動のUIテスト","自動テストツール","WPFアプリケーションテスト","UIテストフレームワーク","AIテストツール","自動テストソリューション"],"ko":["WPF UI 자동화 테스트","AI 기반의 UI 테스트","자동화 테스트 도구","WPF 애플리케이션 테스트","UI 테스트 프레임워크","AI 테스트 도구","자동화 테스트 솔루션"],"es":["pruebas automatizadas WPF","agentes de inteligencia artificial","tests de interfaz de usuario","automatización de pruebas","Claude Code","WPF UI testing","pruebas de clic y entrada de texto","análisis de código"],"fr":["tests automatisés WPF","agents d''intelligence artificielle","tests d''interface utilisateur","automatisation des tests","Claude Code","WPF UI testing","tests de clic et de saisie de texte","analyse de code"],"de":["automatisierte Tests WPF","KI-Agents","Benutzeroberflächentests","Automatisierung von Tests","Claude Code","WPF UI-Testing","Klick- und Texteingabetests","Code-Analyse"],"pt":["agente WPF-UI","teste de interface","automação de testes","Claude Code","desenvolvimento de software","ferramentas de teste","tecnologias de desenvolvimento","IA para testes","WPF"],"ru":["ИИ Агент WPF-UI","тестирование интерфейса","автоматизация тестирования","Claude Code","разработка программного обеспечения","инструменты для тестирования","технологии разработки","ИИ для тестирования","WPF"],"ar":["وحدة تحكم واجهة المستخدم WPF-UI","اختبار واجهة المستخدم","التحقق التلقائي","Claude Code","تطوير البرمجيات","أدوات الاختبار","تقنيات التطوير","الذكاء الاصطناعي للتحقق","WPF"]}},"owner":"shiromac","repo":"wpfAutoTester","repoPath":"shiromac/wpfAutoTester","stars":1,"forks":0,"updatedAt":"2026-03-06T07:48:00Z","topics":[],"category":"community","skillMd":{"name":"wpf-ui","description":"WPF UI操作（調査・クリック・入力・スクリーンショット）","bodyPreview":"WPF UI自動化エージェントを使ってUI操作を行ってください。\n\n指示: $ARGUMENTS\n\n## モード判定\n\n引数からモードを自動判定する:\n- **inspect モード**: 引数なし / \"inspect\" / \"調査\" / \"確認\" / \"スクショ\"\n- **click モード**: \"click\" / \"クリック\" / `--aid` 指定あり（`--text` なし）\n- **type モード**: \"type\" / \"入力\" / `--text` 指定あり\n\n---\n\n## inspect モード（UI調査）\n\n対象アプリのUI状態を調査する。\n\n手順:\n1. `list_windows` ツールで現在のウィンドウ一覧を取得\n2. ユーザーが指定したウィンドウ（またはマッチするもの）に対して `resolve_target` で target_id を取得\n3. `focus_window` でウィンドウを前面に\n4. `list_controls` でコントロールツリーを取得（depth=4）\n5. `screenshot` でスクリーンショットを撮影\n6.","body":"WPF UI自動化エージェントを使ってUI操作を行ってください。\n\n指示: $ARGUMENTS\n\n## モード判定\n\n引数からモードを自動判定する:\n- **inspect モード**: 引数なし / \"inspect\" / \"調査\" / \"確認\" / \"スクショ\"\n- **click モード**: \"click\" / \"クリック\" / `--aid` 指定あり（`--text` なし）\n- **type モード**: \"type\" / \"入力\" / `--text` 指定あり\n\n---\n\n## inspect モード（UI調査）\n\n対象アプリのUI状態を調査する。\n\n手順:\n1. `list_windows` ツールで現在のウィンドウ一覧を取得\n2. ユーザーが指定したウィンドウ（またはマッチするもの）に対して `resolve_target` で target_id を取得\n3. `focus_window` でウィンドウを前面に\n4. `list_controls` でコントロールツリーを取得（depth=4）\n5. `screenshot` でスクリーンショットを撮影\n6. 取得したコントロール一覧を整理して表示（automation_id, name, control_type, enabled/visible）\n\n結果はテーブル形式で見やすく整理する。automation_id が空でないコントロールを優先的に表示する。\n\n---\n\n## click モード（要素クリック）\n\nUI要素をクリックしてスクリーンショットで結果を検証する。\n\n手順:\n1. 対象ウィンドウが未解決の場合、`list_windows` → `resolve_target` で解決\n2. `focus_window` でウィンドウを前面に\n3. 指定されたセレクタで `click` を実行\n4. クリック後に `screenshot` で結果を確認\n5. 必要に応じて `list_controls` で変化を確認\n\nセレクタの指定方法:\n- automation_id: 例 \"SaveButton\"\n- name + control_type: 例 \"OK\" Button\n- 曖昧な場合は先に list_controls で候補を確認してからクリック\n\n---\n\n## type モード（テキスト入力）\n\nUI要素にテキストを入力して値を検証する。\n\n手順:\n1. 対象ウィンドウが未解決の場合、`list_windows` → `resolve_target` で解決\n2. `focus_window` でウィンドウを前面に\n3. 指定されたセレクタで `type_text` を実行\n4. 入力後に `read_text` で値を検証\n5. `screenshot` で結果を確認\n\nセレクタとテキストの指定方法:\n- 例: \"ServerUrlTextBox に http://localhost:8080 を入力\"\n- 例: \"ユーザー名フィールド(automation_id=UsernameBox)に admin を入力\"\n\n---\n\n## セレクタの優先順位\n1. `automation_id` (最も安定)\n2. `name` + `control_type`\n3. `bounding_rect` の中心クリック (最後の手段)\n"},"lastSynced":"2026-03-06T13:11:33.674Z","agentAnalysis":{"suitability":{"en":"Perfect for Desktop Automation Agents needing advanced WPF UI testing capabilities.","zh":"非常适合需要高级WPF UI测试功能的桌面自动化代理。","ja":"デスクトップ自動化エージェントが高度なWPF UIテスト機能を必要とする場合に最適です。","ko":"고급 WPF UI 테스트 기능이 필요한 데스크톱 자동화 에이전트에 적합합니다.","es":"Perfecto para Agentes de Automatización de Escritorio que necesitan capacidades de prueba de interfaz de usuario de WPF avanzadas.","fr":"Parfait pour les agents d''automatisation de bureau nécessitant des capacités de test d''interface utilisateur WPF avancées.","de":"Perfekt für Desktop-Automatisierungsagenten, die erweiterte WPF-Benutzeroberflächentestfunktionen benötigen.","pt":"Perfeito para Agentes de Automação de Desktop que precisam de capacidades avançadas de teste de UI WPF.","ru":"Идеально для агентов автоматизации рабочего стола, которым необходимы расширенные возможности тестирования UI WPF.","ar":"مثالي للوكلاء الآليين لتحسين سطح المكتب الذين يحتاجون إلى قدرات متقدمة لاختبار واجهة المستخدم WPF."},"recommendation":{"en":"Empowers agents to automate UI testing of WPF applications using screenshot analysis and control tree inspection with tools like `list_controls` and `list_windows`, streamlining the development process for .NET desktop applications.","zh":"赋予代理使用截图分析和控件树检查等工具（如`list_controls`和`list_windows`）来自动化WPF应用程序的UI测试，从而简化.NET桌面应用程序的开发过程。","ja":"エージェントがスクリーンショット分析とコントロールツリーの検査などのツール（例： `list_controls`と`list_windows`）を使用してWPFアプリケーションのUIテストを自動化できるようにし、.NETデスクトップアプリケーションの開発プロセスを合理化します。","ko":"에이전트가 스크린샷 분석 및 컨트롤 트리 검사와 같은 도구(`list_controls` 및 `list_windows` 등)를 사용하여 WPF 애플리케이션의 UI 테스트를 자동화할 수 있도록 하여 .NET 데스크톱 애플리케이션 개발 프로세스를 최적화합니다.","es":"Habilita a los agentes a automatizar las pruebas de interfaz de usuario de aplicaciones WPF mediante el análisis de capturas de pantalla y la inspección del árbol de controles con herramientas como `list_controls` y `list_windows`, simplificando el proceso de desarrollo para aplicaciones de escritorio .NET.","fr":"Permet aux agents d''automatiser les tests d''interface utilisateur des applications WPF à l''aide de l''analyse d''captures d''écran et de l''inspection de l''arbre de contrôle avec des outils tels que `list_controls` et `list_windows`, rationalisant le processus de développement pour les applications de bureau .NET.","de":"Ermächtigt Agenten, die Benutzeroberflächentests von WPF-Anwendungen mithilfe von Screenshot-Analyse und Kontrollbaum-Inspektion mit Tools wie `list_controls` und `list_windows` zu automatisieren, wodurch der Entwicklungsprozess für .NET-Desktopanwendungen rationalisiert wird.","pt":"Habilita os agentes a automatizar o teste de UI de aplicações WPF usando análise de captura de tela e inspeção da árvore de controle com ferramentas como `list_controls` e `list_windows`, simplificando o processo de desenvolvimento para aplicações de desktop .NET.","ru":"Позволяет агентам автоматизировать тестирование UI приложений WPF с помощью анализа скриншотов и инспекции дерева управления инструментами как `list_controls` и `list_windows`, оптимизируя процесс разработки для приложений .NET рабочего стола.","ar":"يمكن الوكلاء من توفير تلقيني لاختبار واجهة المستخدم لتطبيقات WPF باستخدام تحليل لقطة الشاشة وتحقيق شجرة التحكم بأدوات مثل `list_controls` و `list_windows`، وبذلك يُبسط عملية تطوير تطبيقات سطح المكتب .NET."},"useCases":{"en":["Automating UI issue detection in WPF applications","Generating test scripts for complex UI interactions","Debugging UI-related bugs in .NET desktop applications"],"zh":["自动化WPF应用程序的UI问题检测","为复杂的UI交互生成测试脚本","调试.NET桌面应用程序中的UI相关错误"],"ja":["WPFアプリケーションのUI問題の検出を自動化する","複雑なUI操作のテストスクリプトを生成する",".NETデスクトップアプリケーションのUI関連のバグをデバッグする"],"ko":["WPF 애플리케이션의 UI 문제 감지를 자동화하는 것","복잡한 UI 상호작용에 대한 테스트 스크립트 생성",".NET 데스크톱 애플리케이션의 UI 관련 오류 디버깅"],"es":["Automatizar la detección de problemas de interfaz de usuario en aplicaciones WPF","Generar scripts de prueba para interacciones de interfaz de usuario complejas","Depurar errores relacionados con la interfaz de usuario en aplicaciones de escritorio .NET"],"fr":["Automatiser la détection de problèmes d''interface utilisateur dans les applications WPF","Générer des scripts de test pour des interactions d''interface utilisateur complexes","Déboguer les bogues liés à l''interface utilisateur dans les applications de bureau .NET"],"de":["Automatisierung der Erkennung von Benutzeroberflächenproblemen in WPF-Anwendungen","Generierung von Testskripten für komplexe Benutzeroberflächeninteraktionen","Fehlerbehebung von Benutzeroberflächenfehlern in .NET-Desktopanwendungen"],"pt":["Automatizar detecção de problemas de UI em aplicações WPF","Gerar scripts de teste para interações de UI complexas","Depurar bugs relacionados à UI em aplicações de desktop .NET"],"ru":["Автоматизировать обнаружение проблем UI в приложениях WPF","Генерировать тестовые сценарии для сложных взаимодействий UI","Отлаживать ошибки, связанные с UI, в приложениях .NET рабочего стола"],"ar":["توفير كشف آلي عن مشاكل واجهة المستخدم في تطبيقات WPF","توليد سيناريوهات اختبار لتفاعلات واجهة المستخدم المعقدة","تصحيح أخطاء متعلقة بواجهة المستخدم في تطبيقات سطح المكتب .NET"]},"limitations":{"en":["Requires WPF application access","Limited to .NET desktop applications","Dependent on Claude Code integration"],"zh":["需要WPF应用程序的访问权限","仅限于.NET桌面应用程序","依赖于Claude Code集成"],"ja":["WPFアプリケーションへのアクセスが必要",".NETデスクトップアプリケーションに限定される","Claude Codeの統合に依存する"],"ko":["WPF 애플리케이션에 대한 액세스 권한이 필요합니다",".NET 데스크톱 애플리케이션으로 제한됩니다","Claude Code 통합에 종속됨"],"es":["Requiere acceso a la aplicación WPF","Limitado a aplicaciones de escritorio .NET","Dependiente de la integración de Claude Code"],"fr":["Nécessite un accès à l''application WPF","Limité aux applications de bureau .NET","Dépendant de l''intégration de Claude Code"],"de":["Benötigt Zugriff auf die WPF-Anwendung","Begrenzt auf .NET-Desktopanwendungen","Abhängig von der Integration von Claude Code"],"pt":["Requer acesso à aplicação WPF","Limitado a aplicações de desktop .NET","Dependente da integração do Claude Code"],"ru":["Требует доступа к приложению WPF","Ограничен для приложений .NET рабочего стола","Зависит от интеграции с Claude Code"],"ar":["يتطلب الوصول إلى تطبيق WPF","محدود لتطبيقات سطح المكتب .NET","يعتمد على تكامل Claude Code"]},"version":4},"contentHash":"ec2b74f6999c9154ad47d98579fb9dde7a5775890a4d618e7e39d174bfccf8e4","qualityScore":20}');
