INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shiromac/wpfAutoTester/wpf-ui', 'wpf-ui', 'shiromac', 'wpfAutoTester', 'community', 'wpf-ui shiromac wpfAutoTester community The wpf-ui skill integrates Claude Code with WPF applications for automated UI testing. It uses screenshot analysis and control tree inspection (`list_controls`, `list_windows`) to autonomously test and fix UI issues, benefiting developers building .NET desktop applications. WPF UI自动化测试AI驱动的UI测试，支持inspect、click和type模式 WPF UI自動化エージェントは、inspect、click、typeモードをサポートするAI駆動のUIテスト WPF UI 자동화 테스트 에이전트는 inspect, click, type 모드를 지원하는 AI 기반의 UI 테스트 WPF UI es un agente de pruebas automatizadas que utiliza la inteligencia artificial para explorar y probar aplicaciones, y corregir errores encontrados WPF UI est un agent de tests automatisés qui utilise l''intelligence artificielle pour explorer et tester des applications, et corriger les erreurs trouvées WPF UI ist ein Agent für automatisierte Tests, der künstliche Intelligenz nutzt, um Anwendungen zu erkunden und zu testen, und Fehler zu beheben O agente WPF-UI é uma ferramenta de teste de interface impulsionada por IA que automatiza a exploração e teste de aplicações WPF ИИ Агент WPF-UI - это инструмент для тестирования интерфейса, работающий на основе ИИ, который автоматизирует исследование и тестирование приложений WPF وحدة تحكم واجهة المستخدم WPF-UI هي أداة اختبار واجهة مدعومة بالذكاء الاصطناعي التي تلقم التحقق التلقائي والتجريب لبرامج WPF wpf-ui AI agent setup how to use wpf-ui with Claude wpf-ui vs traditional UI testing automate WPF application testing wpf-ui install guide Claude Code WPF integration wpf-ui inspect mode tutorial list_controls command wpf WPF UI自动化测试 AI驱动的UI测试 自动化测试工具 WPF应用程序测试 UI测试框架 AI测试工具 自动化测试解决方案 Automated mode detection for ''inspect'', ''click'', or ''type'' operations based on $ARGUMENTS Retrieves window list and control tree hierarchy using `list_windows` and `list_controls` commands Captures application state through integrated `screenshot` functionality for AI analysis Resolves target UI elements for interaction via the `resolve_target` tool Brings target windows to the foreground using the `focus_window` command wpf-ui is an AI agent skill that automates testing for Windows Presentation Foundation (WPF) applications. It uses Claude to read screenshots, understand UI state via the `list_controls` command, and autonomously perform actions like clicking elements or typing text based on mode detection.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('levkiss/lev-cv-website/new-blog-post', 'community', 'levkiss', 'lev-cv-website', 'levkiss/lev-cv-website', 'new-blog-post', 0, 0, 20, '2026-02-20T15:48:03Z', '2026-03-07T03:46:43.958Z', '31b06e8f6972494cd8d4fbad63009f5a56a1e85f585e0612246aa351bcc1bd10', '{"id":"levkiss/lev-cv-website/new-blog-post","name":"new-blog-post","description":{"en":"The new-blog-post skill allows developers to add new article cards to blog.html, maintaining a consistent layout and design. It benefits developers who need to update their blog frequently.","zh":"使用AIエージェント添加新博客文章，创建新文章卡，匹配现有的模式和grid布局","ja":"AIエージェントを使用して新しいブログ投稿を追加し、新しい記事カードを作成します","ko":"AI 도구를 사용하여 새로운 블로그 게시물 추가 및 새로운 게시물 카드 생성","es":"El skill ''new-blog-post'' permite agregar un nuevo artículo a tu blog, manteniendo la estructura y el diseño responsivo","fr":"Le skill ''new-blog-post'' permet d''ajouter un nouvel article à votre blog, en conservant la structure et la conception réactive","de":"Das Skill ''new-blog-post'' ermöglicht es, einen neuen Artikel zu Ihrem Blog hinzuzufügen, wobei die Struktur und das responsive Design beibehalten werden","pt":"O skill new-blog-post permite adicionar novos artigos à página de blog com estrutura de cartão e layout de grade responsivo","ru":"Навык new-blog-post позволяет добавлять новые статьи на страницу блога со структурой карточки и адаптивной сеточной компоновкой","ar":"تمكنك مهارة new-blog-post من إضافة مقالات جديدة إلى صفحة المدونة بهيكل البطاقة وتنسيق الشبكة المستجيب"},"seo":{"title":{"en":"new-blog-post: Automated Blog Post Creation Guide | AI Ag...","zh":"新博客文章设置指南 - AIエージェント","ja":"新しいブログ投稿のベストプラクティス - AIエージェント","ko":"새로운 블로그 게시물 설정 가이드 - AI 도구","es":"Guía de configuración para nuevo post de blog con Agentes...","fr":"Guide d''installation pour nouveau post de blog avec Outil...","de":"Einrichtungsanleitung für neuen Blog-Beitrag mit KI-Tools","pt":"Guia de Configuração do Novo Post de Blog com Ferramentas...","ru":"Настройка нового блог-поста с помощью ИИ Агентов","ar":"دليل إعداد منشور مدونة جديد باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create new blog posts with ease using the new-blog-post skill. Learn how to add new article cards to blog.html and maintain a responsive grid...","zh":"了解如何使用AIエージェント添加新博客文章，包括创建新文章卡和grid布局","ja":"AIエージェントを使用して新しいブログ投稿を追加する方法を学びます。新しい記事カードを作成し、グリッドレイアウトを理解します","ko":"AI 도구를 사용하여 새로운 블로그 게시물 추가 방법을 배우세요. 새로운 게시물 카드를 생성하고 그리드 레이아웃을 이해합니다","es":"Aprende a agregar un nuevo artículo a tu blog con nuestra guía de Agentes de IA, incluyendo estructura de tarjeta y diseño responsivo","fr":"Découvrez comment ajouter un nouvel article à votre blog avec notre guide d''Outils d''IA, y compris la structure de carte et la conception réactive","de":"Erfahren Sie, wie Sie einen neuen Artikel zu Ihrem Blog hinzufügen, mit unserer Anleitung zu KI-Tools, einschließlich Kartenstruktur und responsivem Design","pt":"Aprenda a adicionar um novo artigo à sua página de blog com o skill new-blog-post, incluindo estrutura de cartão e layout de grade responsivo","ru":"Узнайте, как добавить новую статью на страницу блога с помощью навыка new-blog-post, включая структуру карточки и адаптивную сеточную компоновку","ar":"تعلم كيفية إضافة مقال جديد إلى صفحة مدونتك باستخدام مهارة new-blog-post، بما في ذلك هيكل البطاقة وتنسيق الشبكة المستجيب"},"definition":{"en":"new-blog-post is a skill that automates the creation of new blog posts by adding article cards to blog.html, following a predefined pattern and layout.","zh":"新博客文章添加是AIエージェント的一项功能，允许开发者创建新文章卡并将其添加到grid布局中","ja":"新しいブログ投稿の追加は、AIエージェントの機能の1つで、開発者が新しい記事カードを作成し、グリッドレイアウトに追加できるようにします","ko":"새로운 블로그 게시물 추가는 AI 도구의 기능 중 하나로 개발자가 새로운 게시물 카드를 생성하여 그리드 레이아웃에 추가할 수 있습니다","es":"El skill ''new-blog-post'' es una función que permite agregar nuevos artículos a un blog, utilizando Agentes de IA","fr":"Le skill ''new-blog-post'' est une fonction qui permet d''ajouter de nouveaux articles à un blog, en utilisant des Outils d''IA","de":"Das Skill ''new-blog-post'' ist eine Funktion, die es ermöglicht, neue Artikel zu einem Blog hinzuzufügen, mit Hilfe von KI-Tools","pt":"O new-blog-post é um skill que adiciona um novo artigo à página de blog com estrutura de cartão e layout de grade responsivo","ru":"Навык new-blog-post - это способность, которая добавляет новую статью на страницу блога со структурой карточки и адаптивной сеточной компоновкой","ar":"مهارة new-blog-post هي قدرة تضيف مقالًا جديدًا إلى صفحة المدونة بهيكل البطاقة وتنسيق الشبكة المستجيب"},"features":{"en":["Reads blog.html to understand the current card structure and grid layout","Creates new article cards with title, description, tags, estimated read time, and date","Applies proper dark mode classes and hover effects consistent with other cards","Inserts new cards in the appropriate position, maintaining a responsive grid placement","Verifies the grid layout still works after adding new cards"],"zh":["创建新文章卡，匹配现有的模式","支持dark mode类","实现hover效果，保持一致性","响应式grid布局","自动将新卡片添加到grid布局中"],"ja":["新しい記事カードを作成し、既存のパターンに一致させる","ダークモードクラスをサポート","ホバーエフェクトを実装して一貫性を保つ","レスポンシブグリッドレイアウト","新しいカードを自動的にグリッドレイアウトに追加"],"ko":["새로운 게시물 카드를 생성하여 기존의 패턴과 일치","다크 모드 클래스 지원","호버 효과를 구현하여 일관성을 유지","반응형 그리드 레이아웃","새로운 카드를 자동으로 그리드 레이아웃에 추가"],"es":["Estructura de tarjeta de artículo consistente","Diseño responsivo para diferentes dispositivos","Compatibilidad con el modo oscuro","Efectos de hover coherentes con otras tarjetas","Inserción de la nueva tarjeta en la posición adecuada"],"fr":["Structure de carte d''article cohérente","Conception réactive pour différents appareils","Compatibilité avec le mode sombre","Effets de survol cohérents avec d''autres cartes","Insertion de la nouvelle carte à la position appropriée"],"de":["Konsistente Kartenstruktur für Artikel","Responsives Design für verschiedene Geräte","Kompatibilität mit dem dunklen Modus","Kohärente Hover-Effekte mit anderen Karten","Einfügung der neuen Karte an der richtigen Position"],"pt":["Estrutura de cartão personalizada","Layout de grade responsivo","Efeitos de hover consistentes","Classe de modo escuro para cartões","Inserção de cartões em ordem cronológica"],"ru":["Пользовательская структура карточки","Адаптивная сеточная компоновка","Эффекты наведения, согласованные с другими карточками","Класс темного режима для карточек","Вставка карточек в хронологическом порядке"],"ar":["هيكل البطاقة المخصص","تنسيق الشبكة المستجيب","أffects التأثيرات عند التنقل المتوافق مع البطاقات الأخرى","فئة وضع المظلمة للبطاقات","إدراج البطاقات بالترتيب الزمني"]},"keywords":{"en":["how to use new-blog-post","new-blog-post setup guide","automated blog post creation","new-blog-post vs manual blogging","new-blog-post install","responsive grid layout tutorial","blog.html modification guide","new-blog-post alternative","what is new-blog-post"],"zh":["AIエージェント","新博客文章添加","grid布局","dark mode","响应式设计","开发者工具","AI工具"],"ja":["AIエージェント","新しいブログ投稿の追加","グリッドレイアウト","ダークモード","レスポンシブデザイン","開発者ツール","AIツール"],"ko":["AI 도구","새로운 블로그 게시물 추가","그리드 레이아웃","다크 모드","반응형 디자인","개발자 도구","AI 에이전트"],"es":["Agentes de IA para blogs","nuevo post de blog","estructura de tarjeta de artículo","diseño responsivo","modo oscuro","efectos de hover","inserción de tarjeta","desarrollo web con IA"],"fr":["Outils d''IA pour blogs","nouveau post de blog","structure de carte d''article","conception réactive","mode sombre","effets de survol","insertion de carte","développement web avec IA"],"de":["KI-Tools für Blogs","neuer Blog-Beitrag","Kartenstruktur für Artikel","responsives Design","dunkler Modus","Hover-Effekte","Einfügung von Karten","Webentwicklung mit KI"],"pt":["new-blog-post","ferramentas de ia","desenvolvimento web","blog","artigos","estrutura de cartão","layout de grade responsivo","modo escuro","efeitos de hover"],"ru":["new-blog-post","ИИ Агенты","веб-разработка","блог","статьи","структура карточки","адаптивная сеточная компоновка","темный режим","эффекты наведения"],"ar":["new-blog-post","أدوات الذكاء الاصطناعي","تطوير الويب","مدونة","مقالات","هيكل البطاقة","تنسيق الشبكة المستجيب","وضع المظلمة","تأثيرات التنقل"]}},"owner":"levkiss","repo":"lev-cv-website","repoPath":"levkiss/lev-cv-website","stars":0,"forks":0,"updatedAt":"2026-02-20T15:48:03Z","topics":[],"category":"community","skillMd":{"name":"new-blog-post","description":"Add a new blog article card to blog.html","bodyPreview":"# Add New Blog Post\n\nAdd a new article card to `blog.html` for: **$ARGUMENTS**\n\n## Steps\n\n1. Read `blog.html` to understand the current card structure and grid layout\n2. Create a new article card matching the existing pattern:\n   - Title, description, tags, estimated read time, date\n   - Proper dark mode classes\n   - Hover effects consistent with other cards\n   - Responsive grid placement\n3. Insert the new card in the appropriate position (newest first)\n4. Verify the grid layout still works with","body":"# Add New Blog Post\n\nAdd a new article card to `blog.html` for: **$ARGUMENTS**\n\n## Steps\n\n1. Read `blog.html` to understand the current card structure and grid layout\n2. Create a new article card matching the existing pattern:\n   - Title, description, tags, estimated read time, date\n   - Proper dark mode classes\n   - Hover effects consistent with other cards\n   - Responsive grid placement\n3. Insert the new card in the appropriate position (newest first)\n4. Verify the grid layout still works with the new card count\n"},"lastSynced":"2026-03-07T03:46:43.958Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Development Agents needing automated blog post updates with consistent HTML and CSS styling.","zh":"非常适合需要自动化博客文章更新并保持一致的 HTML 和 CSS 样式的 Web Development Agents。","ja":"一貫した HTML と CSS スタイリングを備えた自動化されたブログ投稿更新を必要とする Web Development Agents に最適です。","ko":"일관된 HTML 및 CSS 스타일링을 갖춘 자동화된 블로그 포스트 업데이트가 필요한 Web Development Agents에 완벽합니다.","es":"Perfecto para agentes de desarrollo web que necesitan actualizaciones automatizadas de publicaciones de blog con estilo HTML y CSS coherente.","fr":"Parfait pour les agents de développement Web ayant besoin de mises à jour automatiques de billets de blog avec un style HTML et CSS cohérent.","de":"Perfekt für Webentwicklungsagenten, die automatisierte Blog-Beitrag-Aktualisierungen mit konsistentem HTML- und CSS-Styling benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Web que precisam de atualizações de postagens de blog automatizadas com estilização HTML e CSS consistente.","ru":"Идеально для Веб-разработчиков, агентов, которым нужны автоматические обновления блог-постов с последовательным стилем HTML и CSS.","ar":"مثالي للوكلاء التطوير الويب الذين يحتاجون إلى تحديثات منشورات المدونة الآلية مع أسلوب HTML و CSS متسق."},"recommendation":{"en":"Empowers agents to dynamically generate new article cards in blog.html, utilizing dark mode classes, hover effects, and responsive grid placement, all while maintaining a consistent layout and design.","zh":"赋能代理动态地在 blog.html 中生成新的文章卡片，利用 dark mode classes、hover effects 和 responsive grid placement，同时保持一致的布局和设计。","ja":"ダークモードクラス、ホバー効果、レスポンシブグリッド配置を利用し、一貫したレイアウトとデザインを維持しながら、blog.html 内で新しい記事カードを動的に生成することをエージェントに可能にします。","ko":"다크 모드 클래스, 호버 효과 및 반응형 그리드 배치를 활용하여 일관된 레이아웃과 디자인을 유지하면서 blog.html에서 새로운 아티클 카드를 동적으로 생성하도록 에이전트를 지원합니다.","es":"Habilita a los agentes a generar dinámicamente nuevas tarjetas de artículos en blog.html, utilizando clases de modo oscuro, efectos de desplazamiento y colocación de cuadrícula receptiva, todo mientras mantiene un diseño y disposición coherentes.","fr":"Permet aux agents de générer dynamiquement de nouvelles cartes d''articles dans blog.html, en utilisant des classes de mode sombre, des effets de survol et un placement de grille réactif, le tout en maintenant une disposition et une conception cohérentes.","de":"Ermächtigt die Agenten, neue Artikelkarten in blog.html dynamisch zu generieren, wobei Klassen für den Dunkelmodus, Hover-Effekte und responsives Rasterplatzierung verwendet werden, während die Agenten eine konsistente Layout- und Designausrichtung beibehalten.","pt":"Habilita os agentes a gerar dinamicamente novos cartões de artigo em blog.html, utilizando classes de modo escuro, efeitos de hover e posicionamento de grade responsivo, mantendo ao mesmo tempo um layout e design consistentes.","ru":"Наделяет агентов возможностью динамически генерировать новые карточки статей в blog.html, используя классы темного режима, эффекты наведения и адаптивное размещение сетки, сохраняя при этом последовательный макет и дизайн.","ar":"يمنح الوكلاء القدرة على توليد بطاقات مقال جديدة بشكل ديناميكي في blog.html، باستخدام فئات الوضع الداكن وأFFECTS.hover ووضع شبكة مستجيب، مع الحفاظ في الوقت نفسه على تخطيط وتصميم متسقين."},"useCases":{"en":["Automating blog post updates with newest articles first","Generating responsive article cards with proper CSS styling","Maintaining consistent grid layouts across different blog posts"],"zh":["以最新文章优先的方式自动化博客文章更新","生成具有适当 CSS 样式的响应式文章卡片","在不同的博客文章中保持一致的网格布局"],"ja":["最新の記事を先頭にしてブログ投稿の更新を自動化する","適切な CSS スタイリングを備えたレスポンシブな記事カードを生成する","異なるブログ投稿間で一貫したグリッドレイアウトを維持する"],"ko":["최신 아티클을 우선으로 블로그 포스트 업데이트 자동화","적절한 CSS 스타일링을 갖춘 반응형 아티클 카드 생성","다른 블로그 포스트에 걸쳐 일관된 그리드 레이아웃 유지"],"es":["Automatizar actualizaciones de publicaciones de blog con los artículos más nuevos primero","Generar tarjetas de artículos receptivas con estilo CSS adecuado","Mantener diseños de cuadrícula coherentes en diferentes publicaciones de blog"],"fr":["Automatiser les mises à jour de billets de blog avec les articles les plus récents en premier","Générer des cartes d''articles réactives avec un style CSS approprié","Maintenir des dispositions de grille cohérentes dans différents billets de blog"],"de":["Automatisieren von Blog-Beitrag-Aktualisierungen mit den neuesten Artikeln zuerst","Generieren responsiver Artikelkarten mit ordnungsgemäßen CSS-Styling","Beibehalten konsistenter Rasterlayouts über verschiedene Blog-Beiträge hinweg"],"pt":["Automatizar atualizações de postagens de blog com os artigos mais recentes primeiro","Gerar cartões de artigo responsivos com estilização CSS apropriada","Manter layouts de grade consistentes em diferentes postagens de blog"],"ru":["Автоматизировать обновления блог-постов с последними статьями первыми","Генерировать адаптивные карточки статей с правильным стилем CSS","Сохранять последовательные сеточные макеты на разных блог-постах"],"ar":["تحديث منشورات المدونة آلياً مع المقالات الأحدث أولاً","توليد بطاقات مقال مستجيب مع أسلوب CSS مناسب","الحفاظ على تخطيطات الشبكة المترابطة عبر منشورات المدونة المختلفة"]},"limitations":{"en":["Requires access to blog.html file","Limited to adding new article cards, not editing existing ones","Dependent on consistent existing card structure and grid layout"],"zh":["需要访问 blog.html 文件","仅限于添加新的文章卡片，无法编辑现有的卡片","依赖于现有卡片结构和网格布局的一致性"],"ja":["blog.html ファイルへのアクセスが必要","新しい記事カードの追加に限定され、既存のものの編集はできない","一貫した既存のカード構造とグリッドレイアウトに依存する"],"ko":["blog.html 파일에 대한 액세스 필요","새로운 아티클 카드 추가로 제한되며 기존 카드는 편집 불가","일관된 기존 카드 구조 및 그리드 레이아웃에 의존적"],"es":["Requiere acceso al archivo blog.html","Limitado a agregar nuevas tarjetas de artículos, no a editar las existentes","Dependiente de la estructura de tarjeta y el diseño de cuadrícula existentes coherentes"],"fr":["Nécessite un accès au fichier blog.html","Limité à l''ajout de nouvelles cartes d''articles, et non à la modification des cartes existantes","Dépendant de la structure de carte et de la disposition de grille existantes cohérentes"],"de":["Erfordert Zugriff auf die Datei blog.html","Begrenzt auf Hinzufügen neuer Artikelkarten, nicht auf Bearbeiten vorhandener","Abhängig von konsistenter vorhandener Kartenstruktur und Rasterlayout"],"pt":["Requer acesso ao arquivo blog.html","Limitado à adição de novos cartões de artigo, não edição de cartões existentes","Dependente da estrutura de cartão existente consistente e do layout da grade"],"ru":["Требует доступа к файлу blog.html","Ограничен добавлением новых карточек статей, не редактированием существующих","Зависит от последовательной существующей структуры карточки и макета сетки"],"ar":["يتطلب الوصول إلى ملف blog.html","محدود بإضافة بطاقات مقال جديدة، وليس تحرير البطاقات الحالية","يعتمد على هيكل بطاقة موجود متسق و تخطيط شبكي"]},"version":4},"contentHash":"31b06e8f6972494cd8d4fbad63009f5a56a1e85f585e0612246aa351bcc1bd10","qualityScore":20}');
