INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('steven715/steven_blog/architect', 'architect', 'steven715', 'steven_blog', 'community', 'architect steven715 steven_blog community The Architect skill enables developers to design comprehensive system architectures based on the Architecture Playbook. It benefits system architects and developers by providing a structured approach to business logic and data management. 架构师是一位資深系統架構師，負責根據業務場景推導出完整的系統架構設計 AIエージェントアーキテクトは、ビジネスシナリオに基づいて完全なシステムアーキテクチャ設計を推導する責任を負う 아키텍트는 비즈니스 시나리오에 따라 완전한 시스템 아키텍처 디자인을 유도하는 책임을 가집니다 El arquitecto es un experto en diseño de sistemas que utiliza principios de diseño y patrones de arquitectura para crear soluciones escalables y eficientes L''architecte est un expert en conception de systèmes qui utilise des principes de conception et des modèles d''architecture pour créer des solutions évolutives et efficaces Der Architekt ist ein Experte für Systemdesign, der Designprinzipien und Architekturmuster verwendet, um skalierbare und effiziente Lösungen zu erstellen O skill de arquiteto permite projetar sistemas escaláveis e flexíveis, utilizando conceitos como definição de sistemas e tipos de objetos ИИ Агенты Архитектор позволяет проектировать масштабируемые и гибкие системы, используя такие концепции, как определение систем и типы объектов يسمح مهارات مهندس معماري بتصميم أنظمة قابلة للتحديث ومرنة، باستخدام مفاهيم مثل تعريف النظام و أنواع الكائنات how to use architect skill what is architect ai agent architect alternative for system design architect vs enterprise architecture architect setup guide for developers architect install for ai agents system architecture design principles architecture playbook for business logic 架构师 系统架构设计 業務物件 資源物件 計算器 處理器 管理器 控制器 依賴注入 回調註冊 Applies Architecture Playbook design principles to system architecture Supports business object types, including Calculator, Handler, Manager, and Controller Enables resource object management with Updater for data writing and reading Facilitates communication between business objects using Manager for dependency injection and callback registration Integrates with Controller for external communication and MVC pattern implementation Architect is a system design skill that applies Architecture Playbook principles to create efficient business logic flows and data management systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nematatu/kotobad/write-docs', 'community', 'nematatu', 'kotobad', 'nematatu/kotobad', 'write-docs', 0, 0, 20, '2026-03-06T17:43:20Z', '2026-03-07T03:49:01.630Z', 'ef93e2596f326b80fc164690927f42119d49204c74ea3631b2edc4b63511dbe2', '{"id":"nematatu/kotobad/write-docs","name":"write-docs","description":{"en":"The write-docs skill enables AI agents to generate technical documentation, including handoff logs and spec sheets, using templates from the references/ directory. It benefits developers by streamlining documentation processes.","zh":"Write Docs是一个AI文档生成工具，帮助开发者快速创建高质量文档","ja":"Write DocsはAIエージェントのドキュメント作成を支援するツールで、テンプレートを使用して効率的なドキュメント作成を実現します","ko":"Write Docs는 개발자를 위한 AI 문서 작성 도구로 문서 생성을 최적화합니다","es":"El agente AI ''write-docs'' permite crear documentación técnica de manera eficiente con plantillas y reglas comunes","fr":"L''agent AI ''write-docs'' permet de rédiger une documentation technique de qualité avec des modèles et des règles standard","de":"Der AI-Tool ''write-docs'' ermöglicht die Erstellung technischer Dokumentationen mit Vorlagen und gemeinsamen Regeln","pt":"O Write-docs é uma ferramenta para criar documentação técnica, incluindo logs de entrega e especificações, com templates e regras claras","ru":"Write-docs - это инструмент для создания технической документации, включая журналы передачи и спецификации, с шаблонами и четкими правилами","ar":"Write-docs هو أداة لإنشاء الوثائق الفنية، بما في ذلك سجلات التسليم والمواصفات، مع قوالب وقواعد واضحة"},"seo":{"title":{"en":"write-docs: Technical Documentation Setup Guide | AI Agen...","zh":"AI文档生成工具：Write Docs Setup Guide","ja":"AIエージェントのドキュメント作成：Write Docs ベストプラクティス","ko":"AI 도구 문서 작성 가이드: Write Docs","es":"Guía de configuración para escribir documentación técnica...","fr":"Configurer l''agent AI pour rédiger la documentation techn...","de":"Einrichtungsanleitung für technische Dokumentation mit AI...","pt":"Guia de Configuração do Write-docs: Melhores Práticas par...","ru":"Настройка Write-docs: Руководство по Созданию Технической...","ar":"دليل إعداد Write-docs: أفضل الممارسات لكتابة الوثائق الفنية"},"description":{"en":"Discover how to efficiently create technical documents with write-docs. Learn to generate handoff logs, spec sheets, and work logs with ease. Get started now!","zh":"使用Write Docs AI工具生成高质量文档，了解如何快速开始和最佳实践","ja":"AIエージェントのドキュメント作成を効率化するWrite Docsの使い方とテンプレートの活用方法","ko":"Write Docs를 사용하여 문서를 생성하고 최적화하는 방법을 알아보세요","es":"Aprende a configurar el agente AI para escribir documentación técnica de manera eficiente con plantillas y reglas comunes","fr":"Découvrez comment configurer l''agent AI pour rédiger une documentation technique de qualité avec des modèles et des règles standard","de":"Erfahren Sie, wie Sie den AI-Tool für die Erstellung technischer Dokumentationen mit Vorlagen und gemeinsamen Regeln einrichten","pt":"Aprenda a configurar o Write-docs para criar documentação técnica de alta qualidade, incluindo logs de entrega e especificações","ru":"Узнайте, как настроить Write-docs для создания качественной технической документации, включая журналы передачи и спецификации","ar":"تعرف على كيفية إعداد Write-docs لإنشاء وثائق فنية عالية الجودة، بما في ذلك سجلات التسليم والمواصفات"},"definition":{"en":"write-docs is a technical documentation skill that utilizes templates and specific formatting rules to generate high-quality documents, including handoff logs and spec sheets.","zh":"Write Docs是一种AI驱动的文档生成工具","ja":"Write DocsはAIエージェントのドキュメント作成を支援するツールです","ko":"Write Docs는 문서 생성을 위한 AI 도구입니다","es":"El agente AI ''write-docs'' es una herramienta para crear documentación técnica con plantillas y reglas predefinidas","fr":"L''agent AI ''write-docs'' est un outil pour rédiger une documentation technique avec des modèles et des règles prédéfinies","de":"Der AI-Tool ''write-docs'' ist ein Instrument für die Erstellung technischer Dokumentationen mit Vorlagen und vorgegebenen Regeln","pt":"Write-docs é uma ferramenta de documentação técnica que ajuda a criar logs de entrega e especificações de forma eficiente","ru":"Write-docs - это инструмент технической документации, который помогает создавать журналы передачи и спецификации эффективно","ar":"Write-docs هو أداة وثائق فنية تساعد في إنشاء سجلات التسليم والمواصفات بفعالية"},"features":{"en":["Generates handoff logs using the handoff-template.md template","Supports creation of spec sheets and work logs with required information","Utilizes a flat and concise writing style with absolute dates","Includes specific details such as file paths, commands, and environment variables","Automatically saves logs to the docs/agent-logs directory"],"zh":["使用references/的模板生成文档","支持手动日志和错误日志的记录","可以自动生成README.md文件","支持相对日付和绝对日付的记录","可以记录判断理由和未解決課題"],"ja":["references/のテンプレートを使用してドキュメントを生成","手動ログとエラーログの記録をサポート","README.mdファイルを自動生成","相対日付と絶対日付の記録をサポート","判断理由と未解決課題の記録をサポート"],"ko":["references/의 템플릿을 사용하여 문서 생성","수동 로그와 에러 로그 기록 지원","README.md 파일 자동 생성","상대 날짜와 절대 날짜 기록 지원","판단 이유와 미해결 과제 기록 지원"],"es":["Utiliza plantillas predefinidas para la documentación","Aplica reglas comunes para la redacción de textos","Incluye información específica como rutas de archivos y comandos","Permite la creación de registros de entrega y logs","Utiliza fechas relativas y absolutas para la documentación","Soporta la creación de documentos en formato Markdown"],"fr":["Utilise des modèles prédéfinis pour la documentation","Applique des règles standard pour la rédaction de textes","Inclut des informations spécifiques comme les chemins de fichiers et les commandes","Permet la création de journaux de remise et de logs","Utilise des dates relatives et absolues pour la documentation","Prend en charge la création de documents au format Markdown"],"de":["Verwendet vordefinierte Vorlagen für die Dokumentation","Wendet gemeinsame Regeln für die Texterstellung an","Beinhaltet spezifische Informationen wie Dateipfade und Befehle","Ermöglicht die Erstellung von Übergabeprotokollen und Logs","Verwendet relative und absolute Daten für die Dokumentation","Unterstützt die Erstellung von Dokumenten im Markdown-Format"],"pt":["Utiliza templates de documentação para logs de entrega e especificações","Segue regras claras para criação de documentação técnica","Inclui informações específicas, como caminhos de arquivo e comandos","Permite a criação de logs de entrega e especificações de forma eficiente","Suporta a utilização de datas relativas e absolutas","Oferece uma estrutura para documentação técnica clara e concisa"],"ru":["Использует шаблоны документации для журналов передачи и спецификаций","Следует четким правилам для создания технической документации","Включает конкретную информацию, такую как пути файлов и команды","Позволяет создавать журналы передачи и спецификации эффективно","Поддерживает использование относительных и абсолютных дат","Предоставляет структуру для ясной и краткой технической документации"],"ar":["يستخدم قوالب وثائقية لإنشاء سجلات التسليم والمواصفات","يتابع قواعد واضحة لإنشاء الوثائق الفنية","يضم معلومات محددة، مثل مسارات الملفات والأوامر","يسمح بإنشاء سجلات التسليم والمواصفات بفعالية","يدعم استخدام التواريخ النسبية والمطلقة","يقدم هيكلاً لإنشاء وثائق فنية واضحة وموجزة"]},"keywords":{"en":["how to use write-docs","write-docs setup guide","technical documentation best practices","write-docs alternative","write-docs vs markdown","install write-docs","what is write-docs","write-docs tutorial","write-docs for AI agents"],"zh":["AI文档生成","Write Docs","文档生成工具","AI工具","开发者文档","README.md生成","手动日志记录","错误日志记录"],"ja":["AIエージェント","Write Docs","ドキュメント作成ツール","AIツール","開発者ドキュメント","README.md生成","手動ログ記録","エラーログ記録"],"ko":["AI 도구","Write Docs","문서 생성 도구","개발자 문서","README.md 생성","수동 로그 기록","에러 로그 기록","AI 문서 작성"],"es":["agente AI para documentación técnica","herramientas de documentación","plantillas de documentación","reglas de redacción","documentación en Markdown","registros de entrega","logs de sistema","fechas relativas y absolutas"],"fr":["agent AI pour documentation technique","outils de documentation","modèles de documentation","règles de rédaction","documentation au format Markdown","journaux de remise","logs de système","dates relatives et absolues"],"de":["AI-Tool für technische Dokumentation","Dokumentationswerkzeuge","Dokumentationsvorlagen","Texterstellungsregeln","Dokumentation im Markdown-Format","Übergabeprotokolle","Systemlogs","relative und absolute Daten"],"pt":["Write-docs","documentação técnica","logs de entrega","especificações","templates de documentação","regras de documentação","ferramentas de documentação","criação de documentação","documentação eficiente"],"ru":["Write-docs","техническая документация","журналы передачи","спецификации","шаблоны документации","правила документации","инструменты документации","создание документации","эффективная документация"],"ar":["Write-docs","وثائق فنية","سجلات التسليم","المواصفات","قوالب وثائقية","قواعد وثائقية","أدوات وثائقية","إنشاء وثائق","وثائق فعالة"]}},"owner":"nematatu","repo":"kotobad","repoPath":"nematatu/kotobad","stars":0,"forks":0,"updatedAt":"2026-03-06T17:43:20Z","topics":[],"category":"community","skillMd":{"name":"write-docs","description":"日本語のドキュメント作成（AI引き継ぎログ、仕様書、作業内容ログ/作業記録）に特化。次の依頼で使う: 引き継ぎログの新規作成・更新、仕様書の作成/改訂、作業内容ログの詳細記録、テンプレートに沿った構造化文書の生成。","bodyPreview":"# Write Docs\n\n## Quick Start\n\n- 文書種別を決定する（引き継ぎログ、仕様書、作業ログ）。\n- 不足情報は原則こちらで判断し、「未確認」と明記して進める。質問は原則しない。\n- `references/` のテンプレートを使う。\n\n## Common Rules\n\n- 日本語の敬語で、簡潔に書く。\n- 事実を捏造しない。不明点は「未確認」と明記する。\n- 短文とフラットな箇条書きだけを使う。\n- 具体情報を必ず入れる（ファイルパス、コマンド、環境変数、日付、エラー）。\n- 不採用の案は「不採用」と理由を残す。\n- 相対日付が出たら絶対日付も併記する。\n\n## Handoff Log\n\n- `references/handoff-template.md` を使う。\n- プロダクト概要、現在の目標、変更点（ファイル単位）、実行コマンド、エラー/ログ、判断理由、未解決課題、制約を含める。\n- 既定の出力先は `docs/agent-logs/YYYY-MM-DD-<session-id>/README.md` とする。\n- 生ログは `docs/agent-log","body":"# Write Docs\n\n## Quick Start\n\n- 文書種別を決定する（引き継ぎログ、仕様書、作業ログ）。\n- 不足情報は原則こちらで判断し、「未確認」と明記して進める。質問は原則しない。\n- `references/` のテンプレートを使う。\n\n## Common Rules\n\n- 日本語の敬語で、簡潔に書く。\n- 事実を捏造しない。不明点は「未確認」と明記する。\n- 短文とフラットな箇条書きだけを使う。\n- 具体情報を必ず入れる（ファイルパス、コマンド、環境変数、日付、エラー）。\n- 不採用の案は「不採用」と理由を残す。\n- 相対日付が出たら絶対日付も併記する。\n\n## Handoff Log\n\n- `references/handoff-template.md` を使う。\n- プロダクト概要、現在の目標、変更点（ファイル単位）、実行コマンド、エラー/ログ、判断理由、未解決課題、制約を含める。\n- 既定の出力先は `docs/agent-logs/YYYY-MM-DD-<session-id>/README.md` とする。\n- 生ログは `docs/agent-logs/YYYY-MM-DD-<session-id>/logs/` に置く。\n\n## Spec\n\n- `references/spec-template.md` を使う。\n- 範囲、非対象、前提、受け入れ条件を必ず記載する（未確認は未確認）。\n- リスク、未解決課題、依存、ロールアウト/テスト計画を必要に応じて含める。\n\n## Work Log (Detailed)\n\n- `references/work-log-template.md` を使う。\n- タイムスタンプがある場合は時系列で記録する。\n- ファイルごとの変更概要と実行コマンドを必ず含める。\n- Git 情報（コミット、ブランチ、差分、未コミット）を参照する。\n- 参照コマンド例: `git status -sb` / `git log --oneline -n 20` / `git show <hash>` / `git diff`。\n- 作業ログに参照したコミットの `hash`、件名、日時、関連ファイルを明記する。\n- Git 情報が取得できない場合は「未確認」と明記する。\n"},"lastSynced":"2026-03-07T03:49:01.630Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents needing automated documentation generation for handoff logs and spec sheets.","zh":"适合需要自动化文档生成的技术写作代理，用于创建交接日志和规格表。","ja":"テクニカルライティングエージェントが交付ログや仕様シートの自動化ドキュメント生成に適しています。","ko":"자동화된 문서 생성이 필요한 기술 작성 에이전트에게 적합하여 인도 로그 및 사양 시트를 생성하는 데 사용됩니다.","es":"Perfecto para Agentes de Escritura Técnica que necesitan generación automatizada de documentación para registros de entrega y hojas de especificaciones.","fr":"Parfait pour les agents de rédaction technique ayant besoin de génération automatique de documentation pour les journaux de passation et les feuilles de spécifications.","de":"Perfekt für technische Schreibagenten, die eine automatisierte Generierung von Dokumentationen für Handover-Logs und Spezifikationen benötigen.","pt":"Perfeito para Agentes de Escrita Técnica que necessitam de geração automatizada de documentação para registros de handoff e folhas de especificações.","ru":"Идеально подходит для агентов технической документации, которым требуется автоматизированная генерация документации для журналов передачи и листов спецификаций.","ar":"مثالي للوكلاء الكتابيين الفنيين الذين يحتاجون إلى توليد مستندات آلي لسجلات الحوالات وورقات المواصفات."},"recommendation":{"en":"Empowers agents to generate technical documentation using templates from the references/ directory, streamlining documentation processes with concise Japanese text and absolute date inclusion, while ensuring fact accuracy and specific information like file paths and commands.","zh":"使代理能够使用 references/ 目录中的模板生成技术文档，从而简化文档流程，确保事实准确性和特定信息，如文件路径和命令，并包含简洁的日文文本和绝对日期。","ja":"エージェントが references/ ディレクトリからのテンプレートを使用して技術文書を生成できるようにし、ドキュメント化プロセスを簡素化し、事実の正確性とファイルパスやコマンドなどの特定の情報を保証し、日本語テキストと絶対日付を含める。","ko":"에이전트가 references/ 디렉토리에서 템플릿을 사용하여 기술 문서를 생성할 수 있도록 하여 문서화 프로세스를 간소화하고 사실의 정확성과 파일 경로 및 명령어와 같은 특정 정보를 보장하며, 일본어 텍스트와 절대 날짜를 포함합니다.","es":"Habilita a los agentes a generar documentación técnica utilizando plantillas del directorio references/, optimizando los procesos de documentación con texto japonés conciso e inclusión de fechas absolutas, garantizando la precisión de los hechos y la información específica como rutas de archivos y comandos.","fr":"Permet aux agents de générer une documentation technique à l''aide de modèles du répertoire references/, rationalisant les processus de documentation avec du texte japonais concis et l''inclusion de dates absolues, tout en garantissant l''exactitude des faits et des informations spécifiques comme les chemins de fichiers et les commandes.","de":"Ermöglicht es den Agenten, technische Dokumentationen mithilfe von Vorlagen aus dem Verzeichnis references/ zu generieren, wodurch die Dokumentationsprozesse mit präzisem japanischem Text und absoluten Datumsangaben rationalisiert werden, während die Genauigkeit der Fakten und spezifischer Informationen wie Dateipfade und Befehle gewährleistet bleibt.","pt":"Permite que os agentes gerem documentação técnica usando modelos do diretório references/, simplificando os processos de documentação com texto japonês conciso e inclusão de datas absolutas, garantindo a precisão dos fatos e informações específicas como caminhos de arquivos e comandos.","ru":"Позволяет агентам создавать техническую документацию с помощью шаблонов из директории references/, оптимизируя процессы документации с помощью краткого японского текста и включения абсолютных дат, обеспечивая точность фактов и конкретной информации, такой как пути к файлам и команды.","ar":"تمكن الوكلاء من توليد مستندات فنية باستخدام قوالب من الدليل references/، وتبسيط عمليات المستندات مع نص ياباني موجز وتضمين تواريخ مطلقة، مع ضمان دقة الحقائق والمعلومات المحددة مثل مسارات الملفات والأوامر."},"useCases":{"en":["Automating handoff log creation with product overviews and change points","Generating spec sheets with detailed command and environment variable information","Debugging documentation with clear error and log inclusion"],"zh":["使用产品概述和更改点自动创建交接日志","使用详细命令和环境变量信息生成规格表","使用清晰的错误和日志包含调试文档"],"ja":["製品の概要と変更点を使用してハンドオーバーログを作成する自動化","詳細なコマンドと環境変数の情報を使用して仕様シートを生成する","明確なエラーとログの包含を使用してデバッグドキュメント"],"ko":["제품 개요 및 변경 사항을 사용하여 인도 로그 생성 자동화","자세한 명령 및 환경 변수 정보를 사용하여 사양 시트 생성","명확한 오류 및 로그 포함을 사용하여 디버깅 문서"],"es":["Automatización de la creación de registros de entrega con vistas generales de productos y puntos de cambio","Generación de hojas de especificaciones con información detallada de comandos y variables de entorno","Depuración de documentación con inclusión clara de errores y registros"],"fr":["Automatisation de la création de journaux de passation avec des vues d''ensemble de produits et des points de changement","Génération de feuilles de spécifications avec des informations détaillées de commandes et de variables d''environnement","Débogage de la documentation avec une inclusion claire des erreurs et des journaux"],"de":["Automatisierung der Erstellung von Handover-Logs mit Produktübersichten und Änderungspunkten","Generierung von Spezifikationen mit detaillierter Befehls- und Umgebungsvariableninformation","Fehlerbehebung in der Dokumentation mit klarer Fehler- und Log-Aufnahme"],"pt":["Automatizar a criação de registros de handoff com visões gerais de produtos e pontos de alteração","Gerar folhas de especificações com informações detalhadas de comandos e variáveis de ambiente","Depurar documentação com inclusão clara de erros e logs"],"ru":["Автоматизировать создание журналов передачи с обзорами продуктов и точками изменения","Генерировать листы спецификаций с подробной информацией о командах и переменных среды","Отлаживать документацию с четким включением ошибок и журналов"],"ar":["أتمتة إنشاء سجلات الحوالات مع لمحة عامة عن المنتجات و نقاط التغيير","توليد ورقات مواصفات مع معلومات مفصلة عن الأوامر ومتغيرات البيئة","تصحيح مستندات مع تضمين واضح للأخطاء وسجلات"]},"limitations":{"en":["Requires access to the references/ directory for templates","Limited to Japanese language documentation","Needs strict adherence to template and formatting guidelines"],"zh":["需要访问 references/ 目录以获取模板","仅限日语文档","需要严格遵守模板和格式指南"],"ja":["テンプレートを取得するために references/ ディレクトリへのアクセスが必要","日本語のドキュメントのみ","テンプレートおよび書式設定ガイドラインに厳密に従う必要"],"ko":["템플릿을 얻기 위해 references/ 디렉토리への 액세스가 필요","일본어 문서만 해당","템플릿 및 형식 지침에 엄격히 준수해야 함"],"es":["Requiere acceso al directorio references/ para plantillas","Limitado a la documentación en idioma japonés","Necesita una estricta adherencia a las pautas de plantilla y formato"],"fr":["Nécessite un accès au répertoire references/ pour les modèles","Limité à la documentation en langue japonaise","Nécessite une stricte adhésion aux lignes directrices de modèle et de mise en forme"],"de":["Benötigt Zugriff auf das Verzeichnis references/ für Vorlagen","Begrenzt auf Dokumentationen in japanischer Sprache","Benötigt eine strikte Einhaltung der Vorlagen- und Formatierungsrichtlinien"],"pt":["Requer acesso ao diretório references/ para modelos","Limitado à documentação em língua japonesa","Necessita de adesão estrita às diretrizes de modelo e formatação"],"ru":["Требует доступа к директории references/ для шаблонов","Ограничен документацией на японском языке","Требует строгого соблюдения руководящих принципов шаблона и форматирования"],"ar":["يتطلب الوصول إلى الدليل references/ للقوالب","محدود بالتوثيق باللغة اليابانية","يحتاج إلى اتباع قواعد القوالب وتنسيقها بدقة"]},"version":4},"contentHash":"ef93e2596f326b80fc164690927f42119d49204c74ea3631b2edc4b63511dbe2","qualityScore":20}');
