INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nematatu/kotobad/write-docs', 'write-docs', 'nematatu', 'kotobad', 'community', 'write-docs nematatu kotobad community The write-docs skill enables AI agents to generate technical documentation, including handoff logs and spec sheets, using templates from the references/ directory. It benefits developers by streamlining documentation processes. Write Docs是一个AI文档生成工具，帮助开发者快速创建高质量文档 Write DocsはAIエージェントのドキュメント作成を支援するツールで、テンプレートを使用して効率的なドキュメント作成を実現します Write Docs는 개발자를 위한 AI 문서 작성 도구로 문서 생성을 최적화합니다 El agente AI ''write-docs'' permite crear documentación técnica de manera eficiente con plantillas y reglas comunes L''agent AI ''write-docs'' permet de rédiger une documentation technique de qualité avec des modèles et des règles standard Der AI-Tool ''write-docs'' ermöglicht die Erstellung technischer Dokumentationen mit Vorlagen und gemeinsamen Regeln O Write-docs é uma ferramenta para criar documentação técnica, incluindo logs de entrega e especificações, com templates e regras claras Write-docs - это инструмент для создания технической документации, включая журналы передачи и спецификации, с шаблонами и четкими правилами Write-docs هو أداة لإنشاء الوثائق الفنية، بما في ذلك سجلات التسليم والمواصفات، مع قوالب وقواعد واضحة how to use write-docs write-docs setup guide technical documentation best practices write-docs alternative write-docs vs markdown install write-docs what is write-docs write-docs tutorial write-docs for AI agents AI文档生成 Write Docs 文档生成工具 AI工具 开发者文档 README.md生成 手动日志记录 错误日志记录 Generates handoff logs using the handoff-template.md template Supports creation of spec sheets and work logs with required information Utilizes a flat and concise writing style with absolute dates Includes specific details such as file paths, commands, and environment variables Automatically saves logs to the docs/agent-logs directory write-docs is a technical documentation skill that utilizes templates and specific formatting rules to generate high-quality documents, including handoff logs and spec sheets.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kvcop/ai-kb-assistant/kb-orchestrator-workflow', 'community', 'kvcop', 'ai-kb-assistant', 'kvcop/ai-kb-assistant', 'kb-orchestrator-workflow', 0, 0, 20, '2026-02-25T15:21:29Z', '2026-03-07T03:50:01.041Z', 'b6e3c9ce8286ddc69e0b5ce6e82ce0b69ddfbfc22acd48aebaf15f2dec111982', '{"id":"kvcop/ai-kb-assistant/kb-orchestrator-workflow","name":"kb-orchestrator-workflow","description":{"en":"The kb-orchestrator-workflow skill automates tasks through a reproducible workflow, utilizing Telegram and Codex bridge bot. It benefits developers by providing a clear and efficient workflow process.","zh":"KB Orchestrator Workflow是一种AI KB助手模板，实现了Codex-like任务和Telegram↔Codex桥接机器人，确保任务的可复制性和可靠性","ja":"KB Orchestrator Workflowは、CodexのようなタスクとTelegram↔Codexブリッジボットを実現したAI KBアシスタントテンプレートです","ko":"KB Orchestrator Workflow는 Codex와 같은 작업 및 Telegram↔Codex 브릿지 봇을 구현한 AI KB 어시스턴트 템플릿입니다","es":"kb-orchestrator-workflow es una plantilla de asistente de IA que permite la automatización de tareas a través de un flujo de trabajo definido, con integración con Telegram y Codex","fr":"kb-orchestrator-workflow est un modèle d''assistant d''IA qui permet l''automatisation de tâches via un flux de travail défini, avec intégration à Telegram et Codex","de":"kb-orchestrator-workflow ist eine Vorlage für einen KI-Assistenten, der die Automatisierung von Aufgaben über einen definierten Workflow ermöglicht, mit Integration in Telegram und Codex","pt":"O kb-orchestrator-workflow é um template de assistente de conhecimento que integra Telegram e Codex para automatizar tarefas","ru":"kb-orchestrator-workflow - это шаблон помощника знаний, который интегрирует Telegram и Codex для автоматизации задач","ar":"kb-orchestrator-workflow هو قالب مساعد معرفة يدمج Telegram و Codex لتحسين أداء أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"kb-orchestrator-workflow: Automated Workflow Setup Guide ...","zh":"KB Orchestrator Workflow Setup Guide - AI工具","ja":"KB Orchestrator Workflowベストプラクティス - AIエージェント","ko":"KB Orchestrator Workflow 구축 가이드 - AI 에이전트","es":"Guía de configuración de kb-orchestrator-workflow para Ag...","fr":"Guide de mise en place de kb-orchestrator-workflow pour O...","de":"Einrichtungsleitfaden für kb-orchestrator-workflow mit KI...","pt":"Guia de Configuração do kb-orchestrator-workflow para Des...","ru":"Настройка ИИ Агентов: kb-orchestrator-workflow Руководство","ar":"دليل الإعداد لـ kb-orchestrator-workflow لأدوات الذكاء ال..."},"description":{"en":"Streamline your workflow with kb-orchestrator-workflow. Learn how to automate tasks via Telegram and Codex bridge bot. Get started now!","zh":"了解KB Orchestrator Workflow的技术细节，包括Codex-like任务、Telegram↔Codex桥接机器人和Playwright检查","ja":"KB Orchestrator Workflowの技術的側面を学ぶ、Codexのようなタスク、Telegram↔Codexブリッジボット、Playwrightのチェックを含む","ko":"KB Orchestrator Workflow의 기술적 세부 사항을 학습하세요, Codex와 같은 작업, Telegram↔Codex 브릿지 봇, Playwright 확인 포함","es":"Aprende a implementar kb-orchestrator-workflow para automatizar tareas con Agentes de IA y herramientas de desarrollo como Playwright","fr":"Découvrez comment mettre en place kb-orchestrator-workflow pour automatiser des tâches avec des Outils d''IA et des outils de développement comme Playwright","de":"Erfahren Sie, wie Sie kb-orchestrator-workflow einrichten, um Aufgaben mit KI-Tools und Entwicklungstools wie Playwright zu automatisieren","pt":"Aprenda a configurar o kb-orchestrator-workflow para automatizar tarefas com Telegram e Codex","ru":"Узнайте, как настроить kb-orchestrator-workflow для автоматизации задач с Telegram и Codex","ar":"تعلم كيفية ضبط kb-orchestrator-workflow لتحسين أداء أدوات الذكاء الاصطناعي مع Telegram و Codex"},"definition":{"en":"kb-orchestrator-workflow is a workflow automation template that integrates Telegram and Codex bridge bot for reproducible task execution.","zh":"KB Orchestrator Workflow是一种AI工具，用于自动化任务执行和检查，确保任务的可复制性和可靠性","ja":"KB Orchestrator Workflowは、タスクの実行とチェックを自動化するAIエージェントです","ko":"KB Orchestrator Workflow는 작업 실행 및 확인을 자동화하는 AI 에이전트입니다","es":"kb-orchestrator-workflow es una plantilla de asistente de IA que automatiza tareas mediante un flujo de trabajo definido","fr":"kb-orchestrator-workflow est un modèle d''assistant d''IA qui automatise des tâches via un flux de travail défini","de":"kb-orchestrator-workflow ist eine Vorlage für einen KI-Assistenten, der Aufgaben über einen definierten Workflow automatisiert","pt":"O que é kb-orchestrator-workflow? Um template de assistente de conhecimento para automatizar tarefas","ru":"Что такое kb-orchestrator-workflow? Шаблон помощника знаний для автоматизации задач","ar":"ما هو kb-orchestrator-workflow؟ قالب مساعد معرفة لتحسين أداء أدوات الذكاء الاصطناعي"},"features":{"en":["Utilizes a KB-first workflow for task automation","Integrates with Telegram for seamless communication","Employs a Codex bridge bot for efficient task execution","Supports isolated environments for each task version","Leverages Playwright for UI testing and validation","Generates a final report for task completion"],"zh":["Codex-like任务","Telegram↔Codex桥接机器人","Playwright检查","任务的可复制性和可靠性","多版本支持","隔离环境支持"],"ja":["Codexのようなタスク","Telegram↔Codexブリッジボット","Playwrightのチェック","タスクの再現性と信頼性","マルチバージョンサポート","隔離環境サポート"],"ko":["Codex와 같은 작업","Telegram↔Codex 브릿지 봇","Playwright 확인","작업의 재현성 및 신뢰성","다중 버전 지원","격리 환경 지원"],"es":["Integración con Telegram y Codex","Flujo de trabajo definido para la automatización de tareas","Uso de Playwright para pruebas de UI","Soporte para múltiples versiones de tareas","Entornos de trabajo aislados para cada versión de tarea"],"fr":["Intégration à Telegram et Codex","Flux de travail défini pour l''automatisation de tâches","Utilisation de Playwright pour les tests d''interface utilisateur","Prise en charge de plusieurs versions de tâches","Environnements de travail isolés pour chaque version de tâche"],"de":["Integration in Telegram und Codex","Definierter Workflow für die Automatisierung von Aufgaben","Verwendung von Playwright für Benutzeroberflächentests","Unterstützung für mehrere Versionen von Aufgaben","Isolierte Arbeitsumgebungen für jede Aufgabenversion"],"pt":["Integração com Telegram e Codex","Automatização de tarefas com Playwright","Suporte a múltiplas versões de tasks","Isolamento de ambientes de trabalho","Relatórios finais personalizados"],"ru":["Интеграция с Telegram и Codex","Автоматизация задач с Playwright","Поддержка нескольких версий задач","Изоляция рабочих сред","Пользовательские финальные отчёты"],"ar":["دمج مع Telegram و Codex","تحسين أداء المهام مع Playwright","دعم إصدارات متعددة للمهام","عزل بيئات العمل","تقارير نهائية مخصصة"]},"keywords":{"en":["kb-orchestrator-workflow setup guide","how to use kb-orchestrator-workflow","kb-orchestrator-workflow alternative","kb-orchestrator-workflow vs automation tools","kb-orchestrator-workflow install","what is kb-orchestrator-workflow","kb-orchestrator-workflow tutorial","kb-orchestrator-workflow and Codex integration","kb-orchestrator-workflow workflow automation"],"zh":["AI工具","KB Orchestrator Workflow","Codex-like任务","Telegram↔Codex桥接机器人","Playwright检查","任务自动化","AI开发","机器学习"],"ja":["AIエージェント","KB Orchestrator Workflow","Codexのようなタスク","Telegram↔Codexブリッジボット","Playwrightのチェック","タスク自動化","AI開発","機械学習"],"ko":["AI 에이전트","KB Orchestrator Workflow","Codex와 같은 작업","Telegram↔Codex 브릿지 봇","Playwright 확인","작업 자동화","AI 개발","기계 학습"],"es":["Agentes de IA","Automatización de tareas","Flujo de trabajo","Integración con Telegram","Playwright","Desarrollo de software","Herramientas de desarrollo","Automatización de pruebas"],"fr":["Outils d''IA","Automatisation de tâches","Flux de travail","Intégration à Telegram","Playwright","Développement de logiciels","Outils de développement","Automatisation de tests"],"de":["KI-Tools","Automatisierung von Aufgaben","Definierter Workflow","Integration in Telegram","Playwright","Softwareentwicklung","Entwicklungstools","Automatisierung von Tests"],"pt":["kb-orchestrator-workflow","assistente de conhecimento","Telegram","Codex","automatização de tarefas","Playwright","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["kb-orchestrator-workflow","помощник знаний","Telegram","Codex","автоматизация задач","Playwright","разработка программного обеспечения","инструменты разработки"],"ar":["kb-orchestrator-workflow","مساعد معرفة","Telegram","Codex","تحسين أداء المهام","Playwright","تطوير البرمجيات","أدوات التطوير"]}},"owner":"kvcop","repo":"ai-kb-assistant","repoPath":"kvcop/ai-kb-assistant","stars":0,"forks":0,"updatedAt":"2026-02-25T15:21:29Z","topics":[],"category":"community","skillMd":{"name":"kb-orchestrator-workflow","description":"Orchestrator-first workflow for building and shipping changes via KB Orchestrator (orchestrator/): setup target repo/workdir, run validation jobs with artifacts + safety, then run structured code review and apply fixes (requesting-code-review/receiving-code-review), and verify web UI behavior via Playwright MCP. Use when the user asks “через оркестратор”, wants repeatable stages + audit trail (commands/prompt), or needs phone/VPN-accessible web demo checks.","bodyPreview":"# KB Orchestrator Workflow\n\n## Цель\nСделать выполнение задач **через оркестратор** воспроизводимым: чёткие этапы → артефакты → проверки → ревью → фиксы → (для UI) Playwright‑проверка → финальный отчёт.\n\n## Codex-like Tasks (продуктовый режим)\n- Пользователь ставит задачу как `Task` (repo + base ref + prompt + `N` версий).\n- Каждая версия (`TaskVersion`) живёт в **своём изолированном окружении** (у нас: отдельный `worktree/workspace` на worker’е).\n- Запуск “как в Codex”: `Task` сразу попадает в о","body":"# KB Orchestrator Workflow\n\n## Цель\nСделать выполнение задач **через оркестратор** воспроизводимым: чёткие этапы → артефакты → проверки → ревью → фиксы → (для UI) Playwright‑проверка → финальный отчёт.\n\n## Codex-like Tasks (продуктовый режим)\n- Пользователь ставит задачу как `Task` (repo + base ref + prompt + `N` версий).\n- Каждая версия (`TaskVersion`) живёт в **своём изолированном окружении** (у нас: отдельный `worktree/workspace` на worker’е).\n- Запуск “как в Codex”: `Task` сразу попадает в очередь, а worker **сам** берёт следующее из очереди (без ручного “run-next”/кнопок запуска воркера).\n- Пайплайн стадий (MVP): `research? → execute → tests → review → fix`.\n  - `research` **опционален**: orchestrator решает, нужен ли он по контексту/задаче.\n  - `tests` может включать “run/smoke/Playwright” для веб‑приложений → обычно это делает `tester` с `capability=network`.\n  - “user‑facing deploy” (URL/порт для пользователя) — отдельный **опциональный** Job/подстадия, включаемая только при явной необходимости.\n  - `review` должен быть **read-only** (например, `codex exec -s read-only ...`), результат — отчёт, а не изменения.\n  - `fix` применяет выводы ревью; при необходимости повторить `tests`.\n- UX “версий”:\n  - Код-ревью: параллельно запустить `N` версий, собрать фидбэк и агрегировать уникальное.\n  - Креатив: выбрать лучшую версию/вариант и продолжать только её (или разветвить выбранную ещё на `2–4`).\n\n## Связанные навыки (использовать как подпроцессы)\n- Code review request: `.codex/skills/requesting-code-review/SKILL.md`\n- Code review apply: `.codex/skills/receiving-code-review/SKILL.md`\n- Frontend дизайн: `.codex/skills/frontend-design/SKILL.md`\n- Отправка файлов в Telegram: `.codex/skills/tg-mcp-send-files/SKILL.md`\n\n## Инварианты (safety)\n- Не делать `git push` без явного запроса пользователя.\n- Не использовать `sudo`.\n- Держать рабочее дерево чистым: всё нужное — закоммитить, рантайм/артефакты — в `.gitignore`.\n- Для “executor без сети”: **не полагаться на удачу**. Если нужен интернет — добывать материалы control‑plane’ом и передавать локально.\n\n## Артефакты (канонично)\n- В целевом проекте держать `ORCH_RUN.md`: старт/финиш, исходный prompt, точные команды, ссылки, итерации, job_id.\n- В оркестраторе использовать артефакты `orchestrator/state/artifacts/<job_id>/summary.json` и `iterations.json` как источник правды по времени/итерациям.\n\n## Этапы (строго по порядку)\n\n### 0) Зафиксировать вводные\n- Зафиксировать `pwd` и целевую папку работы (если нужно “не захламлять” — подняться уровнем выше и работать рядом).\n- Создать/обновить `ORCH_RUN.md` (в целевом репо): `Start`, цель, URL (если UI), критерии DoD.\n- Сформулировать **DoD** и stop‑условие (по умолчанию `COMPLETED` строго последней строкой stdout).\n\n### 1) Подготовить целевой репозиторий\n- Создать папку/репо, настроить git‑identity (локально).\n- Добавить `.gitignore`, базовый `README.md`, тестовый каркас, `ruff`/`mypy`.\n- Прогнать проверки локально и сделать baseline commit.\n\n### 2) Сформировать prompt для executor (качество постановки)\n- Явно перечислить: ограничения (no push/sudo), DoD, команды проверок, артефакты.\n- Если задача про UI: указать URL и требование проверить сценарии через Playwright MCP.\n- Встроить “loop hook”: `COMPLETED` (и опционально `BLOCKER`) как последняя строка stdout.\n- Записать prompt в `ORCH_RUN.md` (как “исходный запрос”).\n\n### 3) Выполнить реализацию (executor)\n- Делать маленькие, проверяемые шаги.\n- Коммитить осмысленными порциями; не оставлять мусор/временные файлы вне `.gitignore`.\n- Не менять тесты executor’ом (если политика включена) — для тестов использовать отдельный этап/роль.\n\n### 4) Прогнать проверки через KB Orchestrator (валидировать и собрать артефакты)\n- Зарегистрировать repo:\n  - `cd orchestrator`\n  - `../.venv/bin/python -m kb_orchestrator repo add --id <id> --path <abs_path>`\n- Создать job на проверки (пример):\n  - `../.venv/bin/python -m kb_orchestrator job create --repo <id> --max-iters 3 --completion-keyword COMPLETED -- bash -lc ''<checks...>; echo COMPLETED''`\n- Запустить worker:\n  - `../.venv/bin/python -m kb_orchestrator worker run` (по умолчанию в цикле; `--once` чтобы выполнить один job)\n- Если `blocked`:\n  - “грязное дерево” → создать отдельную cleanup‑подзадачу (commit/ignore), без авто‑удалений.\n  - “executor modified tests” → откатить/перенести изменения тестов в отдельный этап.\n\n### 5) Создать агента на code review (requesting-code-review)\n- В отдельном запуске/топике попросить review по `{BASE_SHA}..{HEAD_SHA}`.\n- Следовать `.codex/skills/requesting-code-review/SKILL.md`.\n- Сохранить результат в целевом репо (например `CODE_REVIEW.md`) и залинковать из `ORCH_RUN.md`.\n\n### 6) Создать агента на фиксы по ревью (receiving-code-review)\n- В отдельном запуске/топике применить рекомендации, **проверяя техническую корректность**.\n- Следовать `.codex/skills/receiving-code-review/SKILL.md`.\n- После каждого батча фиксов повторить этап 4 (оркестратор‑проверки).\n\n### 7) Для UI: проверить поведение через Playwright MCP\n- Поднять сервер на `0.0.0.0` (и зафиксировать PID/лог/stop‑команду в `ORCH_RUN.md`).\n- Проверить сценарий “как пользователь” через MCP Playwright:\n  - `mcp__playwright__browser_navigate` → URL (например `http://192.168.77.4:8000`)\n  - `mcp__playwright__browser_snapshot` → зафиксировать состояние\n  - при проблемах: `mcp__playwright__browser_console_messages`, `mcp__playwright__browser_network_requests`\n- Если найдены ошибки/несостыковки: создать fix‑подзадачу и повторить 4 → 7.\n\n### 8) Финализировать и отчитаться\n- Обновить `ORCH_RUN.md`:\n  - время (start/end), итерации, job_id, список команд, исходный prompt, ссылку на результат.\n- В ответ пользователю всегда дать:\n  1) сколько времени заняло\n  2) сколько итераций (по `iterations.json`)\n  3) `.md` с командами+prompt\n  4) ссылку/URL\n  5) доп. заметки/риски/ограничения\n- Отправить `ORCH_RUN.md` в Telegram документом через MCP (см. `.codex/skills/tg-mcp-send-files/SKILL.md`).\n"},"lastSynced":"2026-03-07T03:50:01.041Z","agentAnalysis":{"suitability":{"en":"Ideal for Workflow Automation Agents needing reproducible task execution via Telegram and Codex bridge bot integration.","zh":"适用于需要通过Telegram和Codex桥接机器人集成实现可复现任务执行的工作流自动化代理。","ja":"TelegramおよびCodexブリッジボットの統合を介して再現可能なタスクの実行が必要なワークフロー自動化エージェントに適しています。","ko":"Telegram 및 Codex 브릿지 봇 통합을 통해 재현 가능한 작업 실행이 필요한 워크플로 자동화 에이전트에 적합합니다.","es":"Ideal para Agentes de Automatización de Flujo de Trabajo que necesitan una ejecución de tareas reproducible a través de la integración del bot de puente de Telegram y Codex.","fr":"Idéal pour les Agents d''Automatisation de Workflow nécessitant une exécution de tâches reproductible via l''intégration du bot de pont Telegram et Codex.","de":"Ideal für Workflow-Automatisierungsagenten, die eine reproduzierbare Aufgabenausführung über die Telegram- und Codex-Brückebot-Integration benötigen.","pt":"Ideal para Agentes de Automação de Fluxo de Trabalho que necessitam de execução de tarefas reprodutíveis via Telegram e integração de bot de ponte Codex.","ru":"Идеально подходит для агентов автоматизации рабочих процессов, которым необходима воспроизводимая выполнение задач через Telegram и интеграцию мостового бота Codex.","ar":"مثالي لعمليات وكيل إتمام مهام التلقائي الذين يحتاجون إلى تنفيذ مهام قابلة للتكرار عبر Telegram ودمج جسر بوت Codex."},"recommendation":{"en":"Empowers agents to automate tasks through a clear and efficient workflow process, utilizing Telegram for communication and Codex for code execution, with features like isolated environments for each task version and Playwright checks for UI validation.","zh":"赋予代理通过清晰高效的工作流程过程自动化任务的能力，利用Telegram进行通信，利用Codex进行代码执行，并具有每个任务版本的隔离环境和Playwright检查用于UI验证等功能。","ja":"エージェントに、Telegramを使用したコミュニケーションとCodexを使用したコードの実行、および各タスクバージョンの分離環境とUIの検証に使用するPlaywrightチェックなどの機能を使用して、タスクを自動化するための明確で効率的なワークフロー処理を可能にします。","ko":"에이전트에게 텔레그램을 통한 커뮤니케이션과 코덱스를 통한 코드 실행, 그리고 각 작업 버전의 분리 환경 및 UI 검증을 위한 Playwright 검사와 같은 기능을 사용하여 작업을 자동화하기 위한 명확하고 효율적인 워크플로우 프로세스를 제공합니다.","es":"Permite a los agentes automatizar tareas a través de un proceso de flujo de trabajo claro y eficiente, utilizando Telegram para la comunicación y Codex para la ejecución de código, con características como entornos aislados para cada versión de tarea y verificaciones de Playwright para la validación de la interfaz de usuario.","fr":"Permet aux agents d''automatiser des tâches à travers un processus de workflow clair et efficace, en utilisant Telegram pour la communication et Codex pour l''exécution de code, avec des fonctionnalités comme des environnements isolés pour chaque version de tâche et des vérifications Playwright pour la validation de l''interface utilisateur.","de":"Ermächtigt Agenten, Aufgaben durch einen klaren und effizienten Workflow-Prozess zu automatisieren, der Telegram für die Kommunikation und Codex für die Code-Ausführung nutzt, mit Funktionen wie isolierten Umgebungen für jede Aufgabenversion und Playwright-Prüfungen für die UI-Validierung.","pt":"Habilita os agentes a automatizar tarefas por meio de um processo de fluxo de trabalho claro e eficiente, utilizando o Telegram para comunicação e o Codex para execução de código, com recursos como ambientes isolados para cada versão de tarefa e verificações Playwright para validação de UI.","ru":"Наделяет агентов возможностью автоматизировать задачи посредством четкого и эффективного рабочего процесса, используя Telegram для общения и Codex для выполнения кода, с функциями, такими как изолированные среды для каждой версии задачи и проверки Playwright для валидации UI.","ar":"يمكن للوكلاء توفير مهام تلقائية من خلال عملية تدفق عمل واضحة وكفؤة، باستخدام Telegram للاتصال و Codex لتنفيذ الشفرة، مع ميزات مثل بيئات معزولة لكل إصدار من مهام واختبارات Playwright للتحقق من واجهة المستخدم."},"useCases":{"en":["Automating development workflows with reproducible task execution","Generating and managing task versions in isolated environments","Validating UI changes using Playwright checks"],"zh":["通过可复现的任务执行自动化开发工作流程","在隔离环境中生成和管理任务版本","使用Playwright检查验证UI更改"],"ja":["再現可能なタスクの実行を使用して開発ワークフローを自動化する","分離環境でタスクバージョンを生成して管理する","Playwrightチェックを使用してUIの変更を検証する"],"ko":["재현 가능한 작업 실행을 사용하여 개발 워크플로를 자동화하는 것","분리 환경에서 작업 버전을 생성 및 관리하는 것","Playwright 검사를 사용하여 UI 변경 사항을 검증하는 것"],"es":["Automatizar flujos de trabajo de desarrollo con ejecución de tareas reproducible","Generar y administrar versiones de tareas en entornos aislados","Validar cambios de interfaz de usuario utilizando verificaciones de Playwright"],"fr":["Automatiser les flux de travail de développement avec une exécution de tâches reproductible","Générer et gérer des versions de tâches dans des environnements isolés","Valider les modifications d''interface utilisateur en utilisant des vérifications Playwright"],"de":["Entwicklungs-Workflows mit reproduzierbarer Aufgabenausführung automatisieren","Aufgabenversionen in isolierten Umgebungen generieren und verwalten","Änderungen an der Benutzeroberfläche mithilfe von Playwright-Prüfungen überprüfen"],"pt":["Automatizar fluxos de trabalho de desenvolvimento com execução de tarefas reprodutíveis","Gerar e gerenciar versões de tarefas em ambientes isolados","Validar alterações de UI usando verificações Playwright"],"ru":["Автоматизировать рабочие процессы разработки с воспроизводимой выполнением задач","Генерировать и управлять версиями задач в изолированных средах","Проверять изменения UI с помощью проверок Playwright"],"ar":["توفير تدفقات عمل التطوير مع تنفيذ مهام قابلة للتكرار","إنشاء وإدارة إصدارات المهام في بيئات معزولة","التحقق من تغييرات واجهة المستخدم باستخدام اختبارات Playwright"]},"limitations":{"en":["Requires Telegram and Codex bridge bot setup","Needs isolated environments for task versions","Playwright required for UI validation"],"zh":["需要Telegram和Codex桥接机器人设置","需要隔离环境用于任务版本","需要Playwright用于UI验证"],"ja":["TelegramとCodexブリッジボットの設定が必要","タスクバージョンに分離環境が必要","UIの検証にはPlaywrightが必要"],"ko":["텔레그램과 코덱스 브릿지 봇 설정이 필요하다","작업 버전에 대한 분리 환경이 필요하다","UI 검증을 위해서는 Playwright가 필요하다"],"es":["Requiere configuración del bot de puente de Telegram y Codex","Necesita entornos aislados para versiones de tareas","Se requiere Playwright para la validación de la interfaz de usuario"],"fr":["Nécessite une configuration du bot de pont Telegram et Codex","Nécessite des environnements isolés pour les versions de tâches","Nécessite Playwright pour la validation de l''interface utilisateur"],"de":["Benötigt eine Einrichtung des Telegram- und Codex-Brückebots","Benötigt isolierte Umgebungen für Aufgabenversionen","Benötigt Playwright für die UI-Validierung"],"pt":["Requer configuração do bot de ponte Telegram e Codex","Necessita de ambientes isolados para versões de tarefas","Playwright é necessário para validação de UI"],"ru":["Требует настройки мостового бота Telegram и Codex","Требует изолированных сред для версий задач","Playwright необходим для валидации UI"],"ar":["يتطلب إعداد بوت جسر Telegram و Codex","يحتاج إلى بيئات معزولة لإصدارات المهام","يتم الحصول على Playwright للتحقق من واجهة المستخدم"]},"version":4},"contentHash":"b6e3c9ce8286ddc69e0b5ce6e82ce0b69ddfbfc22acd48aebaf15f2dec111982","qualityScore":20}');
