INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kvcop/ai-kb-assistant/kb-orchestrator-workflow', 'kb-orchestrator-workflow', 'kvcop', 'ai-kb-assistant', 'community', 'kb-orchestrator-workflow kvcop ai-kb-assistant community The kb-orchestrator-workflow skill automates tasks through a reproducible workflow, utilizing Telegram and Codex bridge bot. It benefits developers by providing a clear and efficient workflow process. KB Orchestrator Workflow是一种AI KB助手模板，实现了Codex-like任务和Telegram↔Codex桥接机器人，确保任务的可复制性和可靠性 KB Orchestrator Workflowは、CodexのようなタスクとTelegram↔Codexブリッジボットを実現したAI KBアシスタントテンプレートです KB Orchestrator Workflow는 Codex와 같은 작업 및 Telegram↔Codex 브릿지 봇을 구현한 AI KB 어시스턴트 템플릿입니다 kb-orchestrator-workflow es una plantilla de asistente de IA que permite la automatización de tareas a través de un flujo de trabajo definido, con integración con Telegram y Codex kb-orchestrator-workflow est un modèle d''assistant d''IA qui permet l''automatisation de tâches via un flux de travail défini, avec intégration à Telegram et Codex kb-orchestrator-workflow ist eine Vorlage für einen KI-Assistenten, der die Automatisierung von Aufgaben über einen definierten Workflow ermöglicht, mit Integration in Telegram und Codex O kb-orchestrator-workflow é um template de assistente de conhecimento que integra Telegram e Codex para automatizar tarefas kb-orchestrator-workflow - это шаблон помощника знаний, который интегрирует Telegram и Codex для автоматизации задач kb-orchestrator-workflow هو قالب مساعد معرفة يدمج Telegram و Codex لتحسين أداء أدوات الذكاء الاصطناعي kb-orchestrator-workflow setup guide how to use kb-orchestrator-workflow kb-orchestrator-workflow alternative kb-orchestrator-workflow vs automation tools kb-orchestrator-workflow install what is kb-orchestrator-workflow kb-orchestrator-workflow tutorial kb-orchestrator-workflow and Codex integration kb-orchestrator-workflow workflow automation AI工具 KB Orchestrator Workflow Codex-like任务 Telegram↔Codex桥接机器人 Playwright检查 任务自动化 AI开发 机器学习 Utilizes a KB-first workflow for task automation Integrates with Telegram for seamless communication Employs a Codex bridge bot for efficient task execution Supports isolated environments for each task version Leverages Playwright for UI testing and validation Generates a final report for task completion kb-orchestrator-workflow is a workflow automation template that integrates Telegram and Codex bridge bot for reproducible task execution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ivuorinen/branch-usage-checker/release-check', 'community', 'ivuorinen', 'branch-usage-checker', 'ivuorinen/branch-usage-checker', 'release-check', 0, 0, 20, '2026-03-02T01:06:07Z', '2026-03-07T03:52:16.261Z', 'd9727706f3a977d397304473e89e8794a345ee0b1b9d8389fa6bd97aa22943af', '{"id":"ivuorinen/branch-usage-checker/release-check","name":"release-check","description":{"en":"The release-check skill cross-checks GitHub branches and Packagist statistics to determine if branches are safe to delete, benefiting developers with automated pre-release verification.","zh":"Release-Check 是一个自动化工具，用于检查 GitHub 分支和 Packagist 下载统计，以确定分支是否安全删除。它通过运行一系列命令，包括 composer lint、测试和构建，来验证分支的安全性","ja":"Release-Check は、GitHub ブランチと Packagist ダウンロード統計をチェックしてブランチの安全性を確認する自動化ツールです。composer lint、テスト、ビルドなどのコマンドを実行してブランチの安全性を検証します","ko":"Release-Check는 GitHub 분기와 Packagist 다운로드 통계를 확인하여 분기 안전성을 확인하는 자동화 도구입니다. composer lint, 테스트, 빌드 등의 명령을 실행하여 분기 안전성을 검증","es":"Release-check es una herramienta que verifica la seguridad de las ramas de GitHub y las estadísticas de descargas de Packagist antes de una versión","fr":"Release-check est un outil qui vérifie la sécurité des branches GitHub et les statistiques de téléchargement de Packagist avant une version","de":"Release-check ist ein Tool, das die Sicherheit von GitHub-Branches und Packagist-Download-Statistiken vor einer Version überprüft","pt":"O release-check é uma ferramenta que verifica a segurança das ramificações no GitHub e Packagist, garantindo a integridade do seu projeto. Ele executa uma série de testes, incluindo composer lint:all e composer test.","ru":"Release-check - это инструмент, проверяющий безопасность веток в GitHub и Packagist, обеспечивая целостность вашего проекта. Он выполняет ряд тестов, включая composer lint:all и composer test, с помощью ИИ Агентов.","ar":"release-check هو أداة للتحقق من سلامة الفروع على GitHub و Packagist، وضمان سلامة مشروعك. يقوم بتنفيذ سلسلة من الاختبارات، بما في ذلك composer lint:all و composer test، مع الأدوات الذكية."},"seo":{"title":{"en":"release-check: Pre-Release Verification Setup Guide | AI ...","zh":"Release-Check 设置指南：自动化分支安全性检查","ja":"Release-Check 導入ガイド：AIエージェントによるブランチ安全性チェック","ko":"Release-Check 설정 가이드: 자동화 분기 안전성 확인","es":"Guía de configuración de release-check para agentes de IA","fr":"Guide de mise en place de release-check pour les outils d''IA","de":"Einrichtungsleitfaden für release-check bei KI-Agents","pt":"Guia de Configuração do release-check: Verificação de Ram...","ru":"Настройка release-check: Проверка Безопасных Веток ИИ Аге...","ar":"دليل إعداد release-check: التحقق من الفروع الآمنة للأدوات..."},"description":{"en":"Discover how release-check simplifies pre-release verification by running composer lint, tests, and build checks. Get started with this AI agent skill today!","zh":"通过 Release-Check AI 工具自动化检查 GitHub 分支和 Packagist 下载统计，确保分支安全删除","ja":"Release-Check AIエージェントを使用して GitHub ブランチと Packagist ダウンロード統計を自動的にチェックし、ブランチの安全性を確認する","ko":"Release-Check AI 도구를 사용하여 GitHub 분기와 Packagist 다운로드 통계를 자동으로 확인하여 분기 안전성을 확인","es":"Aprende a utilizar release-check para verificar ramas de GitHub y estadísticas de descargas de Packagist antes de una versión","fr":"Découvrez comment utiliser release-check pour vérifier les branches GitHub et les statistiques de téléchargement de Packagist avant une version","de":"Erfahren Sie, wie Sie release-check verwenden, um GitHub-Branches und Packagist-Download-Statistiken vor einer Version zu überprüfen","pt":"Aprenda a configurar o release-check para verificar ramificações seguras no GitHub e Packagist, garantindo a integridade do seu projeto","ru":"Узнайте, как настроить release-check для проверки безопасных веток в GitHub и Packagist, обеспечивая целостность вашего проекта с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد release-check للتحقق من الفروع الآمنة على GitHub و Packagist، وضمان سلامة مشروعك مع الأدوات الذكية"},"definition":{"en":"release-check is a skill that automates pre-release verification by running a suite of checks, including composer lint, tests, and build processes.","zh":"Release-Check 是一个用于自动化分支安全性检查的 AI 工具","ja":"Release-Check は、ブランチの安全性を自動的にチェックする AI エージェントです","ko":"Release-Check는 자동화 분기 안전성 확인을 위한 AI 도구","es":"Release-check es una herramienta de verificación de versiones que utiliza GitHub y Packagist","fr":"Release-check est un outil de vérification de versions qui utilise GitHub et Packagist","de":"Release-check ist ein Tool zur Überprüfung von Versionen, das GitHub und Packagist verwendet","pt":"O release-check é uma ferramenta de verificação de ramificações que garante a segurança e integridade do código","ru":"Release-check - это инструмент проверки веток, обеспечивающий безопасность и целостность кода с помощью ИИ Агентов","ar":"release-check هو أداة للتحقق من الفروع التي تضمن سلامة وتماسك الكود مع الأدوات الذكية"},"features":{"en":["Runs composer lint:all to check PHPCS, EditorConfig, and markdownlint","Executes composer test to ensure all tests pass","Builds PHAR using composer build","Performs smoke test on PHAR using builds/branch-usage-checker --version","Checks git status to ensure a clean working tree"],"zh":["自动化检查 GitHub 分支和 Packagist 下载统计","运行 composer lint、测试和构建命令验证分支安全性","支持 PHPCS、EditorConfig 和 markdownlint 语法检查","提供详细的检查结果报告"],"ja":["GitHub ブランチと Packagist ダウンロード統計の自動チェック","composer lint、テスト、ビルドコマンドを実行してブランチの安全性を検証","PHPCS、EditorConfig、markdownlint などの構文チェックをサポート","詳細なチェック結果レポートを提供"],"ko":["GitHub 분기와 Packagist 다운로드 통계 자동 확인","composer lint, 테스트, 빌드 명령을 실행하여 분기 안전성을 검증","PHPCS, EditorConfig, markdownlint 등의 구문 검사를 지원","자세한 확인 결과 보고서 제공"],"es":["Verificación de ramas de GitHub","Análisis de estadísticas de descargas de Packagist","Ejecución de composer lint:all para verificar la sintaxis","Ejecución de composer test para verificar las pruebas","Ejecución de composer build para generar el PHAR","Verificación del estado del árbol de trabajo con git status"],"fr":["Vérification des branches GitHub","Analyse des statistiques de téléchargement de Packagist","Exécution de composer lint:all pour vérifier la syntaxe","Exécution de composer test pour vérifier les tests","Exécution de composer build pour générer le PHAR","Vérification de l''état de l''arbre de travail avec git status"],"de":["Überprüfung von GitHub-Branches","Analyse von Packagist-Download-Statistiken","Ausführung von composer lint:all zur Überprüfung der Syntax","Ausführung von composer test zur Überprüfung der Tests","Ausführung von composer build zur Erstellung des PHAR","Überprüfung des Arbeitsbaumzustands mit git status"],"pt":["Verificação de ramificações no GitHub","Verificação de estatísticas de download no Packagist","Execução de composer lint:all e composer test","Verificação da integridade do código com composer build","Smoke test com builds/branch-usage-checker","Relatório de resultados com git status"],"ru":["Проверка веток в GitHub","Проверка статистики загрузок в Packagist","Выполнение composer lint:all и composer test","Проверка целостности кода с composer build","Тестирование builds/branch-usage-checker","Отчет о результатах с git status с помощью ИИ Агентов"],"ar":["التحقق من الفروع على GitHub","التحقق من إحصائيات التحميل على Packagist","تنفيذ composer lint:all و composer test","التحقق من صحة الكود مع composer build","اختبار builds/branch-usage-checker","تقرير النتائج مع git status مع الأدوات الذكية"]},"keywords":{"en":["how to use release-check","release-check setup guide","pre-release verification tools","composer lint alternatives","release-check vs github branch manager","automated testing with composer test","release-check install","what is release-check","release-check tutorial"],"zh":["Release-Check","AI 工具","自动化分支安全性检查","GitHub 分支检查","Packagist 下载统计检查","composer lint","PHPCS","EditorConfig","markdownlint"],"ja":["Release-Check","AI エージェント","ブランチの安全性自動チェック","GitHub ブランチチェック","Packagist ダウンロード統計チェック","composer lint","PHPCS","EditorConfig","markdownlint"],"ko":["Release-Check","AI 도구","자동화 분기 안전성 확인","GitHub 분기 확인","Packagist 다운로드 통계 확인","composer lint","PHPCS","EditorConfig","markdownlint"],"es":["release-check","agentes de IA","herramientas de IA","verificación de versiones","GitHub","Packagist","composer","PHAR","git status"],"fr":["release-check","outils d''IA","agents d''IA","vérification de versions","GitHub","Packagist","composer","PHAR","git status"],"de":["release-check","KI-Agents","KI-Tools","Überprüfung von Versionen","GitHub","Packagist","composer","PHAR","git status"],"pt":["release-check","verificação de ramificações","GitHub","Packagist","composer lint:all","composer test","composer build","builds/branch-usage-checker","git status"],"ru":["release-check","проверка веток","GitHub","Packagist","composer lint:all","composer test","composer build","builds/branch-usage-checker","git status","ИИ Агенты"],"ar":["release-check","التحقق من الفروع","GitHub","Packagist","composer lint:all","composer test","composer build","builds/branch-usage-checker","git status","الأدوات الذكية"]}},"owner":"ivuorinen","repo":"branch-usage-checker","repoPath":"ivuorinen/branch-usage-checker","stars":0,"forks":0,"updatedAt":"2026-03-02T01:06:07Z","topics":[],"category":"community","skillMd":{"name":"release-check","description":"Run full pre-release verification suite","bodyPreview":"# Pre-Release Verification\n\nRun the complete verification suite before a release.\n\n## Steps\n\n1. Run `composer lint:all` — all linters must pass (PHPCS, EditorConfig, markdownlint)\n2. Run `composer test` — all tests must pass\n3. Run `composer build` — PHAR must build successfully\n4. Run `builds/branch-usage-checker --version` — smoke test the PHAR\n5. Run `git status` — working tree should be clean (no uncommitted changes)\n6. Report go/no-go summary with results of each step","body":"# Pre-Release Verification\n\nRun the complete verification suite before a release.\n\n## Steps\n\n1. Run `composer lint:all` — all linters must pass (PHPCS, EditorConfig, markdownlint)\n2. Run `composer test` — all tests must pass\n3. Run `composer build` — PHAR must build successfully\n4. Run `builds/branch-usage-checker --version` — smoke test the PHAR\n5. Run `git status` — working tree should be clean (no uncommitted changes)\n6. Report go/no-go summary with results of each step\n"},"lastSynced":"2026-03-07T03:52:16.261Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated pre-release verification and GitHub branch management.","zh":"非常适合需要自动化预发布验证和 GitHub 分支管理的开发代理。","ja":"開発エージェントが自動化されたプレリリースの検証と GitHub ブランチの管理を必要とする場合に最適です。","ko":"자동화된 프리 릴리스 검증 및 GitHub 브랜치 관리가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan verificación automática de pre-lanzamiento y administración de ramas de GitHub.","fr":"Parfait pour les agents de développement ayant besoin d''une vérification automatisée de pré-version et de gestion de branches GitHub.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Vorab-Verifizierung und GitHub-Zweigverwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de verificação automatizada pré-lançamento e gerenciamento de branches do GitHub.","ru":"Идеально для агентов разработки, которым требуется автоматизированная предрелизная верификация и управление ветками GitHub.","ar":"مثالي للوكلاء التطويين الذين يحتاجون إلى التحقق التلقائي قبل الإصدار وإدارة الفروع على GitHub."},"recommendation":{"en":"Empowers agents to automate pre-release verification using Composer commands like `composer lint:all` and `composer test`, ensuring PHPCS, EditorConfig, and markdownlint compliance, while also performing smoke tests on PHAR builds and checking Git working tree status.","zh":"赋予代理自动化预发布验证的能力，使用 Composer 命令如 `composer lint:all` 和 `composer test`，确保 PHPCS、EditorConfig 和 markdownlint 的兼容性，同时对 PHAR 构建进行烟雾测试，并检查 Git 工作树状态。","ja":"エージェントにプレリリースの検証を自動化する能力を与え、`composer lint:all` や `composer test` のような Composer コマンドを使用し、PHPCS、EditorConfig、markdownlint の準拠を保証し、同時に PHAR ビルドに対するスモークテストを実行し、Git のワーキングツリーの状態を確認します。","ko":"에이전트에게 자동화된 프리 릴리스 검증 능력을 부여하여 `composer lint:all` 및 `composer test`와 같은 Composer 명령을 사용하여 PHPCS, EditorConfig 및 markdownlint의 호환성을 보장하며 동시에 PHAR 빌드에 대한 스모크 테스트를 수행하고 Git 작업 트리 상태를 확인합니다.","es":"Habilita a los agentes a automatizar la verificación de pre-lanzamiento utilizando comandos de Composer como `composer lint:all` y `composer test`, garantizando el cumplimiento de PHPCS, EditorConfig y markdownlint, mientras también se realizan pruebas de humo en compilandos PHAR y se verifica el estado del árbol de trabajo de Git.","fr":"Permet aux agents d''automatiser la vérification de pré-version en utilisant des commandes Composer comme `composer lint:all` et `composer test`, en garantissant la conformité de PHPCS, EditorConfig et markdownlint, tout en effectuant des tests de fumée sur les builds PHAR et en vérifiant l''état de l''arbre de travail Git.","de":"Ermöglicht es Agenten, die Vorab-Verifizierung mithilfe von Composer-Befehlen wie `composer lint:all` und `composer test` zu automatisieren, wodurch PHPCS-, EditorConfig- und markdownlint-Konformität sichergestellt wird, während auch Rauchtests auf PHAR-Builds durchgeführt und der Status des Git-Arbeitsverzeichnisses überprüft werden.","pt":"Habilita os agentes a automatizar a verificação pré-lançamento usando comandos do Composer, como `composer lint:all` e `composer test`, garantindo a conformidade com PHPCS, EditorConfig e markdownlint, além de realizar testes de fumaça em compilações PHAR e verificar o status da árvore de trabalho do Git.","ru":"Наделяет агентов возможностью автоматизировать предрелизную верификацию с помощью команд Composer, таких как `composer lint:all` и `composer test`, обеспечивая соответствие PHPCS, EditorConfig и markdownlint, а также выполняя тесты дымности для сборок PHAR и проверяя состояние рабочего дерева Git.","ar":"يتمكّن الوكلاء من تutomatisation التحقق قبل الإصدار باستخدام أوامر Composer مثل `composer lint:all` و `composer test`، مما يضمن امتثال PHPCS و EditorConfig و markdownlint، بالإضافة إلى إجراء اختبارات الدخان على بناء PHAR وตรวจ حالة شجرة العمل في Git."},"useCases":{"en":["Automating pre-release checks for GitHub branches","Verifying Composer package builds and dependencies","Validating PHAR builds through smoke testing"],"zh":["自动化 GitHub 分支的预发布检查","验证 Composer 包构建和依赖项","通过烟雾测试验证 PHAR 构建"],"ja":["GitHub ブランチのプレリリースチェックを自動化する","Composer パッケージビルドと依存関係を検証する","スモークテストによって PHAR ビルドを検証する"],"ko":["GitHub 브랜치의 프리 릴리스 검증 자동화","Composer 패키지 빌드 및 종속성 검증","스모크 테스트를 통해 PHAR 빌드 검증"],"es":["Automatización de controles de pre-lanzamiento para ramas de GitHub","Verificación de compilandos de paquetes de Composer y dependencias","Validación de compilandos PHAR a través de pruebas de humo"],"fr":["Automation des vérifications de pré-version pour les branches GitHub","Vérification des builds de packages Composer et des dépendances","Validation des builds PHAR via des tests de fumée"],"de":["Automatisierung von Vorab-Prüfungen für GitHub-Zweige","Überprüfung von Composer-Paketcompilanden und -abhängigkeiten","Validierung von PHAR-Compilanden durch Rauchtests"],"pt":["Automatizar verificações pré-lançamento para branches do GitHub","Verificar compilações e dependências de pacotes do Composer","Validar compilações PHAR por meio de testes de fumaça"],"ru":["Автоматизация предрелизных проверок для веток GitHub","Проверка сборок и зависимостей пакетов Composer","Валидация сборок PHAR с помощью тестов дымности"],"ar":["التحكم التلقائي في عمليات التحقق قبل الإصدار للفروع على GitHub","تحقق من بناء الحزم وتعريفات Composer","التحقق من بناء PHAR من خلال اختبارات الدخان"]},"limitations":{"en":["Requires Composer installation","Limited to GitHub branches and Packagist statistics","Needs Git and Composer command-line access"],"zh":["需要 Composer 安装","仅限 GitHub 分支和 Packagist 统计","需要 Git 和 Composer 命令行访问"],"ja":["Composer のインストールが必要","GitHub ブランチと Packagist 統計のみに限定","Git と Composer のコマンドラインアクセスが必要"],"ko":["Composer 설치가 필요함","GitHub 브랜치 및 Packagist 통계에만 국한됨","Git 및 Composer 명령줄 액세스가 필요함"],"es":["Requiere instalación de Composer","Limitado a ramas de GitHub y estadísticas de Packagist","Necesita acceso a la línea de comandos de Git y Composer"],"fr":["Nécessite l''installation de Composer","Limité aux branches GitHub et aux statistiques Packagist","Nécessite un accès à la ligne de commande Git et Composer"],"de":["Benötigt Composer-Installation","Begrenzt auf GitHub-Zweige und Packagist-Statistiken","Benötigt Zugriff auf die Git- und Composer-Kommandozeile"],"pt":["Requer instalação do Composer","Limitado a branches do GitHub e estatísticas do Packagist","Necessita acesso à linha de comando do Git e do Composer"],"ru":["Требуется установка Composer","Ограничен ветками GitHub и статистикой Packagist","Требуется доступ к командной строке Git и Composer"],"ar":["يتطلب تثبيت Composer","محدود بالفروع على GitHub وإحصائيات Packagist","يحتاج إلى وصول إلى سطر أوامر Git و Composer"]},"version":4},"contentHash":"d9727706f3a977d397304473e89e8794a345ee0b1b9d8389fa6bd97aa22943af","qualityScore":20}');
