INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ivuorinen/branch-usage-checker/release-check', 'release-check', 'ivuorinen', 'branch-usage-checker', 'community', 'release-check ivuorinen branch-usage-checker community The release-check skill cross-checks GitHub branches and Packagist statistics to determine if branches are safe to delete, benefiting developers with automated pre-release verification. Release-Check 是一个自动化工具，用于检查 GitHub 分支和 Packagist 下载统计，以确定分支是否安全删除。它通过运行一系列命令，包括 composer lint、测试和构建，来验证分支的安全性 Release-Check は、GitHub ブランチと Packagist ダウンロード統計をチェックしてブランチの安全性を確認する自動化ツールです。composer lint、テスト、ビルドなどのコマンドを実行してブランチの安全性を検証します Release-Check는 GitHub 분기와 Packagist 다운로드 통계를 확인하여 분기 안전성을 확인하는 자동화 도구입니다. composer lint, 테스트, 빌드 등의 명령을 실행하여 분기 안전성을 검증 Release-check es una herramienta que verifica la seguridad de las ramas de GitHub y las estadísticas de descargas de Packagist antes de una versión Release-check est un outil qui vérifie la sécurité des branches GitHub et les statistiques de téléchargement de Packagist avant une version Release-check ist ein Tool, das die Sicherheit von GitHub-Branches und Packagist-Download-Statistiken vor einer Version überprüft O release-check é uma ferramenta que verifica a segurança das ramificações no GitHub e Packagist, garantindo a integridade do seu projeto. Ele executa uma série de testes, incluindo composer lint:all e composer test. Release-check - это инструмент, проверяющий безопасность веток в GitHub и Packagist, обеспечивая целостность вашего проекта. Он выполняет ряд тестов, включая composer lint:all и composer test, с помощью ИИ Агентов. release-check هو أداة للتحقق من سلامة الفروع على GitHub و Packagist، وضمان سلامة مشروعك. يقوم بتنفيذ سلسلة من الاختبارات، بما في ذلك composer lint:all و composer test، مع الأدوات الذكية. how to use release-check release-check setup guide pre-release verification tools composer lint alternatives release-check vs github branch manager automated testing with composer test release-check install what is release-check release-check tutorial Release-Check AI 工具 自动化分支安全性检查 GitHub 分支检查 Packagist 下载统计检查 composer lint PHPCS EditorConfig markdownlint Runs composer lint:all to check PHPCS, EditorConfig, and markdownlint Executes composer test to ensure all tests pass Builds PHAR using composer build Performs smoke test on PHAR using builds/branch-usage-checker --version Checks git status to ensure a clean working tree release-check is a skill that automates pre-release verification by running a suite of checks, including composer lint, tests, and build processes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('freelawproject/wiki/shipit', 'community', 'freelawproject', 'wiki', 'freelawproject/wiki', 'shipit', 0, 0, 20, '2026-03-06T15:34:16Z', '2026-03-07T03:54:29.426Z', '3a358ca56a7083f2e60b99782a43d4d81ff4e5558b442f56b9fade13680987d9', '{"id":"freelawproject/wiki/shipit","name":"shipit","description":{"en":"shipit is a vibe-coded wiki for FLP staff that facilitates openness while allowing private and restricted pages. It automates Git workflows for efficient code management.","zh":"Shipit 是一个为 FLP 员工提供的 vibe-coded wiki，旨在代码提交和审查的开放性和安全性之间取得平衡","ja":"Shipit は、FLP 職員向けの vibe-coded wiki で、コードのオープン性とセキュリティのバランスを取ることを目的としています","ko":"Shipit은 FLP 직원들을 위한 vibe-coded wiki로, 코드의 개방성과 보안성을 균형 있게 유지하는 것을 목표로 합니다","es":"Shipit es una herramienta de colaboración que permite a los desarrolladores trabajar en proyectos de manera eficiente, utilizando Git y Github para gestionar el código","fr":"Shipit est un outil de collaboration qui permet aux développeurs de travailler sur des projets de manière efficace, en utilisant Git et Github pour gérer le code","de":"Shipit ist ein Kollaborationstool, das es Entwicklern ermöglicht, an Projekten effizient zu arbeiten, indem es Git und Github zur Codeverwaltung nutzt","pt":"O Shipit é uma wiki de código aberto para uso interno, projetada para promover a abertura, mas permitir páginas e diretórios privados e restritos","ru":"Shipit - это вики с открытым кодом для внутреннего использования, предназначенная для содействия открытости, но позволяет создавать приватные и ограниченные страницы и директории","ar":"Shipit هو ويكي مفتوح المصدر للاستخدام الداخلي، مصمم لتعزيز الانفتاح، لكن يسمح بإنشاء صفحات ومجلدات خاصة ومقيدة"},"seo":{"title":{"en":"shipit: Git Workflow Automation for AI Agents | AI Agent ...","zh":"Shipit 文档指南：代码提交和审查最佳实践","ja":"Shipit セットアップガイド：コードレビューとコミットのベストプラクティス","ko":"Shipit 설정 가이드: 코드 리뷰 및 커밋 베스트 프랙티스","es":"Guía de Configuración de Shipit: Implementación de Flujos...","fr":"Shipit: Guide de Mise en Place pour les Développeurs d''Ou...","de":"Shipit Einrichtungsleitfaden: Entwicklung von Arbeitsablä...","pt":"Guia de Configuração do Shipit: Wiki de Código Aberto","ru":" Shipit: Настройка Вики с Открытым Кодом для ИИ Агентов","ar":"دليل إعداد Shipit: ويكي مفتوح المصدر للوكلاء الذكاء الاصط..."},"description":{"en":"Streamline your development process with shipit''s Git workflow automation. Learn how to setup and use shipit for efficient code management and collaboration.","zh":"了解 Shipit 的代码提交和审查流程，包括分支管理和 Pull Request 的最佳实践","ja":"Shipit のコードレビューとコミットの流れについて学び、分岐管理と Pull Request のベストプラクティスをマスターしてください","ko":"Shipit의 코드 리뷰 및 커밋 프로세스를 알아보고 분기 관리 및 Pull Request의 베스트 프랙티스를 마스터하세요","es":"Aprende a configurar Shipit para mejorar tus flujos de trabajo de desarrollo con Git y Github, incluyendo ramas y solicitudes de extracción","fr":"Découvrez comment mettre en place Shipit pour améliorer vos flux de travail de développement avec Git et Github, y compris les branches et les demandes d''ext...","de":"Erfahren Sie, wie Sie Shipit einrichten, um Ihre Entwicklungsarbeitsabläufe mit Git und Github zu verbessern, einschließlich Branches und Pull-Requests","pt":"Aprenda a configurar o Shipit, uma wiki de código aberto para uso interno, com recursos de privacidade e restrição de páginas","ru":"Узнайте, как настроить Shipit, вики с открытым кодом для внутреннего использования, с функциями приватности и ограничения доступа","ar":"تعرف على كيفية إعداد Shipit، ويكي مفتوح المصدر للاستخدام الداخلي، مع ميزات الخصوصية وتقييد الصفحات"},"definition":{"en":"shipit is a Git workflow automation tool that enables developers to manage code commits and branches efficiently.","zh":"Shipit 是一个基于 Git 的代码管理工具，提供分支管理和 Pull Request 功能","ja":"Shipit は、Git ベースのコード管理ツールで、ブランチ管理と Pull Request 機能を提供します","ko":"Shipit은 Git 기반의 코드 관리 도구로, 분기 관리 및 Pull Request 기능을 제공합니다","es":"Shipit es una herramienta de desarrollo que facilita la colaboración y el seguimiento de cambios en el código","fr":"Shipit est un outil de développement qui facilite la collaboration et le suivi des modifications de code","de":"Shipit ist ein Entwicklungstool, das die Zusammenarbeit und die Verfolgung von Codeänderungen erleichtert","pt":"O que é Shipit? Uma wiki de código aberto para uso interno, com recursos de privacidade e restrição de páginas","ru":"Что такое Shipit? Вики с открытым кодом для внутреннего использования, с функциями приватности и ограничения доступа","ar":"ما هو Shipit؟ ويكي مفتوح المصدر للاستخدام الداخلي، مع ميزات الخصوصية وتقييد الصفحات"},"features":{"en":["Creates branches using the format $ISSUE_NUMBER-this-describes-the-issue-$ISO-8601-DATE-WITHOUT-DASHES","Commits work to branches in small logical commits","Pushes branches to remote repositories","Creates draft PRs using the Github Template","Pulls the latest code from the main branch","Supports ISO-8601 date formatting without dashes"],"zh":["基于 Git 的分支管理","Pull Request 功能","代码提交和审查的最佳实践","ISO 8601 日期格式支持","Github Template 集成"],"ja":["Git ベースのブランチ管理","Pull Request 機能","コードのコミットとレビューのベストプラクティス","ISO 8601 日付形式のサポート","Github Template の統合"],"ko":["Git 기반의 분기 관리","Pull Request 기능","코드 커밋 및 리뷰의 베스트 프랙티스","ISO 8601 날짜 형식 지원","Github Template 통합"],"es":["Creación de ramas con formato de nombre personalizable","Commit de cambios en pequeños pasos lógicos","Uso de Github para la gestión de solicitudes de extracción","Integración con Git para el control de versiones","Soporte para fechas en formato ISO 8601 sin guiones"],"fr":["Création de branches avec un format de nom personnalisable","Commit de modifications en petites étapes logiques","Utilisation de Github pour la gestion des demandes d''extraction","Intégration avec Git pour le contrôle de version","Prise en charge des dates au format ISO 8601 sans traits d''union"],"de":["Erstellung von Branches mit anpassbarem Namensformat","Commit von Änderungen in kleinen logischen Schritten","Verwendung von Github für die Verwaltung von Pull-Requests","Integration mit Git für die Versionskontrolle","Unterstützung für Datumswerte im ISO-8601-Format ohne Bindestriche"],"pt":["Criação de branches com formato personalizado","Commits lógicos e pequenos","Push de branches para revisão","Criação de Pull Requests com template do Github","Suporte a privacidade e restrição de páginas","Integração com o Github"],"ru":["Создание веток с индивидуальным форматом","Логические и небольшие коммиты","Публикация веток для ревью","Создание запросов на слияние с шаблоном Github","Поддержка приватности и ограничения доступа к страницам","Интеграция с Github"],"ar":["إنشاء فروع مع تنسيق مخصص","التعهدات المنطقية والصغيرة","دفع الفروع لمراجعة","إنشاء طلبات سحب مع قالب Github","دعم الخصوصية وتقييد الوصول إلى الصفحات","التكامل مع Github"]},"keywords":{"en":["how to use shipit","shipit git workflow","shipit alternative","shipit setup guide","shipit vs gitflow","what is shipit","shipit install","shipit tutorial","shipit best practices","shipit for developers"],"zh":["Shipit","代码提交","代码审查","Git","分支管理","Pull Request","代码管理","开发工具","AIエージェント"],"ja":["Shipit","コードコミット","コードレビュー","Git","ブランチ管理","Pull Request","コード管理","開発ツール","AIエージェント"],"ko":["Shipit","코드 커밋","코드 리뷰","Git","분기 관리","Pull Request","코드 관리","개발 도구","AI 에이전트"],"es":["Shipit","desarrollo de software","colaboración de desarrollo","Git","Github","ramas","solicitudes de extracción","control de versiones","herramientas de desarrollo"],"fr":["Shipit","développement de logiciels","collaboration de développement","Git","Github","branches","demandes d''extraction","contrôle de version","outils de développement"],"de":["Shipit","Software-Entwicklung","Entwickler-Kollaboration","Git","Github","Branches","Pull-Requests","Versionskontrolle","Entwicklungstools"],"pt":["wiki de código aberto","privacidade de páginas","restrição de acesso","github","branches","commits","pull requests"," Shipit","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["вики с открытым кодом","приватность страниц","ограничение доступа","github","ветки","коммиты","запросы на слияние","Shipit","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["ويكي مفتوح المصدر","الخصوصية صفحة","تقييد الوصول","github","فروع","التعهدات","طلبات سحب","Shipit","تطوير البرمجيات","أدوات التطوير","الوكلاء الذكاء الاصطناعي"]}},"owner":"freelawproject","repo":"wiki","repoPath":"freelawproject/wiki","stars":0,"forks":0,"updatedAt":"2026-03-06T15:34:16Z","topics":[],"category":"community","skillMd":{"name":"shipit","description":"Branch, commit the code, push it, and make a PR","bodyPreview":"When the code is done and is not building on existing commits:\n\n1. Pull the latest from main.\n2. Make a branch using the format $ISSUE_NUMBER-this-describes-the-issue-$ISO-8601-DATE-WITHOUT-DASHES. E.g.: 123-fix-typo-2026-10-17\n3. Commit the work to the branch in small logical commits.\n4. Push the branch\n5. Make a draft PR using the Github Template","body":"When the code is done and is not building on existing commits:\n\n1. Pull the latest from main.\n2. Make a branch using the format $ISSUE_NUMBER-this-describes-the-issue-$ISO-8601-DATE-WITHOUT-DASHES. E.g.: 123-fix-typo-2026-10-17\n3. Commit the work to the branch in small logical commits.\n4. Push the branch\n5. Make a draft PR using the Github Template\n"},"lastSynced":"2026-03-07T03:54:29.426Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined Git workflow automation and private wiki management.","zh":"非常适合需要简化 Git 工作流自动化和私人 wiki 管理的开发代理。","ja":"開発エージェントが Git ワークフロー自動化とプライベート Wiki 管理をストリームライン化する必要がある場合に最適です。","ko":"개발 에이전트가 Git 워크플로 자동화와 개인 위키 관리를 간소화해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una automatización de flujo de trabajo de Git optimizada y una gestión de wiki privada.","fr":"Parfait pour les agents de développement ayant besoin d''une automatisation de workflow Git optimisée et d''une gestion de wiki privée.","de":"Perfekt für Entwicklungsmittel, die eine optimierte Git-Workflow-Automatisierung und eine private Wiki-Verwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de automação de fluxo de trabalho Git simplificado e gerenciamento de wiki privado.","ru":"Идеально для агентов разработки, требующих упрощенной автоматизации рабочего процесса Git и управления частной вики.","ar":"مثالي للوكلاء النموزجيون الذين بحاجة إلى تيسير عملية عمل جيت وتحكم في ويكي خاصة."},"recommendation":{"en":"Empowers agents to automate Git workflows using ISO-8601 dated branch formatting, while facilitating openness and restricted page access through vibe-coded wikis, utilizing Github Templates for draft PRs and efficient code commits.","zh":"赋予代理人使用 ISO-8601 日期格式的分支自动化 Git 工作流的能力，同时通过 vibe 编码的 wiki 实现开放性和受限的页面访问，利用 Github 模板进行草稿 PR 和高效的代码提交。","ja":"エージェントが ISO-8601 日付形式のブランチ自動化を使用して Git ワークフローを自動化できるようにし、vibe コーディングされた wiki を使用してオープン性と制限付きのページ アクセスを促進し、Github テンプレートを使用してドラフト PR と効率的なコード コミットを行う。","ko":"에이전트가 ISO-8601 날짜 형식의 분기 자동화를 사용하여 Git 워크플로를 자동화할 수 있도록 하며, vibe 코드화된 위키를 사용하여 개방성과 제한된 페이지 액세스를促進하며, Github 템플릿을 사용하여 초안 PR 및 효율적인 코드 커밋을 수행할 수 있습니다.","es":"Habilita a los agentes a automatizar flujos de trabajo de Git utilizando formato de rama con fechas ISO-8601, mientras facilita la apertura y el acceso restringido a páginas a través de wikis codificados por vibración, utilizando plantillas de Github para borradores de PR y commits de código eficientes.","fr":"Permet aux agents d''automatiser les flux de travail Git en utilisant un format de branche avec des dates ISO-8601, tout en facilitant l''ouverture et l''accès restreint aux pages via des wikis codés par vibration, en utilisant des modèles Github pour des brouillons de PR et des commits de code efficaces.","de":"Ermächtigt Agenten, Git-Workflows mithilfe von ISO-8601-datiertem Branch-Formatting zu automatisieren, während es die Offenheit und den eingeschränkten Zugriff auf Seiten über vibe-codierte Wikis ermöglicht, indem es Github-Vorlagen für Entwurfs-PRs und effiziente Code-Commits nutzt.","pt":"Habilita os agentes a automatizar fluxos de trabalho Git usando formatação de branch com data ISO-8601, ao mesmo tempo em que facilita a abertura e o acesso restrito a páginas por meio de wikis codificados por vibração, utilizando Github Templates para rascunhos de PRs e commits de código eficientes.","ru":"Наделяет агентов возможностью автоматизировать рабочие процессы Git с использованием форматирования веток по дате ISO-8601, одновременно обеспечивая открытость и ограниченный доступ к страницам через вики, закодированные по вибрациям, с использованием Github Templates для черновиков PR и эффективных коммитов кода.","ar":"تمكّن الوكلاء من توفير автоматизации سير عمل جيت باستخدام تنسيق فرع بتarih ISO-8601، في الوقت نفسه تسهيل الانفتاح والوصول المقيد إلى الصفحات من خلال ويكي مشفّر بالاهتزازات، باستخدام قوالب Github لنصوص طلبات السحب و الالتزامات الكودية الفعالة."},"useCases":{"en":["Automating Git branch creation with descriptive naming conventions","Generating draft PRs using Github Templates","Restricting access to sensitive wiki pages"],"zh":["使用描述性命名约定自动创建 Git 分支","使用 Github 模板生成草稿 PR","限制对敏感 wiki 页面的访问"],"ja":["記述的な命名規則を使用して Git ブランチを作成する自動化","Github テンプレートを使用してドラフト PR を生成する","機密の wiki ページへのアクセスを制限する"],"ko":["설명적인命名 규칙을 사용하여 Git 브랜치를 자동으로 생성하는 것","Github 템플릿을 사용하여 초안 PR을 생성하는 것","민감한 위키 페이지에 대한 액세스를 제한하는 것"],"es":["Automatización de la creación de ramas de Git con convenciones de nomenclatura descriptiva","Generación de borradores de PR utilizando plantillas de Github","Restricción del acceso a páginas de wiki sensibles"],"fr":["Automatisation de la création de branches Git avec des conventions de nommage descriptives","Génération de brouillons de PR en utilisant des modèles Github","Restriction de l''accès aux pages de wiki sensibles"],"de":["Automatisierung der Erstellung von Git-Branches mit beschreibenden Benennungskonventionen","Erzeugung von Entwurfs-PRs unter Verwendung von Github-Vorlagen","Einschränkung des Zugriffs auf sensible Wiki-Seiten"],"pt":["Automatizar a criação de branch Git com convenções de nomenclatura descritiva","Gerar rascunhos de PRs usando Github Templates","Restringir o acesso a páginas de wiki sensíveis"],"ru":["Автоматизировать создание веток Git с описательными соглашениями об именах","Генерировать черновики PR с использованием Github Templates","Ограничивать доступ к чувствительным страницам вики"],"ar":["توفير إنشاء فرع جيت آلي مع اتفاقيات命名 وصفية","إنشاء مسودات طلبات السحب باستخدام قوالب Github","الحصر الوصول إلى صفحات ويكي حساسة"]},"limitations":{"en":["Requires Github access","Limited to Git workflow automation","Dependent on ISO-8601 date formatting"],"zh":["需要 Github 访问","仅限 Git 工作流自动化","依赖于 ISO-8601 日期格式"],"ja":["Github アクセスが必要","Git ワークフロー自動化のみ","ISO-8601 日付形式に依存"],"ko":["Github 액세스가 필요","Git 워크플로 자동화에만 국한됨","ISO-8601 날짜 형식에 의존"],"es":["Requiere acceso a Github","Limitado a la automatización del flujo de trabajo de Git","Dependiente del formato de fecha ISO-8601"],"fr":["Nécessite un accès à Github","Limité à l''automatisation du flux de travail Git","Dépendant du format de date ISO-8601"],"de":["Benötigt Zugriff auf Github","Begrenzt auf die Automatisierung des Git-Workflows","Abhängig vom ISO-8601-Datumsformat"],"pt":["Requer acesso ao Github","Limitado à automação de fluxo de trabalho Git","Dependente do formatação de data ISO-8601"],"ru":["Требует доступа к Github","Ограничен автоматизацией рабочего процесса Git","Зависит от форматирования даты ISO-8601"],"ar":["يتطلب الوصول إلى Github","محدود بالتوفير سير عمل جيت","يعتمد على تنسيق تاريخ ISO-8601"]},"version":4},"contentHash":"3a358ca56a7083f2e60b99782a43d4d81ff4e5558b442f56b9fade13680987d9","qualityScore":20}');
