INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('freelawproject/wiki/shipit', 'shipit', 'freelawproject', 'wiki', 'community', 'shipit freelawproject wiki community shipit is a vibe-coded wiki for FLP staff that facilitates openness while allowing private and restricted pages. It automates Git workflows for efficient code management. Shipit 是一个为 FLP 员工提供的 vibe-coded wiki，旨在代码提交和审查的开放性和安全性之间取得平衡 Shipit は、FLP 職員向けの vibe-coded wiki で、コードのオープン性とセキュリティのバランスを取ることを目的としています Shipit은 FLP 직원들을 위한 vibe-coded wiki로, 코드의 개방성과 보안성을 균형 있게 유지하는 것을 목표로 합니다 Shipit es una herramienta de colaboración que permite a los desarrolladores trabajar en proyectos de manera eficiente, utilizando Git y Github para gestionar el código Shipit est un outil de collaboration qui permet aux développeurs de travailler sur des projets de manière efficace, en utilisant Git et Github pour gérer le code Shipit ist ein Kollaborationstool, das es Entwicklern ermöglicht, an Projekten effizient zu arbeiten, indem es Git und Github zur Codeverwaltung nutzt O Shipit é uma wiki de código aberto para uso interno, projetada para promover a abertura, mas permitir páginas e diretórios privados e restritos Shipit - это вики с открытым кодом для внутреннего использования, предназначенная для содействия открытости, но позволяет создавать приватные и ограниченные страницы и директории Shipit هو ويكي مفتوح المصدر للاستخدام الداخلي، مصمم لتعزيز الانفتاح، لكن يسمح بإنشاء صفحات ومجلدات خاصة ومقيدة how to use shipit shipit git workflow shipit alternative shipit setup guide shipit vs gitflow what is shipit shipit install shipit tutorial shipit best practices shipit for developers Shipit 代码提交 代码审查 Git 分支管理 Pull Request 代码管理 开发工具 AIエージェント Creates branches using the format $ISSUE_NUMBER-this-describes-the-issue-$ISO-8601-DATE-WITHOUT-DASHES Commits work to branches in small logical commits Pushes branches to remote repositories Creates draft PRs using the Github Template Pulls the latest code from the main branch Supports ISO-8601 date formatting without dashes shipit is a Git workflow automation tool that enables developers to manage code commits and branches efficiently.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KarubiOhayo/Dev-Agent-Orchestrator/round-main-control', 'community', 'KarubiOhayo', 'Dev-Agent-Orchestrator', 'KarubiOhayo/Dev-Agent-Orchestrator', 'round-main-control', 0, 0, 20, '2026-02-26T08:10:38Z', '2026-03-07T03:59:46.170Z', '1d296284e910524b8235ad31e7c77abe8eedc59a1e02504863b254a1171059fd', '{"id":"KarubiOhayo/Dev-Agent-Orchestrator/round-main-control","name":"round-main-control","description":{"en":"The round-main-control skill ensures main thread judgment quality and checks for inconsistencies across tasks. It benefits developers by automating handoff and relay creation for each round.","zh":"round-main-control 是一种用于优化主线程判定质量和一致性的技术，通过检查 result、review、relay、TASK_BOARD、PROJECT_OVERVIEW 和 CURRENT_STATUS 等文件","ja":"round-main-control は、メインスレッドの判定品質と一致性を最適化する技術で、result、review、relay、TASK_BOARD、PROJECT_OVERVIEW、CURRENT_STATUS などのファイルをチェックします","ko":"round-main-control는 메인 스레드의 판단 품질과 일관성을 최적화하는 기술로, result, review, relay, TASK_BOARD, PROJECT_OVERVIEW, CURRENT_STATUS 등의 파일을 점검합니다","es":"Round-main-control es una habilidad que gestiona la calidad de la toma de decisiones en el hilo principal y verifica la coherencia entre documentos como result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS.","fr":"Round-main-control est une compétence qui gère la qualité de la prise de décision dans le thread principal et vérifie la cohérence entre les documents tels que result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS.","de":"Round-main-control ist eine Fähigkeit, die die Qualität der Entscheidungsfindung im Hauptthread verwaltet und die Konsistenz zwischen Dokumenten wie result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS überprüft.","pt":"O round-main-control é uma habilidade que garante a consistência entre result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS em cada rodada.","ru":"Round-main-control — это навык, обеспечивающий согласованность между result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS на каждом раунде.","ar":"round-main-control هو مهارة تضمن الاتساق بين result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS في كل جولة."},"seo":{"title":{"en":"round-main-control: Round Management Setup Guide | AI Age...","zh":"round-main-control 设置指南：主线程质量控制","ja":"round-main-control のベストプラクティス：メインスレッドの品質管理","ko":"round-main-control 설정 가이드: 메인 스레드 판단 품질 고정","es":"Guía de configuración de round-main-control para la gesti...","fr":"Guide de mise en place de round-main-control pour la gest...","de":"Einrichtungsleitfaden für round-main-control zur Aufgaben...","pt":"Guia de Configuração round-main-control para Controle de ...","ru":"Настройка round-main-control для контроля основных потоков","ar":"دليل إعداد round-main-control للتحكم في الخيوط الرئيسية"},"description":{"en":"Discover how round-main-control ensures consistency across result, review, and relay tasks. Learn to set up and utilize this AI agent skill for streamlined r...","zh":"了解 round-main-control 的技术细节和设置方法，优化主线程的判定质量和一致性","ja":"round-main-control の技術的詳細と設定方法を学び、メインスレッドの判定品質と一致性を最適化する","ko":"round-main-control의 기술적 세부 사항과 설정 방법을 알아보고 메인 스레드의 판단 품질과 일관성을 최적화 하세요","es":"Aprende a configurar round-main-control para mejorar la gestión de tareas y la coordinación en tus proyectos con documentos como PROJECT_OVERVIEW.md y TASK_B...","fr":"Découvrez comment configurer round-main-control pour améliorer la gestion de tâches et la coordination dans vos projets avec des documents tels que PROJECT_O...","de":"Erfahren Sie, wie Sie round-main-control einrichten, um die Aufgabenverwaltung und die Koordination in Ihren Projekten mit Dokumenten wie PROJECT_OVERVIEW.md...","pt":"Aprenda a configurar o round-main-control para garantir a consistência entre result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS","ru":"Узнайте, как настроить round-main-control для обеспечения согласованности между result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS","ar":"تعرف على كيفية إعداد round-main-control لضمان الاتساق بين result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS"},"definition":{"en":"round-main-control is a skill that maintains main thread judgment quality and ensures consistency across result, review, relay, and task board data.","zh":"round-main-control 是一种 AI 工具，用于优化主线程的判定质量和一致性","ja":"round-main-control は、メインスレッドの判定品質と一致性を最適化する AI エージェントです","ko":"round-main-control는 메인 스레드의 판단 품질과 일관성을 최적화하는 AI 에이전트입니다","es":"Round-main-control es una herramienta de gestión de tareas que verifica la coherencia entre documentos y genera un handoff para la próxima ronda.","fr":"Round-main-control est un outil de gestion de tâches qui vérifie la cohérence entre les documents et génère un handoff pour le prochain tour.","de":"Round-main-control ist ein Aufgabenverwaltungstool, das die Konsistenz zwischen Dokumenten überprüft und einen Handoff für die nächste Runde generiert.","pt":"O que é round-main-control? É uma habilidade que controla a qualidade da thread principal em cada rodada.","ru":"Что такое round-main-control? Это навык, контролирующий качество основного потока на каждом раунде.","ar":"ما هو round-main-control؟ هو مهارة تتحكم في جودة الخيط الرئيسي في كل جولة."},"features":{"en":["Checks for inconsistencies across result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS","Creates handoff and Main->Executor relay for each round","Utilizes Markdown files such as PROJECT_OVERVIEW.md, TASK_BOARD.md, and CURRENT_STATUS_*.md","Processes coordination reports including H-00N-result.md and H-00N-review.md","Manages relays via coordination/RELAYS/H-00N-review-to-main"],"zh":["优化主线程的判定质量","检查 result、review、relay、TASK_BOARD、PROJECT_OVERVIEW 和 CURRENT_STATUS 等文件","确保一致性和准确性","支持多种文件格式","易于集成和使用"],"ja":["メインスレッドの判定品質を最適化","result、review、relay、TASK_BOARD、PROJECT_OVERVIEW、CURRENT_STATUS などのファイルをチェック","一致性と精度を確保","多種のファイル形式をサポート","簡単に統合と使用が可能"],"ko":["메인 스레드의 판단 품질을 최적화","result, review, relay, TASK_BOARD, PROJECT_OVERVIEW, CURRENT_STATUS 등의 파일을 점검","일관성과 정확성을 보장","다양한 파일 형식을 지원","쉽게 통합과 사용이 가능"],"es":["Verificación de la coherencia entre documentos como PROJECT_OVERVIEW.md y TASK_BOARD.md","Generación de un handoff para la próxima ronda","Soporte para documentos como result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS","Integración con herramientas de gestión de tareas","Compatibilidad con Markdown y otros formatos de documento","Automatización de la gestión de tareas y la coordinación"],"fr":["Vérification de la cohérence entre les documents tels que PROJECT_OVERVIEW.md et TASK_BOARD.md","Génération d''un handoff pour le prochain tour","Prise en charge des documents tels que result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS","Intégration avec des outils de gestion de tâches","Compatibilité avec Markdown et d''autres formats de document","Automatisation de la gestion de tâches et de la coordination"],"de":["Überprüfung der Konsistenz zwischen Dokumenten wie PROJECT_OVERVIEW.md und TASK_BOARD.md","Generierung eines Handoffs für die nächste Runde","Unterstützung für Dokumente wie result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS","Integration mit Aufgabenverwaltungstools","Kompatibilität mit Markdown und anderen Dokumentenformaten","Automatisierung der Aufgabenverwaltung und der Koordination"],"pt":["Verificação de consistência entre result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS","Criação de handoff e relay entre Main e Executor","Suporte a documentos como PROJECT_OVERVIEW.md e TASK_BOARD.md","Verificação de relatórios como CURRENT_STATUS_*.md e H-00N-result.md","Integração com coordenador de tarefas e relatórios"],"ru":["Проверка согласованности между result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS","Создание handoff и relay между Main и Executor","Поддержка документов как PROJECT_OVERVIEW.md и TASK_BOARD.md","Проверка отчетов как CURRENT_STATUS_*.md и H-00N-result.md","Интеграция с координатором задач и отчетов"],"ar":["التحقق من الاتساق بين result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS","إنشاء handoff و relay بين Main و Executor","دعم مستندات مثل PROJECT_OVERVIEW.md و TASK_BOARD.md","التحقق من تقارير مثل CURRENT_STATUS_*.md و H-00N-result.md","التكامل مع منسق المهام والتقارير"]},"keywords":{"en":["round-main-control setup guide","what is round-main-control","round-main-control vs alternative skills","how to use round-main-control for round management","round-main-control install and configuration","round-main-control for AI agents and automation"],"zh":["round-main-control","AI 工具","主线程判定质量","一致性优化","文件检查","TASK_BOARD","PROJECT_OVERVIEW","CURRENT_STATUS"],"ja":["round-main-control","AI エージェント","メインスレッド判定品質","一致性最適化","ファイルチェック","TASK_BOARD","PROJECT_OVERVIEW","CURRENT_STATUS"],"ko":["round-main-control","AI 에이전트","메인 스레드 판단 품질","일관성 최적화","파일 점검","TASK_BOARD","PROJECT_OVERVIEW","CURRENT_STATUS"],"es":["round-main-control","gestión de tareas","coordinación de proyectos","documentos de proyecto","Markdown","herramientas de gestión de tareas","automatización de tareas","gestión de procesos","Herramientas de AI para la gestión de tareas"],"fr":["round-main-control","gestion de tâches","coordination de projets","documents de projet","Markdown","outils de gestion de tâches","automatisation de tâches","gestion de processus","Outils d''IA pour la gestion de tâches"],"de":["round-main-control","Aufgabenverwaltung","Projektcoordinierung","Projektdokumente","Markdown","Aufgabenverwaltungstools","Automatisierung von Aufgaben","Prozessverwaltung","KI-Tools für die Aufgabenverwaltung"],"pt":["round-main-control","controle de threads","consistência de dados","handoff e relay","coordenador de tarefas","relatórios de status","PROJECT_OVERVIEW.md","TASK_BOARD.md","ИИ Агенты"],"ru":["round-main-control","контроль основных потоков","согласованность данных","handoff и relay","координатор задач","отчеты о статусе","PROJECT_OVERVIEW.md","TASK_BOARD.md","ИИ Агенты"],"ar":["round-main-control","التحكم في الخيوط الرئيسية","اتساق البيانات","handoff و relay","منسق المهام","تقارير الحالة","PROJECT_OVERVIEW.md","TASK_BOARD.md","أدوات الذكاء الاصطناعي"]}},"owner":"KarubiOhayo","repo":"Dev-Agent-Orchestrator","repoPath":"KarubiOhayo/Dev-Agent-Orchestrator","stars":0,"forks":0,"updatedAt":"2026-02-26T08:10:38Z","topics":[],"category":"community","skillMd":{"name":"round-main-control","description":"트리거: Main 스레드에서 라운드 승인/보류 판단, 다음 handoff 1건 확정, Main->Executor 릴레이 생성이 필요할 때 사용. 비트리거: 코드 구현/테스트 실행이 필요한 실행 작업에는 사용하지 않는다.","bodyPreview":"# round-main-control\n\n## 목적\n- Main 스레드의 판단 품질을 고정한다.\n- result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS 간 불일치를 라운드마다 점검한다.\n- 다음 라운드 handoff와 Main->Executor 릴레이를 누락 없이 1건 생성한다.\n\n## 입력\n- 대상 라운드 번호: `H-00N`\n- 필수 문서:\n  - `docs/PROJECT_OVERVIEW.md`\n  - `coordination/TASK_BOARD.md`\n  - `coordination/DECISIONS.md`\n  - `coordination/REPORTS/CURRENT_STATUS_*.md`\n  - `coordination/REPORTS/H-00N-result.md`\n  - `coordination/REPORTS/H-00N-review.md`\n  - `coordination/RELAYS/H-00N-review-to-mai","body":"# round-main-control\n\n## 목적\n- Main 스레드의 판단 품질을 고정한다.\n- result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS 간 불일치를 라운드마다 점검한다.\n- 다음 라운드 handoff와 Main->Executor 릴레이를 누락 없이 1건 생성한다.\n\n## 입력\n- 대상 라운드 번호: `H-00N`\n- 필수 문서:\n  - `docs/PROJECT_OVERVIEW.md`\n  - `coordination/TASK_BOARD.md`\n  - `coordination/DECISIONS.md`\n  - `coordination/REPORTS/CURRENT_STATUS_*.md`\n  - `coordination/REPORTS/H-00N-result.md`\n  - `coordination/REPORTS/H-00N-review.md`\n  - `coordination/RELAYS/H-00N-review-to-main.md` (있으면 필수 반영)\n\n## 수행 절차\n1. 아래 체크리스트로 상태 불일치를 점검한다.\n   - handoff 목표와 result 실제 변경이 일치하는가?\n   - result 테스트 게이트와 review 판단이 충돌하지 않는가?\n   - TASK_BOARD 현재 우선순위와 다음 handoff 제안이 정합적인가?\n   - CURRENT_STATUS와 DECISIONS에 신규 정책 반영 누락이 없는가?\n2. 현재 라운드 판단을 `승인/보류 + 근거` 형태로 작성한다.\n   - 근거는 반드시 파일명 기준으로 남긴다.\n3. 다음 handoff를 반드시 1건 생성/고정한다.\n4. 문서 갱신 항목(`TASK_BOARD`, `DECISIONS`, `CURRENT_STATUS` 등)을 작성한다.\n5. 다음 라운드 시작용 Main->Executor 릴레이 파일을 생성한다.\n   - 경로: `coordination/RELAYS/H-00N-main-to-executor.md`\n   - 템플릿: `coordination/RELAYS/TEMPLATE-main-to-executor.md`\n6. Main 산출물 작성이 끝나면 운영 문서 변경분을 커밋/푸시한다.\n   - 커밋 범위: `coordination/`, `docs/`, `.agents/`\n   - 코드/설정 파일은 커밋 금지\n\n## 금지 사항\n- 코드 수정/코드 병합 금지\n- 구현 세부 리뷰를 Main에서 대체 수행 금지(Review 근거 중심으로 판단)\n\n## 표준 출력/파일 산출 규칙\n- 텍스트 출력은 반드시 아래 3개만 작성한다.\n  1. 현재 라운드 판단(승인/보류 + 근거 파일명)\n  2. 다음 handoff 지시문 1건(여기에 Main->Executor 릴레이 생성 경로/핵심 내용 포함)\n  3. 필요한 문서 갱신 항목\n- 파일 산출:\n  - `coordination/RELAYS/H-00N-main-to-executor.md`를 반드시 생성/갱신한다.\n"},"lastSynced":"2026-03-07T03:59:46.170Z","agentAnalysis":{"suitability":{"en":"Ideal for Workflow Automation Agents requiring precise round management and task consistency checks.","zh":"适合需要精确的轮次管理和任务一致性检查的工作流自动化代理。","ja":"ワークフロー自動化エージェントが正確なラウンド管理とタスクの整合性チェックを必要とする場合に適しています。","ko":"정확한 라운드 관리와 태스크 일관성 확인이 필요한 워크플로 자동화 에이전트에 적합합니다.","es":"Ideal para agentes de automatización de flujo de trabajo que requieren un manejo de rondas preciso y comprobaciones de consistencia de tareas.","fr":"Idéal pour les agents d''automatisation de workflow nécessitant une gestion de rondes précise et des vérifications de cohérence des tâches.","de":"Ideal für Workflow-Automatisierungsagenten, die eine präzise Rundenverwaltung und Konsistenzprüfungen von Aufgaben erfordern.","pt":"Ideal para Agentes de Automação de Fluxo de Trabalho que exigem gerenciamento de rodadas preciso e verificações de consistência de tarefas.","ru":"Идеально подходит для агентов автоматизации рабочих процессов, требующих точного управления раундами и проверок согласованности задач.","ar":"مثالي لعميل автомة سير العمل الذي يتطلب إدارة الدورات الدقيقة وفحوصات الاتساق للงาน."},"recommendation":{"en":"Empowers agents to automate handoff and relay creation for each round, ensuring main thread judgment quality and consistency across tasks like result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS using markdown files like `PROJECT_OVERVIEW.md`, `TASK_BOARD.md`, and `CURRENT_STATUS_*.md`.","zh":"赋予代理人自动化每个轮次的交接和中继创建，确保主线程判断质量和一致性，跨任务如结果/审查/中继/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS 使用 markdown 文件如 `PROJECT_OVERVIEW.md`、`TASK_BOARD.md` 和 `CURRENT_STATUS_*.md`。","ja":"各ラウンドのハンドオフとリレーの作成を自動化することで、メインスレッドの判断の品質と一貫性を確保し、結果/レビュー/リレー/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS などのタスクで markdown ファイル such as `PROJECT_OVERVIEW.md`、`TASK_BOARD.md`、`CURRENT_STATUS_*.md` を使用します。","ko":"각 라운드의 인수와 릴레이 생성을 자동화하여 메인 스레드 판단의 품질과 일관성을 보장하며 결과/검토/릴레이/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS와 같은 태스크에서 `PROJECT_OVERVIEW.md`、`TASK_BOARD.md` 및 `CURRENT_STATUS_*.md`와 같은 마크다운 파일을 사용합니다.","es":"Habilita a los agentes a automatizar la entrega y la creación de retransmisiones para cada ronda, garantizando la calidad y la consistencia del juicio del hilo principal en tareas como resultado/revisión/retransmisión/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS utilizando archivos markdown como `PROJECT_OVERVIEW.md`, `TASK_BOARD.md` y `CURRENT_STATUS_*.md`.","fr":"Permet aux agents d''automatiser la passation et la création de relais pour chaque tour, garantissant la qualité et la cohérence du jugement du thread principal sur des tâches comme résultat/examen/relais/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS en utilisant des fichiers markdown comme `PROJECT_OVERVIEW.md`, `TASK_BOARD.md` et `CURRENT_STATUS_*.md`.","de":"Ermöglicht es Agenten, die Übergabe und Erstellung von Relais für jede Runde zu automatisieren, wodurch die Qualität und Konsistenz des Urteils des Hauptthreads über Aufgaben wie Ergebnis/Überprüfung/Relais/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS unter Verwendung von Markdown-Dateien wie `PROJECT_OVERVIEW.md`, `TASK_BOARD.md` und `CURRENT_STATUS_*.md` gewährleistet wird.","pt":"Habilita os agentes a automatizar a transferência e a criação de relés para cada rodada, garantindo a qualidade e a consistência do julgamento da thread principal em tarefas como resultado/revisão/relé/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS usando arquivos markdown como `PROJECT_OVERVIEW.md`, `TASK_BOARD.md` e `CURRENT_STATUS_*.md`.","ru":"Наделяет агентов возможностью автоматизировать передачу и создание реле для каждого раунда, гарантируя качество и согласованность суждения основной нити в задачах, таких как результат/обзор/реле/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS, используя файлы markdown, такие как `PROJECT_OVERVIEW.md`, `TASK_BOARD.md` и `CURRENT_STATUS_*.md`.","ar":"يمنح الوكلاء القدرة على автоматизировать التخليص والإنشاء المتوازي لكل جولة، مما يضمن جودة وحفظ الحكم على الخيط الرئيسي في المهام مثل النتيجة/المراجعة/المرور/لوحة المهام/محة المشروع/الحالة الحالية باستخدام ملفات markdown مثل `PROJECT_OVERVIEW.md` و `TASK_BOARD.md` و `CURRENT_STATUS_*.md`."},"useCases":{"en":["Automating round-specific handoff and relay creation","Validating consistency across task boards and project overviews","Generating reports for current status and review processes"],"zh":["自动化轮次特定的交接和中继创建","验证任务板和项目概述的一致性","为当前状态和审查过程生成报告"],"ja":["ラウンド特定的ハンドオフとリレーの作成を自動化する","タスクボードとプロジェクト概要の一貫性を検証する","現在のステータスとレビュー処理のレポートを生成する"],"ko":["라운드 특정의 인수와 릴레이 생성을 자동화하는","태스크 보드와 프로젝트 개요의 일관성을 확인하는","현재 상태 및 검토 처리를 위한 보고서 생성"],"es":["Automatización de la entrega y creación de retransmisiones específicas de la ronda","Validación de la consistencia en tableros de tareas y vistas generales de proyectos","Generación de informes para procesos de estado actual y revisión"],"fr":["Automatisation de la passation et de la création de relais spécifiques au tour","Validation de la cohérence sur les tableaux de tâches et les vues d''ensemble de projet","Génération de rapports pour les processus d''état actuel et d''examen"],"de":["Automatisierung der Übergabe und Erstellung von Runden-spezifischen Relais","Validierung der Konsistenz über Aufgaben- und Projektübersichten","Erstellung von Berichten für Prozesse des aktuellen Status und der Überprüfung"],"pt":["Automatizar a transferência e criação de relés específicos de rodada","Validar a consistência em toda a tarefa e visão geral do projeto","Gerar relatórios para o processo de revisão e estado atual"],"ru":["Автоматизировать передачу и создание реле для каждого раунда","Проверять согласованность во всех задачах и обзорах проекта","Генерировать отчеты для процесса обзора и текущего состояния"],"ar":["تأشير التخليص والإنشاء المتوازي الخاص بالدورة","التحقق من الاتساق عبر جميع المهام ومحة المشروع","توليد تقارير لعملية المراجعة والحالة الحالية"]},"limitations":{"en":["Requires access to specific markdown files like `PROJECT_OVERVIEW.md` and `TASK_BOARD.md`","Limited to rounds with predefined numbering format like `H-00N`"],"zh":["需要访问特定的 markdown 文件，如 `PROJECT_OVERVIEW.md` 和 `TASK_BOARD.md`","仅限于具有预定义编号格式的轮次，如 `H-00N`"],"ja":["特定の markdown ファイル such as `PROJECT_OVERVIEW.md` と `TASK_BOARD.md` にアクセスする必要があります","事前に定義された番号形式のラウンドのみ対応 such as `H-00N`"],"ko":["특정 마크다운 파일에 접근할 수 있어야 함 such as `PROJECT_OVERVIEW.md` 및 `TASK_BOARD.md`","사전에 정의된 번호 형식의 라운드만 해당 such as `H-00N`"],"es":["Requiere acceso a archivos markdown específicos como `PROJECT_OVERVIEW.md` y `TASK_BOARD.md`","Limitado a rondas con formato de numeración predefinido como `H-00N`"],"fr":["Nécessite l''accès à des fichiers markdown spécifiques comme `PROJECT_OVERVIEW.md` et `TASK_BOARD.md`","Limité aux tours avec un format de numérotation prédéfini comme `H-00N`"],"de":["Erfordert den Zugriff auf bestimmte Markdown-Dateien wie `PROJECT_OVERVIEW.md` und `TASK_BOARD.md`","Begrenzt auf Runden mit vordefiniertem Zahlenformat wie `H-00N`"],"pt":["Exige acesso a arquivos markdown específicos como `PROJECT_OVERVIEW.md` e `TASK_BOARD.md`","Limitado a rodadas com formato de numeração predefinido como `H-00N`"],"ru":["Требует доступа к определенным файлам markdown, таким как `PROJECT_OVERVIEW.md` и `TASK_BOARD.md`","Ограничен раундами с предварительно определенным форматом нумерации, таким как `H-00N`"],"ar":["يتطلب الوصول إلى ملفات markdown محددة مثل `PROJECT_OVERVIEW.md` و `TASK_BOARD.md`","محدود بالدورات ذات تنسيق ترقيم محدد مسبقاً مثل `H-00N`"]},"version":4},"contentHash":"1d296284e910524b8235ad31e7c77abe8eedc59a1e02504863b254a1171059fd","qualityScore":20}');
