INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('KarubiOhayo/Dev-Agent-Orchestrator/round-main-control', 'round-main-control', 'KarubiOhayo', 'Dev-Agent-Orchestrator', 'community', 'round-main-control KarubiOhayo Dev-Agent-Orchestrator community The round-main-control skill ensures main thread judgment quality and checks for inconsistencies across tasks. It benefits developers by automating handoff and relay creation for each round. round-main-control 是一种用于优化主线程判定质量和一致性的技术，通过检查 result、review、relay、TASK_BOARD、PROJECT_OVERVIEW 和 CURRENT_STATUS 等文件 round-main-control は、メインスレッドの判定品質と一致性を最適化する技術で、result、review、relay、TASK_BOARD、PROJECT_OVERVIEW、CURRENT_STATUS などのファイルをチェックします round-main-control는 메인 스레드의 판단 품질과 일관성을 최적화하는 기술로, result, review, relay, TASK_BOARD, PROJECT_OVERVIEW, CURRENT_STATUS 등의 파일을 점검합니다 Round-main-control es una habilidad que gestiona la calidad de la toma de decisiones en el hilo principal y verifica la coherencia entre documentos como result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS. Round-main-control est une compétence qui gère la qualité de la prise de décision dans le thread principal et vérifie la cohérence entre les documents tels que result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS. Round-main-control ist eine Fähigkeit, die die Qualität der Entscheidungsfindung im Hauptthread verwaltet und die Konsistenz zwischen Dokumenten wie result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS überprüft. O round-main-control é uma habilidade que garante a consistência entre result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS em cada rodada. Round-main-control — это навык, обеспечивающий согласованность между result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS на каждом раунде. round-main-control هو مهارة تضمن الاتساق بين result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS في كل جولة. round-main-control setup guide what is round-main-control round-main-control vs alternative skills how to use round-main-control for round management round-main-control install and configuration round-main-control for AI agents and automation round-main-control AI 工具 主线程判定质量 一致性优化 文件检查 TASK_BOARD PROJECT_OVERVIEW CURRENT_STATUS Checks for inconsistencies across result/review/relay/TASK_BOARD/PROJECT_OVERVIEW/CURRENT_STATUS Creates handoff and Main->Executor relay for each round Utilizes Markdown files such as PROJECT_OVERVIEW.md, TASK_BOARD.md, and CURRENT_STATUS_*.md Processes coordination reports including H-00N-result.md and H-00N-review.md Manages relays via coordination/RELAYS/H-00N-review-to-main round-main-control is a skill that maintains main thread judgment quality and ensures consistency across result, review, relay, and task board data.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('GodBlf/godblf.github.io/firefly-footer-config', 'community', 'GodBlf', 'godblf.github.io', 'GodBlf/godblf.github.io', 'firefly-footer-config', 0, 0, 20, '2026-03-04T05:40:59Z', '2026-03-07T04:04:48.084Z', 'f5b2ddd15eadff621d3680ab034b558f5111fdbac761f7254bd620602f7cd84b', '{"id":"GodBlf/godblf.github.io/firefly-footer-config","name":"firefly-footer-config","description":{"en":"The firefly-footer-config skill allows developers to toggle footer HTML injection and maintain custom footer snippets safely, benefiting web developers and UI designers.","zh":"Firefly Footer Config 是一种安全的自定义页脚配置解决方案，通过读取目标文件、确认请求行为和应用最小更改来实现自定义页脚配置","ja":"Firefly Footer Config は、カスタムフッター設定を安全に行うためのソリューションです。ターゲットファイルの読み込み、リクエスト動作の確認、最小限の変更の適用を行います","ko":"Firefly Footer Config는 맞춤형 푸터 구성에 대한 안전한 솔루션으로, 대상 파일을 읽고 요청 동작을 확인하고 최소한의 변경을 적용하여 푸터를 구성합니다","es":"La configuración de pie de página Firefly permite inyectar HTML de forma segura y mantener fragmentos de pie de página personalizados. Herramientas de inteligencia artificial para desarrolladores","fr":"La configuration de pied de page Firefly permet d''injecter du HTML de manière sécurisée et de maintenir des extraits de pied de page personnalisés. Outils d''intelligence artificielle pour les développeurs","de":"Die Firefly-Fußzeilen-Konfiguration ermöglicht die sichere Injection von HTML und die Wartung von benutzerdefinierten Fußzeilen-Snippets. KI-Tools für Entwickler","pt":"O Firefly Footer Config é uma ferramenta que permite a injeção de HTML de rodapé e a manutenção de snippets de rodapé personalizados de forma segura, garantindo a integridade do código","ru":"Firefly Footer Config - это инструмент, который позволяет безопасно внедрять HTML-футер и поддерживать пользовательские сниппеты футера, сохраняя целостность кода с помощью ИИ Агентов","ar":"Firefly Footer Config هو أداة تمكن من حقن HTML للقدم وضمان استمرار شرائح القدم المخصصة بأمان، مع الحفاظ على سلامة الكود"},"seo":{"title":{"en":"firefly-footer-config: Customizable Footer Configuration ...","zh":"Firefly Footer Config 安装指南 - 自定义页脚解决方案","ja":"Firefly Footer Config セットアップガイド - カスタムフッターのベストプラクティス","ko":"Firefly Footer Config 설정 가이드 - 맞춤형 푸터 구성","es":"Configuración de pie de página Firefly: Guía de configura...","fr":"Configuration de pied de page Firefly: Meilleures pratiques","de":"Firefly-Fußzeilen-Konfiguration: Einrichtungsanleitung","pt":"Guia de Configuração do Firefly Footer Config para Desenv...","ru":"Настройка Firefly Footer Config: Руководство для Разработ...","ar":"دليل إعداد Firefly Footer Config لمنصة التطوير بالعربية"},"description":{"en":"Discover how to safely inject custom footer snippets with firefly-footer-config. Learn how to toggle footer HTML and maintain existing styles with this AI ag...","zh":"使用 Firefly Footer Config 实现安全的自定义页脚配置，了解其工作流程和技术细节","ja":"Firefly Footer Config を使用してカスタムフッターを安全に設定し、そのワークフローとテクニカル詳細を学ぶ","ko":"Firefly Footer Config를 사용하여 맞춤형 푸터를 안전하게 구성하고, 그 워크플로우와 기술 세부 사항을 알아보세요","es":"Aprenda a configurar el pie de página Firefly con nuestra guía paso a paso y mejore su experiencia de usuario con Herramientas de inteligencia artificial","fr":"Découvrez comment configurer le pied de page Firefly avec notre guide étape par étape et améliorez votre expérience utilisateur avec des Outils d''intelligenc...","de":"Erfahren Sie, wie Sie die Firefly-Fußzeile mit unserer Schritt-für-Schritt-Anleitung konfigurieren und Ihre Benutzererfahrung mit KI-Tools verbessern","pt":"Aprenda a configurar o Firefly Footer Config para injeção de HTML de rodapé e manutenção de snippets de rodapé personalizados de forma segura","ru":"Узнайте, как настроить Firefly Footer Config для безопасной инъекции HTML-футера и поддержки пользовательских сниппетов футера с помощью ИИ Агентов","ar":"تعلم كيفية إعداد Firefly Footer Config لحقن HTML للقدم وضمان استمرار شرائح القدم المخصصة بأمان"},"definition":{"en":"firefly-footer-config is a skill that enables the safe injection of custom footer snippets, maintaining existing styles and object structures.","zh":"Firefly Footer Config 是一种 AI 工具，用于安全地配置自定义页脚","ja":"Firefly Footer Config は、カスタムフッターを安全に設定するための AI エージェントです","ko":"Firefly Footer Config는 맞춤형 푸터를 안전하게 구성하기 위한 AI 도구입니다","es":"La configuración de pie de página Firefly es una característica que permite a los desarrolladores inyectar HTML de forma segura en la sección de pie de página","fr":"La configuration de pied de page Firefly est une fonctionnalité qui permet aux développeurs d''injecter du HTML de manière sécurisée dans la section de pied de page","de":"Die Firefly-Fußzeilen-Konfiguration ist eine Funktion, die es Entwicklern ermöglicht, HTML sicher in den Fußzeilenbereich einzuspritzen","pt":"O Firefly Footer Config é uma ferramenta de configuração que permite a edição segura de snippets de rodapé","ru":"Firefly Footer Config - это инструмент настройки, который позволяет безопасно редактировать сниппеты футера с помощью ИИ Агентов","ar":"Firefly Footer Config هو أداة إعداد تمكن من تحرير شرائح القدم بأمان"},"features":{"en":["Toggles footer HTML injection for custom footer snippets","Maintains existing style, object structure, and value types","Applies smallest possible change inside declared scope","Reads current target file(s) before editing","Reports changed keys and paths"],"zh":["读取目标文件以确定自定义页脚配置","确认请求行为以应用最小更改","保持现有的样式、对象结构和值类型","报告更改的键和路径","支持 src/config/footerConfig.ts 和 src/config/FooterConfig.html 文件"],"ja":["ターゲットファイルを読み込んでカスタムフッター設定を決定","リクエスト動作を確認して最小限の変更を適用","既存のスタイル、オブジェクト構造、値の種類を保持","変更されたキーやパスを報告","src/config/footerConfig.ts および src/config/FooterConfig.html ファイルをサポート"],"ko":["대상 파일을 읽어 맞춤형 푸터 구성에 대한 정보를 결정","요청 동작을 확인하여 최소한의 변경을 적용","기존의 스타일, 객체 구조, 값 유형을 유지","변경된 키와 경로를 보고","src/config/footerConfig.ts 및 src/config/FooterConfig.html 파일을 지원"],"es":["Inyección segura de HTML en la sección de pie de página","Mantenimiento de fragmentos de pie de página personalizados","Edición de archivos de configuración en src/config/footerConfig.ts","Compatibilidad con estructuras de objeto y tipos de valor existentes","Informe de cambios en claves y rutas"],"fr":["Injection sécurisée de HTML dans la section de pied de page","Maintenance d''extraits de pied de page personnalisés","Édition de fichiers de configuration dans src/config/footerConfig.ts","Compatibilité avec les structures d''objet et les types de valeur existants","Rapport de modifications des clés et des chemins"],"de":["Sichere Injection von HTML in den Fußzeilenbereich","Wartung von benutzerdefinierten Fußzeilen-Snippets","Bearbeitung von Konfigurationsdateien in src/config/footerConfig.ts","Kompatibilität mit bestehenden Objektstrukturen und Werttypen","Bericht über Änderungen an Schlüsseln und Pfaden"],"pt":["Injeção de HTML de rodapé","Manutenção de snippets de rodapé personalizados","Edição segura de arquivos de configuração","Compatibilidade com src/config/footerConfig.ts","Compatibilidade com src/config/FooterConfig.html"],"ru":["Внедрение HTML-футера","Поддержка пользовательских сниппетов футера","Безопасное редактирование файлов конфигурации","Совместимость с src/config/footerConfig.ts","Совместимость с src/config/FooterConfig.html с помощью ИИ Агентов"],"ar":["حقن HTML للقدم","ضمان استمرار شرائح القدم المخصصة","تحرير آمن لملفات الإعداد","التوافق مع src/config/footerConfig.ts","التوافق مع src/config/FooterConfig.html"]},"keywords":{"en":["how to use firefly-footer-config","firefly-footer-config setup guide","custom footer snippet injection","footer HTML configuration","firefly-footer-config alternative","firefly-footer-config vs other footer config tools","install firefly-footer-config","firefly-footer-config for web development"],"zh":["Firefly Footer Config","AI 工具","自定义页脚","页脚配置","安全配置","footerConfig.ts","FooterConfig.html","AIエージェント"],"ja":["Firefly Footer Config","AI エージェント","カスタムフッター","フッター設定","安全設定","footerConfig.ts","FooterConfig.html","AIツール"],"ko":["Firefly Footer Config","AI 도구","맞춤형 푸터","푸터 구성","안전 구성","footerConfig.ts","FooterConfig.html","AI 솔루션"],"es":["configuración de pie de página firefly","inyección de html","fragmentos de pie de página personalizados","herramientas de inteligencia artificial para desarrolladores","configuración de footer","edición de archivos de configuración","compatibilidad con estructuras de objeto"],"fr":["configuration de pied de page firefly","injection de html","extraits de pied de page personnalisés","outils d''intelligence artificielle pour les développeurs","configuration de pied de page","édition de fichiers de configuration","compatibilité avec les structures d''objet"],"de":["firefly-fußzeilen-konfiguration","html-injection","benutzerdefinierte fußzeilen-snippets","ki-tools für entwickler","fußzeilen-konfiguration","bearbeitung von konfigurationsdateien","kompatibilität mit objektstrukturen"],"pt":["Firefly Footer Config","injeção de HTML de rodapé","snippets de rodapé personalizados","edição segura de arquivos de configuração","desenvolvimento web","ferramentas de desenvolvimento","configuração de rodapé"],"ru":["Firefly Footer Config","ИИ Агенты","внедрение HTML-футера","пользовательские сниппеты футера","безопасное редактирование файлов конфигурации","разработка веб-приложений","инструменты разработки","настройка футера"],"ar":["Firefly Footer Config","أدوات التطوير","حقن HTML للقدم","شرائح القدم المخصصة","تحرير آمن لملفات الإعداد","تطوير الويب","إعدادات القدم","ادوات تطوير الويب"]}},"owner":"GodBlf","repo":"godblf.github.io","repoPath":"GodBlf/godblf.github.io","stars":0,"forks":0,"updatedAt":"2026-03-04T05:40:59Z","topics":[],"category":"community","skillMd":{"name":"firefly-footer-config","description":"修改 Firefly 页脚注入配置。Use when toggling custom footer HTML or editing备案和统计代码 in src/config/footerConfig.ts and src/config/FooterConfig.html.","bodyPreview":"# Firefly Footer Config\n\n## Overview\n\nToggle footer HTML injection and maintain custom footer snippets safely.\n\n## Workflow\n\n1. Read the current target file(s) before editing.\n2. Confirm the requested behavior and map it to existing keys.\n3. Apply the smallest possible change inside the declared scope.\n4. Keep existing style, object structure, and value types.\n5. Report changed keys and paths.\n\n## Edit Scope\n\n- src/config/footerConfig.ts\n- src/config/FooterConfig.html\n\n## Common Keys\n\n- footerCo","body":"# Firefly Footer Config\n\n## Overview\n\nToggle footer HTML injection and maintain custom footer snippets safely.\n\n## Workflow\n\n1. Read the current target file(s) before editing.\n2. Confirm the requested behavior and map it to existing keys.\n3. Apply the smallest possible change inside the declared scope.\n4. Keep existing style, object structure, and value types.\n5. Report changed keys and paths.\n\n## Edit Scope\n\n- src/config/footerConfig.ts\n- src/config/FooterConfig.html\n\n## Common Keys\n\n- footerConfig.enable\n- FooterConfig.html custom HTML blocks\n\n## Guardrails\n\n1. Do not modify files outside Edit Scope unless explicitly requested.\n2. Keep booleans, numbers, arrays, enums, and URLs in valid types.\n3. Preserve existing comments unless they conflict with the new behavior.\n4. Prefer minimal diffs that are easy to review.\n"},"lastSynced":"2026-03-07T04:04:48.084Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing precise control over HTML injection and custom footer snippets.","zh":"非常适合需要精确控制HTML注入和自定义页脚代码段的前端代理。","ja":"HTMLの挿入とカスタムフッタースニペットを正確に制御する必要があるフロントエンドエージェントに最適です。","ko":"HTML 주입과 사용자 정의 푸터 스니펫을 정확하게 제어해야 하는 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan un control preciso sobre la inyección de HTML y fragmentos de pie de página personalizados.","fr":"Parfait pour les agents Frontend qui nécessitent un contrôle précis sur l''injection de HTML et les extraits de pied de page personnalisés.","de":"Perfekt für Frontend-Agents, die eine präzise Kontrolle über die HTML-Injektion und benutzerdefinierte Fußzeilen-Snippets benötigen.","pt":"Perfeito para Agentes Frontend que precisam de controle preciso sobre a injeção de HTML e trechos de rodapé personalizados.","ru":"Идеально для фронтенд-агентов, которым требуется точный контроль над внедрением HTML и настраиваемыми фрагментами футера.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى التحكم الدقيق في حقن HTML والشذرات التابعة المخصصة."},"recommendation":{"en":"Empowers agents to toggle footer HTML injection and maintain custom footer snippets safely, utilizing TypeScript and HTML files such as footerConfig.ts and FooterConfig.html, and modifying specific keys like ''footerCo''.","zh":"使代理能够安全地切换页脚HTML注入并维护自定义页脚代码段，利用TypeScript和HTML文件，例如footerConfig.ts和FooterConfig.html，并修改特定的键值，如''footerCo''。","ja":"エージェントがフッターのHTMLの挿入を安全に切り替え、カスタムフッタースニペットを維持できるようにし、TypeScriptやHTMLファイル（例：footerConfig.tsやFooterConfig.html）を使用して、''footerCo''などの特定のキーを変更します。","ko":"에이전트가 푸터 HTML 주입을 안전하게 토글하고 사용자 정의 푸터 스니펫을 유지할 수 있도록 하며, TypeScript 및 HTML 파일(예: footerConfig.ts 및 FooterConfig.html)을 사용하여 ''footerCo''와 같은 특정 키를 수정합니다.","es":"Habilita a los agentes a alternar la inyección de HTML de pie de página y mantener de manera segura fragmentos de pie de página personalizados, utilizando TypeScript y archivos HTML como footerConfig.ts y FooterConfig.html, y modificando claves específicas como ''footerCo''.","fr":"Permet aux agents de basculer l''injection de HTML de pied de page et de maintenir en toute sécurité des extraits de pied de page personnalisés, en utilisant TypeScript et des fichiers HTML tels que footerConfig.ts et FooterConfig.html, et en modifiant des clés spécifiques comme ''footerCo''.","de":"Ermächtigt Agenten, die HTML-Injektion des Fußbereichs umzuschalten und benutzerdefinierte Fußzeilen-Snippets sicher zu warten, indem sie TypeScript und HTML-Dateien wie footerConfig.ts und FooterConfig.html verwenden und bestimmte Schlüssel wie ''footerCo'' modifizieren.","pt":"Habilita os agentes a alternar a injeção de HTML do rodapé e manter trechos de rodapé personalizados com segurança, utilizando TypeScript e arquivos HTML, como footerConfig.ts e FooterConfig.html, e modificando chaves específicas como ''footerCo''.","ru":"Позволяет агентам переключать внедрение HTML-футера и сохранять настраиваемые фрагменты футера безопасно, используя TypeScript и файлы HTML, такие как footerConfig.ts и FooterConfig.html, и изменяя определенные ключи, такие как ''footerCo''.","ar":"تمكين الوكلاء من تبديل حقن HTML للتبعية والحفاظ على شذرات التابعة المخصصة بأمان، باستخدام TypeScript وملفات HTML مثل footerConfig.ts وFooterConfig.html، وتعديل مفاتيح محددة مثل ''footerCo''."},"useCases":{"en":["Automating footer updates across multiple web pages","Generating custom footer snippets for UI design projects","Debugging issues related to HTML injection in footer sections"],"zh":["跨多个网页自动更新页脚","为UI设计项目生成自定义页脚代码段","调试与页脚HTML注入相关的问题"],"ja":["複数のWebページのフッターを自動更新する","UIデザインプロジェクト用のカスタムフッタースニペットを生成する","フッターのHTML挿入に関する問題をデバッグする"],"ko":["여러 웹 페이지의 푸터를 자동으로 업데이트하는 것","UI 디자인 프로젝트를 위한 사용자 정의 푸터 스니펫을 생성하는 것","푸터 HTML 주입과 관련된 문제를 디버깅하는 것"],"es":["Automatizar actualizaciones de pie de página en varias páginas web","Generar fragmentos de pie de página personalizados para proyectos de diseño de UI","Depurar problemas relacionados con la inyección de HTML en secciones de pie de página"],"fr":["Automatiser les mises à jour de pied de page sur plusieurs pages Web","Générer des extraits de pied de page personnalisés pour les projets de conception d''UI","Déboguer les problèmes liés à l''injection de HTML dans les sections de pied de page"],"de":["Automatisieren von Fußzeilen-Aktualisierungen über mehrere Webseiten hinweg","Erstellen benutzerdefinierter Fußzeilen-Snippets für UI-Design-Projekte","Beheben von Problemen im Zusammenhang mit der HTML-Injektion in Fußbereichen"],"pt":["Automatizar atualizações de rodapé em várias páginas web","Gerar trechos de rodapé personalizados para projetos de design de UI","Depurar problemas relacionados à injeção de HTML em seções de rodapé"],"ru":["Автоматизация обновлений футера на нескольких веб-страницах","Генерация настраиваемых фрагментов футера для проектов дизайна UI","Отладка проблем, связанных с внедрением HTML в секции футера"],"ar":["توفير تحديثات التابعة عبر صفحات ويب متعددة","генерация شذرات التابعة المخصصة لمشاريع تصميم الواجهة","تصحيح الأخطاء المتعلقة بحقن HTML في أقسام التابعة"]},"limitations":{"en":["Requires access to src/config/footerConfig.ts and src/config/FooterConfig.html files","Limited to modifying footer HTML injection and custom snippets"],"zh":["需要访问src/config/footerConfig.ts和src/config/FooterConfig.html文件","仅限修改页脚HTML注入和自定义代码段"],"ja":["src/config/footerConfig.tsとsrc/config/FooterConfig.htmlファイルへのアクセスが必要","フッターのHTML挿入とカスタムスニペットの変更のみに限定される"],"ko":["src/config/footerConfig.ts 및 src/config/FooterConfig.html 파일에 액세스해야 함","푸터 HTML 주입 및 사용자 정의 스니펫 수정에만 제한됨"],"es":["Requiere acceso a los archivos src/config/footerConfig.ts y src/config/FooterConfig.html","Limitado a la modificación de la inyección de HTML de pie de página y fragmentos personalizados"],"fr":["Nécessite un accès aux fichiers src/config/footerConfig.ts et src/config/FooterConfig.html","Limité à la modification de l''injection de HTML de pied de page et d''extraits personnalisés"],"de":["Erfordert Zugriff auf die Dateien src/config/footerConfig.ts und src/config/FooterConfig.html","Begrenzt auf die Modifizierung der HTML-Injektion des Fußbereichs und benutzerdefinierter Snippets"],"pt":["Requer acesso aos arquivos src/config/footerConfig.ts e src/config/FooterConfig.html","Limitado à modificação da injeção de HTML do rodapé e trechos personalizados"],"ru":["Требуется доступ к файлам src/config/footerConfig.ts и src/config/FooterConfig.html","Ограничен изменением внедрения HTML-футера и настраиваемых фрагментов"],"ar":["يتطلب الوصول إلى الملفات src/config/footerConfig.ts و src/config/FooterConfig.html","محدود بالتحكم في حقن HTML للتبعية والشذرات المخصصة"]},"version":4},"contentHash":"f5b2ddd15eadff621d3680ab034b558f5111fdbac761f7254bd620602f7cd84b","qualityScore":20}');
