INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('GodBlf/godblf.github.io/firefly-footer-config', 'firefly-footer-config', 'GodBlf', 'godblf.github.io', 'community', 'firefly-footer-config GodBlf godblf.github.io community The firefly-footer-config skill allows developers to toggle footer HTML injection and maintain custom footer snippets safely, benefiting web developers and UI designers. Firefly Footer Config 是一种安全的自定义页脚配置解决方案，通过读取目标文件、确认请求行为和应用最小更改来实现自定义页脚配置 Firefly Footer Config は、カスタムフッター設定を安全に行うためのソリューションです。ターゲットファイルの読み込み、リクエスト動作の確認、最小限の変更の適用を行います Firefly Footer Config는 맞춤형 푸터 구성에 대한 안전한 솔루션으로, 대상 파일을 읽고 요청 동작을 확인하고 최소한의 변경을 적용하여 푸터를 구성합니다 La configuración de pie de página Firefly permite inyectar HTML de forma segura y mantener fragmentos de pie de página personalizados. Herramientas de inteligencia artificial para desarrolladores La configuration de pied de page Firefly permet d''injecter du HTML de manière sécurisée et de maintenir des extraits de pied de page personnalisés. Outils d''intelligence artificielle pour les développeurs Die Firefly-Fußzeilen-Konfiguration ermöglicht die sichere Injection von HTML und die Wartung von benutzerdefinierten Fußzeilen-Snippets. KI-Tools für Entwickler O Firefly Footer Config é uma ferramenta que permite a injeção de HTML de rodapé e a manutenção de snippets de rodapé personalizados de forma segura, garantindo a integridade do código Firefly Footer Config - это инструмент, который позволяет безопасно внедрять HTML-футер и поддерживать пользовательские сниппеты футера, сохраняя целостность кода с помощью ИИ Агентов Firefly Footer Config هو أداة تمكن من حقن HTML للقدم وضمان استمرار شرائح القدم المخصصة بأمان، مع الحفاظ على سلامة الكود how to use firefly-footer-config firefly-footer-config setup guide custom footer snippet injection footer HTML configuration firefly-footer-config alternative firefly-footer-config vs other footer config tools install firefly-footer-config firefly-footer-config for web development Firefly Footer Config AI 工具 自定义页脚 页脚配置 安全配置 footerConfig.ts FooterConfig.html AIエージェント Toggles footer HTML injection for custom footer snippets Maintains existing style, object structure, and value types Applies smallest possible change inside declared scope Reads current target file(s) before editing Reports changed keys and paths firefly-footer-config is a skill that enables the safe injection of custom footer snippets, maintaining existing styles and object structures.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('leomancini/projects-site-generator/push', 'community', 'leomancini', 'projects-site-generator', 'leomancini/projects-site-generator', 'push', 0, 0, 20, '2026-03-03T02:06:19Z', '2026-03-07T04:08:47.811Z', '782b1125c32c1f6260f645c465436aa58281dc80f93289cfb6ab9dbb88fec1dc', '{"id":"leomancini/projects-site-generator/push","name":"push","description":{"en":"The push skill automates the deployment process for developers, using a project''s push script to commit and deploy changes with a simple command.","zh":"Push 脚本用于自动化项目的部署和提交，提高开发效率。","ja":"Push スクリプトは、プロジェクトのデプロイとコミットを自動化するために使用されます。","ko":"Push 스크립트는 프로젝트 배포와 커밋을 자동화하여 개발 효율성을 높입니다.","es":"El script de push de proyecto permite commit y despliegue de cambios con mensajes de commit personalizados basados en las modificaciones realizadas.","fr":"Le script de push de projet permet de commit et de déployer des modifications avec des messages de commit personnalisés basés sur les modifications apportées.","de":"Das Push-Skript des Projekts ermöglicht das Committen und Bereitstellen von Änderungen mit benutzerdefinierten Commit-Nachrichten basierend auf den vorgenommenen Änderungen.","pt":"O push é uma ferramenta que utiliza o script do projeto para commit e deploy de alterações. Execute ./push \"$ARGUMENTS\" para commitar e deployar suas alterações","ru":"Push - это инструмент, который использует скрипт проекта для коммита и деплоя изменений. Выполните ./push \"$ARGUMENTS\" для коммита и деплоя ваших изменений","ar":"Push هو أداة تستخدم سكريبت المشروع لارسال وتحديث التغييرات. قم بتشغيل ./push \"$ARGUMENTS\" لارسال وتحديث التغييرات"},"seo":{"title":{"en":"push: Automated Deployment Setup Guide | AI Agent Skill","zh":"Push Setup Guide: 项目部署和提交","ja":"Push ベストプラクティス: プロジェクトのデプロイとコミット","ko":"Push 사용법: 프로젝트 배포와 커밋","es":"Guía de configuración de push para desarrollo","fr":"Guide de mise en place de push pour les développeurs","de":"Push-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Push: Commit e Deploy de Alterações","ru":"Настройка Push: Коммит и Деплой Изменений с ИИ Агентами","ar":"دليل إعداد Push: إرسال وتحديث التغييرات باستخدام أدوات ال..."},"description":{"en":"Discover how to streamline your workflow with the push skill, learn to deploy changes with ease and get started with a simple ./push command","zh":"了解如何使用 Push 脚本自动化项目的部署和提交，提高开发效率。AIエージェント","ja":"Push スクリプトを使用してプロジェクトのデプロイとコミットを自動化する方法を学びます。AIエージェント","ko":"Push 스크립트를 사용하여 프로젝트 배포와 커밋을 자동화하는 방법을 알아보세요. AI 도구","es":"Aprende a utilizar el script de push de proyecto para commit y despliegue de cambios con mensajes de commit personalizados","fr":"Découvrez comment utiliser le script de push de projet pour commit et déployer des modifications avec des messages de commit personnalisés","de":"Erfahren Sie, wie Sie das Push-Skript des Projekts verwenden, um Änderungen zu committen und bereitzustellen, mit benutzerdefinierten Commit-Nachrichten","pt":"Aprenda a usar o script de push do projeto para commit e deploy de alterações com um guia passo a passo","ru":"Узнайте, как использовать скрипт push проекта для коммита и деплоя изменений с помощью ИИ Агентов","ar":"تعلم كيفية استخدام سكريبت Push في مشروعك لارسال وتحديث التغييرات باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"push is a skill that automates the deployment process using a project''s push script to commit and deploy changes","zh":"Push 是一种自动化项目部署和提交的脚本，使用 CLI 运行。","ja":"Push は、プロジェクトのデプロイとコミットを自動化するスクリプトであり、CLI で実行されます。","ko":"Push는 프로젝트 배포와 커밋을 자동화하는 스크립트로, CLI에서 실행됩니다.","es":"Push es una funcionalidad que utiliza un script de proyecto para commit y despliegue de cambios","fr":"Push est une fonctionnalité qui utilise un script de projet pour commit et déployer des modifications","de":"Push ist eine Funktionalität, die ein Projekt-Skript verwendet, um Änderungen zu committen und bereitzustellen","pt":"Push é uma ferramenta de deploy que utiliza o script do projeto para commit e deploy de alterações","ru":"Push - это инструмент деплоя, который использует скрипт проекта для коммита и деплоя изменений","ar":"Push هو أداة تحديث تستخدم سكريبت المشروع لارسال وتحديث التغييرات"},"features":{"en":["Runs the project''s push script to commit and deploy changes","Executes the command ./push \"$ARGUMENTS\"","Generates a short commit message based on changes made if no argument is provided","Passes the generated commit message as an argument to the push script","Supports custom commit messages via the $ARGUMENTS variable"],"zh":["自动化项目部署","自动化项目提交","支持 CLI 运行","可自动生成提交信息","支持自定义提交信息"],"ja":["プロジェクトのデプロイを自動化","プロジェクトのコミットを自動化","CLI で実行可能","コミットメッセージを自動生成","カスタムコミットメッセージをサポート"],"ko":["프로젝트 배포 자동화","프로젝트 커밋 자동화","CLI에서 실행","커밋 메시지 자동 생성","커밋 메시지 사용자 지정"],"es":["Utiliza un script de proyecto personalizado","Permite commit y despliegue de cambios","Genera mensajes de commit personalizados basados en las modificaciones","Soporta la ejecución de comandos CLI","Permite la personalización de los mensajes de commit"],"fr":["Utilise un script de projet personnalisé","Permet de commit et de déployer des modifications","Génère des messages de commit personnalisés basés sur les modifications","Prend en charge l''exécution de commandes CLI","Permet la personnalisation des messages de commit"],"de":["Verwendet ein benutzerdefiniertes Projekt-Skript","Ermöglicht das Committen und Bereitstellen von Änderungen","Generiert benutzerdefinierte Commit-Nachrichten basierend auf den Änderungen","Unterstützt die Ausführung von CLI-Befehlen","Ermöglicht die Anpassung der Commit-Nachrichten"],"pt":["Utiliza o script do projeto para commit e deploy de alterações","Gera uma mensagem de commit curta com base nas alterações feitas","Suporta a execução de comandos CLI","Permite a personalização da mensagem de commit","Integração com o fluxo de trabalho do projeto"],"ru":["Использует скрипт проекта для коммита и деплоя изменений","Генерирует короткое сообщение коммита на основе внесенных изменений","Поддерживает выполнение команд CLI","Позволяет настраивать сообщение коммита","Интегрируется с рабочим процессом проекта"],"ar":["تستخدم سكريبت المشروع لارسال وتحديث التغييرات","توليد رسالة ارسال قصيرة بناءً على التغييرات التي تم إجراؤها","دعم تشغيل أوامر CLI","السماح بالتخصيص لرسالة الإرسال","التكامل مع تدفق عمل المشروع"]},"keywords":{"en":["how to use push","push setup guide","automated deployment with push","push alternative","push vs git push","push install","what is push","push script","deploy changes with push"],"zh":["Push 脚本","项目部署","项目提交","CLI","AIエージェント","自动化开发","开发效率"],"ja":["Push スクリプト","プロジェクトのデプロイ","プロジェクトのコミット","CLI","AIエージェント","自動化開発","開発効率"],"ko":["Push 스크립트","프로젝트 배포","프로젝트 커밋","CLI","AI 도구","자동화 개발","개발 효율성"],"es":["push para desarrolladores","script de push de proyecto","commit y despliegue de cambios","mensajes de commit personalizados","CLI para desarrolladores","herramientas de desarrollo de software","AI Agent para desarrolladores","desarrollo de software con AI"],"fr":["push pour développeurs","script de push de projet","commit et déployer des modifications","messages de commit personnalisés","CLI pour développeurs","outils de développement de logiciels","Agent IA pour développeurs","développement de logiciels avec IA"],"de":["Push für Entwickler","Push-Skript des Projekts","Committen und Bereitstellen von Änderungen","benutzerdefinierte Commit-Nachrichten","CLI für Entwickler","Software-Entwicklungstools","KI-Agent für Entwickler","Software-Entwicklung mit KI"],"pt":["push","commit","deploy","script do projeto","mensagem de commit","CLI","fluxo de trabalho","desenvolvimento de software","ferramentas de deploy"],"ru":["push","коммит","деплой","скрипт проекта","сообщение коммита","CLI","рабочий процесс","разработка программного обеспечения","инструменты деплоя","ИИ Агенты"],"ar":["push","إرسال","تحديث","سكريبت المشروع","رسالة الإرسال","CLI","تدفق عمل","تطوير البرمجيات","أدوات التحديث","أدوات الذكاء الاصطناعي"]}},"owner":"leomancini","repo":"projects-site-generator","repoPath":"leomancini/projects-site-generator","stars":0,"forks":0,"updatedAt":"2026-03-03T02:06:19Z","topics":[],"category":"community","skillMd":{"name":"push","description":"Push changes to remote. Use this whenever the user wants to push, deploy, or publish changes.","bodyPreview":"Use the project''s push script to commit and deploy changes.\n\nRun: `./push \"$ARGUMENTS\"`\n\nIf no commit message argument is provided, generate a short commit message based on the changes made and pass it as the argument.","body":"Use the project''s push script to commit and deploy changes.\n\nRun: `./push \"$ARGUMENTS\"`\n\nIf no commit message argument is provided, generate a short commit message based on the changes made and pass it as the argument.\n"},"lastSynced":"2026-03-07T04:08:47.811Z","agentAnalysis":{"suitability":{"en":"Ideal for Deployment Agents requiring streamlined project deployment automation using commit scripts.","zh":"适合于需要使用提交脚本进行流畅项目部署自动化的部署代理。","ja":"コミットスクリプトを使用したプロジェクトのデプロイ自動化を必要とするデプロイエージェントに最適です。","ko":"커밋 스크립트를 사용하여 프로젝트 배포 자동화를 간소화해야 하는 배포 에이전트에 적합합니다.","es":"Ideal para agentes de implementación que requieren una automatización de implementación de proyectos simplificada utilizando scripts de confirmación.","fr":"Idéal pour les agents de déploiement nécessitant une automatisation de déploiement de projet simplifiée à l''aide de scripts de commit.","de":"Ideal für Deployment-Agents, die eine vereinfachte Automatisierung der Projekteinrichtung unter Verwendung von Commit-Skripten erfordern.","pt":"Ideal para Agentes de Implantação que exigem automação de implantação de projetos otimizada usando scripts de commit.","ru":"Идеально для агентов развертывания, требующих оптимизированной автоматизации развертывания проектов с использованием скриптов фиксации.","ar":"مثالي لموكلات النشر التي تتطلب آليّة نشر مشروع مسرّعة باستخدام سكربتات الالتزام."},"recommendation":{"en":"Empowers agents to automate deployment processes using a project''s push script, committing and deploying changes with a simple command, and generating short commit messages based on changes made when no message is provided, leveraging command-line interfaces and version control systems.","zh":"赋予代理自动化部署流程的能力，使用项目的推送脚本，提交和部署更改只需一个简单的命令，并在未提供消息时根据所做的更改生成短的提交消息，利用命令行接口和版本控制系统。","ja":"エージェントにプロジェクトのプッシュスクリプトを使用してデプロイプロセスを自動化する能力を付与し、変更をコミットしてデプロイするためのシンプルなコマンドを提供し、メッセージが提供されていない場合に変更された内容に基づいて短いコミットメッセージを生成し、コマンドラインインターフェイスとバージョン管理システムを活用します。","ko":"에이전트가 프로젝트의 푸시 스크립트를 사용하여 배포 프로세스를 자동화할 수 있도록 하며, 변경 사항을 커밋하고 배포하기 위한 간단한 명령어를 제공하고, 메시지가 제공되지 않은 경우에 변경된 내용을 기준으로 짧은 커밋 메시지를 생성하며, 명령줄 인터페이스와 버전 관리 시스템을 활용합니다.","es":"Habilita a los agentes a automatizar los procesos de implementación utilizando el script de push de un proyecto, confirmando y desplegando cambios con un simple comando, y generando mensajes de confirmación cortos en función de los cambios realizados cuando no se proporciona ningún mensaje, aprovechando las interfaces de línea de comandos y los sistemas de control de versiones.","fr":"Permet aux agents d''automatiser les processus de déploiement en utilisant le script de push d''un projet, en validant et en déployant les modifications avec une simple commande, et en générant des messages de commit courts en fonction des modifications apportées lorsque aucun message n''est fourni, en exploitant les interfaces de ligne de commande et les systèmes de contrôle de version.","de":"Ermächtigt die Agenten, die Bereitstellungsprozesse mithilfe eines Projekts-Push-Skripts zu automatisieren, Änderungen mit einem einfachen Befehl zu überprüfen und bereitzustellen und kurze Commit-Mitteilungen basierend auf den vorgenommenen Änderungen zu generieren, wenn keine Meldung bereitgestellt wird, indem es die Kommandozeilen-Schnittstellen und Versionskontrollsysteme nutzt.","pt":"Habilita os agentes a automatizar processos de implantação usando um script de push de um projeto, commitando e implantando alterações com um comando simples, e gerando mensagens de commit curtas com base nas alterações feitas quando nenhuma mensagem é fornecida, aproveitando interfaces de linha de comando e sistemas de controle de versão.","ru":"Наделяет агентов возможностью автоматизировать процессы развертывания с использованием скрипта публикации проекта, фиксируя и развертывая изменения с помощью простой команды, а также генерируя короткие сообщения фиксации на основе внесенных изменений, когда не предоставлено никакое сообщение, используя командную строку и системы контроля версий.","ar":"تمكّن الوكلاء من آليّة عمليات النشر باستخدام سكربت دفع لمشروع، والالتزام والنشر التغييرات باستخدام أمر بسيط، وتوليد رسائل الالتزام القصيرة بناءً على التغييرات التي تم إجراؤها عندما لا يتم توفير أي رسالة، مستفيدة من واجهات سطر الأوامر وأنظمة التحكم في الإصدار."},"useCases":{"en":["Automating project deployments","Committing changes with generated messages","Streamlining development workflows with push scripts"],"zh":["自动化项目部署","提交更改并生成消息","使用推送脚本简化开发工作流"],"ja":["プロジェクトのデプロイを自動化する","変更をコミットしてメッセージを生成する","プッシュスクリプトを使用して開発ワークフローを簡素化する"],"ko":["프로젝트 배포 자동화","변경 사항 커밋 및 메시지 생성","푸시 스크립트를 통한 개발 워크플로우 간소화"],"es":["Automatización de implementaciones de proyectos","Confirmación de cambios con mensajes generados","Optimización de flujos de trabajo de desarrollo con scripts de push"],"fr":["Automatisation des déploiements de projets","Validation des modifications avec des messages générés","Optimisation des flux de travail de développement avec des scripts de push"],"de":["Automatisierung von Projekteinrichtungen","Überprüfung von Änderungen mit generierten Nachrichten","Optimierung von Entwicklungsworkflows mit Push-Skripten"],"pt":["Automatizar implantações de projetos","Commitar alterações com mensagens geradas","Otimizar fluxos de desenvolvimento com scripts de push"],"ru":["Автоматизировать развертывание проектов","Фиксировать изменения с сгенерированными сообщениями","Оптимизировать рабочие процессы разработки с помощью скриптов публикации"],"ar":["آليّة نشر المشاريع","الالتزام بالتغيرات مع رسائل مولّدة","تبسيط سلاسل العمل التطويرية بسكربتات الدفع"]},"limitations":{"en":["Requires a project push script","Command-line interface needed","No support for complex commit messages without user input"],"zh":["需要项目推送脚本","需要命令行接口","不支持复杂的提交消息，除非用户输入"],"ja":["プロジェクトプッシュスクリプトが必要","コマンドラインインターフェイスが必要","ユーザー入力がない場合、複雑なコミットメッセージはサポートされません"],"ko":["프로젝트 푸시 스크립트가 필요함","명령줄 인터페이스가 필요함","사용자 입력이 없는 경우 복잡한 커밋 메시지는 지원되지 않음"],"es":["Se requiere un script de push de proyecto","Se necesita una interfaz de línea de comandos","No se admite el mensaje de confirmación complejo sin entrada del usuario"],"fr":["Un script de push de projet est requis","Une interface de ligne de commande est nécessaire","Aucun support pour les messages de commit complexes sans saisie utilisateur"],"de":["Ein Projektpush-Skript ist erforderlich","Eine Kommandozeilen-Schnittstelle ist erforderlich","Keine Unterstützung für komplexe Commit-Nachrichten ohne Benutzereingabe"],"pt":["Exige um script de push de projeto","Interface de linha de comando necessária","Sem suporte a mensagens de commit complexas sem entrada do usuário"],"ru":["Требуется скрипт публикации проекта","Необходимо командное оформление","Нет поддержки сложных сообщений фиксации без ввода пользователя"],"ar":["يتطلب سكربت دفع لمشروع","مطلوب واجهة سطر الأوامر","لا دعم للرسائل الملتزمة المعقّدة بدون مدخلات المستخدم"]},"version":4},"contentHash":"782b1125c32c1f6260f645c465436aa58281dc80f93289cfb6ab9dbb88fec1dc","qualityScore":20}');
