INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('leomancini/projects-site-generator/push', 'push', 'leomancini', 'projects-site-generator', 'community', 'push leomancini projects-site-generator community The push skill automates the deployment process for developers, using a project''s push script to commit and deploy changes with a simple command. Push 脚本用于自动化项目的部署和提交，提高开发效率。 Push スクリプトは、プロジェクトのデプロイとコミットを自動化するために使用されます。 Push 스크립트는 프로젝트 배포와 커밋을 자동화하여 개발 효율성을 높입니다. El script de push de proyecto permite commit y despliegue de cambios con mensajes de commit personalizados basados en las modificaciones realizadas. Le script de push de projet permet de commit et de déployer des modifications avec des messages de commit personnalisés basés sur les modifications apportées. Das Push-Skript des Projekts ermöglicht das Committen und Bereitstellen von Änderungen mit benutzerdefinierten Commit-Nachrichten basierend auf den vorgenommenen Änderungen. O push é uma ferramenta que utiliza o script do projeto para commit e deploy de alterações. Execute ./push "$ARGUMENTS" para commitar e deployar suas alterações Push - это инструмент, который использует скрипт проекта для коммита и деплоя изменений. Выполните ./push "$ARGUMENTS" для коммита и деплоя ваших изменений Push هو أداة تستخدم سكريبت المشروع لارسال وتحديث التغييرات. قم بتشغيل ./push "$ARGUMENTS" لارسال وتحديث التغييرات how to use push push setup guide automated deployment with push push alternative push vs git push push install what is push push script deploy changes with push Push 脚本 项目部署 项目提交 CLI AIエージェント 自动化开发 开发效率 Runs the project''s push script to commit and deploy changes Executes the command ./push "$ARGUMENTS" Generates a short commit message based on changes made if no argument is provided Passes the generated commit message as an argument to the push script Supports custom commit messages via the $ARGUMENTS variable push is a skill that automates the deployment process using a project''s push script to commit and deploy changes');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bagrinsergiu/MB-migration/sub-agent-decompose-worker-review', 'community', 'bagrinsergiu', 'MB-migration', 'bagrinsergiu/MB-migration', 'sub-agent-decompose-worker-review', 0, 0, 20, '2026-03-02T12:23:13Z', '2026-03-07T04:09:54.366Z', '8966f940f690db9da8087f6938c103f5aaaa2d173fb531db802c2ff4a2863b3e', '{"id":"bagrinsergiu/MB-migration/sub-agent-decompose-worker-review","name":"sub-agent-decompose-worker-review","description":{"en":"The sub-agent-decompose-worker-review skill automates task decomposition, execution, and review. It benefits developers by streamlining workflows and improving code quality.","zh":"子任务分解工作者审查AIエージェント是一种任务分解和执行工具，使用task-decomposer和task-worker进行任务处理","ja":"AIエージェントのサブタスク分解ワーカーレビューは、タスクを分解して実行するツールで、task-decomposerとtask-workerを使用します","ko":"AI 에이전트의 서브 에이전트 분해 작업자 리뷰는 task-decomposer와 task-worker를 사용하여 태스크를 분해하고 실행하는 도구입니다","es":"El sub-agent-decompose-worker-review es un componente clave para mejorar el rendimiento de los agentes de IA, permitiendo la descomposición de tareas en subprocesos con orden y criterios de finalización","fr":"Le sub-agent-decompose-worker-review est un composant essentiel pour améliorer les performances des outils d''IA, permettant la décomposition de tâches en sous-processus avec ordre et critères de finition","de":"Der sub-agent-decompose-worker-review ist ein wichtiger Bestandteil, um die Leistung von KI-Agents zu verbessern, indem er die Aufteilung von Aufgaben in Subprozesse mit Reihenfolge und Abgeschlossenheitskriterien ermöglicht","pt":"O sub-agent-decompose-worker-review é um conjunto de agentes que trabalham em cadeia para decompor tarefas em sub-tarefas com ordem e critérios de prontidão","ru":"Суб-агенты Decomposer → Worker → Reviewer работают по цепочке для декомпозиции задач в подзадачи с порядком и критериями готовности для ИИ Агентов","ar":"وكلاء ذكاء اصطناعي يعتملون بالتسلسل لتقسيم المهام إلى مهام فرعية مع ترتيب ومتطلبات إتمام"},"seo":{"title":{"en":"sub-agent-decompose-worker-review: Pipeline Automation Se...","zh":"AIエージェント子任务分解工作者审查设置指南","ja":"AIエージェントのサブタスク分解ワーカーレビューのベストプラクティス","ko":"AI 에이전트 서브 에이전트 분해 작업자 리뷰 설정 가이드","es":"Guía de configuración de sub-agent-decompose-worker-revie...","fr":"Guide de démarrage rapide pour sub-agent-decompose-worker...","de":"Einrichtungsleitfaden für sub-agent-decompose-worker-revi...","pt":"Guia de Configuração do sub-agent-decompose-worker-review...","ru":"Настройка суб-агентов: Decomposer → Worker → Reviewer для...","ar":"دليل إعداد sub-agent-decompose-worker-review: تقسيم المها..."},"description":{"en":"Unlock efficient task management with sub-agent-decompose-worker-review. Discover how to automate pipelines and optimize workflows. Learn more and get starte...","zh":"了解子任务分解工作者审查AIエージェント的技术细节，包括任务分解、工作者执行和审查流程","ja":"AIエージェントのサブタスク分解ワーカーレビューの機能と技術詳細を紹介します","ko":"AI 에이전트의 서브 에이전트 분해 작업자 리뷰 기능과 기술 세부 사항을 알아보세요","es":"Aprende a configurar sub-agent-decompose-worker-review para mejorar el rendimiento de tus agentes de IA con tecnologías como CLI y Python","fr":"Découvrez comment configurer sub-agent-decompose-worker-review pour améliorer les performances de vos outils d''IA avec des technologies comme CLI et Python","de":"Erfahren Sie, wie Sie sub-agent-decompose-worker-review einrichten, um die Leistung Ihrer KI-Agents mit Technologien wie CLI und Python zu verbessern","pt":"Aprenda a configurar o sub-agent-decompose-worker-review para decompor tarefas em sub-tarefas com ordem e critérios de prontidão","ru":"Узнайте, как настроить суб-агенты для декомпозиции задач в подзадачи с порядком и критериями готовности для ИИ Агентов","ar":"تعرف على كيفية إعداد وكلاء ذكاء اصطناعي لتقسيم المهام إلى مهام فرعية مع ترتيب ومتطلبات إتمام"},"definition":{"en":"sub-agent-decompose-worker-review is a pipeline automation skill that decomposes tasks, executes them, and reviews the results using a chain of three agents: task-decomposer, task-worker, and reviewer.","zh":"子任务分解工作者审查AIエージェント是一种自动化任务处理工具","ja":"AIエージェントのサブタスク分解ワーカーレビューは、自動化タスク処理ツールの一種です","ko":"AI 에이전트의 서브 에이전트 분해 작업자 리뷰는 자동화 태스크 처리 도구의 일종입니다","es":"El sub-agent-decompose-worker-review es un agente de IA que descompone tareas en subprocesos con orden y criterios de finalización","fr":"Le sub-agent-decompose-worker-review est un agent d''IA qui décompose les tâches en sous-processus avec ordre et critères de finition","de":"Der sub-agent-decompose-worker-review ist ein KI-Agent, der Aufgaben in Subprozesse mit Reihenfolge und Abgeschlossenheitskriterien unterteilt","pt":"O sub-agent-decompose-worker-review é um conjunto de agentes que trabalham em cadeia para decompor tarefas","ru":"Суб-агенты - это набор агентов, работающих по цепочке для декомпозиции задач","ar":"الوكلاء هم مجموعة من الوكلاء التي تعمل بالتسلسل لتقسيم المهام"},"features":{"en":["Decomposes tasks into subtasks with order and readiness criteria using the task-decomposer agent","Executes subtasks with minimal safe changes and adherence to main.m rules using the task-worker agent","Supports separate execution of each step in the pipeline","Allows for analysis of codebases and decomposition of tasks into manageable parts","Enables review of task execution results for quality assurance","Utilizes a chain of three agents for automated task management"],"zh":["任务分解功能使用task-decomposer","工作者执行功能使用task-worker","支持最小安全更改和主代码库规则遵守","可单独运行每个步骤","支持多任务处理"],"ja":["タスク分解機能はtask-decomposerを使用","ワーカー実行機能はtask-workerを使用","最小安全変更とメインコードベースのルール遵守をサポート","各ステップを個別に実行可能","複数タスク処理をサポート"],"ko":["태스크 분해 기능은 task-decomposer를 사용","작업자 실행 기능은 task-worker를 사용","최소 안전 변경과 메인 코드베이스 규칙 준수를 지원","각 단계를 개별적으로 실행할 수 있음","다중 태스크 처리를 지원"],"es":["Descomposición de tareas en subprocesos con orden y criterios de finalización","Compatibilidad con tecnologías como CLI y Python","Integración con agentes de IA para mejorar el rendimiento","Posibilidad de ejecutar