INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bagrinsergiu/MB-migration/sub-agent-decompose-worker-review', 'sub-agent-decompose-worker-review', 'bagrinsergiu', 'MB-migration', 'community', 'sub-agent-decompose-worker-review bagrinsergiu MB-migration community The sub-agent-decompose-worker-review skill automates task decomposition, execution, and review. It benefits developers by streamlining workflows and improving code quality. 子任务分解工作者审查AIエージェント是一种任务分解和执行工具，使用task-decomposer和task-worker进行任务处理 AIエージェントのサブタスク分解ワーカーレビューは、タスクを分解して実行するツールで、task-decomposerとtask-workerを使用します AI 에이전트의 서브 에이전트 분해 작업자 리뷰는 task-decomposer와 task-worker를 사용하여 태스크를 분해하고 실행하는 도구입니다 El sub-agent-decompose-worker-review es un componente clave para mejorar el rendimiento de los agentes de IA, permitiendo la descomposición de tareas en subprocesos con orden y criterios de finalización Le sub-agent-decompose-worker-review est un composant essentiel pour améliorer les performances des outils d''IA, permettant la décomposition de tâches en sous-processus avec ordre et critères de finition Der sub-agent-decompose-worker-review ist ein wichtiger Bestandteil, um die Leistung von KI-Agents zu verbessern, indem er die Aufteilung von Aufgaben in Subprozesse mit Reihenfolge und Abgeschlossenheitskriterien ermöglicht O sub-agent-decompose-worker-review é um conjunto de agentes que trabalham em cadeia para decompor tarefas em sub-tarefas com ordem e critérios de prontidão Суб-агенты Decomposer → Worker → Reviewer работают по цепочке для декомпозиции задач в подзадачи с порядком и критериями готовности для ИИ Агентов وكلاء ذكاء اصطناعي يعتملون بالتسلسل لتقسيم المهام إلى مهام فرعية مع ترتيب ومتطلبات إتمام how to use sub-agent-decompose-worker-review sub-agent-decompose-worker-review pipeline automation sub-agent-decompose-worker-review alternative sub-agent-decompose-worker-review setup guide sub-agent-decompose-worker-review vs competing skills what is sub-agent-decompose-worker-review sub-agent-decompose-worker-review install automating task decomposition with sub-agent-decompose-worker-review sub-agent-decompose-worker-review for developers sub-agent-decompose-worker-review workflow optimization AIエージェント 子任务分解 工作者审查 任务分解工具 自动化任务处理 task-decomposer task-worker 最小安全更改 主代码库规则遵守 Decomposes tasks into subtasks with order and readiness criteria using the task-decomposer agent Executes subtasks with minimal safe changes and adherence to main.m rules using the task-worker agent Supports separate execution of each step in the pipeline Allows for analysis of codebases and decomposition of tasks into manageable parts Enables review of task execution results for quality assurance Utilizes a chain of three agents for automated task management sub-agent-decompose-worker-review is a pipeline automation skill that decomposes tasks, executes them, and reviews the results using a chain of three agents: task-decomposer, task-worker, and reviewer.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aquarius-wing/polymarket-dev-tools/chrome-webstore-listing', 'community', 'aquarius-wing', 'polymarket-dev-tools', 'aquarius-wing/polymarket-dev-tools', 'chrome-webstore-listing', 0, 0, 20, '2026-02-21T07:06:42Z', '2026-03-07T04:14:35.956Z', '8dea6749642314d5ceae973944b577af2964be9d79e4958ed380633e7c0ae03b', '{"id":"aquarius-wing/polymarket-dev-tools/chrome-webstore-listing","name":"chrome-webstore-listing","description":{"en":"The chrome-webstore-listing skill provides utilities for developers on polymarket.com pages, such as one-click copy for Event Slug and Market Slug, and page highlight debugging for improved development efficiency","zh":"创建高质量的Chrome网上应用店listing，包括标题、摘要和关键词优化","ja":"Chrome Web Store リスティングを最適化するためのベストプラクティス - タイトル、サマリー、キーワード最適化","ko":"Chrome 웹 스토어 목록을 최적화하는 방법 - 제목, 요약, 키워드 최적화 포함","es":"La lista de chrome-webstore-listing ofrece utilidades para desarrolladores en polymarket.com, como copia de un clic para Event Slug y Market Slug","fr":"La liste de chrome-webstore-listing propose des utilitaires pour les développeurs sur polymarket.com, tels que la copie d''un clic pour Event Slug et Market Slug","de":"Die chrome-webstore-listing-Liste bietet Entwicklern auf polymarket.com Utilitys wie Ein-Klick-Kopie für Event Slug und Market Slug","pt":"A lista de loja do Chrome é fundamental para o sucesso da sua extensão. Nossa guia de melhores práticas para chrome-webstore-listing ajuda a criar uma lista de alta qualidade.","ru":"Страница листинга в магазине Chrome имеет решающее значение для успеха вашего расширения. Наше руководство по chrome-webstore-listing для ИИ Агентов поможет создать высококачественную страницу.","ar":"قائمة متجر Chrome هي أساسية لنجاح امتدادك. دليل أفضل الممارسات لchrome-webstore-listing يساعد على إنشاء قائمة بجودة عالية."},"seo":{"title":{"en":"Chrome Webstore Listing: Best Practices for Developers | ...","zh":"Chrome 网上应用店listing最佳实践指南","ja":"Chrome Web Store リスティングの設定ガイド - AIエージェント","ko":"Chrome 웹 스토어 목록 최적화 설정 가이드","es":"Guía de configuración de chrome-webstore-listing para des...","fr":"Meilleures pratiques pour chrome-webstore-listing - Guide...","de":"Einrichtungsleitfaden für chrome-webstore-listing - Entwi...","pt":"Guia de Configuração para chrome-webstore-listing: Melhor...","ru":"Настройка ИИ Агентов для chrome-webstore-listing: Руковод...","ar":"دليل إعداد إضافة chrome-webstore-listing: إرشادات وأفضل م..."},"description":{"en":"Optimize your Chrome extension''s visibility with expert tips on crafting a compelling store listing, including title and summary best practices - learn how t...","zh":"了解如何创建高质量的Chrome网上应用店listing，包括标题、摘要和关键词优化","ja":"Chrome Web Store リスティングを最適化するためのベストプラクティス - AIエージェントを使用して","ko":"Chrome 웹 스토어 목록을 최적화하는 방법을 알아보세요 - 제목, 요약, 키워드 최적화 포함","es":"Aprende a crear una lista de chrome-webstore-listing efectiva con nuestras mejores prácticas y herramientas para desarrolladores","fr":"Découvrez les meilleures pratiques pour créer une liste de chrome-webstore-listing de haute qualité avec nos outils et ressources pour développeurs","de":"Erstellen Sie eine effektive chrome-webstore-listing-Liste mit unseren besten Praktiken und Tools für Entwickler","pt":"Aprenda a criar uma lista de loja de alta qualidade para sua extensão do Chrome com nossa guia de melhores práticas para chrome-webstore-listing","ru":"Узнайте, как создать привлекательную и высококачественную страницу листинга в магазине Chrome с помощью нашего руководства по chrome-webstore-listing для ИИ ...","ar":"تعرف على كيفية إنشاء قائمة متجر بجودة عالية لامتداد Chrome الخاص بك باستخدام دليل أفضل الممارسات لchrome-webstore-listing"},"definition":{"en":"chrome-webstore-listing is a set of developer-focused utilities for optimizing Chrome Web Store listings, including title and summary fields","zh":"Chrome网上应用店listing是开发者向用户展示其扩展程序的途径","ja":"Chrome Web Store リスティングは、開発者が拡張機能をユーザーに提示するための方法です","ko":"Chrome 웹 스토어 목록은 개발자가 확장 프로그램을 사용자에게 표시하는 방법입니다","es":"chrome-webstore-listing es una herramienta de AI que proporciona utilidades para desarrolladores en polymarket.com","fr":"chrome-webstore-listing est un outil d''IA qui propose des utilitaires pour les développeurs sur polymarket.com","de":"chrome-webstore-listing ist ein AI-Tool, das Entwicklern auf polymarket.com Utilitys bietet","pt":"O que é chrome-webstore-listing? É um conjunto de utilitários para desenvolvedores que ajudam a criar listas de loja de alta qualidade para extensões do Chrome.","ru":"Что такое chrome-webstore-listing? Это набор утилит для разработчиков, помогающих создать высококачественные страницы листинга для расширений Chrome.","ar":"ما هو chrome-webstore-listing؟ هو مجموعة من الأدوات المساعدة للمطورين التي تساعد على إنشاء قوائم متجر بجودة عالية لامتدادات Chrome."},"features":{"en":["Generates clear and descriptive titles for Chrome extensions","Crafts concise and unique summaries for improved visibility","Supports one-click copy for Event Slug and Market Slug","Provides page highlight debugging for efficient development","Follows best practices for title and summary fields to avoid keyword-stuffing"],"zh":["支持一键复制Event Slug / Market Slug","页面高亮调试功能","清晰且具有描述性的标题","简洁且唯一的摘要","关键词优化"],"ja":["イベントスラッグ / マーケットスラッグの一括コピー","ページハイライトデバッグ機能","明確で記述的なタイトル","簡潔で一意のサマリー","キーワード最適化"],"ko":["이벤트 슬러그 / 마켓 슬러그 일괄 복사","페이지 하이라이트 디버깅 기능","명확하고 설명적인 제목","간결하고 고유한 요약","키워드 최적화"],"es":["Título claro y descriptivo para la lista de chrome-webstore-listing","Resumen conciso y único para la lista de chrome-webstore-listing","Utilidades de copia de un clic para Event Slug y Market Slug","Depuración de resaltado de página para desarrolladores","Compatibilidad con polymarket.com"],"fr":["Titre clair et descriptif pour la liste de chrome-webstore-listing","Résumé concis et unique pour la liste de chrome-webstore-listing","Utilitaires de copie d''un clic pour Event Slug et Market Slug","Débogage de mise en surbrillance de page pour les développeurs","Compatibilité avec polymarket.com"],"de":["Klarer und beschreibender Titel für die chrome-webstore-listing-Liste","Konziser und eindeutiger Zusammenfassung für die chrome-webstore-listing-Liste","Ein-Klick-Kopie-Utilitys für Event Slug und Market Slug","Seitenauszeichnungs-Debugging für Entwickler","Kompatibilität mit polymarket.com"],"pt":["Título claro e descritivo para a extensão do Chrome","Resumo conciso e único para a página de lista","Uso de campos de texto para destacar recursos importantes","Evitar palavras-chave em excesso para nomes de extensões","Uso de recursos de depuração para melhorar a experiência do usuário"],"ru":["Ясное и описательное название расширения Chrome","Краткое и уникальное описание страницы листинга","Использование текстовых полей для выделения важных функций","Избегание избыточного использования ключевых слов в названиях расширений","Использование функций отладки для улучшения пользовательского опыта"],"ar":["عنوان واضح ومفصّل لامتداد Chrome","ملخص موجز وفريد للقائمة","استخدام حقول النص لتوضيح المزايا المهمة","تجنب استخدام الكلمات الرئيسية بشكل زائد في أسماء الامتدادات","استخدام ميزات التصحيح لتحسين تجربة المستخدم"]},"keywords":{"en":["how to use chrome-webstore-listing","what is chrome-webstore-listing","chrome-webstore-listing best practices","chrome-webstore-listing setup guide","chrome-webstore-listing vs other tools","chrome-webstore-listing alternative","chrome-webstore-listing install","optimizing chrome web store listings","chrome extension development tools"],"zh":["Chrome网上应用店listing","AI工具","扩展程序开发","标题优化","摘要优化","关键词优化","页面高亮调试","一键复制Event Slug"],"ja":["Chrome Web Store リスティング","AIエージェント","拡張機能開発","タイトル最適化","サマリー最適化","キーワード最適化","ページハイライトデバッグ","イベントスラッグの一括コピー"],"ko":["Chrome 웹 스토어 목록","AI 도구","확장 프로그램 개발","제목 최적화","요약 최적화","키워드 최적화","페이지 하이라이트 디버깅","이벤트 슬러그 일괄 복사"],"es":["chrome web store listing","desarrollo de extensiones","herramientas para desarrolladores","polymarket.com","ai agentes","utilidades de copia de un clic","depuración de resaltado de página"],"fr":["chrome web store listing","développement d''extensions","outils pour développeurs","polymarket.com","agents d''IA","utilitaires de copie d''un clic","débogage de mise en surbrillance de page"],"de":["chrome web store listing","erweiterungsentwicklung","tools für entwickler","polymarket.com","künstliche intelligenz agenten","ein-klick-kopie-utilitys","seitenauszeichnungs-debugging"],"pt":["chrome-webstore-listing","melhores práticas para desenvolvedores","criar lista de loja de alta qualidade","extensões do Chrome","utilitários para desenvolvedores","iot de lista de loja","otimização de lista de loja"],"ru":["chrome-webstore-listing","лучшие практики для разработчиков","создание высококачественной страницы листинга","расширения Chrome","утилиты для разработчиков","ИИ Агенты для листинга","оптимизация листинга"],"ar":["chrome-webstore-listing","أفضل الممارسات للمطورين","إنشاء قائمة متجر بجودة عالية","امتدادات Chrome","أدوات مساعدة للمطورين","وكلاء الذكاء الاصطناعي للقوائم","تحسين القوائم"]}},"owner":"aquarius-wing","repo":"polymarket-dev-tools","repoPath":"aquarius-wing/polymarket-dev-tools","stars":0,"forks":0,"updatedAt":"2026-02-21T07:06:42Z","topics":[],"category":"community","skillMd":{"name":"chrome-webstore-listing","description":"Guides creation and optimization of Chrome Web Store listing assets including title, summary, description, icons, screenshots, and promotional images. Use when preparing, reviewing, or improving a Chrome extensions store listing page, writing copy for the Web Store, or when the user mentions store listing, CWS listing, extension description, promo tiles, or screenshots.","bodyPreview":"# Chrome Web Store Listing\n\nBest practices for building a compelling, high-quality store listing.\n\n## Text Fields\n\n### Title\n- Clear and descriptive — users should understand the extension''s core function at a glance\n- Concise and unique\n- **Don''t** keyword-stuff; short, catchy names are more memorable\n\n### Summary (≤132 chars, plain text)\n- Primary copy shown on homepage, category pages, and search results\n- Lead with the most important feature/use case\n- **Don''t** use superlatives (\"best\", \"fa","body":"# Chrome Web Store Listing\n\nBest practices for building a compelling, high-quality store listing.\n\n## Text Fields\n\n### Title\n- Clear and descriptive — users should understand the extension''s core function at a glance\n- Concise and unique\n- **Don''t** keyword-stuff; short, catchy names are more memorable\n\n### Summary (≤132 chars, plain text)\n- Primary copy shown on homepage, category pages, and search results\n- Lead with the most important feature/use case\n- **Don''t** use superlatives (\"best\", \"fastest\", \"greatest\") or reference competitors\n\n### Description\nFormat: **overview paragraph → bullet list of main features**\n\n- Concise, informative, accurate — more than one sentence\n- Focus on features users unlock after installing\n- Avoid typos, excessive symbols, and keyword stuffing (risks suspension under Keyword Spam policy)\n- **Don''t** add irrelevant keywords to game search results\n\n## Images\n\n### Store Icon\n- Simple, recognizable, brand-consistent\n- **Don''t** include screenshots or UI elements (illegible at small sizes)\n- Follow [extension icon best practices](https://developer.chrome.com/docs/webstore/images#icon)\n\n### Screenshots (minimum 1, up to 5)\n- Size: **1280×800** or **640×400** px, square corners, no padding (full bleed)\n- Show actual UX focused on core features; keep up to date with latest version\n- Use visual aids (infographics, callouts) to explain onboarding and key flows\n- **Don''t** use blurry, rotated, or distorted images; avoid overwhelming text\n- Branding must be consistent with icon and promo images\n\n### Small Promo Tile — 440×280 px\n- Appears on homepage, category pages, search results\n- Keep simple: saturated colors, well-defined edges, fill entire region\n- **Don''t** use excessive text, \"busy\" imagery, or misleading badges (\"Editor''s Choice\", \"#1\")\n\n### Marquee Image — 1400×560 px\n- Used if featured in the rotating carousel on the CWS homepage\n- Must remain uncluttered and look good at half size\n- Consistent branding with other listing assets\n- Avoid lots of white/light gray; avoid misleading claims\n\n## Additional Fields\nFill in **website URL** and **support URL** in the developer dashboard — these build user trust.\n\n## Quality Ranking Factors\nItems are ranked by ratings, download/uninstall ratio, and:\n- Pleasant, polished design\n- Clear purpose that fills a real user need\n- Intuitive setup and onboarding\n- Ease of use\n"},"lastSynced":"2026-03-07T04:14:35.956Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing efficient Chrome Web Store listing optimization and debugging tools.","zh":"非常适合需要高效的Chrome网上应用店列表优化和调试工具的开发者代理。","ja":"Chrome Web Storeのリスト最適化およびデバッグツールを効率的に必要とするDeveloper Agentsに最適です。","ko":"効率적인 Chrome 웹 스토어 목록 최적화 및 디버깅 도구가 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan optimización y herramientas de depuración eficientes para la lista de la Chrome Web Store.","fr":"Parfait pour les agents de développement nécessitant une optimisation et des outils de débogage efficaces pour la liste de la Chrome Web Store.","de":"Perfekt für Entwickleragenten, die eine effiziente Optimierung und Debugging-Tools für die Chrome Web Store-Liste benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam de ferramentas de otimização e depuração eficientes para a lista da Chrome Web Store.","ru":"Идеально подходит для агентов-разработчиков, которым необходимы эффективные инструменты для оптимизации и отладки списка Chrome Web Store.","ar":"مثالي για وكلاء المطورين الذين يحتاجون إلى أدوات فعالة لتحسين وتصحيح قائمة Chrome Web Store."},"recommendation":{"en":"Empowers agents to create high-quality store listings with clear and descriptive titles, concise summaries, and effective debugging tools, utilizing HTML and plain text formatting to enhance user experience and search visibility.","zh":"赋予代理创建高质量的商店列表的能力，具有清晰和描述性的标题、简洁的摘要以及有效的调试工具，利用HTML和纯文本格式来增强用户体验和搜索可见性。","ja":"エージェントが明確で説明的なタイトル、簡潔なサマリー、効果的なデバッグツールを使用して、高品質のストアリストを作成できるようにし、HTMLおよびプレーンテキスト形式を使用してユーザーエクスペリエンスと検索の可視性を向上させる。","ko":"에이전트가 명확하고 설명적인 제목, 간결한 요약 및 효과적인 디버깅 도구를 사용하여 고품질의 스토어 목록을 만들 수 있도록 하며, HTML 및 평문 형식을 사용하여 사용자 경험 및 검색 가시성을 향상시킵니다.","es":"Permite a los agentes crear listas de tienda de alta calidad con títulos claros y descriptivos, resúmenes concisos y herramientas de depuración efectivas, utilizando formato de HTML y texto plano para mejorar la experiencia del usuario y la visibilidad de búsqueda.","fr":"Permet aux agents de créer des listes de magasin de haute qualité avec des titres clairs et descriptifs, des résumés concis et des outils de débogage efficaces, en utilisant le formatage HTML et le texte brut pour améliorer l''expérience utilisateur et la visibilité de recherche.","de":"Ermöglicht es Agenten, hochwertige Store-Listings mit klaren und beschreibenden Titeln, präzisen Zusammenfassungen und effektiven Debugging-Tools zu erstellen, indem HTML- und Plain-Text-Formatierung verwendet wird, um die Benutzererfahrung und Suchsichtbarkeit zu verbessern.","pt":"Habilita os agentes a criar listas de loja de alta qualidade com títulos claros e descritivos, resumos concisos e ferramentas de depuração eficazes, utilizando formatação HTML e texto simples para melhorar a experiência do usuário e a visibilidade de pesquisa.","ru":"Наделяет агентов возможностью создавать качественные списки магазина с четкими и описательными заголовками, краткими резюме и эффективными инструментами отладки, используя форматирование HTML и простой текст для улучшения пользовательского опыта и видимости поиска.","ar":"تمكن الوكلاء من إنشاء قوائم متجر عالية الجودة مع عناوين واضحة وصفية وملخصات موجزة وأدوات فحص فعالة، باستخدام تنسيق HTML والنص العادي لتحسين تجربة المستخدم ووضوح البحث."},"useCases":{"en":["Debugging page highlights for improved development efficiency","Generating one-click copies for Event Slug and Market Slug","Optimizing store listing text fields for better user engagement"],"zh":["用于提高开发效率的页面调试突出显示","用于事件Slug和市场Slug的单击复制生成","优化商店列表文本字段以提高用户参与度"],"ja":["開発効率の向上のためのページデバッグの強調表示","イベントスラッグおよびマーケットスラッグのワンクリックコピー生成","ストアリストテキストフィールドの最適化によるユーザー関与の向上"],"ko":["개발 효율성 향상을 위한 페이지 디버깅 하이라이트","이벤트 슬러그 및 시장 슬러그를 위한 한 클릭 복사 생성","사용자 참여도 향상을 위한 스토어 목록 텍스트 필드 최적화"],"es":["Depuración de resaltados de página para una mayor eficiencia en el desarrollo","Generación de copias de un solo clic para Event Slug y Market Slug","Optimización de campos de texto de la lista de la tienda para una mejor participación del usuario"],"fr":["Débogage des highlights de page pour une meilleure efficacité de développement","Génération de copies en un seul clic pour Event Slug et Market Slug","Optimisation des champs de texte de la liste de magasin pour une meilleure implication de l''utilisateur"],"de":["Debugging von Seitenhervorhebungen für verbesserte Entwicklungseffizienz","Generierung von Ein-Klick-Kopien für Event Slug und Market Slug","Optimierung von Textfeldern der Store-Liste für eine bessere Benutzerverbindung"],"pt":["Depuração de realces de página para melhoria da eficiência de desenvolvimento","Geração de cópias de um clique para Event Slug e Market Slug","Otimização dos campos de texto da lista da loja para melhor engajamento do usuário"],"ru":["Отладка страницы подсветки для повышения эффективности разработки","Генерация копий в один клик для Event Slug и Market Slug","Оптимизация полей текста списка магазина для лучшего взаимодействия с пользователем"],"ar":["تصحيح الأخطاء في تنسيق صفحة لتحسين كفاءة التطوير","إنشاء نسخ من خلال نقرة واحدة لنص حدث Slug ونص سوق Slug","تحسين حقول نص قائمة المتجر لتعزيز تفاعل المستخدم"]},"limitations":{"en":["Requires access to polymarket.com pages","Limited to Chrome Web Store listing optimization"],"zh":["需要访问polymarket.com页面","仅限于Chrome Web Store列表优化"],"ja":["polymarket.comページへのアクセスが必要","Chrome Web Storeリスト最適化のみ"],"ko":["polymarket.com 페이지에 대한 액세스가 필요합니다.","Chrome 웹 스토어 목록 최적화만 해당"],"es":["Requiere acceso a páginas de polymarket.com","Limitado a la optimización de la lista de la Chrome Web Store"],"fr":["Nécessite un accès aux pages de polymarket.com","Limité à l''optimisation de la liste de la Chrome Web Store"],"de":["Benötigt Zugriff auf polymarket.com-Seiten","Begrenzt auf die Optimierung der Chrome Web Store-Liste"],"pt":["Requer acesso às páginas do polymarket.com","Limitado à otimização da lista da Chrome Web Store"],"ru":["Требует доступа к страницам polymarket.com","Ограничен оптимизацией списка Chrome Web Store"],"ar":["يتطلب الوصول إلى صفحات polymarket.com","محدود بتحسين قائمة Chrome Web Store"]},"version":4},"contentHash":"8dea6749642314d5ceae973944b577af2964be9d79e4958ed380633e7c0ae03b","qualityScore":20}');
