INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aquarius-wing/polymarket-dev-tools/chrome-webstore-listing', 'chrome-webstore-listing', 'aquarius-wing', 'polymarket-dev-tools', 'community', 'chrome-webstore-listing aquarius-wing polymarket-dev-tools community The chrome-webstore-listing skill provides utilities for developers on polymarket.com pages, such as one-click copy for Event Slug and Market Slug, and page highlight debugging for improved development efficiency 创建高质量的Chrome网上应用店listing，包括标题、摘要和关键词优化 Chrome Web Store リスティングを最適化するためのベストプラクティス - タイトル、サマリー、キーワード最適化 Chrome 웹 스토어 목록을 최적화하는 방법 - 제목, 요약, 키워드 최적화 포함 La lista de chrome-webstore-listing ofrece utilidades para desarrolladores en polymarket.com, como copia de un clic para Event Slug y Market Slug La liste de chrome-webstore-listing propose des utilitaires pour les développeurs sur polymarket.com, tels que la copie d''un clic pour Event Slug et Market Slug Die chrome-webstore-listing-Liste bietet Entwicklern auf polymarket.com Utilitys wie Ein-Klick-Kopie für Event Slug und Market Slug A lista de loja do Chrome é fundamental para o sucesso da sua extensão. Nossa guia de melhores práticas para chrome-webstore-listing ajuda a criar uma lista de alta qualidade. Страница листинга в магазине Chrome имеет решающее значение для успеха вашего расширения. Наше руководство по chrome-webstore-listing для ИИ Агентов поможет создать высококачественную страницу. قائمة متجر Chrome هي أساسية لنجاح امتدادك. دليل أفضل الممارسات لchrome-webstore-listing يساعد على إنشاء قائمة بجودة عالية. how to use chrome-webstore-listing what is chrome-webstore-listing chrome-webstore-listing best practices chrome-webstore-listing setup guide chrome-webstore-listing vs other tools chrome-webstore-listing alternative chrome-webstore-listing install optimizing chrome web store listings chrome extension development tools Chrome网上应用店listing AI工具 扩展程序开发 标题优化 摘要优化 关键词优化 页面高亮调试 一键复制Event Slug Generates clear and descriptive titles for Chrome extensions Crafts concise and unique summaries for improved visibility Supports one-click copy for Event Slug and Market Slug Provides page highlight debugging for efficient development Follows best practices for title and summary fields to avoid keyword-stuffing chrome-webstore-listing is a set of developer-focused utilities for optimizing Chrome Web Store listings, including title and summary fields');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('clairifyai/documentation/new-release', 'community', 'clairifyai', 'documentation', 'clairifyai/documentation', 'new-release', 0, 0, 20, '2026-03-05T22:26:27Z', '2026-03-07T04:19:03.143Z', 'e0333a97c17acf07516e081b034347152fcca7d7cdc49715f756a2175b474da1', '{"id":"clairifyai/documentation/new-release","name":"new-release","description":{"en":"The new-release skill automates the creation of release notes for new versions, benefiting developers by simplifying the documentation process. It creates a new branch and file using the provided content.","zh":"新版本技能帮助您自动创建发布说明，通过创建新分支和文件，简化版本管理流程","ja":"新しいリリースのための自動化されたリリースノートの作成：新しいブランチとファイルを作成してバージョン管理を簡素化","ko":"새 릴리스 노트를 자동으로 생성하여 버전 관리를 간소화하는 새 버전 스킬","es":"El nuevo skill new-release permite a los desarrolladores crear notas de versión automatizadas con ramas y archivos Markdown personalizados.","fr":"Le nouveau skill new-release permet aux développeurs de créer des notes de version automatisées avec des branches et des fichiers Markdown personnalisés.","de":"Das neue Skill new-release ermöglicht es Entwicklern, automatisierte Versionshinweise mit benutzerdefinierten Branches und Markdown-Dateien zu erstellen.","pt":"O new-release é uma ferramenta que ajuda a criar notas de lançamento para novas versões, utilizando tecnologias como mkdocs e Git.","ru":"new-release - это инструмент, который помогает создать заметки о выпуске для новых версий, используя технологии như mkdocs и Git.","ar":"new-release هو أداة تساعد في إنشاء ملاحظات الإصدار للنسخ الجديدة، باستخدام تقنيات مثل mkdocs و Git."},"seo":{"title":{"en":"new-release: Automated Release Notes Setup Guide | AI Age...","zh":"新版本发布指南：自动创建发布说明","ja":"新しいリリースのためのセットアップガイド：AIエージェント","ko":"새 릴리스 노트 생성 가이드: 버전 관리 자동화","es":"Guía de configuración de new-release para notas de versión","fr":"Guide de configuration de new-release pour les notes de v...","de":"Konfigurationsleitfaden für new-release zur Erstellung vo...","pt":"Guia de Configuração do new-release: Crie Notas de Lançam...","ru":"Настройка new-release: Создание заметок о выпуске с помощ...","ar":"دليل إعداد new-release: إنشاء ملاحظات الإصدار باستخدام أد..."},"description":{"en":"Streamline your release process with new-release AI agent skill. Learn how to automate release notes creation and update mkdocs.yml with ease.","zh":"使用新版本技能，自动创建发布说明，简化版本管理流程，提高开发效率","ja":"新しいリリースのための自動化されたリリースノートの作成：AIエージェントを使用して開発の生産性を向上","ko":"새 릴리스 노트를 자동으로 생성하여 버전 관리를 간소화하고 개발 효율성을 높입니다","es":"Aprende a configurar new-release para crear notas de versión automatizadas conramas y archivos Markdown personalizados","fr":"Découvrez comment configurer new-release pour créer des notes de version automatisées avec des branches et des fichiers Markdown personnalisés","de":"Erfahren Sie, wie Sie new-release konfigurieren, um automatisierte Versionshinweise mit benutzerdefinierten Branches und Markdown-Dateien zu erstellen","pt":"Aprenda a criar notas de lançamento para novas versões com o new-release, utilizando tecnologias como mkdocs e Git","ru":"Узнайте, как создать заметки о выпуске для новых версий с помощью new-release, используя технологии như mkdocs и Git","ar":"تعرف على كيفية إنشاء ملاحظات الإصدار للنسخ الجديدة مع new-release، باستخدام تقنيات مثل mkdocs و Git"},"definition":{"en":"new-release is an AI agent skill that automates the creation of release notes for new software versions, following a standardized format.","zh":"新版本技能是一种自动创建发布说明的工具，帮助开发者简化版本管理流程","ja":"新しいリリーススキルは、開発者がバージョン管理プロセスを簡素化するために自動化されたリリースノートを作成するツールです","ko":"새 버전 스킬은 자동으로 릴리스 노트를 생성하여 개발자가 버전 관리 프로세스를 간소화하는 도구입니다","es":"new-release es una herramienta de AI que crea notas de versión automatizadas con ramas y archivos Markdown personalizados","fr":"new-release est un outil d''IA qui crée des notes de version automatisées avec des branches et des fichiers Markdown personnalisés","de":"new-release ist ein AI-Tool, das automatisierte Versionshinweise mit benutzerdefinierten Branches und Markdown-Dateien erstellt","pt":"O new-release é uma ferramenta de Inteligência Artificial que cria notas de lançamento para novas versões","ru":"new-release - это ИИ Агент, который создает заметки о выпуске для новых версий","ar":"new-release هو أداة ذكاء اصطناعي لإنشاء ملاحظات الإصدار للنسخ الجديدة"},"features":{"en":["Creates a new branch named `release-notes/$ARGUMENTS` for organized version control","Generates a new file at `docs/release-notes/rn-$ARGUMENTS.md` with formatted release note content","Updates `mkdocs.yml` to include the new release notes file","Removes dots from version numbers for consistent file naming","Formats release notes to match the style of existing documents, such as `docs/release-notes/rn-300.md`"],"zh":["自动创建新分支","创建发布说明文件","更新mkdocs.yml文件","支持版本号格式化","简化版本管理流程"],"ja":["新しいブランチの自動作成","リリースノートファイルの作成","mkdocs.ymlファイルの更新","バージョン番号のフォーマット対応","バージョン管理プロセスの簡素化"],"ko":["새 브랜치 자동 생성","릴리스 노트 파일 생성","mkdocs.yml 파일 업데이트","버전 번호 형식 지원","버전 관리 프로세스 간소화"],"es":["Creación de ramas personalizadas con nombres de versión","Generación de archivos Markdown para notas de versión","Actualización automática de mkdocs.yml","Compatibilidad con versiones de software con números de versión personalizados","Integración con flujos de trabajo de desarrollo existentes"],"fr":["Création de branches personnalisées avec des noms de version","Génération de fichiers Markdown pour les notes de version","Mise à jour automatique de mkdocs.yml","Compatibilité avec des versions de logiciels à des numéros de version personnalisés","Intégration avec des flux de travail de développement existants"],"de":["Erstellung von benutzerdefinierten Branches mit Versionsnamen","Generierung von Markdown-Dateien für Versionshinweise","Automatische Aktualisierung von mkdocs.yml","Kompatibilität mit Softwareversionen mit benutzerdefinierten Versionsnummern","Integration in bestehende Entwicklungswerkflüsse"],"pt":["Criação de notas de lançamento para novas versões","Utilização de tecnologias como mkdocs e Git","Criação de branches e arquivos para notas de lançamento","Formatação de conteúdo para notas de lançamento","Atualização de arquivos de configuração como mkdocs.yml"],"ru":["Создание заметок о выпуске для новых версий","Использование технологий как mkdocs и Git","Создание веток и файлов для заметок о выпуске","Форматирование контента для заметок о выпуске","Обновление файлов конфигурации как mkdocs.yml"],"ar":["إنشاء ملاحظات الإصدار للنسخ الجديدة","استخدام تقنيات مثل mkdocs و Git","إنشاء فروع وملفات لملاحظات الإصدار","تنسيق المحتوى لملاحظات الإصدار","تحديث ملفات التهيئة مثل mkdocs.yml"]},"keywords":{"en":["how to use new-release","new-release setup guide","automated release notes creation","new-release alternative","new-release vs manual documentation","mkdocs.yml update","release notes best practices","new-release install","software version control"],"zh":["新版本技能","自动创建发布说明","版本管理","开发工具","AIエージェント","自动化版本管理","简化版本管理","开发效率"],"ja":["新しいリリーススキル","自動化されたリリースノートの作成","バージョン管理","開発ツール","AIエージェント","自動化バージョン管理","バージョン管理の簡素化","開発の生産性"],"ko":["새 버전 스킬","自动으로 릴리스 노트 생성","버전 관리","개발 도구","AI 에이전트","자동화 버전 관리","버전 관리 프로세스 간소화","개발 효율성"],"es":["new-release","notas de versión","ramas personalizadas","archivos Markdown","mkdocs.yml","versions de software","desarrollo de software","herramientas de AI","automatización de tareas"],"fr":["new-release","notes de version","branches personnalisées","fichiers Markdown","mkdocs.yml","versions de logiciel","développement de logiciel","outils d''IA","automatisation de tâches"],"de":["new-release","Versionshinweise","benutzerdefinierte Branches","Markdown-Dateien","mkdocs.yml","Softwareversionen","Softwareentwicklung","AI-Tools","Automatisierung von Aufgaben"],"pt":["new-release","notas de lançamento","mkdocs","Git","ferramentas de Inteligência Artificial","criação de notas de lançamento","configuração de new-release"],"ru":["new-release","заметки о выпуске","mkdocs","Git","ИИ Агенты","создание заметок о выпуске","настройка new-release"],"ar":["new-release","ملاحظات الإصدار","mkdocs","Git","أدوات الذكاء الاصطناعي","إنشاء ملاحظات الإصدار","تهيئة new-release"]}},"owner":"clairifyai","repo":"documentation","repoPath":"clairifyai/documentation","stars":0,"forks":0,"updatedAt":"2026-03-05T22:26:27Z","topics":[],"category":"community","skillMd":{"name":"new-release","description":"Creates release notes for a new version of Clairify","bodyPreview":"The user wants to create release notes for a new version. The version number is: $ARGUMENTS\n\nFollow these steps:\n\n1. Ask the user to paste in the release note content.\n2. Create a new branch named `release-notes/$ARGUMENTS`.\n3. Create a new file at `docs/release-notes/rn-$ARGUMENTS.md` (remove dots from the version number, e.g. 4.0.0 → rn-400.md) using the content provided, formatted to match the style of `docs/release-notes/rn-300.md`.\n4. Update `mkdocs.yml` to add the new release notes file at","body":"The user wants to create release notes for a new version. The version number is: $ARGUMENTS\n\nFollow these steps:\n\n1. Ask the user to paste in the release note content.\n2. Create a new branch named `release-notes/$ARGUMENTS`.\n3. Create a new file at `docs/release-notes/rn-$ARGUMENTS.md` (remove dots from the version number, e.g. 4.0.0 → rn-400.md) using the content provided, formatted to match the style of `docs/release-notes/rn-300.md`.\n4. Update `mkdocs.yml` to add the new release notes file at the top of the \"Release Notes\" nav section.\n5. Run `conda run -n docs mkdocs serve` in the background so the user can preview the changes at http://127.0.0.1:8000.\n6. Tell the user the site is ready to preview and ask if they''d like to make any changes.\n"},"lastSynced":"2026-03-07T04:19:03.143Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated documentation and version control management.","zh":"适用于需要自动化文档和版本控制管理的开发代理。","ja":"自動化ドキュメントとバージョン管理が必要な開発エージェントに最適です。","ko":"자동화된 문서 및 버전 관리가 필요한 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren documentación automatizada y administración de control de versiones.","fr":"Idéal pour les agents de développement nécessitant une documentation automatisée et une gestion de contrôle de version.","de":"Ideal für Entwicklungsmittel benötigende automatisierte Dokumentation und Versionenkontrollmanagement.","pt":"Ideal para Agentes de Desenvolvimento que exigem documentação automatizada e gerenciamento de controle de versão.","ru":"Идеально для агентов разработки, требующих автоматизированной документации и управления контролем версий.","ar":"مثالي لعميل التطوير الذين يتطلبون توثيقًا أوتوماتيكيًا وإدارة التحكم الإصدار."},"recommendation":{"en":"Empowers agents to automate release note creation using Markdown formatting and version control branching, streamlining the documentation process with precise file naming conventions and updates to mkdocs.yml for seamless integration.","zh":"使代理能够使用Markdown格式和版本控制分支自动创建发布说明，通过精确的文件命名约定和对mkdocs.yml的更新来简化文档流程，从而实现无缝集成。","ja":"エージェントがMarkdown形式とバージョン管理ブランチを使用してリリースノートの作成を自動化できるようにし、ファイル命名規則の正確さとmkdocs.ymlへの更新により、ドキュメントのプロセスを簡素化し、シームレスな統合を実現します。","ko":"에이전트가 Markdown 형식 및 버전 관리 분기를 사용하여 릴리스 노트 생성을 자동화할 수 있도록 하여, 파일命명 규칙의 정확성 및 mkdocs.yml에 대한 업데이트로 문서 프로세스를 간소화하고, 무중단 통합을 달성합니다.","es":"Habilita a los agentes a automatizar la creación de notas de lanzamiento utilizando formato Markdown y ramificación de control de versiones, racionalizando el proceso de documentación con convenciones de nombramiento de archivos precisas y actualizaciones a mkdocs.yml para una integración sin problemas.","fr":"Permet aux agents d''automatiser la création de notes de version en utilisant le formatage Markdown et la gestion de branches de contrôle de version, rationalisant ainsi le processus de documentation avec des conventions de nommage de fichiers précises et des mises à jour de mkdocs.yml pour une intégration sans problème.","de":"Ermöglicht es Agenten, die Erstellung von Versionshinweisen mithilfe von Markdown-Formatierung und Versionskontroll-Branching zu automatisieren, strafft so den Dokumentationsprozess mit präzisen Dateinamenskonventionen und Aktualisierungen von mkdocs.yml für eine nahtlose Integration.","pt":"Habilita os agentes a automatizar a criação de notas de lançamento usando formatação Markdown e ramificação de controle de versão, simplificando o processo de documentação com convenções de nomenclatura de arquivos precisas e atualizações para mkdocs.yml para integração sem problemas.","ru":"Наделяет агентов возможностью автоматизировать создание заметок о выпуске с помощью форматирования Markdown и ветвления контроля версий, оптимизируя процесс документации с точными соглашениями об именовании файлов и обновлениями для mkdocs.yml для бесшовной интеграции.","ar":"تمكّن الوكلاء من توفير ملاحظات إصدار باستخدام تنسيق Markdown وفرع التحكم في الإصدار، مبسطًا عملية التوثيق مع اتفاقيات命名 الملفات الدقيقة وتحديثات mkdocs.yml من أجل التكامل السلس."},"useCases":{"en":["Automating release note generation for new software versions","Creating and managing version-controlled branches for release notes","Updating documentation configurations with new release notes files"],"zh":["为新的软件版本自动生成发布说明","为发布说明创建和管理版本控制分支","使用新的发布说明文件更新文档配置"],"ja":["新しいソフトウェアバージョンの自動リリースノート生成","リリースノートのバージョン管理ブランチの作成と管理","新しいリリースノートファイルを使用したドキュメント構成の更新"],"ko":["새로운 소프트웨어 버전에 대한 자동 릴리스 노트 생성","릴리스 노트를 위한 버전 관리 분기 생성 및 관리","새로운 릴리스 노트 파일을 사용한 문서 구성 업데이트"],"es":["Automatizar la generación de notas de lanzamiento para nuevas versiones de software","Crear y administrar ramas controladas por versiones para notas de lanzamiento","Actualizar configuraciones de documentación con nuevos archivos de notas de lanzamiento"],"fr":["Automatiser la génération de notes de version pour les nouvelles versions de logiciels","Créer et gérer des branches contrôlées par version pour les notes de version","Mettre à jour les configurations de documentation avec de nouveaux fichiers de notes de version"],"de":["Automatisieren der Generierung von Versionshinweisen für neue Softwareversionen","Erstellen und Verwalten von versionskontrollierten Branches für Versionshinweise","Aktualisieren von Dokumentationskonfigurationen mit neuen Versionshinweisen-Dateien"],"pt":["Automatizar geração de notas de lançamento para novas versões de software","Criar e gerenciar branches controlados por versão para notas de lançamento","Atualizar configurações de documentação com novos arquivos de notas de lançamento"],"ru":["Автоматизировать генерацию заметок о выпуске для новых версий программного обеспечения","Создавать и управлять ветвями, контролируемыми версией, для заметок о выпуске","Обновлять конфигурации документации с новыми файлами заметок о выпуске"],"ar":["توفير ملاحظات إصدار آليًا لنسخ جديدة من البرمجيات","إنشاء وإدارة فروعควบคلة الإصدار للملاحظات الإصدار","تحديث إعدادات التوثيق مع ملفات ملاحظات إصدار جديدة"]},"limitations":{"en":["Requires access to version control systems like Git","Limited to Markdown file format","Needs specific directory structure for release notes"],"zh":["需要访问Git等版本控制系统","仅限Markdown文件格式","需要特定的目录结构来存储发布说明"],"ja":["Gitなどのバージョン管理システムへのアクセスが必要","Markdownファイル形式のみの対応","リリースノートを保存するための特定のディレクトリ構造が必要"],"ko":["Git과 같은 버전 관리 시스템에 대한 액세스가 필요합니다","Markdown 파일 형식만 해당","릴리스 노트를 저장하기 위한 특정 디렉토리 구조가 필요합니다"],"es":["Requiere acceso a sistemas de control de versiones como Git","Limitado al formato de archivo Markdown","Necesita una estructura de directorio específica para las notas de lanzamiento"],"fr":["Nécessite un accès à des systèmes de contrôle de version tels que Git","Limité au format de fichier Markdown","Nécessite une structure de répertoire spécifique pour les notes de version"],"de":["Benötigt Zugriff auf Versionskontrollsysteme wie Git","Begrenzt auf Markdown-Dateiformat","Benötigt eine spezifische Verzeichnisstruktur für Versionshinweise"],"pt":["Exige acesso a sistemas de controle de versão como Git","Limitado ao formato de arquivo Markdown","Necessita de estrutura de diretório específica para notas de lançamento"],"ru":["Требует доступа к системам контроля версий, таким как Git","Ограничен форматом файла Markdown","Требует конкретной структуры директории для заметок о выпуске"],"ar":["يتطلب الوصول إلى أنظمة التحكم في الإصدار مثل Git","محدود بتنسيق ملف Markdown","يحتاج إلى هيكل دلالي محدد للملاحظات الإصدار"]},"version":4},"contentHash":"e0333a97c17acf07516e081b034347152fcca7d7cdc49715f756a2175b474da1","qualityScore":20}');
