INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('clairifyai/documentation/new-release', 'new-release', 'clairifyai', 'documentation', 'community', 'new-release clairifyai documentation community The new-release skill automates the creation of release notes for new versions, benefiting developers by simplifying the documentation process. It creates a new branch and file using the provided content. 新版本技能帮助您自动创建发布说明，通过创建新分支和文件，简化版本管理流程 新しいリリースのための自動化されたリリースノートの作成：新しいブランチとファイルを作成してバージョン管理を簡素化 새 릴리스 노트를 자동으로 생성하여 버전 관리를 간소화하는 새 버전 스킬 El nuevo skill new-release permite a los desarrolladores crear notas de versión automatizadas con ramas y archivos Markdown personalizados. Le nouveau skill new-release permet aux développeurs de créer des notes de version automatisées avec des branches et des fichiers Markdown personnalisés. Das neue Skill new-release ermöglicht es Entwicklern, automatisierte Versionshinweise mit benutzerdefinierten Branches und Markdown-Dateien zu erstellen. O new-release é uma ferramenta que ajuda a criar notas de lançamento para novas versões, utilizando tecnologias como mkdocs e Git. new-release - это инструмент, который помогает создать заметки о выпуске для новых версий, используя технологии như mkdocs и Git. new-release هو أداة تساعد في إنشاء ملاحظات الإصدار للنسخ الجديدة، باستخدام تقنيات مثل mkdocs و Git. how to use new-release new-release setup guide automated release notes creation new-release alternative new-release vs manual documentation mkdocs.yml update release notes best practices new-release install software version control 新版本技能 自动创建发布说明 版本管理 开发工具 AIエージェント 自动化版本管理 简化版本管理 开发效率 Creates a new branch named `release-notes/$ARGUMENTS` for organized version control Generates a new file at `docs/release-notes/rn-$ARGUMENTS.md` with formatted release note content Updates `mkdocs.yml` to include the new release notes file Removes dots from version numbers for consistent file naming Formats release notes to match the style of existing documents, such as `docs/release-notes/rn-300.md` new-release is an AI agent skill that automates the creation of release notes for new software versions, following a standardized format.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stakiran/collaboration-modules/random', 'community', 'stakiran', 'collaboration-modules', 'stakiran/collaboration-modules', 'random', 0, 0, 20, '2026-03-06T12:59:22.244Z', '2026-03-06T14:30:38.972Z', 'd409fa221eafe190b4280757eac6213e8683b166cc7c0989722fa81619d326cc', '{"id":"stakiran/collaboration-modules/random","name":"random","description":{"en":"The random skill provides conceptual tools for flexible collaboration, allowing users to pick up collaboration modules randomly. It benefits developers by streamlining module selection.","zh":"随机协作模块提供了灵活的团队合作解决方案，通过随机选取协作模块，实现高效的开发流程","ja":"ランダムコラボレーションモジュールは、柔軟なチーム協業のための解決策を提供し、ランダムにコラボレーションモジュールを選択することで効率的な開発プロセスを実現","ko":"랜덤 협업 모듈은 유연한 팀 협력을 위한 솔루션을 제공하며, 랜덤으로 협업 모듈을 선택하여 효율적인 개발 프로세스를 구현","es":"El módulo de colaboración aleatorio selecciona herramientas de colaboración de forma aleatoria, permitiendo una mayor flexibilidad en los proyectos","fr":"Le module de collaboration aléatoire sélectionne des outils de collaboration de manière aléatoire, permettant une plus grande flexibilité dans les projets","de":"Das zufällige Kollaborationsmodul wählt Kollaborations-Tools zufällig aus, wodurch eine größere Flexibilität in den Projekten ermöglicht wird","pt":"O módulo aleatório permite a colaboração flexível, selecionando módulos de colaboração de forma aleatória","ru":"Модуль случайного выбора позволяет гибко сотрудничать, выбирая модули сотрудничества случайным образом","ar":"الوحدة العشوائية تسمح بالتعاون المرن، حيث تقوم باختيار وحدات التعاون بشكل عشوائي"},"seo":{"title":{"en":"random: Flexible Collaboration Module Picker | AI Agent S...","zh":"随机协作模块设置指南","ja":"ランダムコラボレーションモジュールのベストプラクティス","ko":"랜덤 협업 모듈 구축 가이드","es":"Guía de configuración de herramientas de colaboración ale...","fr":"Guide de mise en place d''outils de collaboration aléatoires","de":"Einrichtungsleitfaden für zufällige Kollaborations-Tools","pt":"Guia de Configuração do Módulo Aleatório para Colaboração...","ru":"Настройка модуля случайного выбора для гибкого сотрудниче...","ar":"دليل إعداد الوحدة العشوائية للتعاون المرن لأدوات الذكاء ا..."},"description":{"en":"Discover how to leverage random for efficient collaboration module selection - learn how to pick up modules randomly and streamline your workflow today!","zh":"了解如何使用随机协作模块实现灵活的团队合作，提高开发效率","ja":"ランダムコラボレーションモジュールを使用して柔軟なチーム協業を実現する方法を学ぶ","ko":"랜덤 협업 모듈을 사용하여 유연한 팀 협력을 구현하고 개발 효율성을 높이는 방법","es":"Aprende a utilizar herramientas de colaboración aleatorias para mejorar la flexibilidad en tus proyectos con esta guía paso a paso","fr":"Découvrez comment utiliser des outils de collaboration aléatoires pour améliorer la flexibilité de vos projets avec ce guide étape par étape","de":"Erfahren Sie, wie Sie zufällige Kollaborations-Tools verwenden können, um die Flexibilität in Ihren Projekten zu verbessern, mit diesem Schritt-für-Schritt-L...","pt":"Aprenda a utilizar o módulo aleatório para colaboração flexível, com dicas e práticas para desenvolvedores","ru":"Узнайте, как использовать модуль случайного выбора для гибкого сотрудничества в ИИ Агентах, с советами и лучшими практиками для разработчиков","ar":"تعرف على كيفية استخدام الوحدة العشوائية للتعاون المرن في أدوات الذكاء الاصطناعي، مع نصائح وأفضل الممارسات للمطورين"},"definition":{"en":"random is a skill that enables the random selection of collaboration modules, providing a flexible and efficient way to work with multiple modules.","zh":"随机协作模块是一种概念工具，用于实现灵活的团队合作","ja":"ランダムコラボレーションモジュールは、柔軟なチーム協業を実現するための概念ツール","ko":"랜덤 협업 모듈은 유연한 팀 협력을 구현하기 위한 개념 도구","es":"Herramienta de colaboración aleatoria: un módulo que selecciona herramientas de colaboración de forma aleatoria para mejorar la flexibilidad","fr":"Outil de collaboration aléatoire : un module qui sélectionne des outils de collaboration de manière aléatoire pour améliorer la flexibilité","de":"Zu