INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stakiran/collaboration-modules/random', 'random', 'stakiran', 'collaboration-modules', 'community', 'random stakiran collaboration-modules community The random skill provides conceptual tools for flexible collaboration, allowing users to pick up collaboration modules randomly. It benefits developers by streamlining module selection. 随机协作模块提供了灵活的团队合作解决方案，通过随机选取协作模块，实现高效的开发流程 ランダムコラボレーションモジュールは、柔軟なチーム協業のための解決策を提供し、ランダムにコラボレーションモジュールを選択することで効率的な開発プロセスを実現 랜덤 협업 모듈은 유연한 팀 협력을 위한 솔루션을 제공하며, 랜덤으로 협업 모듈을 선택하여 효율적인 개발 프로세스를 구현 El módulo de colaboración aleatorio selecciona herramientas de colaboración de forma aleatoria, permitiendo una mayor flexibilidad en los proyectos Le module de collaboration aléatoire sélectionne des outils de collaboration de manière aléatoire, permettant une plus grande flexibilité dans les projets Das zufällige Kollaborationsmodul wählt Kollaborations-Tools zufällig aus, wodurch eine größere Flexibilität in den Projekten ermöglicht wird O módulo aleatório permite a colaboração flexível, selecionando módulos de colaboração de forma aleatória Модуль случайного выбора позволяет гибко сотрудничать, выбирая модули сотрудничества случайным образом الوحدة العشوائية تسمح بالتعاون المرن، حيث تقوم باختيار وحدات التعاون بشكل عشوائي how to use random what is random random alternative random vs collaboration tools random install guide random setup for AI agents random for developers collaboration module picker flexible workflow tools AI工具 随机协作模块 团队合作 开发效率 协作模块 灵活合作 随机选取 开发流程 Picks up collaboration modules randomly Supports variable module count specification, defaulting to 10 Formats picked modules as ''(1-origin serial number): (module file name) | (module title name)'' Allows for efficient collaboration module management Enables random selection of modules for flexible workflow Provides a simple and efficient way to select collaboration modules random is a skill that enables the random selection of collaboration modules, providing a flexible and efficient way to work with multiple modules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('way-platform/tachograph-go/asn1', 'community', 'way-platform', 'tachograph-go', 'way-platform/tachograph-go', 'asn1', 8, 2, 20, '2026-02-24T15:25:34Z', '2026-03-06T06:49:07.160Z', '73be1f426f0bd8aa2334460eb22af8574adb55d7a263a9ee636d450c945ced5c', '{"id":"way-platform/tachograph-go/asn1","name":"asn1","description":{"en":"The asn1 skill provides a Go SDK for working with tachograph (.DDD) files, utilizing ASN.1 and its encoding rules. It benefits developers working with tachograph data.","zh":"ASN.1是一种抽象语法表示法，用于定义数据结构。该技能提供了ASN.1和其编码规则（BER/DER）的参考资料","ja":"ASN.1はデータ構造を定義するための抽象構文表現法です。このスキルでは、ASN.1とそのエンコード規則（BER/DER）に関する参考資料を提供します","ko":"ASN.1은 데이터 구조를 정의하는 데 사용되는 추상 구문 표기법입니다. 이 스킬은 ASN.1 및 BER/DER 인코딩 규칙에 대한 참조 자료를 제공합니다","es":"El SDK de Go para ASN.1 permite trabajar con archivos de tacógrafo (.DDD) y proporciona una referencia para la notación de sintaxis abstracta uno (ASN.1) y sus reglas de codificación (BER/DER).","fr":"Le SDK Go pour ASN.1 permet de travailler avec les fichiers de tachygraphe (.DDD) et fournit une référence pour la notation de syntaxe abstraite uno (ASN.1) et ses règles de codage (BER/DER).","de":"Das Go-SDK für ASN.1 ermöglicht die Arbeit mit Tachographen-Dateien (.DDD) und bietet eine Referenz für die abstrakte Syntaxnotation eins (ASN.1) und ihre Kodierungsregeln (BER/DER).","pt":"A biblioteca ASN.1 em Go fornece funcionalidades para trabalhar com arquivos tachograph (.DDD). Ela suporta tags universais como BOOLEAN, INTEGER e OCTET STRING.","ru":"Библиотека ASN.1 для языка Go обеспечивает функциональность для работы с файлами такографа (.DDD). Она поддерживает универсальные теги, такие как BOOLEAN, INTEGER и OCTET STRING, с помощью ИИ Агентов","ar":"مكتبة ASN.1 في Go توفر możliات للعمل مع ملفات التخطيط (.DDD). وهي تدعم علامات عالمية مثل BOOLEAN و INTEGER و OCTET STRING باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"asn1: Mastering ASN.1 Encoding for Tachograph Files | AI ...","zh":"ASN.1 Setup Guide for Tachograph Files","ja":"ASN.1の設定ガイド: Tachographファイル編","ko":"ASN.1 설정 가이드: Tachograph 파일","es":"Guía de configuración de ASN.1 para archivos de tacógrafo","fr":"Guide de configuration ASN.1 pour les fichiers de tachygr...","de":"ASN.1-Konfigurationsleitfaden für Tachographen-Dateien","pt":"Guia de Configuração do ASN.1 para Arquivos Tachograph (....","ru":"Руководство по настройке ASN.1 для файлов такографа (.DDD...","ar":"دليل إعداد ASN.1 لملفات التخطيط (.DDD) باستخدام أدوات الذ..."},"description":{"en":"Unlock the power of Abstract Syntax Notation One (ASN.1) for tachograph files. Learn how to work with BER and DER encoding rules with our expert guide.","zh":"了解ASN.1和其编码规则（BER/DER），并使用Go SDK处理tachograph (.DDD)文件","ja":"ASN.1とそのエンコード規則（BER/DER）について学び、Go SDKでtachograph (.DDD)ファイルを処理する","ko":"ASN.1 및 BER/DER 인코딩 규칙을 이해하고 Go SDK를 사용하여 Tachograph (.DDD) 파일을 처리합니다","es":"Aprende a trabajar con archivos de tacógrafo (.DDD) utilizando el SDK de Go para ASN.1 y descubre sus características clave","fr":"Découvrez comment travailler avec les fichiers de tachygraphe (.DDD) en utilisant le SDK Go pour ASN.1 et explorez ses fonctionnalités clés","de":"Erfahren Sie, wie Sie mit Tachographen-Dateien (.DDD) mithilfe des Go-SDK für ASN.1 arbeiten und entdecken Sie seine wichtigsten Funktionen","pt":"Aprenda a trabalhar com arquivos tachograph (.DDD) usando a biblioteca ASN.1 em Go e descubra como ela pode ajudar no desenvolvimento de aplicações","ru":"Изучите возможности библиотеки ASN.1 для работы с файлами такографа (.DDD) на языке Go и узнайте, как она может помочь в разработке приложений с помощью ИИ А...","ar":"تعرف على كيفية العمل مع ملفات التخطيط (.DDD) باستخدام مكتبة ASN.1 في Go واكتشف كيف يمكن أن تساعد في تطوير التطبيقات باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"asn1 is a set of encoding rules for Abstract Syntax Notation One (ASN.1), used for encoding data in tachograph files, including BER and DER formats.","zh":"ASN.1是一种抽象语法表示法，用于定义数据结构","ja":"ASN.1はデータ構造を定義するための抽象構文表現法です","ko":"ASN.1은 데이터 구조를 정의하는 데 사용되는 추상 구문 표기법입니다","es":"ASN.1 es una notación de sintaxis abstracta que se utiliza para describir datos en una variedad de contextos, incluyendo la codificación de archivos de tacógrafo","fr":"ASN.1 est une notation de syntaxe abstraite utilisée pour décrire des données dans une variété de contextes, notamment pour la codification de fichiers de tachygraphe","de":"ASN.1 ist eine abstrakte Syntaxnotation, die verwendet wird, um Daten in verschiedenen Kontexten zu beschreiben, einschließlich der Kodierung von Tachographen-Dateien","pt":"ASN.1 é uma notação de sintaxe abstrata que define a estrutura de dados para a comunicação de informações","ru":"ASN.1 - это абстрактная синтаксическая нотация, определяющая структуру данных для обмена информацией с помощью ИИ Агентов","ar":"ASN.1 هو نظام لترميز البيانات باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Supports BER and DER encoding rules","Provides a Go SDK for tachograph (.DDD) files","Includes reference material for Universal Tags, such as BOOLEAN and INTEGER","Enables working with SEQUENCE and SET data types","Allows encoding of PrintableString and T61String types","Supports IA5String and UTCTime data types"],"zh":["支持Universal Tags（BOOLEAN、INTEGER、BIT STRING等）","支持BER/DER编码规则","提供Go SDK用于处理tachograph (.DDD)文件","支持 PrintableString、T61String、IA5String等字符串类型","支持UTCTime时间类型"],"ja":["Universal Tags（BOOLEAN、INTEGER、BIT STRING等）をサポート","BER/DERエンコード規則をサポート","Go SDKを使用してtachograph (.DDD)ファイルを処理","PrintableString、T61String、IA5String等の文字列タイプをサポート","UTCTime時間タイプをサポート"],"ko":["Universal Tags（BOOLEAN、INTEGER、BIT STRING 등）을 지원","BER/DER 인코딩 규칙을 지원","Go SDK를 사용하여 Tachograph (.DDD) 파일을 처리","PrintableString、T61String、IA5String 등 문자열 유형을 지원","UTCTime 시간 유형을 지원"],"es":["Soporte para la notación de sintaxis abstracta uno (ASN.1)","Reglas de codificación BER/DER para archivos de tacógrafo","Tipos de datos universales como BOOLEAN, INTEGER y OCTET STRING","Compatibilidad con el SDK de Go para desarrollo de aplicaciones","Referencia para la creación de archivos de tacógrafo (.DDD)","Soporte para la codificación de datos en formato UTCTime"],"fr":["Prise en charge de la notation de syntaxe abstraite uno (ASN.1)","Règles de codage BER/DER pour les fichiers de tachygraphe","Types de données universels tels que BOOLEAN, INTEGER et OCTET STRING","Compatibilité avec le SDK Go pour le développement d''applications","Référence pour la création de fichiers de tachygraphe (.DDD)","Prise en charge de la codification de données au format UTCTime"],"de":["Unterstützung für die abstrakte Syntaxnotation eins (ASN.1)","Kodierungsregeln BER/DER für Tachographen-Dateien","Universelle Datentypen wie BOOLEAN, INTEGER und OCTET STRING","Kompatibilität mit dem Go-SDK für die Entwicklung von Anwendungen","Referenz für die Erstellung von Tachographen-Dateien (.DDD)","Unterstützung für die Kodierung von Daten im UTCTime-Format"],"pt":["Suporte a tags universais como BOOLEAN, INTEGER e OCTET STRING","Trabalho com arquivos tachograph (.DDD) em Go","Uso de BER e DER para codificação de dados","Compatibilidade com a biblioteca Go para desenvolvimento de aplicações"],"ru":["Поддержка универсальных тегов, таких как BOOLEAN, INTEGER и OCTET STRING","Работа с файлами такографа (.DDD) на языке Go с помощью ИИ Агентов","Использование BER и DER для кодирования данных","Совместимость с библиотекой Go для разработки приложений"],"ar":["دعم علامات عالمية مثل BOOLEAN و INTEGER و OCTET STRING","العمل مع ملفات التخطيط (.DDD) في Go باستخدام أدوات الذكاء الاصطناعي","استخدام BER و DER لتشفير البيانات","التوافق مع مكتبة Go لتطوير التطبيقات"]},"keywords":{"en":["how to use asn1","asn1 encoding rules","tachograph file format","BER vs DER","asn1 Go SDK","asn1 tutorial","asn1 setup guide","asn1 alternative","asn1 install"],"zh":["ASN.1","BER/DER","tachograph","Go SDK","数据结构","抽象语法表示法","AIエージェント","AI工具"],"ja":["ASN.1","BER/DER","tachograph","Go SDK","データ構造","抽象構文表現法","AIエージェント","AIツール"],"ko":["ASN.1","BER/DER","tachograph","Go SDK","데이터 구조","추상 구문 표기법","AI 에이전트","AI 도구"],"es":["ASN.1","tacógrafo","Go SDK","BER/DER","notación de sintaxis abstracta","archivos de tacógrafo","desarrollo de aplicaciones","SDK de Go","codificación de datos"],"fr":["ASN.1","tachygraphe","SDK Go","BER/DER","notation de syntaxe abstraite","fichiers de tachygraphe","développement d''applications","SDK Go","codage de données"],"de":["ASN.1","Tachograph","Go-SDK","BER/DER","abstrakte Syntaxnotation","Tachographen-Dateien","Anwendungsentwicklung","Go-SDK","Datenkodierung"],"pt":["asn1","tachograph","arquivos ddd","go","desenvolvimento de aplicações","biblioteca asn1","tags universais","ber","der"],"ru":["asn1","такограф","файлы ddd","go","разработка приложений","библиотека asn1","универсальные теги","ber","der","ИИ Агенты"],"ar":["asn1","تخطيط","ملفات ddd","go","تطوير التطبيقات","مكتبة asn1","علامات عالمية","ber","der","أدوات الذكاء الاصطناعي"]}},"owner":"way-platform","repo":"tachograph-go","repoPath":"way-platform/tachograph-go","stars":8,"forks":2,"updatedAt":"2026-02-24T15:25:34Z","topics":["dtco","go","tachograph"],"category":"community","skillMd":{"name":"asn1","description":"Reference for ASN.1 notation, BER (Basic Encoding Rules), and DER (Distinguished Encoding Rules). Use when decoding/encoding binary data, debugging ASN.1 structures, or understanding PKCS standards.","bodyPreview":"# ASN.1, BER, and DER\n\nThis skill provides reference material for Abstract Syntax Notation One (ASN.1) and its encoding rules (BER/DER).\n\n## Quick Reference\n\n### Universal Tags\n\n| Tag (Hex) | Type |\n| :--- | :--- |\n| `01` | BOOLEAN |\n| `02` | INTEGER |\n| `03` | BIT STRING |\n| `04` | OCTET STRING |\n| `05` | NULL |\n| `06` | OBJECT IDENTIFIER |\n| `10` | SEQUENCE / SEQUENCE OF |\n| `11` | SET / SET OF |\n| `13` | PrintableString |\n| `14` | T61String |\n| `16` | IA5String |\n| `17` | UTCTime |\n\n### Ident","body":"# ASN.1, BER, and DER\n\nThis skill provides reference material for Abstract Syntax Notation One (ASN.1) and its encoding rules (BER/DER).\n\n## Quick Reference\n\n### Universal Tags\n\n| Tag (Hex) | Type |\n| :--- | :--- |\n| `01` | BOOLEAN |\n| `02` | INTEGER |\n| `03` | BIT STRING |\n| `04` | OCTET STRING |\n| `05` | NULL |\n| `06` | OBJECT IDENTIFIER |\n| `10` | SEQUENCE / SEQUENCE OF |\n| `11` | SET / SET OF |\n| `13` | PrintableString |\n| `14` | T61String |\n| `16` | IA5String |\n| `17` | UTCTime |\n\n### Identifier Octet (First Byte)\n\nBits 8-7: Class\n- `00`: Universal\n- `01`: Application\n- `10`: Context-specific\n- `11`: Private\n\nBit 6: PC (Primitive/Constructed)\n- `0`: Primitive (Value is directly in contents)\n- `1`: Constructed (Contents are nested TLV elements)\n\nBits 5-1: Tag Number (if < 31)\n\n## Detailed Guide\n\nFor a comprehensive guide on notation, encoding rules, and specific type handling, read the bundled reference:\n\n`references/guide.md`\n\n### Contents of the Guide:\n1.  **Introduction**: Overview of OSI, ASN.1, BER, DER.\n2.  **ASN.1 Notation**: Simple types, structured types, tagging.\n3.  **BER**: Primitive vs. Constructed, Definite vs. Indefinite length.\n4.  **DER**: subset of BER for unique encoding (Canonical).\n5.  **Type-Specific Encodings**: Detailed breakdown of how to encode INTEGER, BIT STRING, SEQUENCE, etc.\n6.  **Example**: Walkthrough of an X.500 Name encoding.\n\n## Common Operations\n\n### Deciphering a Tag\nIf you encounter byte `0x30`:\n- Binary: `0011 0000`\n- Class: `00` (Universal)\n- P/C: `1` (Constructed)\n- Tag: `10000` (16 -> SEQUENCE)\n\nIf you encounter byte `0xA0`:\n- Binary: `1010 0000`\n- Class: `10` (Context-specific)\n- P/C: `1` (Constructed)\n- Tag: `00000` (0 -> [0])\n\n### Variable Lengths\n- **Short Form**: `0x00` - `0x7F` (0-127 bytes).\n- **Long Form**: Bit 8 is 1. Bits 7-1 = number of length bytes following.\n  - Example: `0x81 0x80` -> Length is in next 1 byte (`0x81`), value is `0x80` (128).\n  - Example: `0x82 0x01 0x00` -> Length is in next 2 bytes (`0x82`), value is `0x0100` (256)."},"lastSynced":"2026-03-06T06:49:07.160Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents working with tachograph data, requiring expertise in Abstract Syntax Notation One (ASN.1) and its encoding rules (BER/DER).","zh":"适合处理tachograph数据的AI代理，需要在抽象语法标记语言一（ASN.1）及其编码规则（BER/DER）方面具有专业知识。","ja":"tachographデータを扱うAIエージェントに適しており、抽象構文記法1（ASN.1）およびその符号化規則（BER/DER）に関する専門知識が必要です。","ko":"tachograph 데이터를 처리하는 AI 에이전트에게 적합하며, 추상 구문 표기법 1(ASN.1) 및その 인코딩 규칙(BER/DER)에 대한 전문 지식이 필요합니다.","es":"Ideal para Agentes de IA que trabajan con datos de tacógrafo, que requieren experiencia en Notación de Sintaxis Abstracta Uno (ASN.1) y sus reglas de codificación (BER/DER).","fr":"Idéal pour les agents IA travaillant avec des données de tachygraphe, nécessitant une expertise en Notation de syntaxe abstraite un (ASN.1) et ses règles de codage (BER/DER).","de":"Ideal für KI-Agenten, die mit Fahrtenschreiber-Daten arbeiten und Erfahrung mit Abstract Syntax Notation One (ASN.1) und ihren Kodierregeln (BER/DER) benötigen.","pt":"Ideal para Agentes de IA que trabalham com dados de tacógrafo, requerendo especialização em Abstract Syntax Notation One (ASN.1) e suas regras de codificação (BER/DER).","ru":"Идеально подходит для агентов ИИ, работающих с данными тахографа, требующих опыта в Abstract Syntax Notation One (ASN.1) и его правилах кодирования (BER/DER).","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يعملون مع بيانات التاكوغراف، يتطلبون خبرة في Abstract Syntax Notation One (ASN.1) وقواعد الترميز الخاصة به (BER/DER)."},"recommendation":{"en":"Empowers agents to decode and encode tachograph (.DDD) files using ASN.1, leveraging its encoding rules such as Basic Encoding Rules (BER) and Distinguished Encoding Rules (DER), to work with data types like BOOLEAN, INTEGER, and OBJECT IDENTIFIER.","zh":"使代理能够使用ASN.1及其编码规则（如基本编码规则（BER）和区别编码规则（DER））解码和编码tachograph（.DDD）文件，以处理诸如BOOLEAN、INTEGER和OBJECT IDENTIFIER等数据类型。","ja":"ASN.1およびその符号化規則（例：基本符号化規則（BER）および区別符号化規則（DER））を使用して、tachograph（.DDD）ファイルの解码および符号化をエージェントに可能にし、BOOLEAN、INTEGER、OBJECT IDENTIFIERなどのデータ型を処理できるようにします。","ko":"ASN.1 및 그 인코딩 규칙(예: 기본 인코딩 규칙(BER) 및 구별 인코딩 규칙(DER))을 사용하여 tachograph(.DDD) 파일을 디코딩 및 인코딩할 수 있도록 에이전트를 활성화하여, BOOLEAN, INTEGER, OBJECT IDENTIFIER 등의 데이터 타입을 처리할 수 있습니다.","es":"Habilita a los agentes para decodificar y codificar archivos de tacógrafo (.DDD) utilizando ASN.1, aprovechando sus reglas de codificación como Reglas básicas de codificación (BER) y Reglas de codificación distinguidas (DER), para trabajar con tipos de datos como BOOLEAN, INTEGER y OBJECT IDENTIFIER.","fr":"Permet aux agents de décoder et d''encoder des fichiers de tachygraphe (.DDD) en utilisant ASN.1, en exploitant ses règles de codage telles que les Règles de codage de base (BER) et les Règles de codage distinguées (DER), pour travailler avec des types de données comme BOOLEAN, INTEGER et OBJECT IDENTIFIER.","de":"Ermöglicht es Agenten, Fahrtenschreiber-Dateien (.DDD) mithilfe von ASN.1 zu decodieren und zu codieren, indem es seine Kodierregeln wie Basic Encoding Rules (BER) und Distinguished Encoding Rules (DER) nutzt, um mit Datentypen wie BOOLEAN, INTEGER und OBJECT IDENTIFIER zu arbeiten.","pt":"Habilita os agentes a decodificar e codificar arquivos de tacógrafo (.DDD) usando ASN.1, aproveitando suas regras de codificação, como Basic Encoding Rules (BER) e Distinguished Encoding Rules (DER), para trabalhar com tipos de dados como BOOLEAN, INTEGER e OBJECT IDENTIFIER.","ru":"Наделяет агентов возможностью декодировать и кодировать файлы тахографа (.DDD) с помощью ASN.1, используя его правила кодирования, такие как Basic Encoding Rules (BER) и Distinguished Encoding Rules (DER), для работы с типами данных, такими как BOOLEAN, INTEGER и OBJECT IDENTIFIER.","ar":"يمنح الوكلاء القدرة على فك وتشفير ملفات التاكوغراف (.DDD) باستخدام ASN.1، مستفيدة من قواعد الترميز الخاصة به، مثل Basic Encoding Rules (BER) و Distinguished Encoding Rules (DER)، للعمل مع أنواع البيانات مثل BOOLEAN و INTEGER و OBJECT IDENTIFIER."},"useCases":{"en":["Decoding tachograph files for data analysis","Generating ASN.1 encoded data for tachograph files","Validating BER and DER encoded data"],"zh":["用于数据分析的tachograph文件解码","为tachograph文件生成ASN.1编码数据","验证BER和DER编码数据"],"ja":["データ分析のためのtachographファイルの解码","tachographファイルのためのASN.1符号化データの生成","BERおよびDER符号化データの検証"],"ko":["데이터 분석을 위한 tachograph 파일 디코딩","tachograph 파일을 위한 ASN.1 인코딩 데이터 생성","BER 및 DER 인코딩 데이터의 유효성 검사"],"es":["Decodificar archivos de tacógrafo para análisis de datos","Generar datos codificados con ASN.1 para archivos de tacógrafo","Validar datos codificados con BER y DER"],"fr":["Décoder des fichiers de tachygraphe pour l''analyse de données","Générer des données codées ASN.1 pour des fichiers de tachygraphe","Valider des données codées BER et DER"],"de":["Fahrtenschreiber-Dateien für Datenanalyse decodieren","ASN.1-codierte Daten für Fahrtenschreiber-Dateien generieren","BER- und DER-codierte Daten validieren"],"pt":["Decodificação de arquivos de tacógrafo para análise de dados","Geração de dados codificados em ASN.1 para arquivos de tacógrafo","Validação de dados codificados em BER e DER"],"ru":["Декодирование файлов тахографа для анализа данных","Генерация данных, закодированных в ASN.1, для файлов тахографа","Проверка данных, закодированных в BER и DER"],"ar":["فك تشفير ملفات التاكوغراف لتحليل البيانات","توليد بيانات مشفرة بتقنية ASN.1 لملفات التاكوغراف","التحقق من صحة البيانات المشفرة بتقنيتي BER و DER"]},"limitations":{"en":["Requires understanding of ASN.1 and its encoding rules","Limited to working with tachograph (.DDD) files"],"zh":["需要了解ASN.1及其编码规则","仅限于处理tachograph（.DDD）文件"],"ja":["ASN.1およびその符号化規則の理解が必要","tachograph（.DDD）ファイルのみを処理可能"],"ko":["ASN.1 및 그 인코딩 규칙에 대한 이해가 필요","tachograph(.DDD) 파일만 처리 가능"],"es":["Requiere comprensión de ASN.1 y sus reglas de codificación","Limitado a trabajar con archivos de tacógrafo (.DDD)"],"fr":["Nécessite une compréhension de ASN.1 et de ses règles de codage","Limité à travailler avec des fichiers de tachygraphe (.DDD)"],"de":["Erfordert Verständnis von ASN.1 und ihren Kodierregeln","Eingeschränkt auf die Arbeit mit Fahrtenschreiber-Dateien (.DDD)"],"pt":["Requer entendimento de ASN.1 e suas regras de codificação","Limitado a trabalhar com arquivos de tacógrafo (.DDD)"],"ru":["Требует понимания ASN.1 и его правил кодирования","Ограничен работой с файлами тахографа (.DDD)"],"ar":["يتطلب فهمًا لتقنية ASN.1 وقواعد الترميز الخاصة بها","محدود بالعمل مع ملفات التاكوغراف (.DDD)"]},"version":4},"contentHash":"73be1f426f0bd8aa2334460eb22af8574adb55d7a263a9ee636d450c945ced5c","qualityScore":20}');
