INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SatoryKono/BioactivityDataAcquisition/py-review-orchestrator', 'py-review-orchestrator', 'SatoryKono', 'BioactivityDataAcquisition', 'community', 'py-review-orchestrator SatoryKono BioactivityDataAcquisition community bioactivity chembl cheminformatics data-pipeline data-quality delta-lake drug-discovery etl medallion-architecture pubchem python uniprot py-review-orchestrator is a skill that runs role-specific workflows for bioactivity data processing, benefiting developers and data scientists working with bioinformatics and cheminformatics datasets. py-review-orchestrator 是一个数据处理框架，用于获取、规范化和验证来自多个外部源的生物活性相关数据集 py-review-orchestrator は、複数の外部ソースからの生物活性関連データセットを取得、正規化、検証するデータ処理フレームワークです py-review-orchestrator 는 여러 외부 소스에서 유래한 생물학적 활성 관련 데이터 세트를 수집, 정규화 및 검증하기 위한 데이터 처리 프레임워크입니다 py-review-orchestrator es un framework para la ejecución de flujos de trabajo de datos, incluyendo la orquestación jerárquica y la gestión de dependencias. Se utiliza para la adquisición, normalización y validación de conjuntos de datos de bioactividad py-review-orchestrator est un framework pour l''exécution de flux de travail de données, y compris l''orchestration hiérarchique et la gestion des dépendances. Il est utilisé pour l''acquisition, la normalisation et la validation de jeux de données de bioactivité py-review-orchestrator ist ein Framework für die Ausführung von Daten-Workflows, einschließlich hierarchischer Orchestrierung und Abhängigkeitsverwaltung. Es wird für die Beschaffung, Normalisierung und Überprüfung von Bioaktivitäts-Datensätzen verwendet O py-review-orchestrator é um framework para orquestração de fluxo de trabalho que utiliza tecnologias como Python e Delta Lake py-review-orchestrator - это фреймворк для управления рабочим процессом, использующий технологии Python и Delta Lake py-review-orchestrator هو إطار عمل لأدوات الذكاء الاصطناعي في إدارة التدفقات العملية باستخدام تقنيات مثل Python و Delta Lake how to use py-review-orchestrator py-review-orchestrator setup guide bioactivity data processing with py-review-orchestrator py-review-orchestrator vs BioETL py-review-orchestrator install what is py-review-orchestrator py-review-orchestrator alternative py-review-orchestrator workflow execution py-review-orchestrator for cheminformatics py-review-orchestrator for bioinformatics py-review-orchestrator 数据处理 生物活性 AI 工具 Python Delta Lake Medallion Architecture ChemBL PubChem Executes hierarchical review orchestration using Wave 1 and Wave 2 workflows Respects sector dependencies for accurate data processing Follows the py-review-orchestrator profile for role-specific workflow execution Utilizes the Medallion architecture for data pipeline management Supports integration with external sources such as ChEMBL and PubChem py-review-orchestrator is a data processing framework skill that orchestrates hierarchical reviews for bioactivity-related datasets from multiple external sources.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eat-pray-ai/yutu/yutu-activity', 'community', 'eat-pray-ai', 'yutu', 'eat-pray-ai/yutu', 'yutu-activity', 0, 0, 20, '2026-03-08T01:57:15.275Z', '2026-03-08T02:00:38.870Z', '7233f20646ec4513d8c43792c4ad4e8372ca8859b2dc2928c9d19170f60d7831', '{"id":"eat-pray-ai/yutu/yutu-activity","name":"yutu-activity","description":{"en":"yutu-activity is a fully functional MCP server and CLI for YouTube, enabling developers to manage activities. It benefits developers working with YouTube operations.","zh":"yutu-activity是一个完全功能的MCP服务器和CLI，为YouTube提供服务。开发者可以使用它来设置和管理YouTube活动","ja":"yutu-activityは、YouTube用の完全なMCPサーバーとCLIです。開発者はこれを使用してYouTubeの活動を設定して管理できます","ko":"yutu-activity는 YouTube용 완전한 MCP 서버 및 CLI입니다. 개발자는 이를 사용하여 YouTube 활동을 설정하고 관리할 수 있습니다","es":"yutu-activity es un servidor MCP y CLI de YouTube completamente funcional. Proporciona una forma eficiente de listar actividades.","fr":"yutu-activity est un serveur MCP et une interface de ligne de commande YouTube entièrement fonctionnelle. Il offre un moyen efficace de lister les activités.","de":"yutu-activity ist ein voll funktionsfähiger MCP-Server und YouTube-CLI. Es bietet eine effiziente Möglichkeit, Aktivitäten zu listen.","pt":"O yutu-activity é um servidor MCP e CLI para YouTube que oferece funcionalidades como listagem de atividades","ru":"yutu-activity - это полнофункциональный сервер MCP и CLI для YouTube, который предоставляет функции, такие как список активностей","ar":"yutu-activity هو خادم MCP و CLI كامل لليوتيوب يقدم ميزات مثل قائمة النشاطات"},"seo":{"title":{"en":"yutu-activity: MCP Server and CLI Setup Guide | AI Agent ...","zh":"yutu-activity.setup指南：YouTube MCP服务器和CLI","ja":"yutu-activityセットアップガイド：YouTube用MCPサーバーとCLI","ko":"yutu-activity 설정 가이드: YouTube MCP 서버 및 CLI","es":"Guía de configuración de yutu-activity para servidores MC...","fr":"Guide d''installation de yutu-activity pour les serveurs M...","de":"Einrichtungsleitfaden für yutu-activity: MCP-Server und Y...","pt":"Guia de Configuração do yutu-activity: Servidor MCP e CLI...","ru":"Настройка yutu-activity: Полнофункциональный сервер MCP и...","ar":"دليل إعداد yutu-activity: خادم MCP و CLI كامل لليوتيوب"},"description":{"en":"Discover how to leverage yutu-activity for YouTube operations. Learn to list activities and more with this comprehensive AI agent skill.","zh":"了解yutu-activity的功能和特点，包括YouTube MCP服务器和CLI，帮助开发者快速设置和使用","ja":"yutu-activityの機能と特徴を紹介します。YouTube用MCPサーバーとCLIを設定して使用する方法を解説します","ko":"yutu-activity의 기능과 특징을 알아보세요. YouTube MCP 서버와 CLI를 설정하고 사용하는 방법을介绍합니다","es":"Descubre cómo utilizar yutu-activity para crear un servidor MCP y una interfaz de línea de comandos para YouTube, y explora sus características clave.","fr":"Découvrez comment utiliser yutu-activity pour créer un serveur MCP et une interface de ligne de commande pour YouTube, et explorez ses fonctionnalités clés.","de":"Erfahren Sie, wie Sie yutu-activity verwenden, um einen MCP-Server und eine Befehlszeilen-Schnittstelle für YouTube zu erstellen, und erkunden Sie seine wich...","pt":"Aprenda a configurar o yutu-activity, um servidor MCP e CLI para YouTube, e descubra suas funcionalidades","ru":"Узнайте, как настроить yutu-activity, полнофункциональный сервер MCP и CLI для YouTube, и его возможности","ar":"تعرف على كيفية إعداد yutu-activity، خادم MCP و CLI كامل لليوتيوب، واكتشف ميزاته"},"definition":{"en":"yutu-activity is a command-line interface and server for managing YouTube activities, providing operations like listing activities.","zh":"yutu-activity是一种AIエージェント，提供YouTube MCP服务器和CLI的功能","ja":"yutu-activityは、YouTube用MCPサーバーとCLIを提供するAIエージェントです","ko":"yutu-activity는 YouTube MCP 서버 및 CLI를 제공하는 AI 에이전트입니다","es":"yutu-activity es una herramienta de agente de inteligencia artificial (AI) que ofrece un servidor MCP y una CLI para YouTube.","fr":"yutu-activity est un outil d''agent d''intelligence artificielle (IA) qui propose un serveur MCP et une interface de ligne de commande pour YouTube.","de":"yutu-activity ist ein Tool für künstliche Intelligenz (KI)-Agenten, das einen MCP-Server und eine Befehlszeilen-Schnittstelle für YouTube bietet.","pt":"O yutu-activity é um servidor MCP e CLI para YouTube que permite gerenciar atividades","ru":"yutu-activity - это сервер MCP и CLI для YouTube, который позволяет управлять активностями","ar":"yutu-activity هو خادم MCP و CLI لليوتيوب يسمح بإدارة النشاطات"},"features":{"en":["Lists activities using the ''list'' operation","Supports referencing activity details via ''details'' link","Provides a fully functional MCP server for YouTube operations","Offers a CLI for interacting with YouTube activities","Includes documentation for activity listing via ''activity-list.md'' reference"],"zh":["支持YouTube MCP服务器","提供CLI命令行工具","支持活动列表功能","集成了YouTube API"],"ja":["YouTube用MCPサーバーをサポート","CLIコマンドラインツールを提供","活動リスト機能をサポート","YouTube APIを統合"],"ko":["YouTube MCP 서버 지원","CLI 명령줄 도구 제공","활동 목록 기능 지원","YouTube API 통합"],"es":["Servidor MCP completamente funcional","Interfaz de línea de comandos (CLI) para YouTube","Listado de actividades","Compatibilidad con operaciones de lista","Documentación detallada para actividades","Soporte para desarrollo de aplicaciones personalizadas"],"fr":["Serveur MCP entièrement fonctionnel","Interface de ligne de commande (CLI) pour YouTube","Liste d''activités","Prise en charge des opérations de liste","Documentation détaillée pour les activités","Support pour le développement d''applications personnalisées"],"de":["Voll funktionsfähiger MCP-Server","Befehlszeilen-Schnittstelle (CLI) für YouTube","Auflistung von Aktivitäten","Unterstützung für Listenvorgänge","Detaillierte Dokumentation für Aktivitäten","Unterstützung für die Entwicklung von benutzerdefinierten Anwendungen"],"pt":["Servidor MCP para YouTube","CLI para gerenciar atividades","Listagem de atividades","Compatibilidade com tecnologias de desenvolvimento","Integração com a plataforma YouTube","Gerenciamento de atividades via linha de comando"],"ru":["Полнофункциональный сервер MCP для YouTube","CLI для управления активностями","Список активностей","Поддержка технологий разработки","Интеграция с платформой YouTube","Управление активностями через командную строку"],"ar":["خادم MCP كامل لليوتيوب","واجهة سطر الأوامر لإدارة النشاطات","قائمة النشاطات","دعم لتكنولوجيا التطوير","التكامل مع منصة اليوتيوب","إدارة النشاطات عبر سطر الأوامر"]},"keywords":{"en":["how to use yutu-activity","yutu-activity setup guide","yutu-activity alternative","yutu-activity vs YouTube API","yutu-activity install","what is yutu-activity","yutu-activity for YouTube operations","yutu-activity CLI commands","yutu-activity MCP server setup"],"zh":["yutu-activity","YouTube MCP服务器","CLI命令行工具","AIエージェント","YouTube API","活动列表"],"ja":["yutu-activity","YouTube用MCPサーバー","CLIコマンドラインツール","AIエージェント","YouTube API","活動リスト"],"ko":["yutu-activity","YouTube MCP 서버","CLI 명령줄 도구","AI 에이전트","YouTube API","활동 목록"],"es":["yutu-activity","servidor MCP","CLI de YouTube","agente de inteligencia artificial","herramientas de desarrollo","listado de actividades","desarrollo de aplicaciones personalizadas","MCP y CLI","YouTube y AI"],"fr":["yutu-activity","serveur MCP","interface de ligne de commande YouTube","agent d''intelligence artificielle","outils de développement","liste d''activités","développement d''applications personnalisées","MCP et CLI","YouTube et IA"],"de":["yutu-activity","MCP-Server","Befehlszeilen-Schnittstelle YouTube","künstliche Intelligenz-Agent","Entwicklungstools","Auflistung von Aktivitäten","Entwicklung von benutzerdefinierten Anwendungen","MCP und CLI","YouTube und KI"],"pt":["yutu-activity","servidor MCP","CLI para YouTube","gerenciamento de atividades","desenvolvimento de software","tecnologias de desenvolvimento","YouTube API","integração com YouTube"],"ru":["yutu-activity","полнофункциональный сервер MCP","CLI для YouTube","упра